L["|cffffd100the spell for %s went out after all|r -- the error before it was about something else."] = "|cffffd100l'incantesimo per %s è partito comunque|r -- l'errore precedente riguardava altro."
L["|cffffd100%s was buffed after all|r -- the error before it was about something else."] = "|cffffd100%s ha ricevuto il beneficio, alla fine|r -- l'errore precedente riguardava altro."
