L["example macros to try"] = "esempi di macro da provare"
L["Manners commands:"] = "Comandi di Manners:"
L["|cffffd100/mnr|r works in place of |cffffd100/manners|r in all of them."] = "|cffffd100/mnr|r funziona al posto di |cffffd100/manners|r in tutti i comandi."
L["|cffff8080own buffs: last scan not believed (%s)|r -- %d read, baseline %d"] = "|cffff8080benefici su di te: ultima scansione non attendibile (%s)|r -- %d letti, riferimento %d"
L["|cffffd100own buffs: baseline not settled|r -- %d read, waiting for a second scan to agree"] = "|cffffd100benefici su di te: riferimento non stabilito|r -- %d letti, in attesa di una seconda scansione che confermi"
L["own buffs: %d read, baseline %d"] = "benefici su di te: %d letti, riferimento %d"
L["%d changes to your auras this session, read in %d walks"] = "%d cambiamenti alle tue aure in questa sessione, letti in %d passaggi"
L["thank with an emote: |cff00ff00on|r"] = "ringraziamento con emote: |cff00ff00attivato|r"
L["thank with an emote: |cffff0000off|r"] = "ringraziamento con emote: |cffff0000disattivato|r"
L["last thanked: |cffffffff%s|r, %ds ago (the game answered %s)"] = "ultimo ringraziamento: |cffffffff%s|r, %d s fa (risposta del gioco: %s)"
L["last not thanked: |cffffffff%s|r, %ds ago (%s)"] = "ultimo ringraziamento saltato: |cffffffff%s|r, %d s fa (%s)"
L["try cleared -- the normal cast takes effect when this fight ends; until then a press runs the macro already on the button."] = "try annullato -- il lancio normale torna quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["try cleared -- back to the normal cast."] = "try annullato -- si torna al lancio normale."
L["try armed: |cff80ff80%s|r"] = "try attivato: |cff80ff80%s|r"
L["|cffff8080not armed for now:|r %s."] = "|cffff8080per ora non attivato:|r %s."
L["expands to: |cffffffff%s|r"] = "diventa: |cffffffff%s|r"
L["%d characters -- %d over the %d a macro body holds. The client will cut it, and what runs is not what is printed above."] = "%d caratteri -- %d oltre i %d che il testo di una macro può contenere. Il client lo taglierà, e ciò che viene eseguito non è ciò che vedi qui sopra."
L["It takes effect when this fight ends; until then a press runs the macro already on the button. |cffffd100/manners try|r with nothing clears it."] = "Ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante. |cffffd100/manners try|r da solo lo annulla."
L["The prompt arms it once they have one. |cffffd100/manners try|r with nothing clears it."] = "Il riquadro lo attiva appena il giocatore ne ha uno. |cffffd100/manners try|r da solo lo annulla."
L["Click the prompt to run it. |cffffd100/manners try|r with nothing clears it."] = "Fai clic sul riquadro per eseguirlo. |cffffd100/manners try|r da solo lo annulla."
L["Targeting forms, for /manners try:"] = "Modi di indicare il bersaglio, per /manners try:"
L["(on yourself)"] = "(su di te)"
L["Tokens: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} is what a debt is filed under, {aim} is what a targeting line wants. Use \\n for a new line."] = "Segnaposto: |cffffd100{unit} {name} {aim} {first} {spell} {id}|r. {name} è il nome sotto cui si registra un debito, {aim} è ciò che serve a una riga di bersaglio. Usa \\n per andare a capo."
L["the favour ledger did not load -- reinstalling Manners should bring it back."] = "il registro dei favori non si è caricato -- reinstallare Manners dovrebbe riportarlo."
L["unlocked -- it can be dragged once this fight ends; until then a press still casts what the fight froze. Then |cffffd100/manners lock|r."] = "sbloccato -- potrai trascinarlo quando finisce questo combattimento; fino ad allora un clic lancia ancora ciò che il combattimento ha congelato. Poi |cffffd100/manners lock|r."
L["unlocked -- it can be dragged once this fight ends; nothing is armed meanwhile. Then |cffffd100/manners lock|r."] = "sbloccato -- potrai trascinarlo quando finisce questo combattimento; nel frattempo il pulsante è vuoto. Poi |cffffd100/manners lock|r."
L["unlocked -- drag the prompt, then |cffffd100/manners lock|r."] = "sbloccato -- trascina il riquadro, poi |cffffd100/manners lock|r."
L["unlocked, but the addon is |cffff8080off|r so there is no prompt to drag -- |cffffd100/manners on|r first."] = "sbloccato, ma l'add-on è |cffff8080disattivato|r, quindi non c'è nessun riquadro da trascinare -- prima |cffffd100/manners on|r."
L["locked."] = "bloccato."
L["hand your target back after buffing: |cff00ff00on|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "ripristino del bersaglio dopo un beneficio: |cff00ff00attivato|r -- ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["hand your target back after buffing: |cffff0000off|r -- takes effect when this fight ends; until then a press runs the macro already on the button."] = "ripristino del bersaglio dopo un beneficio: |cffff0000disattivato|r -- ha effetto quando finisce questo combattimento; fino ad allora un clic esegue la macro già sul pulsante."
L["hand your target back after buffing: |cff00ff00on|r"] = "ripristino del bersaglio dopo un beneficio: |cff00ff00attivato|r"
L["hand your target back after buffing: |cffff0000off|r"] = "ripristino del bersaglio dopo un beneficio: |cffff0000disattivato|r"
L["click logging: |cff00ff00on|r"] = "log dei clic: |cff00ff00attivato|r"
L["click logging: |cffff0000off|r"] = "log dei clic: |cffff0000disattivato|r"
L["verbose: |cff00ff00on|r -- a line in your own chat when somebody buffs you, when a favour is counted as repaid, and when a click fails, is skipped, or leaves somebody owed"] = "verbose: |cff00ff00attivato|r -- una riga nella tua chat quando qualcuno ti dà un beneficio, quando un favore viene considerato ricambiato, e quando un clic fallisce, viene saltato o lascia un favore da ricambiare"
L["verbose: |cffff0000off|r"] = "verbose: |cffff0000disattivato|r"
L["enabled."] = "attivato."
L["disabled."] = "disattivato."
L["nobody is on your never-offer list. Shift-right-click the prompt to put whoever it is showing on it."] = "non c'è nessuno tra i tuoi esclusi. Fai Maiusc+clic destro sul riquadro per aggiungere agli esclusi il giocatore che mostra."
L["never offered anything unless they buff you: %s"] = "mai proposti, a meno che non ti diano un beneficio: %s"
L["say who: |cffffd100/manners allow Name|r. |cffffd100/manners never|r lists everybody on the list."] = "indica chi: |cffffd100/manners allow Name|r. |cffffd100/manners never|r elenca tutti gli esclusi."
L["|cffffffff%s|r can be offered again."] = "|cffffffff%s|r può di nuovo essere proposto."
L["nobody called %s is on your never-offer list."] = "tra i tuoi esclusi non c'è nessuno che si chiami %s."
L["snooze takes a number of minutes from 1 to %d, or off -- for example |cffffd100/manners snooze 15|r or |cffffd100/manners snooze 1h|r."] = "snooze accetta un numero di minuti da 1 a %d, oppure off -- per esempio |cffffd100/manners snooze 15|r o |cffffd100/manners snooze 1h|r."
L["your settings are in the box under |cffffd100Share as text|r on the Profiles tab of the options -- click in it, select all and copy."] = "le tue impostazioni sono nella casella sotto |cffffd100Condividi come testo|r nella scheda Profili delle opzioni -- fai clic nella casella, seleziona tutto e copia."
L["this string is too long to be imported back -- a very long phrase box under What I say is the usual cause. Shorten it if you want to share these settings."] = "questa stringa è troppo lunga per essere reimportata -- di solito la causa è una casella delle frasi molto lunga nella scheda Cosa dico. Accorciala se vuoi condividere queste impostazioni."
L["paste the settings string into the box under |cffffd100Share as text|r on the Profiles tab, or type |cffffd100/manners import|r followed by it."] = "incolla la stringa delle impostazioni nella casella sotto |cffffd100Condividi come testo|r nella scheda Profili, oppure scrivi |cffffd100/manners import|r seguito dalla stringa."
L["type |cffffd100/manners import|r followed by a settings string."] = "scrivi |cffffd100/manners import|r seguito da una stringa delle impostazioni."
L["Tools for testing Manners on this client:"] = "Strumenti per testare Manners su questo client:"
L["nothing has broken this session."] = "in questa sessione non è andato storto niente."
L["|cffffd100the last %d of %d|r |cff808080(%d kept)|r:"] = "|cffffd100gli ultimi %d di %d|r |cff808080(%d conservati)|r:"
L["|cffffd100the last %d of %d|r:"] = "|cffffd100gli ultimi %d di %d|r:"
L["Flavour.lua did not load -- check the toc's file list"] = "Flavour.lua non si è caricato -- controlla l'elenco dei file del toc"
L["your own buff: not offered -- %s is switched off."] = "il tuo beneficio personale: non proposto -- l'opzione %s è disattivata."
L["switched OFF on this profile -- nothing is recorded or offered; /manners on"] = "DISATTIVATO in questo profilo -- non si registra né si propone niente; /manners on"
L["|cffff4040this client has never heard of %s|r -- Manners has the wrong spell ids for %s on %s. Please report this line."] = "|cffff4040questo client non conosce %s|r -- Manners ha gli ID incantesimo sbagliati per %s su %s. Segnala questa riga, per favore."
L["owes returning: |cffffffff%s|r (%ds left, buffed you %ds ago)"] = "da ricambiare: |cffffffff%s|r (%d s rimasti, ti ha dato un beneficio %d s fa)"
L["not watching for favours -- Manners is switched off."] = "nessun controllo dei favori -- Manners è disattivato."
L["Favours are not recorded while \"People who buff me\" is off, on the Who to buff tab."] = "I favori non vengono registrati mentre l'opzione \"Chi mi dà un beneficio\" è disattivata, nella scheda Destinatari."
L["not watching for favours -- |cffffd100People who buff me|r is switched off."] = "nessun controllo dei favori -- l'opzione |cffffd100Chi mi dà un beneficio|r è disattivata."
L["nobody has buffed you recently."] = "nessuno ti ha dato un beneficio di recente."
L["your own buff: offered to you when you are missing it."] = "il tuo beneficio personale: proposto quando non ce l'hai."
L["your own buff: nothing you cast goes on yourself alone."] = "il tuo beneficio personale: niente di ciò che lanci va solo su di te."
L["prompt is UNLOCKED -- it will not buff anyone until you /manners lock"] = "il riquadro è SBLOCCATO -- non darà benefici a nessuno finché non scrivi /manners lock"
L["|cffffd100snoozed until %s|r -- no prompt until then; /manners snooze off ends it"] = "|cffffd100in pausa fino alle %s|r -- nessun riquadro fino ad allora; /manners snooze off la termina"
L["|cffffd100mounted|r -- Not while mounted keeps the prompt away until you get off"] = "|cffffd100in sella|r -- l'opzione Non in sella tiene nascosto il riquadro finché non scendi dalla cavalcatura"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only your own buff and people who buffed you or asked are offered"] = "|cffffd100risparmio di mana|r -- finché non torni al %d%% di mana, il riquadro propone solo il tuo beneficio personale e chi ti ha dato un beneficio o te l'ha chiesto"
L["|cffffd100saving mana|r -- until you are back to %d%% mana, only people who buffed you or asked are offered"] = "|cffffd100risparmio di mana|r -- finché non torni al %d%% di mana, il riquadro propone solo chi ti ha dato un beneficio o te l'ha chiesto"
L["|cffffd100ready check|r -- your party or raid comes first until the pull"] = "|cffffd100appello|r -- il tuo gruppo o la tua incursione ha la precedenza fino all'inizio del combattimento"
L["|cffffd100raid groups|r -- in a raid, only groups %s are offered unasked"] = "|cffffd100gruppi dell'incursione|r -- in un'incursione, solo i gruppi %s vengono proposti senza che lo chiedano"
L["|cffffd100raid groups|r -- every group is unticked, so in a raid nobody is offered unasked"] = "|cffffd100gruppi dell'incursione|r -- nessun gruppo è spuntato, quindi in un'incursione nessuno viene proposto senza che lo chieda"
L["|cffff8080/manners try is armed:|r %s -- clear it with a bare /manners try"] = "|cffff8080/manners try è attivato:|r %s -- annullalo con /manners try da solo"
L["queue now: %d"] = "in coda ora: %d"
L["queue if switched on: %d"] = "in coda se attivato: %d"
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners help|r lists them all."] = "non esiste |cffffd100/manners %s|r -- intendevi |cffffd100/manners %s|r? |cffffd100/manners help|r li elenca tutti."
L["there is no |cffffd100/manners %s|r -- did you mean |cffffd100/manners %s|r? |cffffd100/manners dev|r lists the testing tools."] = "non esiste |cffffd100/manners %s|r -- intendevi |cffffd100/manners %s|r? |cffffd100/manners dev|r elenca gli strumenti di test."
L["Thank ye kindly, {name}! First round's on me when we're back at the forge."] = "Grazie di cuore, {name}! Alla forgia il primo giro lo offro io."
L["Much obliged, {name}. Ye've a friend in the mountain now."] = "Grazie assai, {name}. Ora hai un amico nella montagna."
L["Thank ye, {name}! I'd have been fine without it, mind. But thank ye."] = "Grazie, {name}! Me la sarei cavata anche senza, sia chiaro. Ma grazie."
L["Bless ye, {name}! I'd hug ye, but ye'd be needin' a healer after."] = "Evviva, {name}! Ti abbraccerei, ma poi ti servirebbe un guaritore."
L["Paid back already, {name}. Quicker than I've ever settled a bar tab."] = "Già ricambiato, {name}. Mai saldato un conto all'osteria così in fretta."
L["I'll tell this at the Thunderbrew like ye saved me life, {name}. Thank ye!"] = "A Kharanos lo racconterò come se mi avessi salvato la vita, {name}. Grazie!"
L["Grand, {name}! I'd carve ye a statue, but this is quicker."] = "Magnifico, {name}! Ti scolpirei una statua, ma così si fa prima."
L["The Titans made us of stone, {name}, but that still touched me. Thank ye."] = "I Titani ci fecero di pietra, {name}, ma stavolta hai fatto breccia. Grazie."
L["Thank ye, {name}. Back at ye, before me pride notices I needed it."] = "Grazie, {name}. Ricambio, prima che l'orgoglio scopra che mi serviva."
L["Thank ye, {name}. Muradin says a debt left unpaid rusts. Here, before it does."] = "Grazie, {name}. Muradin dice che i debiti arrugginiscono. Eccolo, ancora lucido."
L["Thank ye, {name}. Even me ram looked impressed, and he hates everybody."] = "Grazie, {name}. Perfino il mio ariete ne è rimasto colpito, e lui odia tutti."
L["The Explorers' League'll ask where ye dug up such manners, {name}. Thanks!"] = "La Lega degli Esploratori vorrà sapere in che scavo trovi tanta educazione, {name}!"
L["Thank ye, {name}. Warmed me right down to me boots, that did."] = "Grazie, {name}. Mi ha scaldato fino agli stivali, questo."
L["Mined half o' Khaz Modan, {name}. Never struck a vein that rich. Yer cut."] = "Mezza Khaz Modan scavata, {name}, e mai un filone così ricco. Ecco la tua parte."
L["Like a Kharanos hearth in a Dun Morogh blizzard, that, {name}. Thank ye."] = "Come un camino di Kharanos in una bufera di Dun Morogh, {name}. Grazie."
L["Came back to ye like a Wildhammer's stormhammer, {name}. Less painful, mind."] = "Torna da te come il martello di un Granmartello, {name}. Fa meno male, però."
L["Come to Ironforge, {name}. Me mam'll feed ye till ye can't stand. Thank ye!"] = "Passa a Forgiardente, {name}. Mia mamma ti rimpinza finché non rotoli. Grazie!"
L["Checked it fer gunpowder out o' habit, {name}. Clean as a whistle. Here's yers!"] = "Controllato: niente polvere da sparo, {name}. Abitudine. Ecco, ricambio!"
L["Aye, {name}, ye only had to ask. Hold still now, like a good anvil."] = "Ma certo, {name}, bastava chiedere! Ora immobile, come una brava incudine."
L["Say no more, {name}. Stone and steel, here it comes."] = "Non dire altro, {name}. Pietra e acciaio, eccolo che arriva!"
L["Ask a dwarf fer help, {name}, and ye'll get it. Loudly."] = "Chiedi aiuto a un nano, {name}, e l'avrai. A pieni polmoni."
L["Right, {name}. Brace yerself; I do everything like I'm swingin' a hammer."] = "Bene, {name}. Tieniti forte: io faccio tutto come se brandissi un martello."
L["Aye, {name}, and a story about it ye didn't ask fer. Where to begin..."] = "Certo, {name}, con tanto di storia che non hai chiesto. Da dove comincio..."
L["One {buff}, pulled fresh like a proper pint, {name}."] = "{buff} alla spina, {name}. Spillatura a regola d'arte."
L["Done, {name}. Dwarven work: over-built, under-priced and guaranteed."] = "Fatto, {name}. Lavoro nanico: sovradimensionato, sottocosto e garantito."
L["Easy, {name}. Last time I helped a gnome, it cost me both eyebrows."] = "Facile, {name}. L'ultima volta che ho aiutato uno gnomo, ci ho rimesso le sopracciglia."
L["Aye, {name}. Mountain kings never refuse. I'm more a foothill, but same rule."] = "Certo, {name}. Un Re della Montagna non dice mai di no. Io, re della collina, nemmeno."
L["Tempered and quenched, {name}. Mind, it's still hot."] = "Forgiato e temprato, {name}. Occhio, scotta ancora."
L["Done afore ye finished, {name}. Dwarves hear 'please' through solid rock."] = "Fatto prima che finissi, {name}. Un nano sente 'per favore' anche nella roccia."
L["Aye, {name}. In Dun Morogh ye help quick, or ye both freeze standin' there."] = "Certo, {name}. A Dun Morogh si aiuta in fretta, o si gela tutti e due lì impalati."
L["Aye, {name}. Ye'll feel it in yer boots first. That's how ye know it's dwarven."] = "Certo, {name}. Lo sentirai prima negli stivali. È così che capisci che è nanico."
L["Aye, {name}. Say no, and ye'd ask a gnome, and then I'd feel responsible."] = "Certo, {name}. Se dico di no chiederai a uno gnomo, e poi mi sentirei in colpa."
L["Here, {name}, a wee somethin' to keep ye on yer feet. Wee, like me."] = "Tieni, {name}, un aiutino per tenerti in piedi. Piccolo, come me."
L["Off ye go, {name}, steady as the mountain."] = "Va' pure, {name}, con passo saldo come la montagna."
L["Here, {name}. Ale's for after; this is for before."] = "Tieni, {name}. La birra è per dopo; questo è per prima."
L["Magni turned to diamond fer the cause, {name}. This is the cheaper option."] = "Magni diventò diamante per la causa, {name}. Questa è la versione economica."
L["A dwarf's got yer back, {name}. Well, yer knees. Close enough."] = "Un nano ti copre le spalle, {name}. Be', le ginocchia. Quasi uguale."
L["If a trogg bothers ye, {name}, tell it a dwarf sent ye. Then run."] = "Se un trogg ti dà noia, {name}, digli che ti manda un nano. Poi scappa."
L["If it wears off, {name}, give it a good thump. That's how we fix everything."] = "Se svanisce, {name}, dagli una bella botta. Noi aggiustiamo tutto così."
L["Take this, {name}. I'd give ye some stubbornness too, but I'm usin' all mine."] = "Prendi, {name}. Ti darei anche un po' della mia testa dura, ma mi serve tutta."
L["Mind the wendigos, {name}: big, hairy and grumpy. Like me, but hungrier."] = "Occhio ai wendigo, {name}: grossi, pelosi, scorbutici. Come me, ma con più fame."
L["Take this, {name}. Me grandad fought three wars with a pickaxe and this."] = "Prendi, {name}. Mio nonno ha fatto tre guerre con un piccone e questo."
L["Dwarven make, {name}. Drop it off Thandol Span and it'd still work. Don't."] = "Lavoro nanico, {name}: lancialo dal Ponte di Thandol e funziona ancora. Non farlo."
L["Stonewrought Dam holds back a whole loch, {name}. This'll hold ye together."] = "La diga di Loch Modan trattiene un lago intero, {name}. Questo ti terrà insieme."
L["Won't keep yer boots dry in the Wetlands, {name}. Nothin' does. The rest, aye."] = "Nelle Paludi non ti terrà asciutti gli stivali, {name}. Niente ci riesce. Il resto sì."
L["Old miner's rule, {name}: never go down a hole without a lamp, a mate and this."] = "Regola da minatore, {name}: mai giù in un pozzo senza lampada, un amico e questo."
L["Brann Bronzebeard went explorin' with less, {name}, and wrote three books."] = "Brann Barbabronzea è partito con meno di così, {name}, e ci ha scritto tre libri."
L["Mountaineers swear by it, {name}. Ye'll climb no better, but land softer."] = "I montanari lo giurano, {name}: non scalerai meglio, ma cadrai più morbido."
L["Ironforge's gates have never fallen, {name}. Neither should ye. Take this."] = "Le porte di Forgiardente non sono mai cadute, {name}. Nemmeno tu dovresti. Prendi."
L["Me cousins down Blackrock way would've set it alight first, {name}. Fer luck."] = "I cugini di Roccianera ci avrebbero dato fuoco prima, {name}. Porta bene."
L["Stone and hammer keep ye, cousin {name}!"] = "Pietra e martello ti proteggano, {name}! Siamo della stessa roccia."
L["Three Hammers, one round, cousin {name}!"] = "Tre Martelli, un giro in famiglia, {name}!"
L["Yer cousin's cousin married mine, {name}, I'd wager. It's a small mountain."] = "Tuo cugino di terzo grado avrà sposato il mio, {name}. La montagna è piccola."
L["Two dwarves together, {name}. Pity whatever's standin' in our way."] = "Due nani insieme, {name}. Povero chi ci sbarra la strada."
L["Bronzebeard, Wildhammer, Dark Iron, Earthen, {name}: one family, nobody agrees."] = "Barbabronzea, Granmartello, Ferroscuro, Terrigeni, {name}: una famiglia, mai d'accordo."
L["Between the pair of us, {name}, we could out-stubborn a mountain."] = "Noi due, {name}, abbiamo la testa più dura di una montagna."
L["Me grandmother'd climb out of her tomb if I did any less fer kin, {name}."] = "Mia nonna uscirebbe dalla tomba se facessi di meno per la famiglia, {name}."
L["The Titans carved us both from the same rock, {name}. Explains the headaches."] = "I Titani ci scolpirono nella stessa roccia, {name}. Ecco spiegati i mal di testa."
L["Kin's kin, {name}, far from the mountain or under it."] = "Parenti si resta, {name}, lontano dalla montagna o sotto di essa."
L["Stand behind me, {name}. Aye, I know. Crouch a bit."] = "Mettiti dietro di me, {name}. Sì, lo so. Abbassati un po'."
L["Right, {name}: I take the front, ye take the loot, and we argue after."] = "Allora, {name}: io sto davanti, tu prendi il bottino, e poi litighiamo."
L["If I start singin', {name}, the fight's gone well. Or very badly."] = "Se comincio a cantare, {name}, va alla grande. O malissimo."
L["Dwarves never leave a mate behind, {name}. Nor a keg, come to that."] = "Un nano non lascia indietro un compagno, {name}. E nemmeno un barile, a dirla tutta."
L["Beards out, {name}! Them without beards, look fierce. It's nearly as good."] = "Barbe al vento, {name}! Chi non ce l'ha, sguardo feroce. Funziona quasi."
L["Knocked on the nearest rock, {name}. Solid. No cave-ins fer us today."] = "Tocco roccia, {name}, altro che ferro. Solida: oggi niente crolli."
L["No fires near me pack, {name}. It's mostly gunpowder. And a sandwich."] = "Niente fuoco vicino al mio zaino, {name}: c'è polvere da sparo. E un panino."
L["Dwarves don't retreat, {name}. Our legs aren't built fer it."] = "I nani non ripiegano, {name}. Le nostre gambe non sono fatte per questo."
L["Stay close, {name}. If it goes dark, follow the cursin'. That'll be me."] = "Stammi vicino, {name}. Se si fa buio, segui le imprecazioni. Sarò io."
L["Dwarves always know which way is down, {name}. Up's yer problem."] = "Un nano sa sempre da che parte è giù, {name}. Il su è affar tuo."
L["Anythin' made o' stone, {name}, let me talk to it first. Might be a cousin."] = "Tutto ciò che è di pietra, {name}, lo saluto prima io. Magari è un cugino."
L["If the ceilin' creaks, {name}, I'll tell ye. If I go quiet, run."] = "Se il soffitto scricchiola, {name}, te lo dico. Se sto zitto, scappa."
L["Mornin', {name}! Too early for ale. Almost. Have this first."] = "'Giorno, {name}! Troppo presto per la birra. Quasi. Prima questo."
L["Up with the forge fires, {name}! A dwarf's day starts with a hammer and this."] = "Si accendono le forge, {name}! La giornata di un nano: martello, e questo."
L["Early, {name}? Nonsense. The mine's been open two hours. Here."] = "Presto, {name}? Macché. La miniera è aperta da due ore. Tieni."
L["Mornin', {name}. Me eyes are still abed. The rest o' me's ready."] = "'Giorno, {name}. Gli occhi sono ancora a letto. Il resto di me è pronto."
L["Mornin', {name}. Porridge, a pipe and this. The other two are mine."] = "'Giorno, {name}. Polenta, pipa e questo. Le prime due sono mie."
L["The rams had me up at dawn, {name}. Headbutted the door till I came out. Here."] = "Gli arieti mi hanno buttato giù dal letto, {name}. A testate sulla porta. Tieni."
L["Mornin', {name}. Ears still ringin' from last night's singin'. Here."] = "'Giorno, {name}. Le orecchie fischiano ancora per i canti di ieri. Tieni."
L["My thanks, {name}. Let me return the kindness before a bard gets it wrong."] = "Ti ringrazio, {name}. Ricambio, prima che un bardo la racconti storta."
L["Kindly done, {name}. Let no one say we forget a friend."] = "Molto gentile, {name}. Nessuno dirà che dimentichiamo gli amici."
L["Thank you, {name}. I'd knight you, but apparently I 'need permission'."] = "Grazie, {name}. Ti farei cavaliere, ma pare che mi serva il 'permesso'."
L["Repaid on the spot, {name}. In Stormwind that'd take three forms and a stamp."] = "Ricambiato all'istante, {name}. A Roccavento: tre moduli e una marca da bollo."
L["Thanks, {name}. Prompter than Stormwind ever paid its stonemasons."] = "Grazie, {name}. Più puntuale di Roccavento coi suoi scalpellini."
L["Much obliged, {name}. Mother said always return a kindness. And the dish."] = "Grazie, {name}. Mamma diceva: ricambia sempre una gentilezza. E riporta la teglia."
L["Thank you, {name}. In Elwynn, no kindness goes home unanswered."] = "Grazie, {name}. A Elwynn nessuna gentilezza torna a casa senza risposta."
L["You shame me, {name}; I should have thought of it first. Allow me."] = "Mi hai fatto fare brutta figura, {name}: dovevo pensarci io. Permetti."
L["Heartier than Westfall Stew, {name}, and I've wept over that stew. Thank you."] = "Più ricco dello stufato delle Marche Occidentali, {name}, che mi ha commosso. Grazie."
L["Thank you, {name}. I'll tell Marshal Dughan. He won't care, but I'll tell him."] = "Grazie, {name}. Lo dirò al Maresciallo Dughan. Non gli importerà, ma glielo dirò."
L["Job's done, {name}! My grandad built half of Stormwind saying that. Thanks."] = "Lavoro finito, {name}! Mio nonno ha costruito mezza Roccavento dicendolo. Grazie."
L["Lakeshire will finish its bridge before I forget this, {name}. So, never."] = "Borgolago finirà il suo ponte prima che io dimentichi questo, {name}. Cioè mai."
L["Kul Tirans say a kindness goes back on the next tide, {name}. There it goes."] = "A Kul Tiras si dice che una gentilezza torna con la marea, {name}. Eccola che va."
L["Thank you, {name}. Northshire's brothers would call that the Light at work."] = "Grazie, {name}. I confratelli della Contea del Nord direbbero che è opera della Luce."
L["Not since Mum packed my lunches, {name}, have I felt so looked after. Thanks."] = "Nessuno mi coccolava così dai pranzi al sacco della mamma, {name}. Grazie."
L["Into my memoirs, {name}. Chapter nine: 'Everyone Was Lovely'. Thank you."] = "Nelle mie memorie, {name}. Capitolo nove: 'Tutti gentilissimi'. Grazie."
L["I'll toast you at the Pig and Whistle, {name}. Then the pig. Then the whistle."] = "Brinderò a te al Maiale e Fischietto, {name}. Poi al maiale. Poi al fischietto."
L["Of course, {name}. Hold still and look heroic; it helps the bards."] = "Certo, {name}. Resta immobile e fa' la faccia da eroe: aiuta i bardi."
L["Right away, {name}. Keep your shield high."] = "Subito, {name}. Tieni alto lo scudo."
L["More work? Gladly, {name}. It beats the lumber mill."] = "Altro lavoro? Volentieri, {name}. Meglio della segheria."
L["Of course, {name}. Humans excel at helping and overpromising. This is helping."] = "Certo, {name}. Noi umani aiutiamo e promettiamo mari e monti. Questo è l'aiuto."
L["Certainly, {name}. Westfall farm manners: you help first and ask why later."] = "Certo, {name}. Nelle fattorie delle Marche Occidentali si aiuta prima e si chiede dopo."
L["Hold still, {name}, like a statue in the Valley of Heroes. You'd fit right in."] = "Non muoverti, {name}, come una statua nella Valle degli Eroi. Ci staresti bene."
L["Right away, {name}. The Light helps those who ask. So do I, and I'm quicker."] = "Subito, {name}. La Luce aiuta chi chiede. Anch'io, e faccio prima."
L["Sailors' rule, {name}: somebody calls for help, you row. Here."] = "Regola da marinaio, {name}: se qualcuno chiede aiuto, si rema. Ecco."
L["Of course, {name}. Stand up straight; my old sergeant is watching, somewhere."] = "Certo, {name}. Schiena dritta: il mio vecchio sergente ci guarda, da qualche parte."
L["Of course, {name}. A polite request is rarer than a quiet night in Duskwood."] = "Certo, {name}. Chiedere con garbo è più raro di una notte tranquilla a Boscovespro."
L["Right away, {name}. I'll play the Archbishop; you pretend to be impressed."] = "Subito, {name}. Io faccio l'Arcivescovo, tu fai finta di essere colpito."
L["Step out of the shade, {name}; I like to see where I'm aiming."] = "Esci dall'ombra, {name}: mi piace vedere dove miro."
L["Stormwind rose from rubble, {name}. I can manage one {buff}."] = "Roccavento è risorta dalle macerie, {name}. {buff} è una passeggiata."
L["Of course, {name}. Last one I did was a Westfall scarecrow. Long story."] = "Certo, {name}. L'ultimo? Uno spaventapasseri delle Marche Occidentali. Lunga storia."
L["Aye, {name}. Kul Tiran terms: a handshake, and I spare you the shanty."] = "Certo, {name}. Patto kultirano: stretta di mano, e niente canti marinari."
L["The road ahead is long, {name}. This won't shorten it, but it'll help."] = "La strada è lunga, {name}. Questo non la accorcia, ma aiuta."
L["Fair winds and following seas, {name}."] = "Buon vento e mare calmo, {name}."
L["Take this, {name}. Elves have centuries to be generous; I've got fifty years."] = "Prendi, {name}. Gli elfi hanno secoli per essere generosi; io ho cinquant'anni."
L["A little something, {name}. Don't tell the guards; they'll all want one."] = "Un pensierino, {name}. Non dirlo alle guardie, o lo vorranno tutte."
L["Here, {name}. If a kobold asks, you don't have a candle."] = "Tieni, {name}. Se un coboldo te lo chiede, candele non ne hai."
L["For you, {name}. A human gift: well meant, hastily made, surprisingly sturdy."] = "Per te, {name}. Dono umano: buone intenzioni, fatto in fretta, robusto a sorpresa."
L["Mind the murlocs, {name}. Take this; I've seen what they do to a picnic."] = "Occhio ai murloc, {name}. Prendi: ho visto cosa fanno a un picnic."
L["Every road needs a hero, {name}. Today it's me, apparently. Take this."] = "Ogni strada ha bisogno di un eroe, {name}. Oggi tocca a me, pare. Prendi."
L["Stay out of Duskwood after dark, {name}. It's always dark. Take this."] = "Stai lontano da Boscovespro col buio, {name}. È sempre buio. Prendi."
L["Redridge gnolls take anything not nailed down, {name}. This is nailed down."] = "Gli gnoll di Crestarossa rubano tutto quel che non è inchiodato, {name}. Questo lo è."
L["If you meet Hogger, {name}, take this and a friend. Mostly the friend."] = "Se incontri Hogger, {name}, porta questo e un amico. Soprattutto l'amico."
L["The Light and a good pair of boots, {name}. Now you've got one of them."] = "La Luce e un buon paio di stivali, {name}. Ora una delle due ce l'hai."
L["Every hero in Stormwind began with a kindness and a borrowed sword, {name}."] = "Ogni eroe di Roccavento è partito da una gentilezza e una spada prestata, {name}."
L["Here, {name}. The Defias can't steal this one. They've tried everything else."] = "Tieni, {name}. Questo i Defias non possono rubarlo. Tutto il resto, sì."
L["Uther blessed strangers on the road, {name}. I've less hammer, same idea."] = "Uther benediceva i viandanti, {name}. Io ho meno martello, ma l'idea è quella."
L["Take this, {name}. Goldshire custom: no traveller leaves empty-handed."] = "Prendi, {name}. Usanza di Borgodoro: nessun viandante riparte a mani vuote."
L["The wolves in Elwynn look friendly, {name}. They are not. Take this."] = "I lupi di Elwynn sembrano amichevoli, {name}. Non lo sono. Prendi."
L["Arathor's children stand together, {name}."] = "I figli di Arathor restano uniti, {name}."
L["A fellow human, {name}! Quick, let's found a kingdom before lunch."] = "Tra umani, {name}! Presto, fondiamo un regno prima di pranzo."
L["Stormwind or Boralus, {name}, we'll both complain about the weather."] = "Roccavento o Boralus, {name}, ci lamenteremo comunque del tempo."
L["Human to human, {name}: no, I don't know why everything happens to us either."] = "Da umano a umano, {name}: no, non so neanch'io perché capitano tutte a noi."
L["Short lives, long to-do lists, {name}. We humans must help each other along."] = "Vita breve, lista delle cose da fare lunghissima, {name}. Tra umani ci si aiuta."
L["Stormwind stone or Kul Tiran oak, {name}, we outlast everyone's expectations."] = "Pietra di Roccavento o quercia kultirana, {name}: duriamo più del previsto."
L["Humans stick together, {name}. Everyone else is taller, older or furrier."] = "Noi umani restiamo uniti, {name}. Gli altri sono più alti, vecchi o pelosi."
L["Our lot built half the world on bread, stubbornness and bad luck, {name}."] = "La nostra gente ha fatto mezzo mondo con pane, testardaggine e sfortuna, {name}."
L["Don't tell the dwarves, {name}, but it was us humans who invented the tavern."] = "Non dirlo ai nani, {name}, ma l'osteria l'abbiamo inventata noi umani."
L["Keep close, {name}. Humans have always won by outnumbering things."] = "Stammi vicino, {name}. Gli umani vincono da sempre perché sono di più."
L["Stay in formation, {name}. We haven't got one, but stay in it anyway."] = "Mantieni la formazione, {name}. Non ne abbiamo una, ma mantienila lo stesso."
L["I'll draw up a plan, {name}, and then we can all ignore it together."] = "Preparo un piano, {name}, così poi possiamo ignorarlo tutti insieme."
L["Every hero in the songs had friends, {name}. Nobody sings about them. I will."] = "Ogni eroe delle ballate aveva degli amici, {name}. Nessuno li canta. Io sì."
L["Shields up, {name}. Stormwind taught me to march; nobody taught me to stop."] = "Scudi alzati, {name}. Roccavento mi ha insegnato a marciare; a fermarmi, nessuno."
L["If this goes badly, {name}, we regroup at the nearest inn. Human tactics."] = "Se va male, {name}, ci raduniamo alla locanda più vicina. Tattica umana."
L["I've made us a flag, {name}. It's a handkerchief on a stick, but it's ours."] = "Ci ho fatto una bandiera, {name}. È un fazzoletto su un bastone, ma è nostra."
L["Keep a torch lit, {name}. Humans can't see in the dark, and we hate it."] = "Tieni accesa una torcia, {name}. Noi umani al buio non vediamo, e lo odiamo."
L["Watch my back, {name}; I'll watch yours. The Light has the rest. Better view."] = "Guardami le spalle, {name}, io guardo le tue. Al resto pensa la Luce: vede meglio."
L["Humans always rise to the occasion, {name}. Usually after tripping over it."] = "Gli umani colgono sempre l'occasione, {name}. Di solito inciampandoci sopra."
L["Do this well, {name}. Some elf will be telling the story for a thousand years."] = "Facciamolo bene, {name}. Qualche elfo lo racconterà per mille anni."
L["Farmers, sailors, bakers, {name}: every army Stormwind ever raised. Onward!"] = "Contadini, marinai, fornai, {name}: ogni esercito di Roccavento. Avanti!"
L["Ishnu-alah, {name}. Returned the same day, which for a kaldorei is rushing."] = "Ishnu-alah, {name}. Ricambio in giornata: per un kaldorei è andare di corsa."
L["Thank you, {name}. Elune smiles on the generous."] = "Grazie, {name}. Elune sorride a chi è generoso."
L["Thank you, {name}. Even the wisps glow brighter, and they're hard to impress."] = "Grazie, {name}. Anche i fuochi fatui brillano di più, e non è facile stupirli."
L["Elune saw that, {name}. She sees everything, so I had best return it."] = "Elune ha visto, {name}. Lei vede tutto, quindi meglio che ricambi."
L["Thank you, {name}. Kindness planted, kindness grown. Here."] = "Grazie, {name}. Gentilezza seminata, gentilezza raccolta. Tieni."
L["Thank you, {name}. The Ancients will hear of this. They're dreadful gossips."] = "Grazie, {name}. Gli Antichi lo verranno a sapere. Sono dei gran pettegoli."
L["Thank you, {name}. I'll tell the Sentinels to stop aiming at you."] = "Grazie, {name}. Dirò alle Sentinelle di smettere di prenderti di mira."
L["My people never hurry, {name}. For you, an exception."] = "Il mio popolo non ha fretta, {name}. Per te, un'eccezione."
L["Ande'thoras-ethil, {name}. May your troubles be diminished, as mine just were."] = "Ande'thoras-ethil, {name}. Che i tuoi affanni si riducano, come i miei ora."
L["We gave up immortality at Hyjal, {name}. Kindness has been worth double since."] = "Sul Monte Hyjal perdemmo l'immortalità, {name}. Da allora la gentilezza vale doppio."
L["My ears have gone a shade darker, {name}. Kaldorei blush there first."] = "Mi si sono scurite le orecchie, {name}. Noi kaldorei arrossiamo prima lì."
L["Azshara's court never gave a thing away, {name}. You've outdone a queen."] = "La corte di Azshara non regalava mai niente, {name}. Hai battuto una regina."
L["The owls turned their heads for that, {name}. All the way round. High praise."] = "I gufi si sono girati a guardare, {name}. Di trecentosessanta gradi. Gran complimento."
L["I outlived the Sundering, {name}. I'll not outlive a debt to you. Here."] = "Ho visto il mondo spaccarsi, {name}. Un debito con te durerà molto meno. Tieni."
L["All those centuries of memories, {name}, and this one goes near the front."] = "Secoli di ricordi, {name}, e questo va in prima fila."
L["I'll tell the moon about you tonight, {name}. She likes a good story."] = "Stanotte parlerò di te alla luna, {name}. Ama le belle storie."
L["Gladly, {name}. Be still, and let the moonlight find you."] = "Con gioia, {name}. Resta immobile e lascia che la luna ti trovi."
L["Of course, {name}. Elune's blessings are meant to be shared."] = "Certo, {name}. Le benedizioni di Elune vanno condivise."
L["At last, {name}! I've waited ten thousand years for someone to ask."] = "Finalmente, {name}! Sono diecimila anni che aspetto che qualcuno chieda."
L["No riddle, no omen from Elune, {name}. Just a plain yes, for once."] = "Niente enigmi, niente presagi di Elune, {name}. Solo un sì, per una volta."
L["Of course, {name}. Ask in Darnassian next time and I'll add a bow."] = "Certo, {name}. Chiedilo in darnassiano e ci aggiungo un inchino."
L["Elune already said yes, {name}. I'm merely catching up."] = "Elune ha già detto di sì, {name}. Io mi sto solo adeguando."
L["Of course, {name}. Stand still and pretend you're a tree. It helps."] = "Certo, {name}. Resta immobile e fingi di essere un albero. Aiuta."
L["Step into the light, {name}. The last kaldorei I did this for Shadowmelded."] = "Spostati alla luce, {name}: l'ultimo kaldorei che ho aiutato si è fuso con l'ombra."
L["Certainly, {name}. Ask a kaldorei anything, except how old we are."] = "Certo, {name}. A un kaldorei puoi chiedere tutto, tranne l'età."
L["In Darnassus, {name}, this takes a moonwell and a priestess. Out here, just me."] = "A Darnassus, {name}, servirebbero un pozzo lunare e una sacerdotessa. Qui, basto io."
L["The last army to ask me for help was fighting demons, {name}. You're politer."] = "L'ultimo esercito a chiedermi aiuto combatteva demoni, {name}. Tu hai più garbo."
L["Gladly, {name}. Consider it on loan from Elune. She's never once collected."] = "Con gioia, {name}. Consideralo un prestito di Elune. Non ha mai riscosso."
L["One moment, {name}. My hair is older than most kingdoms, and it tangles."] = "Un attimo, {name}. I miei capelli sono più vecchi di molti regni, e si annodano."
L["Darnassian has nine words for 'yes', {name}. I'll spare you eight of them."] = "Il darnassiano ha nove parole per dire 'sì', {name}. Te ne risparmio otto."
L["Of course, {name}. The Sentinels would want a password. I'll accept 'please'."] = "Certo, {name}. Le Sentinelle vorrebbero la parola d'ordine. A me basta 'per favore'."
L["Elune-adore, {name}. Walk softly; the trees are light sleepers."] = "Elune-adore, {name}. Cammina lieve: gli alberi hanno il sonno leggero."
L["May the forest shelter you, {name}, wherever you roam."] = "Che la foresta ti protegga, {name}, ovunque tu vada."
L["A gift from the shadows, {name}. No, don't look. You won't find me."] = "Un dono dalle ombre, {name}. No, non guardarti intorno. Non mi troverai."
L["Elune lights your path, {name}. I'm merely holding the lantern."] = "Elune illumina il tuo cammino, {name}. Io reggo solo la lanterna."
L["The owls pointed you out, {name}. They have strong opinions. Here."] = "I gufi mi hanno indicato te, {name}. Hanno le idee chiare. Tieni."
L["Tyrande would insist, {name}, and nobody argues with Tyrande."] = "Tyrande insisterebbe, {name}, e nessuno discute con Tyrande."
L["Take this, {name}. The last one went to a hippogryph. It was less grateful."] = "Prendi, {name}. L'ultimo è andato a un ippogrifo. È stato meno riconoscente."
L["Mind the wildlife, {name}. Half of it is a druid, and all of it is watching."] = "Occhio alla fauna, {name}. Metà sono druidi, e tutti ti osservano."
L["Walk with Elune, {name}. If she's busy, walk with this."] = "Cammina con Elune, {name}. Se è impegnata, cammina con questo."
L["Mind the satyrs, {name}. They were Highborne once. You can tell by the sneer."] = "Occhio ai satiri, {name}. Un tempo erano nobili di corte: si vede dal ghigno."
L["The trees spoke well of you, {name}. I thought I'd add my word."] = "Gli alberi parlano bene di te, {name}. Ci aggiungo la mia."
L["Most furbolgs are friendly, {name}. This is for the other ones."] = "Quasi tutti i furbolg sono amichevoli, {name}. Questo è per gli altri."
L["Moonwell water would be better, {name}, but it travels badly. This doesn't."] = "L'acqua di un pozzo lunare sarebbe meglio, {name}, ma viaggia male. Questo no."
L["A gift from Teldrassil, {name}. It's a long way down; I nearly dropped it."] = "Un dono da Teldrassil, {name}. È lunga la discesa: per poco non mi cadeva."
L["I'd stay to chat, {name}, but kaldorei chats run to the next full moon. Here."] = "Chiacchiererei, {name}, ma tra kaldorei si arriva alla prossima luna piena. Tieni."
L["Bandu thoribas, {name}: prepare to fight. There. Now you're prepared."] = "Bandu thoribas, {name}: preparati a combattere. Ecco, ci ho pensato io."
L["From the kaldorei, the moon and a very old tree, {name}. Mostly from me."] = "Dai kaldorei, dalla luna e da un albero molto antico, {name}. Soprattutto da me."
L["Ishnu-alah, {name}. Elune keeps her children close."] = "Ishnu-alah, {name}. Elune tiene vicini i suoi figli."
L["Of course I saw you, {name}. It takes a kaldorei to spot a kaldorei."] = "Certo che ti ho visto, {name}. Solo un kaldorei scova un kaldorei."
L["Kaldorei to kaldorei, {name}: we gave up eternity, not each other."] = "Da kaldorei a kaldorei, {name}: abbiamo rinunciato all'eternità, non l'uno all'altro."
L["A kaldorei never leaves kin in the dark, {name}. Unless it's for cover."] = "Un kaldorei non lascia i suoi al buio, {name}. Salvo per nascondersi."
L["Two kaldorei, {name}, and still no helmet made that fits either pair of ears."] = "Due kaldorei, {name}, quattro orecchie, e ancora nessun elmo che le contenga."
L["Sentinel, druid or simply stubborn, {name}? I'm all three on a good night."] = "Sentinella, druido o testa dura, {name}? Nelle notti buone io sono tutti e tre."
L["Between us, {name}, twenty thousand years of telling everyone 'we tried that'."] = "Tra noi due, {name}, ventimila anni a dire a tutti 'già provato, non funziona'."
L["Let's Shadowmeld together sometime, {name}, and see who notices."] = "Un giorno svaniamo nell'ombra insieme, {name}. Vediamo chi se ne accorge."
L["Our shan'do sleeps in the Dream, {name}. Let's make his waking worth it."] = "Il nostro shan'do dorme nel Sogno, {name}. Che al risveglio ne valga la pena."
L["Our people are thin on the ground, {name}, and very thick in the trees."] = "Siamo pochi sul terreno, {name}, e fittissimi tra i rami."
L["Quick one, {name}? By kaldorei reckoning we'll be done before we start."] = "Una cosa veloce, {name}? Per un kaldorei, finiamo prima di cominciare."
L["I'll be the one you can't see, {name}. That's not a mistake; that's the plan."] = "Io sarò l'ombra che non vedi, {name}. Non è un errore: è il piano."
L["Elune watches the whole party, {name}. I'm just the one who waves at her."] = "Elune veglia su tutto il gruppo, {name}. Io mi limito a salutarla."
L["Ten thousand years of companions, {name}. You lot rank rather high."] = "In diecimila anni di compagni, {name}, voi siete in zona podio."
L["Stay close, {name}. We misplaced half a continent once. Not you, though."] = "Stammi vicino, {name}. Una volta abbiamo perso mezzo continente. Te no, però."
L["If I fall, {name}, don't fret. I'll float about as a wisp, looking wise."] = "Se cado, {name}, niente ansia. Fluttuerò come un fuoco fatuo, con aria saggia."
L["I fought beside Neltharion once, {name}. You're already a better ally."] = "Ho combattuto al fianco di Neltharion, {name}. Come alleato, tu sei già meglio."
L["Follow me, {name}. I know these paths. They were a forest last time, mind."] = "Seguimi, {name}. Conosco questi sentieri. L'ultima volta erano una foresta."
L["Should we fail, {name}, I'll remember you fondly for several thousand years."] = "Se falliamo, {name}, ti ricorderò con affetto per qualche migliaio d'anni."
L["I've watched heroes charge in blind for millennia, {name}. Let's try eyes open."] = "Da millenni vedo eroi caricare alla cieca, {name}. Proviamo a occhi aperti."
L["If anyone asks, {name}, we were always this good."] = "Se qualcuno chiede, {name}, l'abbiamo sempre fatto così bene."
L["I'll take first watch, {name}. And second. A kaldorei barely notices a night."] = "Primo turno di guardia a me, {name}. Anche il secondo: a un kaldorei una notte vola."
L["The moon's up, {name}. For a kaldorei, this is the middle of the morning."] = "È sorta la luna, {name}. Per un kaldorei è metà mattina."
L["Everyone sensible is asleep, {name}. Elune and I prefer it this way."] = "Le persone assennate dormono, {name}. Elune e io preferiamo così."
L["Elune's light is on you, {name}. Here's a second layer."] = "La luce di Elune è su di te, {name}. Eccone un secondo strato."
L["Dark at last, {name}. Now I see perfectly and everything else has to guess."] = "Finalmente buio, {name}. Ora io vedo benissimo, e gli altri tirano a indovinare."
L["Same stars I saw ten thousand years ago, {name}. They've aged better than me."] = "Le stesse stelle di diecimila anni fa, {name}. Sono invecchiate meglio di me."
L["Moonrise, {name}. Every kaldorei just woke up a little, and got a little smug."] = "Sorge la luna, {name}: ogni kaldorei si sveglia un po', e si dà un po' di arie."
L["Morning, {name}. My people slept through these for millennia. I'm adapting."] = "Per millenni il mio popolo ha dormito a quest'ora, {name}. Mi sto adattando."
L["Dawn, {name}. Elune's gone to bed, so I'm covering for her."] = "Alba, {name}. Elune è andata a letto: la copro io."
L["The sun's up, {name}, and so, reluctantly, am I."] = "Il sole si è alzato, {name}, e io con lui. Controvoglia."
L["Too bright, {name}. I'll squint through this one; Elune forgives squinting."] = "Troppa luce, {name}. Andrò avanti a occhi socchiusi: Elune perdona."
L["Daybreak, {name}: the one hour a night elf is easy to spot. Quick, take this."] = "L'alba, {name}: l'unica ora in cui un elfo della notte si vede bene. Presto, prendi."
L["Up early, {name}? I'm up late. Let's meet in the middle, with this."] = "Tu in piedi presto, {name}, io tardi. Incontriamoci a metà, con questo."
L["The shadows remember kindness, {name}. So do I."] = "Le ombre ricordano la gentilezza, {name}. E anch'io."
L["My thanks, {name}. The ren'dorei do not forget a kindness."] = "Ti ringrazio, {name}. I ren'dorei non dimenticano una gentilezza."
L["Thank you, {name}. The voices approve of you, which is frankly alarming."] = "Grazie, {name}. Le voci ti approvano, il che è francamente allarmante."
L["Thank you, {name}. Few give gifts to someone who glows this ominously."] = "Grazie, {name}. Pochi fanno doni a chi brilla in modo così inquietante."
L["Kindness is rare in the Void, {name}. I'll return yours before it notices."] = "La gentilezza è rara nel Vuoto, {name}. Ricambio la tua prima che se ne accorga."
L["Silvermoon threw us out, {name}. People like you make it hard to mind."] = "Lunargenta ci ha cacciati, {name}. Con gente come te, è difficile rimpiangerla."
L["Returned in full, {name}. It may be slightly purple. That's normal."] = "Ricambiato per intero, {name}. Potrebbe essere un po' viola. È normale."
L["The Void only takes, {name}. I, however, give back."] = "Il Vuoto prende e basta, {name}. Io, invece, restituisco."
L["Thank you, {name}. The whispers went quiet. That's how I know it was sincere."] = "Grazie, {name}. I sussurri si sono zittiti. Così so che era sincero."
L["Thank you, {name}. I'd smile, but people say it's unsettling. So: imagine one."] = "Grazie, {name}. Sorriderei, ma dicono che inquieta. Quindi: immaginalo."
L["Returned, {name}: cold hands, warm intentions. That's us in a sentence."] = "Ricambiato, {name}: mani fredde, cuore caldo. Noi ren'dorei in una frase."
L["Returned, {name}. You may hear it twice; my spells echo now."] = "Ricambiato, {name}. Se ti arriva due volte, è l'eco del Vuoto."
L["The Void offered me forbidden knowledge, {name}. Yours was the nicer gift."] = "Il Vuoto mi ha offerto conoscenze proibite, {name}. Il tuo dono era più carino."
L["Alleria says the Void can be mastered, {name}. Kindness, I find, is easier."] = "Per Alleria il Vuoto si può domare, {name}. La gentilezza, per me, è più facile."
L["Much obliged, {name}. Most people give us a wide berth. You gave me this."] = "Grazie, {name}. La gente di solito ci dà le spalle. Tu mi hai dato questo."
L["Thank you, {name}. My shadow bowed as well. It never does. You've impressed it."] = "Grazie, {name}. Si è inchinata anche la mia ombra. Non lo fa mai. L'hai colpita."
L["As you wish, {name}. The shadows answer kindly today."] = "Come desideri, {name}. Oggi le ombre sono benevole."
L["Consider it done, {name}. The Void obeys us, not the other way round."] = "Consideralo fatto, {name}. Il Vuoto obbedisce a noi, non il contrario."
L["Certainly, {name}. The whispers said no, so it's an easy yes."] = "Certo, {name}. I sussurri hanno detto di no, quindi è un sì facile."
L["Of course, {name}. One {buff}, lightly seasoned with the Void."] = "Certo, {name}. Ecco {buff}, con Vuoto quanto basta."
L["Of course, {name}. Hold still; the shadows are shy with strangers."] = "Certo, {name}. Non muoverti: le ombre sono timide con gli sconosciuti."
L["Gladly, {name}. Ren'dorei manners: the Void waits its turn."] = "Volentieri, {name}. Galateo ren'dorei: il Vuoto fa la fila."
L["Asked so nicely, {name}? Then you'll have my best."] = "Con tanta gentilezza, {name}? Allora avrai il meglio di me."
L["Of course, {name}. Stand in the light, please; the Void gets ideas in corners."] = "Certo, {name}. Stai alla luce, ti prego: negli angoli il Vuoto si fa idee strane."
L["Of course, {name}. The Void asked why. I said 'manners'. It's still puzzled."] = "Certo, {name}. Il Vuoto chiede perché. Io: 'buone maniere'. È ancora perplesso."
L["Gladly, {name}. Nobody asks us for anything but 'please stop whispering'."] = "Volentieri, {name}. A noi chiedono solo 'per favore, smettila di sussurrare'."
L["Happy to, {name}. Just let me finish arguing with myself. There. I won."] = "Con piacere, {name}. Finisco di litigare con me... Ecco. Ho vinto io."
L["Certainly, {name}. I could rift over there first, but that feels showy."] = "Certo, {name}. Potrei aprire un varco fin lì, ma sarebbe esibizionismo."
L["Asking questions got us exiled, {name}. Answering one is quite safe, I'm told."] = "Fare domande ci è costato l'esilio, {name}. Rispondere, dicono, è sicuro."
L["Of course, {name}. A slight chill and a faint chorus are both perfectly normal."] = "Certo, {name}. Un lieve brivido e un coro lontano sono del tutto normali."
L["A touch of shadow for you, {name}. Quite safe. Mostly."] = "Un tocco d'ombra per te, {name}. Del tutto sicuro. Quasi."
L["Walk carefully in the dark places, {name}."] = "Cammina con cautela nei luoghi oscuri, {name}."
L["A little something from the Telogrus Rift, {name}. It's cleaner than it sounds."] = "Un pensierino dalla Faglia di Telogrus, {name}. È più pulito di quanto sembri."
L["Take this, {name}. Any tentacles you see are purely decorative."] = "Prendi, {name}. Eventuali tentacoli sono puramente decorativi."
L["The shadows asked after you, {name}. I told them to mind their manners."] = "Le ombre hanno chiesto di te, {name}. Ho detto loro di comportarsi bene."
L["Here, {name}. We walked into the Void so you wouldn't have to."] = "Tieni, {name}. Siamo entrati nel Vuoto perché tu non dovessi farlo."
L["I checked your shadow, {name}. Nothing lurking. Take this anyway."] = "Ho controllato la tua ombra, {name}. Nessuno in agguato. Prendi comunque."
L["Umbric sends his regards, {name}. He doesn't, but he would."] = "Umbric ti manda i suoi saluti, {name}. Non è vero, ma lo farebbe."
L["Take this, {name}. It may whisper a compliment. Pretend you didn't hear."] = "Prendi, {name}. Potrebbe sussurrarti un complimento. Fai finta di niente."
L["Here, {name}. Looks sinister, works beautifully. Rather like me."] = "Tieni, {name}. Sembra sinistro, funziona a meraviglia. Un po' come me."
L["Take this, {name}. The Void had worse in mind for you. I intercepted."] = "Prendi, {name}. Il Vuoto aveva in serbo di peggio per te. L'ho intercettato."
L["If the dark whispers at you today, {name}, pay it no mind. Take this."] = "Se oggi il buio ti sussurra, {name}, non dargli retta. Tieni."
L["Here, {name}. We ren'dorei don't often get to be the nice surprise."] = "Tieni, {name}. Non capita spesso che noi ren'dorei siamo la bella sorpresa."
L["I left Quel'Thalas with only a knack for the dark, {name}. Here's the knack."] = "Da Quel'Thalas me ne andai col solo talento per il buio, {name}. Eccotelo."
L["Here, {name}. Don't thank the shadows; they'll only want something. Thank me."] = "Tieni, {name}. Non ringraziare le ombre: poi vogliono qualcosa. Ringrazia me."
L["I owe a kindness for every ominous look I've given, {name}. I'm badly behind."] = "Devo una gentilezza per ogni occhiata sinistra, {name}. Sono parecchio in arretrato."
L["We ren'dorei look after our own, {name}."] = "Noi ren'dorei ci prendiamo cura dei nostri, {name}."
L["Silvermoon's loss, {name}. We're doing splendidly without it."] = "Peggio per Lunargenta, {name}. Senza di lei ce la passiamo benissimo."
L["Your whispers and mine should really meet sometime, {name}."] = "I tuoi sussurri e i miei dovrebbero conoscersi, prima o poi, {name}."
L["Two ren'dorei in one place, {name}. Quick, look brooding. It's expected."] = "Due ren'dorei insieme, {name}. Presto, aria tenebrosa: se l'aspettano tutti."
L["Nobody else understands the hair, {name}. It was blond once. I think."] = "Nessun altro capisce i capelli, {name}. Un tempo erano biondi. Credo."
L["Telogrus felt like home in the end, {name}. A very draughty, very dark home."] = "Alla fine Telogrus è diventata casa, {name}. Una casa buia e piena di spifferi."
L["Ren'dorei to ren'dorei, {name}: what's yours whispering? Mine's on about soup."] = "Da ren'dorei a ren'dorei, {name}: il tuo Vuoto cosa sussurra? Il mio? Minestrone."
L["Stay close, {name}. The whispers are much quieter in company."] = "Stammi vicino, {name}. In compagnia i sussurri abbassano la voce."
L["If the shadows start giving orders, {name}, ignore them. I usually do."] = "Se le ombre cominciano a dare ordini, {name}, ignorale. Io di solito lo faccio."
L["Keep an eye on my shadow, {name}. It wanders off when there's a fight."] = "Tieni d'occhio la mia ombra, {name}. Quando c'è da combattere se la svigna."
L["If I start glowing purple, {name}, carry on. It only means I'm keen."] = "Se brillo di viola, {name}, vai avanti. Vuol dire solo che sono in vena."
L["We ren'dorei make fine companions, {name}. We bring our own dark to hide in."] = "Noi ren'dorei siamo ottima compagnia, {name}: il buio ce lo portiamo da casa."
L["If I seem to talk to nobody, {name}, I'm fine. If nobody talks back, worry."] = "Se parlo col nulla, {name}, tutto bene. Se il nulla risponde, preoccupati."
L["I'll open a rift if it goes wrong, {name}. Only for me, sadly. But I'll wave."] = "Se va male, {name}, apro un varco. Solo per me, ahimè. Ma ti saluto con la mano."
L["Try to enjoy this, {name}. We ren'dorei rarely get invited anywhere twice."] = "Godiamocela, {name}. Noi ren'dorei raramente veniamo invitati due volte."
L["Keep the lanterns lit, {name}. I don't need them; the shadows behave better."] = "Tieni accese le lanterne, {name}. A me non servono: le ombre si comportano meglio."
L["Keep an eye on the corners, {name}. I'll keep an eye on what's in them."] = "Tieni d'occhio gli angoli, {name}. Io tengo d'occhio cosa c'è dentro."
L["The Void promised me power, {name}. It never mentioned company this good."] = "Il Vuoto mi promise potere, {name}. Di compagnia così bella non disse nulla."
L["If you hear whispers mid-fight, {name}, they're cheering. For us, I think."] = "Se senti sussurri in combattimento, {name}, fanno il tifo. Per noi, credo."
L["Should anything eldritch turn up, {name}, let me talk to it. I speak a little."] = "Se spunta un orrore indicibile, {name}, ci parlo io. La lingua la mastico un po'."
L["Night suits the ren'dorei, {name}. We match the decor."] = "La notte ci dona, {name}. Siamo in tinta con l'arredo."
L["The shadows are longest now, {name}, and in a very generous mood."] = "Ora le ombre sono più lunghe, {name}, e di umore molto generoso."
L["Late, {name}? The whispers love a late hour. Lately, so do I."] = "È tardi, {name}? I sussurri amano le ore piccole. E ormai anch'io."
L["Midnight, {name}. The one hour my shadow and I agree on anything."] = "Mezzanotte, {name}. L'unica ora in cui io e la mia ombra siamo d'accordo."
L["Stars out, {name}. I've seen what's between them, and I prefer the stars."] = "Ci sono le stelle, {name}. Ho visto cosa c'è in mezzo, e preferisco le stelle."
L["Thanks, {name}! Kindness received, catalogued and returned!"] = "Grazie, {name}! Gentilezza ricevuta, catalogata e restituita!"
L["Reciprocity engaged! Much obliged, {name}."] = "Reciprocità attivata! Grazie mille, {name}."
L["By my calculations, {name}, you're owed exactly one {buff}."] = "Calcoli alla mano, {name}, ti spetta {buff}. Né più né meno."
L["Thanks, {name}! I'd build you a thank-you machine, but it'd explode."] = "Grazie, {name}! Ti costruirei una macchina per dire grazie, ma esploderebbe."
L["Thank you, {name}! Gnomeregan's finest couldn't have timed that better."] = "Grazie, {name}! Nemmeno i migliori di Gnomeregan avrebbero avuto un tempismo simile."
L["You're too kind, {name}! Returning the favour took only four schematics."] = "Troppo gentile, {name}! Ricambiare mi è costato solo quattro schemi."
L["Drat, {name}! I was going to invent gratitude, but you beat me to it."] = "Accidenti, {name}! Stavo per inventare la gratitudine, e mi hai preceduto."
L["Oh, {name}, how kind! My heart's doing that whirring thing again."] = "Oh, {name}, che gentile! Il mio cuore fa di nuovo quel ronzio."
L["Noted in my lab journal, {name}, page four hundred: 'people are lovely'."] = "Annotato sul quaderno di laboratorio, {name}, pag. 400: 'la gente è adorabile'."
L["Splendid, {name}! Returning it at once, before I'm tempted to improve it."] = "Splendido, {name}! Ricambio subito, prima che mi venga voglia di migliorarlo."
L["Thanks, {name}! Kindness is a reversible reaction. I checked. Here's yours."] = "Grazie, {name}! La gentilezza è una reazione reversibile. Verificato. Ecco la tua."
L["My mechanostrider would salute you, {name}, but it only knows falling over."] = "Il mio meccanostrider ti saluterebbe, {name}, ma sa solo cadere."
L["My transporter would've sent this to Gadgetzan, {name}. Hand-delivered instead!"] = "Il mio teletrasporto l'avrebbe spedito a Gadgetzan, {name}. Consegna a mano!"
L["Oh, thank you, {name}! I haven't felt this good since before the troggs."] = "Oh, grazie, {name}! Non stavo così bene da prima dei trogg."
L["I'll name my next invention after you, {name}! It's a very small cannon."] = "Darò il tuo nome alla mia prossima invenzione, {name}! È un cannoncino."
L["Thanks, {name}! Ironforge has been good to us gnomes, and so have you."] = "Grazie, {name}! Forgiardente è stata buona con noi gnomi, e tu pure."
L["You're on my list of favourite people, {name}! It's short. Mostly clockwork."] = "Sei tra le mie persone preferite, {name}! Sono poche. Quasi tutte a orologeria."
L["Request received, {name}! Processing... done!"] = "Richiesta ricevuta, {name}! Elaborazione... fatto!"
L["One upgrade, coming right up, {name}! Stand still for calibration."] = "Un potenziamento in arrivo, {name}! Non muoverti, devo calibrare."
L["Of course, {name}! I built a machine for this. It's in pieces, so: by hand."] = "Certo, {name}! Ho costruito una macchina apposta. È in pezzi, quindi: a mano."
L["Certainly, {name}! Stand on the X. There's no X. Stand anywhere."] = "Certo, {name}! Mettiti sulla X. Non c'è una X. Mettiti dove vuoi."
L["Right away, {name}! Goggles on. Not for you, I just like them."] = "Subito, {name}! Su gli occhialoni. Non servono: mi piacciono e basta."
L["{buff}, {name}? Simple in theory and practice. Suspicious!"] = "{buff}, {name}? Semplice in teoria e in pratica. Sospetto!"
L["Happy to, {name}! Keep hands, feet and eyebrows well clear."] = "Volentieri, {name}! Mani, piedi e sopracciglia ben lontani."
L["Right away, {name}! Stand back three paces. Four. Five. There, perfect."] = "Subito, {name}! Tre passi indietro. Quattro. Cinque. Ecco, perfetto."
L["Happy to, {name}! It beats sorting springs by size. Though that's fun too."] = "Volentieri, {name}! Meglio che smistare molle. Anche se è uno spasso."
L["Excellent request, {name}! No moving parts. I'll try to add some next time."] = "Ottima richiesta, {name}! Zero parti mobili. Rimedierò la prossima volta."
L["Standard model or deluxe, {name}? They're the same. Deluxe sounds nicer."] = "Modello base o deluxe, {name}? Sono identici. Ma deluxe suona meglio."
L["Coming up, {name}! Fresh off the workbench, still warm, only slightly smoking."] = "In arrivo, {name}! Fresco d'officina, ancora caldo, fuma solo un pochino."
L["Approved, {name}! Stamped, signed and filed under 'obviously'."] = "Approvato, {name}! Timbrato, firmato e archiviato sotto 'ovvio'."
L["Of course, {name}! A twist of the gyromatic micro-adjustor... there!"] = "Certo, {name}! Un giro al microregolatore giromatico... ecco!"
L["Gnomes never refuse a problem, {name}. Occasionally we cause them. Here!"] = "Uno gnomo non rifiuta mai un problema, {name}. Al massimo lo inventa. Ecco!"
L["Hold still, {name}, this is perfectly safe. Probably!"] = "Non muoverti, {name}, è perfettamente sicuro. Probabilmente!"
L["Science says you need this, {name}. Who am I to argue?"] = "La scienza dice che ti serve, {name}. Chi sono io per contraddirla?"
L["A small upgrade for you, {name}. No cogs required."] = "Un piccolo potenziamento per te, {name}. Senza ingranaggi."
L["Take it, {name}, I've a spare. I've three spares of everything."] = "Prendi, {name}, ho il ricambio. Ho tre ricambi di tutto."
L["Try this, {name}! Version one had legs. Version two is much better."] = "Prova, {name}! La versione 1.0 aveva le gambe. La 2.0 va molto meglio."
L["The High Tinker says share our genius, {name}. Here's a sample!"] = "Il Gran Meccanista vuole genio condiviso, {name}. Eccone un assaggio!"
L["Gnomeregan Forever, {name}! This lasts rather less, but it's free."] = "Gnomeregan per sempre, {name}! Questo dura un po' meno, ma è gratis."
L["I'm small, {name}, but my gifts come full-sized. Here!"] = "Io sono tascabile, {name}, i miei doni no. Ecco!"
L["Don't worry, {name}! It worked on the chicken, and the chicken's thrilled."] = "Niente paura, {name}! Sul pollo ha funzionato, e il pollo è entusiasta."
L["Field notes say it works on everyone, {name}. Let's make it unanimous!"] = "Gli appunti sul campo dicono che funziona su tutti, {name}. Facciamo l'unanimità!"
L["One size fits all, {name}, gnome to tauren. I measured. The tauren was patient."] = "Taglia unica, {name}, da gnomo a tauren. Ho misurato. Il tauren è stato un santo."
L["Take this, {name}! Unlike my Net-o-Matic, it never lands on me."] = "Prendi, {name}! Il mio lanciareti mi finisce addosso, questo mai."
L["The Gnomish Army Knife does twelve things badly, {name}. This does one well."] = "Il coltellino gnomico fa dodici cose male, {name}. Questo ne fa una bene."
L["Guarantee void if exposed to troggs, dragonfire or enthusiasm, {name}. Enjoy!"] = "Garanzia nulla in caso di trogg, fuoco di drago o entusiasmo, {name}. Goditelo!"
L["Nothing up my sleeves, {name}! Well, a spanner and two fuses. Nothing sinister."] = "Niente nelle maniche, {name}! Be', una chiave inglese e due micce. Innocue."
L["Here, {name}! It's small, but so is a keystone, and look what those hold up."] = "Ecco, {name}! È piccolo, ma anche la chiave di volta, e guarda cosa regge."
L["I'd explain how it works, {name}, but that takes three days and a chalkboard."] = "Ti spiegherei come funziona, {name}, ma servono tre giorni e una lavagna."
L["If you hear ticking, {name}, that's my pocket watch. Almost certainly."] = "Se senti ticchettare, {name}, è il mio orologio. Quasi di sicuro."
L["For Gnomeregan, {name}! Always nice to talk to somebody at eye level."] = "Per Gnomeregan, {name}! Che bello parlare con qualcuno alla mia altezza."
L["A fellow gnome, {name}! I'll hold the schematic; you hold the bucket."] = "Tra gnomi, {name}! Io tengo lo schema, tu tieni il secchio."
L["Flesh or cogs, {name}, we're all gnomes. Some of us just need oiling."] = "Carne o ingranaggi, {name}, siamo tutti gnomi. Solo, qualcuno va oliato."
L["One gnome to another, {name}: you did turn the reactor off, didn't you?"] = "Da gnomo a gnomo, {name}: il reattore l'hai spento, vero?"
L["Two gnomes, {name}! Stacked up, we're very nearly a night elf."] = "Due gnomi, {name}! In pila, facciamo quasi un elfo della notte."
L["You check my sums, {name}, I check yours, and we're both quietly offended."] = "Tu controlli i miei conti, {name}, io i tuoi, e ci offendiamo in silenzio."
L["You still owe me a sprocket, {name}. Every gnome owes me a sprocket."] = "Mi devi ancora un pignone, {name}. Tutti gli gnomi mi devono un pignone."
L["One day, {name}, we'll walk back into Gnomeregan together. With the lights on."] = "Un giorno, {name}, torneremo insieme a Gnomeregan. Con le luci accese."
L["Between gnomes, {name}: we both know it'll explode, and we both want to watch."] = "Tra gnomi, {name}: sappiamo che esploderà, e nessuno dei due vuole perderselo."
L["Shall we build something huge, {name}? Just to see the tall folk's faces?"] = "Costruiamo qualcosa di enorme, {name}? Per vedere la faccia degli spilungoni."
L["Party-wide calibration complete, {name}! Nobody touch anything shiny."] = "Gruppo calibrato, {name}! Nessuno tocchi niente che luccica."
L["I've run the numbers, {name}: with you here, we win. I rounded up."] = "Ho fatto i calcoli, {name}: con te qui, vinciamo. Ho arrotondato per eccesso."
L["If I shout 'duck', {name}, don't look for a duck. That went badly last time."] = "Se grido 'Bomba!', {name}, non è un complimento. L'ultima volta è finita male."
L["Formation, {name}: tall folk at the front, me somewhere safe and clever."] = "Formazione, {name}: gli alti davanti, io in un punto sicuro e geniale."
L["Everyone gets one, {name}! Standardised parts are the secret of a good machine."] = "Uno per tutti, {name}! I pezzi standard sono il segreto di una buona macchina."
L["My plan, {name}: step one, survive. Step two is still in development."] = "Il piano, {name}: fase uno, sopravvivere. Fase due: in fase di sviluppo."
L["Don't panic, {name}. Whatever goes wrong, I'll have a gadget for it. Next week."] = "Niente panico, {name}. Per ogni guaio avrò l'aggeggio giusto. Da martedì."
L["If I vanish, {name}, check under the nearest boot. Politely, please."] = "Se sparisco, {name}, guarda sotto lo stivale più vicino. Con garbo."
L["When this is over, {name}, I want samples. Of everything. The big one first."] = "Finito qui, {name}, voglio dei campioni. Di tutto. Prima quello grosso."
L["Every explosion today, {name}, is on purpose. I'll decide which ones later."] = "Oggi ogni esplosione è voluta, {name}. Quali, lo decido dopo."
L["Clipboard ready, {name}! Today I'm writing down everyone's heroics."] = "Taccuino pronto, {name}! Oggi annoto le gesta di tutti."
L["If we get separated, {name}, follow the smoke. It'll be me."] = "Se ci perdiamo, {name}, segui il fumo. Sarò io."
L["Everyone keep their fingers, {name}. I've counted. I'll count again after."] = "Nessuno perda le dita, {name}. Le ho contate. Le riconto dopo."
L["Morning, {name}! Up since three. The toaster needed a new engine."] = "Buongiorno, {name}! In piedi dalle tre: il tostapane voleva un motore nuovo."
L["Good morning, {name}! The coffee's brewing itself. It learned how. Worrying."] = "Buongiorno, {name}! La moka si fa il caffè da sola. Ha imparato. Preoccupante."
L["Early start, {name}! Best ideas come before breakfast. So do the explosions."] = "Di buon'ora, {name}! Le idee migliori vengono prima di colazione. E le esplosioni."
L["Morning, {name}! Tinker Town's been clanking since dawn, and so have I. Here!"] = "Buongiorno, {name}! Le officine di Forgiardente sferragliano dall'alba, e io con loro. Tieni!"
L["Up early, {name}? I dreamt of a better sprocket and couldn't wait. Here!"] = "Già in piedi, {name}? Ho sognato un pignone perfetto, non resistevo. Ecco!"
L["Morning, {name}! The sun's a bit dim today. I've been meaning to fix that."] = "Buongiorno, {name}! Il sole oggi è un po' fioco. Prima o poi lo aggiusto."
L["The Light rewards kindness, {name}. I'm simply its fastest courier."] = "La Luce premia la gentilezza, {name}. Io consegno: corriere espresso."
L["Archenon poros, {name}. Your gift is returned."] = "Archenon poros, {name}. Ricambio il tuo dono."
L["Thanks, {name}. I'd offer a lift in the Exodar, but you've seen how it lands."] = "Grazie, {name}. Ti darei un passaggio sull'Exodar, ma hai visto come atterra."
L["A gift freely given, {name}. The naaru hum a little louder. Returned."] = "Un dono fatto col cuore, {name}. I Naaru ronzano un po' più forte. Ricambiato."
L["Kindly done, {name}. On Argus we'd have carved that in crystal. Here."] = "Gentile davvero, {name}. Su Argus l'avremmo inciso nel cristallo. Tieni."
L["Across a dozen worlds, {name}, kindness is the one tongue I never had to learn."] = "Dodici mondi, {name}, e la gentilezza è l'unica lingua che non ho dovuto imparare."
L["What a kindness, {name}. It almost makes up for the Legion. Almost."] = "Che gentilezza, {name}. Quasi mi ripaga della Legione. Quasi."
L["Thank you, {name}. I'd say it in Draenei, but that takes eleven minutes."] = "Grazie, {name}. Lo direi in draenei, ma ci vogliono undici minuti."
L["Thank you, {name}. My people call that a debt of honour. Here."] = "Grazie, {name}. Il mio popolo lo chiama debito d'onore. Tieni."
L["Sargeras once offered my people gifts, {name}. We ran. Yours, I'll keep."] = "Sargeras offrì dei doni al mio popolo, {name}. Fuggimmo. Il tuo lo tengo."
L["Thank you, {name}. I've fled demons across the stars, but never from a debt."] = "Grazie, {name}. Ho seminato demoni per tutte le stelle, mai un creditore."
L["Thank you, {name}. I'll add you to my prayers. The list goes back to Argus."] = "Grazie, {name}. Ti aggiungo alle mie preghiere. L'elenco parte da Argus."
L["The Legion took a world from us, {name}. Folk like you keep giving bits back."] = "La Legione ci tolse un mondo, {name}. Gente come te ce lo ridà a pezzetti."
L["You gave first, {name}. A prophet would call it an omen. I call it manners."] = "Il primo dono è tuo, {name}. Un profeta direbbe: presagio. Io: buone maniere."
L["With the Light's compliments, {name}. It asked me to add 'nicely done'."] = "Con i complimenti della Luce, {name}. E mi fa aggiungere: 'ben fatto'."
L["Of course, {name}. The naaru guide your steps; this puts a spring in them."] = "Certo, {name}. I Naaru guidano i tuoi passi; questo li rende più leggeri."
L["Gladly, {name}. The Light answers those who ask."] = "Con piacere, {name}. La Luce risponde a chi chiede."
L["Velen foresaw you asking, {name}. I foresaw saying yes."] = "Velen previde la tua richiesta, {name}. Io previdi il sì."
L["The Light is not rationed, {name}. Take as much as you like."] = "La Luce non è razionata, {name}. Prendine quanta ne vuoi."
L["Of course, {name}. I've outrun the Burning Legion; I can manage this."] = "Certo, {name}. Ho seminato la Legione Infuocata: questo è un gioco da ragazzi."
L["At once, {name}. Hooves planted, crystals humming, here it comes."] = "Subito, {name}. Zoccoli ben piantati, cristalli in risonanza... ecco!"
L["Gladly, {name}. I followed a talking crystal across the stars. This is easy."] = "Volentieri, {name}. Ho seguito un cristallo parlante tra le stelle. Questo è facile."
L["Certainly, {name}. Velen taught us patience. Luckily, this takes none."] = "Certo, {name}. Velen ci insegnò la pazienza. Per fortuna, qui non serve."
L["Gladly, {name}. The naaru never say no. They say 'hmmm', but it means yes."] = "Volentieri, {name}. I Naaru non dicono mai no: dicono 'mmm', che vuol dire sì."
L["On the Exodar this took three crystals and a prayer, {name}. Here: the prayer."] = "Sull'Exodar servivano tre cristalli e una preghiera, {name}. Ecco: la preghiera."
L["Of course, {name}. I only refuse demons, and they so rarely say please."] = "Certo, {name}. Rifiuto solo i demoni, e chiedono per favore così di rado."
L["Gladly, {name}. We were refugees long enough to know what asking costs."] = "Con piacere, {name}. Da profughi abbiamo imparato quanto costa chiedere."
L["Of course, {name}. My people crossed the stars looking for friends. Found one."] = "Certo, {name}. Il mio popolo solcò le stelle cercando amici. Eccone uno."
L["Ask a draenei, {name}: one yes, one blessing, possibly a history lesson."] = "Chiedi a un draenei, {name}: un sì, una benedizione, forse un corso di storia."
L["The Light is with you, {name}. Go in peace, or at least go prepared."] = "La Luce è con te, {name}. Va' in pace, o almeno con la guardia alta."
L["Walk in the Light, {name}. May it shelter you always."] = "Cammina nella Luce, {name}. Che ti protegga sempre."
L["Take this, {name}. My people always travel Light."] = "Prendi, {name}. Il mio popolo fa tutto alla Luce del sole."
L["Take this, {name}. The Legion is always coming. I'd know."] = "Prendi, {name}. La Legione arriva sempre. Lo so bene."
L["I'm out of miracles today, {name}. Will {buff} do?"] = "Oggi ho finito i miracoli, {name}. Va bene {buff}?"
L["For the road, {name}. Mine has been twenty-five thousand years long."] = "Per il viaggio, {name}. Il mio dura da venticinquemila anni."
L["Blessed by a naaru, {name}. Well, I stood near one. It still counts."] = "Con la benedizione di un Naaru, {name}. Be', ero lì accanto. Conta lo stesso."
L["Take this, {name}. It glows a bit. Everything we own does."] = "Prendi, {name}. Brilla un po'. Come tutto quello che abbiamo."
L["Here, {name}. We draenei pack for the end of the world. We've had the practice."] = "Tieni, {name}. Noi draenei facciamo le valigie per la fine del mondo. Siamo esperti."
L["Take this, {name}. The crystals only hum like that for friends."] = "Prendi, {name}. I cristalli vibrano così solo per gli amici."
L["The naaru shine on all, {name}. Here is your share."] = "I Naaru brillano su tutti, {name}. Ecco la tua parte."
L["A stranger shared bread with me on Azuremyst, {name}. I'm still paying it back."] = "Uno sconosciuto divise il pane con me a Brumazzurra, {name}. Lo sto ancora ripagando."
L["Velen sees a thousand futures, {name}. I see one: you, better prepared. Here."] = "Velen vede mille futuri, {name}. Io ne vedo uno: il tuo, più sicuro. Tieni."
L["Don't drink from the streams on Bloodmyst, {name}. Do take this."] = "Non bere dai ruscelli di Brumacremisi, {name}. Questo invece prendilo."
L["Eredar magic from before the fall, {name}. We only kept the good kind. Here."] = "Magia eredar di prima della caduta, {name}. Solo quella buona. Tieni."
L["Archenon poros, {name}! The children of Argus look after one another."] = "Archenon poros, {name}! I figli di Argus si prendono cura l'uno dell'altro."
L["Home is wherever two draenei meet, {name}. Today, it's here."] = "Casa è ovunque si incontrino due draenei, {name}. Oggi, è qui."
L["We crossed the stars on the same ship, {name}. That still means something."] = "Abbiamo attraversato le stelle sulla stessa nave, {name}. Significa ancora qualcosa."
L["Tails up, {name}. Argus would be proud of what we've made of exile."] = "Coda alta, {name}. Argus sarebbe fiero di ciò che abbiamo fatto dell'esilio."
L["Two draenei, {name}, and between us nearly fifty thousand years of worrying."] = "Due draenei, {name}, e tra noi quasi cinquantamila anni di preoccupazioni."
L["Horns, hooves and hope, {name}. The Legion never found a cure for any of them."] = "Corna, coda e speranza, {name}. Per la Legione, tre mali incurabili."
L["Children of Velen, {name}: exiled, hopeful and dreadfully polite."] = "Figli di Velen, {name}: esuli, fiduciosi e terribilmente educati."
L["Third world's the charm, {name}. We draenei are owed one that stays put."] = "La terza è la volta buona, {name}. Ci spetta un mondo che resti al suo posto."
L["Stay near, {name}. I lost a world once; I'm keeping hold of this party."] = "Stammi vicino, {name}. Ho già perso un mondo: questo gruppo me lo tengo stretto."
L["Twenty-five thousand years on the run, {name}. Walking with friends is nicer."] = "Venticinquemila anni in fuga, {name}. Camminare con gli amici è più bello."
L["The naaru would call this a fellowship, {name}. I call it good luck."] = "I Naaru la chiamerebbero fratellanza, {name}. Io la chiamo fortuna."
L["I've watched worlds end, {name}. Whatever's ahead of us hardly worries me."] = "Ho visto finire dei mondi, {name}. Quello che ci aspetta non mi spaventa."
L["Stay together, {name}. The Light finds us easier when we're all in one place."] = "Restiamo uniti, {name}. La Luce ci trova più facilmente se siamo tutti insieme."
L["Stay close, {name}. We draenei are very good at leaving places in a hurry."] = "Stammi vicino, {name}. Noi draenei siamo bravissimi ad andarcene di corsa."
L["We draenei take the long view, {name}. This fight will be a footnote."] = "Noi draenei guardiamo lontano, {name}. Questo scontro sarà una nota a piè di pagina."
L["Let me go first, {name}. Anything watching will see a very tall optimist."] = "Vado avanti io, {name}. Chi ci osserva vedrà un ottimista molto alto."
L["We draenei follow prophets, {name}. Today I'll settle for following you."] = "Noi draenei seguiamo i profeti, {name}. Oggi mi accontento di seguire te."
L["The Exodar carried thousands, {name}, and this little party still feels safer."] = "L'Exodar ne portava migliaia, {name}, ma questo gruppetto mi pare più sicuro."
L["Shoulder to shoulder, {name}. Mine's a bit higher, but the principle holds."] = "Spalla a spalla, {name}. La mia è un po' più in alto, ma il principio è quello."
L["A short prayer for the party, {name}. The long one would take an age."] = "Una breve preghiera per il gruppo, {name}. Quella lunga durerebbe un'era."
L["Much obliged, {name}. Gilneas never forgets a kindness, and nor does my nose."] = "Grazie infinite, {name}. Gilneas non dimentica una gentilezza. Il mio naso nemmeno."
L["Thank you, {name}. You have my gratitude, and my best howl."] = "Grazie, {name}. Hai la mia gratitudine, e il mio ululato migliore."
L["Thank you, {name}. If worgen had tails, mine would be wagging."] = "Grazie, {name}. Se i worgen avessero la coda, la mia scodinzolerebbe."
L["You've made a friend for life, {name}. Loyalty is rather our thing."] = "Amicizia a vita, {name}. La fedeltà è un po' il nostro forte."
L["The beast in me wants to growl, {name}. The Gilnean in me insists on thanks."] = "La bestia in me vuole ringhiare, {name}. Il gilneano insiste per un grazie."
L["Thank you, {name}. I'd offer a hand, but mine have claws now."] = "Grazie, {name}. Ti darei la mano, ma ora ho gli artigli."
L["We walled ourselves off for years, {name}. You make that look silly."] = "Anni chiusi dietro un muro, {name}. Con te sembra proprio una sciocchezza."
L["Obliged, {name}. You've earned a spot by the fire. The good spot."] = "Grazie, {name}. Ti spetta un posto vicino al fuoco. Quello buono."
L["Thank you, {name}. Gilneas had a word for folk like you: neighbour."] = "Grazie, {name}. A Gilneas c'era una parola per gente come te: vicino."
L["Returned, {name}, with a stiff upper lip. The lower one shows teeth; ignore it."] = "Ricambiato, {name}, senza battere ciglio. Il labbro invece scopre i denti: ignoralo."
L["Thank you, {name}. I'd tip my hat, but it doesn't fit over the ears these days."] = "Grazie, {name}. Mi toglierei il cappello, ma con queste orecchie non entra più."
L["Thank you, {name}. Most folk just scratch my ears and hope for the best."] = "Grazie, {name}. Di solito la gente mi gratta le orecchie e spera in bene."
L["Returned, {name}. A Gilnean pays debts; a worgen pays them at a sprint."] = "Ricambiato, {name}. Un gilneano salda i debiti; un worgen li salda di corsa."
L["My mother would have had you round for tea, {name}. Thank you."] = "Mia madre ti avrebbe offerto il tè, {name}. Grazie."
L["Certainly, {name}. Hold still, I don't bite. Much."] = "Certamente, {name}. Non muoverti, non mordo. Non troppo."
L["Right you are, {name}. Stand steady now."] = "Senz'altro, {name}. Ora non muoverti."
L["Right away, {name}. Stay, now. I've always wanted to say that."] = "Subito, {name}. Resta! Ho sempre sognato di dirlo."
L["Gladly, {name}. Rain or shine, and in Gilneas it's rain."] = "Volentieri, {name}. Pioggia o sole, e a Gilneas è pioggia."
L["Certainly, {name}. Mind the claws."] = "Certo, {name}. Occhio agli artigli."
L["Say no more, {name}. These ears heard you before you'd decided to ask."] = "Basta così, {name}. Le mie orecchie ti hanno sentito prima che tu chiedessi."
L["Of course, {name}. You asked nicer than the last fellow who threw me a stick."] = "Certo, {name}. Più gentile dell'ultimo tizio che mi ha tirato un legnetto."
L["Glad to, {name}. Few people ask a seven-foot wolf for favours. I love it."] = "Volentieri, {name}. Pochi chiedono favori a un lupo di due metri. Lo adoro."
L["Certainly, {name}. I'll stay in this form. The other one causes a scene."] = "Certo, {name}. Resto in questa forma: l'altra fa sempre scalpore."
L["Straight to business without tea, {name}? How un-Gilnean."] = "Dritti al sodo senza un tè, {name}? Così poco gilneano."
L["Of course, {name}. In Gilneas, nobody had to ask twice."] = "Certo, {name}. A Gilneas nessuno doveva chiedere due volte."
L["Of course, {name}. It would be rude to keep you waiting."] = "Certo, {name}. Sarebbe scortese farti aspettare."
L["Of course, {name}. Anything but a bath."] = "Certo, {name}. Tutto, tranne il bagno."
L["Stay off the moors after dark, {name}. Take this."] = "Evita le brughiere dopo il tramonto, {name}. Prendi questo."
L["Keep your wits about you, {name}. Something is always hunting."] = "Tieni gli occhi aperti, {name}. C'è sempre qualcosa a caccia."
L["I'd have brought this sooner, {name}, but I stopped to chase something."] = "Te l'avrei portato prima, {name}, ma dovevo inseguire una cosa."
L["For you, {name}. No, I don't want a treat. Well. Perhaps a small one."] = "Per te, {name}. No, non voglio un biscottino. Be'. Magari uno piccolo."
L["Gilneans always offer, {name}. The claws are just part of the outfit."] = "Un gilneano offre sempre, {name}. Gli artigli sono solo un accessorio."
L["An old Gilnean remedy, {name}. Good for colds, gloom and most curses. Not mine."] = "Rimedio gilneano, {name}: per raffreddore, malumore e maledizioni. Non la mia."
L["Run with this, {name}. Trust me, I know about running."] = "Corri con questo, {name}. Fidati, di corse me ne intendo."
L["Brought you this, {name}. Don't make a fuss over it."] = "Ti ho portato questo, {name}. Non farne un caso."
L["Here, {name}. Gilnean roads were never safe alone, and nor are these."] = "Tieni, {name}. Le strade di Gilneas non erano mai sicure da soli, e nemmeno queste."
L["For you, {name}. Not everything that prowls was as well raised as I was."] = "Per te, {name}. Non tutte le bestie in giro sono educate come me."
L["From a Gilnean of good family, {name}. The fur is new; the manners are old."] = "Da un gilneano di buona famiglia, {name}. Il pelo è nuovo, le buone maniere no."
L["Someone did this for me in Duskhaven once, {name}. I never forgot."] = "Una volta, a Gilneas, qualcuno l'ha fatto per me, {name}. Non l'ho mai dimenticato."
L["Liam would have cried 'For Gilneas!', {name}. I'll just say: for you."] = "Liam avrebbe gridato 'Per Gilneas!', {name}. Io dico solo: per te."
L["Tal'doren's druids taught me to leash the beast, {name}. It lets me do this."] = "I druidi di Tal'doren mi hanno insegnato a domare la bestia, {name}. Così posso farlo."
L["Be careful out there, {name}. Take it from someone who was bitten once."] = "Occhio là fuori, {name}. Parola di chi è stato morso, una volta."
L["Here, {name}. In Gilneas we'd have sent it with a jar of preserves."] = "Tieni, {name}. A Gilneas l'avremmo mandato con un vasetto di marmellata."
L["Take this, {name}. I'd offer my coat, but it's attached."] = "Prendi, {name}. Ti darei la pelliccia, ma non si stacca."
L["Here, {name}. Chin up, hackles down. Words to live by."] = "Tieni, {name}. Mento su, pelo giù: un motto per la vita."
L["The curse binds us, {name}, but Gilneas binds us tighter."] = "La maledizione ci lega, {name}, ma Gilneas ci lega ancora di più."
L["No need to explain the ears to you, {name}."] = "A te non devo spiegare le orecchie, {name}."
L["Fur, fog and rain, {name}. Only a Gilnean understands all three."] = "Pelo, nebbia e pioggia, {name}. Solo un gilneano capisce tutte e tre."
L["Pack looks after pack, {name}. Always has."] = "Il branco bada al branco, {name}. Da sempre."
L["Do you shed this badly too, {name}? Between us we could knit a third worgen."] = "Anche tu perdi così tanto pelo, {name}? In due ci sferruzziamo un terzo worgen."
L["Two worgen, {name}. Somewhere, a cat's having a very bad day."] = "Due worgen, {name}. Da qualche parte, un gatto sta sudando freddo."
L["Honestly, {name}, do you ever forget which form you left home in?"] = "Dimmi la verità, {name}: ti scordi mai con che forma esci di casa?"
L["Gilnean to Gilnean, {name}: the finest-mannered wolves in all Azeroth."] = "Da gilneano a gilneano, {name}: i lupi più educati di tutta Azeroth."
L["Pack rules, {name}: nobody wanders off, and nobody mentions the fleas."] = "Regole del branco, {name}: nessuno si allontana, e nessuno parla delle pulci."
L["A pack again, {name}. I hadn't known how much I'd missed one."] = "Di nuovo un branco, {name}. Non sapevo quanto mi fosse mancato."
L["I'll catch the scent of trouble first, {name}. It's the one perk of the curse."] = "I guai li fiuto prima io, {name}. L'unico vantaggio della maledizione."
L["If I howl, {name}, it's a battle cry. Howl back if you like."] = "Se ululo, {name}, è un grido di battaglia. Ulula anche tu, se ti va."
L["Lead on, {name}. I'll trot. It's undignified, but it's much quicker."] = "Fai strada, {name}. Io trotterello. Poco dignitoso, ma molto più veloce."
L["If I stop and stare at a wall, {name}, something's behind it. Or it's a wall."] = "Se mi fermo a fissare un muro, {name}, c'è qualcosa dietro. O è solo un muro."
L["Years on the Greymane Wall, {name}. Holding a line with you is a holiday."] = "Anni sul Muro di Mantogrigio, {name}. Tenere la linea con te è una vacanza."
L["After this, {name}, a proper cup of tea. Before this, a proper mauling."] = "Dopo, {name}, un tè come si deve. Prima, si sbrana come si deve."
L["If I limp back, {name}, don't fuss. Worgen mend quickly."] = "Se torno zoppicando, {name}, niente storie. I worgen guariscono in fretta."
L["When we rest, {name}, I'll take first watch. I hear everything anyway."] = "Quando ci fermiamo, {name}, il primo turno di guardia è mio. Tanto sento tutto."
L["Stay together, {name}. Being a lone wolf is overrated."] = "Restiamo uniti, {name}. Fare il lupo solitario è sopravvalutato."
L["Night again, {name}. I'm at my best and my worst. This is the best part."] = "Di nuovo notte, {name}. Do il meglio e il peggio di me. Questo è il meglio."
L["Look at that moon, {name}. Gilneas taught us not to trust it."] = "Guarda che luna, {name}. Gilneas ci ha insegnato a non fidarci."
L["Gilneas at night was fog and footsteps, {name}. These days I'm the footsteps."] = "Gilneas di notte era nebbia e passi, {name}. Ora i passi sono io."
L["Curfew in Gilneas was sundown, {name}. For good reason, as it turned out."] = "A Gilneas il coprifuoco era al tramonto, {name}. Col senno di poi, giustamente."
L["Something out there keeps rustling, {name}. Stay close; I'll look."] = "Qualcosa là fuori continua a frusciare, {name}. Stammi vicino: vado a vedere."
L["Past dark, {name}: ears up, nose working, manners on. Two out of three will do."] = "Col buio, {name}: orecchie tese, naso all'opera, buone maniere. Due su tre bastano."
L["Morning, {name}. I'd have been up sooner, but the rug by the fire was so warm."] = "Buongiorno, {name}. Il tappeto davanti al fuoco era troppo caldo per alzarsi."
L["Smells like rain this morning, {name}. Everything in Gilneas smelled like rain."] = "Stamattina c'è odore di pioggia, {name}. A Gilneas tutto sapeva di pioggia."
L["Up already, {name}? I've been prowling since first light."] = "Già in piedi, {name}? Io sono in giro dalle prime luci."
L["Morning, {name}. Tea, toast, a shave. The shave takes rather longer now."] = "Buongiorno, {name}. Tè, toast, rasatura. La rasatura ora dura un po' di più."
L["Morning, {name}. The birds woke me, so I woke the birds. It seemed only fair."] = "Buongiorno, {name}. Sveglia degli uccelli; io ho ricambiato. Mi pareva giusto."
L["Morning, {name}. The fog's lifting, which it never did in Gilneas."] = "Buongiorno, {name}. La nebbia si alza, cosa che a Gilneas non faceva mai."
L["Throm-ka, {name}! Honour is repaid."] = "Throm-ka, {name}! L'onore è ripagato."
L["You give freely, {name}. I return the favour."] = "Tu doni senza chiedere, {name}. Io ricambio il favore."
L["Orcs keep their thanks short, {name}. Thanks."] = "Gli orchi ringraziano in breve, {name}. Grazie."
L["Orcs return every blow twice, {name}. The kind ones too."] = "Un orco rende ogni colpo due volte, {name}. Anche quelli gentili."
L["You helped me, I help you, {name}. That is the old way."] = "Tu hai aiutato me, io aiuto te, {name}. È l'antica usanza."
L["In the old days I'd have repaid you with a boar, {name}. This keeps better."] = "Un tempo ti avrei ripagato con un cinghiale, {name}. Questo si conserva meglio."
L["Owing somebody itches worse than Durotar sand, {name}. There. Itch gone."] = "Un debito prude più della sabbia di Durotar, {name}. Ecco. Prurito passato."
L["Strong stuff, {name}. I could wrestle a kodo now. So can you."] = "Roba forte, {name}. Ora potrei fare a botte con un kodo. E anche tu."
L["Ambushed by kindness, {name}. No orc trains for that. Returned in full."] = "Agguato di gentilezza, {name}. Nessun orco è addestrato a questo. Ricambio."
L["Honour is a debt, {name}, and orcs pay on the spot."] = "L'onore è un debito, {name}, e gli orchi pagano sull'unghia."
L["An orc remembers a kindness like a scar, {name}: fondly, and for good."] = "Per un orco una gentilezza è come una cicatrice, {name}: cara, e per sempre."
L["I'd give you my axe, {name}, but we're not that close yet. Take this."] = "Ti darei la mia ascia, {name}, ma non siamo ancora così amici. Prendi."
L["Thanks, {name}. My wolf growled at you. That's how he says it."] = "Grazie, {name}. Il mio lupo ti ha ringhiato: è il suo grazie."
L["I've had gifts from shamans and chieftains, {name}. None came so freely."] = "Ho avuto doni da sciamani e capotribù, {name}. Nessuno così spontaneo."
L["We once took strength from demons, {name}. Yours comes on far better terms."] = "Un tempo la forza ce la davano i demoni, {name}. La tua costa molto meno."
L["The spirits saw that, {name}. They'll remember it, and so will I."] = "Gli spiriti l'hanno visto, {name}. Se lo ricorderanno, e anch'io."
L["I'll carve that on my axe handle, {name}. Next to the notches. Thank you."] = "Lo inciderò sul manico dell'ascia, {name}. Accanto alle tacche. Grazie."
L["Kindness unasked is rare as rain in Durotar, {name}. Returned."] = "Una gentilezza spontanea è rara come la pioggia in Durotar, {name}. Ricambiata."
L["In my clan, {name}, a gift is answered with a bigger one. Here."] = "Nel mio clan, {name}, a un dono si risponde con uno più grande. Tieni."
L["Dabu, {name}. It is done."] = "Dabu, {name}. È fatto."
L["Hold still, {name}. Strength for the fight ahead."] = "Non muoverti, {name}. Forza per la battaglia che ti aspetta."
L["Ask an orc for help and you get it, {name}. Ask for subtlety and you wait."] = "Chiedi aiuto a un orco e lo ottieni, {name}. Chiedigli finezza e aspetti."
L["Help, yes. Hugging, no. Hold still, {name}."] = "Aiuto, sì. Abbracci, no. Non muoverti, {name}."
L["You want {buff}? You have {buff}, {name}. Next."] = "Vuoi {buff}? Hai {buff}, {name}. Avanti il prossimo."
L["Don't flinch, {name}. My helping face looks exactly like my fighting face."] = "Non tremare, {name}. La mia faccia da aiuto è identica a quella da battaglia."
L["Short question, short answer, {name}: yes."] = "Domanda breve, risposta breve, {name}: sì."
L["Done, {name}. I was a peon once; I never refuse honest work."] = "Ecco, {name}. Ho fatto il peone: non rifiuto mai un lavoro onesto."
L["A challenge, {name}? Ah, a request. I accept either way."] = "Una sfida, {name}? Ah, una richiesta. Accetto comunque."
L["Yes, {name}. I was sharpening my axe, but it'll keep. It always keeps."] = "Sì, {name}. Stavo affilando l'ascia, ma può aspettare. Lei sa aspettare."
L["In the Valley of Honor this would cost you a duel, {name}. For you, a nod."] = "Nella Valle dell'Onore ti costerebbe un duello, {name}. A te, un cenno."
L["Now, {name}? Now. Orcs never learned the word 'later'."] = "Ora, {name}? Ora. Gli orchi non conoscono la parola 'dopo'."
L["One {buff}, {name}. Orc style: fast, direct, a bit too hard."] = "{buff}, {name}. Stile orco: rapido, diretto, un po' troppo forte."
L["Stand still, {name}. I aim this like a throwing axe, and I rarely miss."] = "Non muoverti, {name}. Lo tiro come un'ascia da lancio, e sbaglio di rado."
L["Lok'tar, {name}. It means 'victory'. Today it also means 'yes'."] = "Lok'tar, {name}. Vuol dire 'vittoria'. Oggi vuol dire anche 'sì'."
L["Lok'tar ogar, {name}! Take this into battle. A tavern brawl also counts."] = "Lok'tar ogar, {name}! Portalo in battaglia. Anche una rissa in taverna vale."
L["Blood and thunder, {name}! Go and earn your glory."] = "Sangue e tuono, {name}! Va' e conquista la tua gloria."
L["Among orcs, {name}, making you stronger is how we say we like you."] = "Tra orchi, {name}, renderti più forte è il nostro modo di dire che ci piaci."
L["An orc giving gifts unasked? Tell no one, {name}. It ruins the image."] = "Un orco che fa regali? Acqua in bocca, {name}. Rovina l'immagine."
L["The Warchief wants us diplomatic, {name}. This is my diplomacy."] = "Il Capoguerra ci vuole diplomatici, {name}. Questa è la mia diplomazia."
L["Go hit something for me, {name}. Or set it on fire. Orcs aren't fussy."] = "Picchia qualcosa per me, {name}. O dagli fuoco. Gli orchi non fanno storie."
L["Don't thank me, {name}. Just win, and do it loudly."] = "Non ringraziarmi, {name}. Vinci, e fa' rumore."
L["I'd make a speech, {name}, but it's mostly shouting. Just take it."] = "Farei un discorso, {name}, ma sarebbe soprattutto urla. Prendi e basta."
L["An orc at your back, {name}, even when I'm not there. Take this."] = "Un orco alle tue spalle, {name}, anche quando non ci sono. Prendi."
L["'Strike first,' Grom always said, {name}. So: here, before you could ask."] = "'Colpisci per primo', diceva Grom, {name}. Quindi tieni, prima che tu chieda."
L["Take it, {name}. A grunt who walks past a comrade gets a talking-to. From me."] = "Prendi, {name}. Un soldato che ignora un compagno si becca una strigliata. Da me."
L["Frostwolves share the hunt, {name}. I caught nothing today, so share this."] = "I Lupi Bianchi spartiscono la preda, {name}. Oggi niente preda: spartiamo questo."
L["Walk the Durotar way, {name}: head up, sun on your neck, scorpid underfoot."] = "Stile Durotar, {name}: testa alta, sole sul collo, scorpidi sotto i piedi."
L["Here, {name}. The spirits favour the generous."] = "Tieni, {name}. Gli spiriti favoriscono chi è generoso."
L["Orcs give two things freely, {name}: advice and this. Skip the advice."] = "Gli orchi regalano due cose, {name}: consigli e questo. Salta i consigli."
L["The Barrens don't end, {name}. They just get more zhevra. Take this."] = "Le Savane non finiscono, {name}. Aumentano solo le zhevra. Prendi."
L["Strength for your arm, {name}. The honour, I see, you brought yourself."] = "Forza per il tuo braccio, {name}. L'onore, vedo, l'hai portato da te."
L["My wolf wanted you to have his bone, {name}. I talked him down to this."] = "Il mio lupo voleva regalarti il suo osso, {name}. Ho trattato: questo."
L["Throm-ka, {name}! The blood of the clans runs strong in you."] = "Throm-ka, {name}! Il sangue dei clan scorre forte in te."
L["An orc, {name}! Finally, somebody who shouts at my volume."] = "Sangue orchesco, {name}! Finalmente qualcuno che urla al mio volume."
L["Frostwolf, Warsong or Blackrock, {name}, we all argue like family."] = "Lupi Bianchi, Cantaguerra o Roccianera, {name}: litighiamo come una famiglia."
L["Between orcs no words are needed, {name}. Good. I was out of them."] = "Tra orchi non servono parole, {name}. Meglio. Le avevo finite."
L["Grunt or shaman, {name}, it's the same stubborn blood."] = "Soldato o sciamano, {name}, il sangue è lo stesso: testardo."
L["Two orcs, {name}, and nobody's shouted yet. The shamans will call it an omen."] = "Due orchi, {name}, e nessuno urla ancora. Per gli sciamani è un presagio."
L["Our clans probably feuded once, {name}. Everybody's did. Let's call it settled."] = "Di sicuro i nostri clan erano in faida, {name}. Come tutti. Pace fatta."
L["Between orcs, {name}, 'victory or death' is just how we say 'see you later'."] = "Tra orchi, {name}, 'vittoria o morte' è solo il nostro modo di dire 'a dopo'."
L["Your tusks and mine have seen worse days, {name}. This is a better one."] = "Le tue zanne e le mie ne hanno viste di peggio, {name}. Oggi va meglio."
L["The plan, {name}: we hit it. Questions? No? Good plan."] = "Il piano, {name}: lo colpiamo. Domande? No? Ottimo piano."
L["A true warband, {name}. Loud, angry, and all on the same side for once."] = "Una vera schiera, {name}. Chiassosa, furiosa, e per una volta dalla stessa parte."
L["Stay with the warband, {name}. Strength in numbers. And in axes."] = "Resta con la schiera, {name}. L'unione fa la forza. E le asce pure."
L["If you fall, {name}, I carry you out. Complaining the whole way, but I carry."] = "Se cadi, {name}, ti porto fuori io. Lamentandomi tutto il tempo, ma ti porto."
L["Fight well, {name}, and tonight you share our fire. And our boasting."] = "Combatti bene, {name}, e stasera siedi al nostro fuoco. Spacconate incluse."
L["Nobody runs, {name}. Walking briskly away is allowed. Barely."] = "Nessuno scappa, {name}. Andarsene a passo svelto si può. Appena."
L["I'll go first, {name}. I have the thickest skull here, and I'm proud of it."] = "Vado avanti io, {name}. La testa più dura qui è la mia, e me ne vanto."
L["When the war drums start, {name}, charge. We have no drums. I'll hum."] = "Ai tamburi di guerra, {name}, carica. Non ne abbiamo. Canticchio io."
L["Watch my back, {name}. The front I can see; that's the part I hit."] = "Guardami le spalle, {name}. Il davanti lo vedo: è lì che colpisco."
L["One clan today, {name}: the Clan of Whoever Showed Up. Finest there is."] = "Oggi un solo clan, {name}: il clan Chi c'è c'è. Il migliore di tutti."
L["Anything big comes through that door, {name}, it's mine. Anything bigger, ours."] = "Roba grossa da quella porta, {name}: mia. Roba più grossa: nostra."
L["Scars are stories, {name}. Let's all come out of this with short ones."] = "Le cicatrici sono storie, {name}. Usciamone tutti con storie brevi."
L["Old chieftains had war councils, {name}. We have me pointing at things."] = "Un tempo c'erano consigli di guerra, {name}. Ora ci sono io che indico cose."
L["If I charge early, {name}, it isn't impatience. It's tradition."] = "Se carico in anticipo, {name}, non è impazienza. È tradizione."
L["Thank you, {name}. It would warm my heart, if it still beat."] = "Grazie, {name}. Mi scalderebbe il cuore, se battesse ancora."
L["Such warmth, for one so cold? Returned in full, {name}."] = "Tanto calore per chi è così freddo? Te lo rendo tutto, {name}."
L["Thank you, {name}. I'd blush, but the blood stopped reaching my face."] = "Grazie, {name}. Arrossirei, ma il sangue non mi arriva più in faccia."
L["My undying gratitude, {name}. For once, the phrase is accurate."] = "Gratitudine eterna, {name}. Detto da un non-morto, è letterale."
L["Most kind, {name}. You've lifted me from 'deceased' to 'mildly deceased'."] = "Che gentilezza, {name}. Da trapassato remoto a trapassato prossimo."
L["Returned, {name}. Death took my pulse, not my manners."] = "Ricambiato, {name}. La morte mi ha tolto il polso, non le buone maniere."
L["I felt that, {name}, and I don't feel much these days. Here, feel this."] = "L'ho sentito, {name}, e ormai sento ben poco. Tieni, senti questo."
L["Thank you, {name}. That's the first colour I've seen all week."] = "Grazie, {name}. È il primo colore che vedo in tutta la settimana."
L["Thank you, {name}. Kindness above ground; I'd almost forgotten it happens."] = "Grazie, {name}. Gentilezza in superficie: avevo quasi scordato che esistesse."
L["Too kind, {name}. Returned, with a little grave chill on it."] = "Troppo gentile, {name}. Ricambio, con un filo di gelo d'oltretomba."
L["The last gift I got was the plague, {name}. Yours is a big improvement."] = "L'ultimo dono che ho ricevuto era la piaga, {name}. Il tuo è molto meglio."
L["Thank you, {name}. Nothing this fresh has touched me since Lordaeron fell."] = "Grazie, {name}. Niente di così fresco mi tocca dalla caduta di Lordaeron."
L["Sylvanas says we repay every debt, {name}. She rarely means the nice ones."] = "Sylvanas vuole ogni debito ripagato, {name}. Di solito con la stessa moneta."
L["My posture's improved, {name}. It's been slumping since the Third War. Thanks."] = "La mia postura è migliorata, {name}. Si incurvava dalla Terza Guerra. Grazie."
L["Repaid at once, {name}. We Forsaken never carry debts. They rot."] = "Ripagato subito, {name}. Noi Reietti non teniamo debiti. Marciscono."
L["Thank you, {name}. I've an eternity to remember this, and I intend to."] = "Grazie, {name}. Ho un'eternità per ricordarlo, e intendo farlo."
L["Thank you, {name}. I'll keep this somewhere safe. My ribcage has room."] = "Grazie, {name}. Lo terrò al sicuro. Nella gabbia toracica c'è posto."
L["Thank you, {name}. Once I'd have baked you a pie for that."] = "Grazie, {name}. Un tempo ti avrei sfornato una torta, per questo."
L["I'll mention you to the Dark Lady, {name}. She won't care, but I will."] = "Parlerò di te alla Dama Oscura, {name}. A lei non importerà, a me sì."
L["Kindness returned, {name}. Even the flies around me look impressed."] = "Gentilezza ricambiata, {name}. Persino le mie mosche sembrano colpite."
L["In all my years with the Scourge, nobody once said this, {name}. Thank you."] = "Anni nel Flagello, {name}, e nessuno mi ha mai detto questo: grazie."
L["I'll drink to you tonight, {name}. It all leaks out, but it's the thought."] = "Stasera brindo a te, {name}. Mi cola tutto fuori, ma è il pensiero che conta."
L["The Dark Lady says trust no gift, {name}. I'll risk it, and send one back."] = "La Dama Oscura dice: diffida dei doni, {name}. Corro il rischio, e ricambio."
L["Thank you, {name}. You've made my list of reasons to keep going. It's short."] = "Grazie, {name}. Ora sei nella mia lista di motivi per tirare avanti. È corta."
L["Thank you, {name}. No contract, no fine print. Varimathras should take notes."] = "Grazie, {name}. Nessun contratto, nessuna clausola. Varimathras, prendi nota."
L["Grave dirt and gratitude, {name}: all I own. You'll prefer the gratitude."] = "Terra di tomba e gratitudine, {name}: tutto ciò che ho. Meglio la gratitudine."
L["Thank you, {name}. Eternity drags; this was the best bit of the decade."] = "Grazie, {name}. L'eternità non passa mai; questo è il meglio del decennio."
L["Faranell would want notes on that reaction, {name}. I'll just return it."] = "Faranell vorrebbe annotare questa reazione, {name}. Io mi limito a ricambiare."
L["Thank you, {name}. Lordaeron had manners once. Glad somebody kept them."] = "Grazie, {name}. Lordaeron aveva buone maniere. Almeno tu le hai conservate."
L["Even the Deathguard would nod at that, {name}, and they nod at nothing."] = "Perfino le guardie dei Reietti annuirebbero, {name}, e loro non annuiscono mai."
L["I'd have Lordaeron's bells rung for you, {name}, but they only do funerals now."] = "Farei suonare le campane di Lordaeron per te, {name}, ma ora suonano solo a morto."
L["Thank you, {name}. Next time I'm in Brill, I'll name a pumpkin after you."] = "Grazie, {name}. Appena torno a Brill, darò il tuo nome a una zucca."
L["Thank you, {name}. My afterlife had rather let itself go. You've tidied it up."] = "Grazie, {name}. Il mio aldilà si era lasciato andare. L'hai rimesso in sesto."
L["Certainly, {name}. Try not to die. It's overrated."] = "Certo, {name}. Cerca di non morire. È sopravvalutato."
L["You need only ask, {name}. The dead are patient."] = "Basta chiedere, {name}. I morti sono pazienti."
L["Ask the dead for a favour, {name}. We rarely have other plans."] = "Chiedi pure un favore ai morti, {name}. Raramente abbiamo altri impegni."
L["Certainly, {name}. Stand clear; I'd hate to drop anything on you."] = "Certo, {name}. Stai indietro: non vorrei perdere qualche pezzo su di te."
L["A moment, {name}. Rigor mortis is hard on the casting hand."] = "Un attimo, {name}. Il rigor mortis è duro con la mano che lancia."
L["Nice to be asked for something, {name}, besides the way to the graveyard."] = "Che bello, {name}, che mi si chieda qualcosa oltre alla strada per il cimitero."
L["Gladly, {name}. It takes my mind off the smell. Mine, I mean."] = "Volentieri, {name}. Mi distrae dall'odore. Il mio, intendo."
L["Certainly, {name}. Hold still. My aim drifts when my eye does."] = "Certo, {name}. Non muoverti: se mi cade l'occhio, addio mira."
L["In Undercity nobody says please, {name}. Mostly they gurgle. Here you are."] = "A Sepulcra nessuno dice per favore, {name}. Al massimo gorgogliano. Ecco."
L["Just {buff}, {name}? The apothecaries always want a sample too."] = "Solo {buff}, {name}? Gli speziali vorrebbero anche un campione."
L["I always rise when called, {name}. Unfortunate history. Here you are."] = "Io risorgo sempre quando mi chiamano, {name}. Brutti trascorsi. Ecco."
L["Anything for you, {name}. Within reason, and what's left of mine."] = "Tutto per te, {name}, nei limiti della ragione. Di quel che ne resta."
L["Of course, {name}. I'd say 'over my dead body', but that's been tried."] = "Certo, {name}. Direi 'sul mio cadavere', ma è già stato fatto."
L["Right away, {name}. The dead don't dawdle. We shamble with purpose."] = "Subito, {name}. I morti non bighellonano. Barcolliamo con uno scopo."
L["Of course, {name}. Free will is a gift. I spend mine on things like this."] = "Certo, {name}. Il libero arbitrio è un dono. Io lo spendo così."
L["At once, {name}. I've had far worse requests from the Apothecarium."] = "Subito, {name}. Gli speziali mi hanno chiesto ben di peggio."
L["Of course, {name}. After a winter in the Plaguelands, this counts as a holiday."] = "Certo, {name}. Dopo un inverno nelle Terre Infette, questa è una vacanza."
L["{buff}, {name}? With the Dark Lady's compliments."] = "{buff}, {name}? Con gli omaggi della Dama Oscura."
L["Of course, {name}. I don't sleep or eat, so I may as well be useful."] = "Certo, {name}. Non dormo e non mangio: tanto vale rendermi utile."
L["Glad to, {name}. The Scourge used my hands for worse."] = "Volentieri, {name}. Il Flagello ha usato le mie mani per cose peggiori."
L["Stay among the living a little longer, {name}."] = "Resta tra i vivi ancora un po', {name}."
L["Take this, {name}. The grave can wait."] = "Prendi, {name}. La tomba può aspettare."
L["I was a physician in Lordaeron, {name}. Old habits die harder than I did."] = "Ero medico a Lordaeron, {name}. Certe abitudini sono più dure a morire di me."
L["No charge, {name}. The apothecaries would have made you sign something."] = "Gratis, {name}. Gli speziali ti avrebbero fatto firmare qualcosa."
L["A gift from the grave, {name}. Don't worry, I washed it."] = "Un dono dalla tomba, {name}. Niente paura, l'ho lavato."
L["Every traveller needs a little help, {name}. Here's yours."] = "Ogni viandante ha bisogno di un aiuto, {name}. Ecco il tuo."
L["I've seen where heroes end up, {name}. I live there. Take this."] = "Ho visto dove finiscono gli eroi, {name}. Ci abito. Prendi."
L["Take this, {name}. I learned the hard way you can't take it with you."] = "Prendi, {name}. Ho imparato a mie spese che nella tomba non te lo porti."
L["Take this, {name}. It's the only thing I own that isn't slightly damp."] = "Prendi, {name}. È l'unica cosa che ho che non sia un po' umida."
L["Hold on to yourself, {name}. Trust me, the pieces are hard to find later."] = "Tieniti tutto intero, {name}. Fidati, dopo i pezzi non si trovano più."
L["Take this, {name}. The Plaguelands are full of people who didn't."] = "Prendi, {name}. Le Terre Infette sono piene di gente che non l'ha fatto."
L["A small kindness, {name}. Tirisfal could use more of them."] = "Una piccola gentilezza, {name}. A Tirisfal ne servirebbero di più."
L["Tirisfal fog gets into everything, {name}. So does this, but pleasantly."] = "La nebbia di Tirisfal entra dappertutto, {name}. Anche questo, ma con garbo."
L["Here, {name}. Kept cool for you, like everything I carry."] = "Tieni, {name}. Conservato al fresco, come tutto ciò che porto."
L["I've outlived everyone I knew, {name}. I'd rather not outlive you. Take this."] = "Sono sopravvissuto a tutti, {name}. A te preferirei di no. Prendi."
L["Pardon me, {name}. I'm told I lurk. I'm trying to lurk helpfully."] = "Scusa, {name}. Dicono che sono losco. Provo a esserlo a fin di bene."
L["Out of my own pocket, {name}. The dead don't need much."] = "Di tasca mia, {name}. Ai morti serve poco."
L["I've already had the worst day there is, {name}. Let's spare you yours."] = "Il giorno peggiore possibile l'ho già vissuto, {name}. Il tuo evitiamolo."
L["Wind's off the Plaguelands, {name}. Take this, and breathe through your mouth."] = "Tira vento dalle Terre Infette, {name}. Prendi, e respira con la bocca."
L["The crows have been watching you, {name}. Let's disappoint them."] = "I corvi ti tengono d'occhio, {name}. Deludiamoli."
L["Here, {name}. Tirisfal grows nothing but pumpkins and grudges. This is neither."] = "Tieni, {name}. A Tirisfal crescono solo zucche e rancori. Questo no."
L["Take this, {name}. The only thing in Undercity that needn't be boiled first."] = "Prendi, {name}. L'unica cosa a Sepulcra che non va bollita prima."
L["Eternity is long, {name}, and I've spent a fair bit of it practising this."] = "L'eternità è lunga, {name}. Ne ho passata un bel pezzo a provare questo."
L["For the road, {name}. Undercity-made, so do keep it away from open flame."] = "Per il viaggio, {name}. Fatto a Sepulcra: tienilo lontano dal fuoco."
L["Take this, {name}. It's odourless, which I'm told makes it my best feature."] = "Prendi, {name}. È inodore, e dicono che sia il mio lato migliore."
L["Forsaken are famously patient, {name}. I just couldn't wait to give you this."] = "I Reietti sono pazientissimi, {name}. Ma questo non vedevo l'ora di dartelo."
L["No strings attached, {name}. I cut mine when the Lich King lost his grip."] = "Senza fili, {name}: i miei li ho tagliati quando il Re dei Lich perse la presa."
L["Fresh from Tirisfal, {name}. Well, fresh for Tirisfal."] = "Fresco di Tirisfal, {name}. Cioè, fresco per Tirisfal."
L["Take this, {name}. The Bulwark taught me to look out for the living."] = "Prendi, {name}. Il Baluardo mi ha insegnato a badare ai vivi."
L["We Forsaken must look after each other, {name}."] = "Noi Reietti dobbiamo badare l'uno all'altro, {name}."
L["Between us corpses, {name}, you're remarkably well preserved."] = "Detto tra cadaveri, {name}, ti conservi benissimo."
L["Lose a finger, {name}, and I've a spare. Forsaken share."] = "Perdi un dito, {name}? Te ne presto uno. Tra Reietti si usa."
L["Is your jaw clicking too, {name}, or is that just me?"] = "Anche a te scricchiola la mascella, {name}, o è solo la mia?"
L["Victory for Sylvanas, {name}. A small one this time, but it's ours."] = "Vittoria per Sylvanas, {name}. Piccola, stavolta, ma nostra."
L["Brill or Deathknell, {name}? We all woke up somewhere. I got the damp crypt."] = "Tutti ci siamo svegliati da qualche parte, {name}. A me è toccata la cripta umida."
L["When the Scourge comes calling, {name}, we won't be home. Not ever again."] = "Quando il Flagello busserà, {name}, non saremo in casa. Mai più."
L["The Bulwark still holds, {name}, and so do we. Held together, but holding."] = "Il Baluardo regge, {name}, e noi pure. A punti di sutura, ma reggiamo."
L["Lordaeron raised us twice, {name}: once as children, once as Forsaken."] = "Lordaeron ci ha tirati su due volte, {name}: da bambini e da Reietti."
L["Somewhere in Northrend, {name}, the Lich King is sulking about us. Good."] = "In Nordania, {name}, il Re dei Lich ci tiene ancora il muso. Bene."
L["The Dark Lady needs us whole, {name}. Near enough will do."] = "La Dama Oscura ci vuole interi, {name}. Più o meno."
L["You smell of Tirisfal, {name}. From one of us, that's a compliment."] = "Profumi di Tirisfal, {name}. Detto da uno di noi, è un complimento."
L["We've both got forever, {name}. Let's not spend it all waiting for the lift."] = "Abbiamo l'eternità, {name}. Non passiamola tutta ad aspettare l'ascensore."
L["One Forsaken to another, {name}: the sewer shortcut is not a shortcut."] = "Tra Reietti, {name}: la scorciatoia delle fogne non è una scorciatoia."
L["If the Deathguard ask, {name}, we're on patrol. A very, very slow patrol."] = "Se chiedono le guardie, {name}, siamo di ronda. Una ronda lentissima."
L["Our kind don't get many kindnesses, {name}. Let's keep them in the family."] = "Quelli come noi ricevono poche gentilezze, {name}. Teniamocele in famiglia."
L["Same grave dirt, same Dark Lady, {name}. That's family."] = "Stessa terra di tomba, stessa Dama Oscura, {name}. Questa è famiglia."
L["Keep the faith, {name}. In each other, I mean. It answers more often."] = "Abbi fede, {name}. L'uno nell'altro, intendo. Risponde più spesso."
L["The dead look after the dead, {name}. The living could learn a thing or two."] = "I morti badano ai morti, {name}. I vivi avrebbero qualcosa da imparare."
L["We've both seen the inside of a grave, {name}. Dreadful service. No view."] = "Conosciamo entrambi la tomba da dentro, {name}. Servizio pessimo, zero vista."
L["Stay alive, {name}. Undercity's housing list is already very long."] = "Non morire, {name}. A Sepulcra la lista d'attesa per le case è già lunga."
L["If I fall down, {name}, give it a minute. Old habit."] = "Se cado, {name}, dammi un minuto. Vecchia abitudine."
L["I'll take the front, {name}. What's the worst that could happen? Again?"] = "Sto davanti io, {name}. Cosa potrebbe succedere di peggio? Di nuovo?"
L["Keep upwind of me, {name}. It's better for morale."] = "Stammi sopravento, {name}. È meglio per il morale."
L["The last party I joined, {name}, I woke up in a crypt. Let's improve on that."] = "Col mio ultimo gruppo, {name}, il risveglio fu in una cripta. Facciamo meglio."
L["Anything that bites, {name}, point it at me. There's nothing left worth eating."] = "Ciò che morde, {name}, mandalo da me. Non ho più niente di commestibile."
L["Heal the others first, {name}. I run on spite and embalming fluid."] = "Cura prima gli altri, {name}. Io vado a rancore e formalina."
L["If this goes badly, {name}, don't worry. I've died before; it passes."] = "Se va male, {name}, niente paura. La morte l'ho già provata: passa."
L["I've fought the Scourge from both sides, {name}. This side's better company."] = "Ho visto il Flagello da dentro e da fuori, {name}. Fuori la compagnia è migliore."
L["Stay close, {name}. I'm the one who won't scream at the ghouls. Old neighbours."] = "Stammi vicino, {name}. Io coi ghoul non urlo. Vecchi vicini di casa."
L["I've walked the Plaguelands at night, {name}. This is a stroll by comparison."] = "Ho attraversato le Terre Infette di notte, {name}. Questa è una passeggiata."
L["The corpse at the back is me, {name}. Please don't bury it."] = "Il cadavere in fondo sono io, {name}. Per favore, non seppellirlo."
L["Stay together, {name}. It's easier than putting somebody back together."] = "Stiamo insieme, {name}. È più facile che rimettere insieme qualcuno."
L["Don't wait for me, {name}. I shamble, but I shamble forever. I'll catch up."] = "Non aspettarmi, {name}. Arranco, ma arranco per sempre. Ti raggiungo."
L["Keep the torches clear of me, {name}. I'm old, dry and very flammable."] = "Tieni le torce lontane, {name}. Sono vecchio, secco e molto infiammabile."
L["Don't check me for a pulse after, {name}. It only worries people."] = "Dopo, non sentirmi il polso, {name}. Fa solo preoccupare la gente."
L["Mind the green puddles, {name}. I've seen what they do. I'm what they do."] = "Occhio alle pozze verdi, {name}. So cosa fanno. Io sono quello che fanno."
L["Lordaeron fell with me in it, {name}. This won't be worse."] = "Lordaeron è caduta con me dentro, {name}. Questo non sarà peggio."
L["Stick together, {name}. The apothecaries pay well for strays."] = "Restiamo uniti, {name}. Gli speziali pagano bene i randagi."
L["If this ends underwater, {name}, don't mind me. Breathing's optional now."] = "Se finiamo sott'acqua, {name}, non badare a me. Per me respirare è facoltativo."
L["The Dark Lady trusts no one, {name}. I've made an exception for this party."] = "La Dama Oscura non si fida di nessuno, {name}. Io di questo gruppo sì."
L["When we win, {name}, drinks at the Gallows' End in Brill. My treat. Your risk."] = "Quando vinciamo, {name}, si beve alla locanda di Brill. Offro io. Rischi tu."
L["Don't mind the flies, {name}. They're with me."] = "Non badare alle mosche, {name}. Sono con me."
L["I'll watch the rear, {name}. Nothing sneaks up on someone who can't blink."] = "Copro io le spalle, {name}. Non si sorprende chi non può sbattere le palpebre."
L["Any blood on the floor after, {name}, it isn't mine. I stopped carrying any."] = "Il sangue per terra, dopo, {name}, non sarà mio. Io non ne ho più."
L["The dead keep terrible hours, {name}. Nice to have company for once."] = "I morti fanno orari assurdi, {name}. Bello avere compagnia, per una volta."
L["Midnight, {name}: the best hour to be up and about when you shouldn't be."] = "Mezzanotte, {name}: l'ora migliore per andare in giro quando non si dovrebbe."
L["The living are all asleep, {name}. We Forsaken call this the quiet shift."] = "I vivi dormono, {name}. Noi Reietti lo chiamiamo il turno tranquillo."
L["Late, {name}? In Undercity, this is lunchtime."] = "Tardi, {name}? A Sepulcra è ora di pranzo."
L["This is the hour the Scourge used to walk, {name}. Now it's ours."] = "Un tempo a quest'ora usciva il Flagello, {name}. Ora è nostra."
L["Night, {name}. The one time nobody can tell I'm pale."] = "Notte, {name}: nessuno si accorge che sono pallido."
L["Dark as the Undercity, {name}. Finally, some proper lighting."] = "Buio come a Sepulcra, {name}. Finalmente una luce come si deve."
L["Fog, moonlight and a hint of mildew, {name}. Proper Tirisfal weather."] = "Nebbia, luna e un filo di muffa, {name}. Il vero clima di Tirisfal."
L["The banshees start singing about now, {name}. Relax. They're only practising."] = "A quest'ora cantano le banshee, {name}. Niente panico: sono solo le prove."
L["Stars over Tirisfal, {name}. The one thing up there that never rotted."] = "Stelle su Tirisfal, {name}. L'unica cosa lassù che non è mai marcita."
L["Past midnight, {name}. The graveyards are quiet. The good ones, anyway."] = "Mezzanotte passata, {name}. I cimiteri sono tranquilli. Quelli buoni, almeno."
L["An owl just saw me and left, {name}. They're sensible birds."] = "Un gufo mi ha visto e se n'è andato, {name}. Uccelli assennati."
L["Morning already, {name}? I've been up all night. And all of last decade."] = "Già mattina, {name}? Sono in piedi da ieri sera. E dallo scorso decennio."
L["The sun's up, {name}. I'll stand in the shade, if you don't mind. Things peel."] = "C'è il sole, {name}. Io sto all'ombra, se permetti: qui si spella tutto."
L["Early start, {name}. Of all things, I miss yawning."] = "Di buon'ora, {name}. Fra tutte le cose, mi manca sbadigliare."
L["Sunrise, {name}. My least favourite colour."] = "L'alba, {name}. Il colore che odio di più."
L["Dawn over Tirisfal, {name}: grey, then slightly less grey. Glorious."] = "Alba su Tirisfal, {name}: grigio, poi un po' meno grigio. Splendido."
L["Morning, {name}. The Gallows' End porridge moved again. Have this instead."] = "Buongiorno, {name}. La polenta della locanda si è mossa di nuovo. Meglio questo."
L["The roosters in Brill still crow, {name}. Nobody's had the heart to tell them."] = "I galli di Brill cantano ancora, {name}. Nessuno ha avuto il cuore di dirglielo."
L["Morning, {name}. The Deathguard change shifts now. They just turn round."] = "Buongiorno, {name}. Ora le guardie cambiano turno. Si girano e basta."
L["Take the lift slowly, {name}. The last man who rushed it is still coming down."] = "Con calma sull'ascensore, {name}. L'ultimo che correva sta ancora scendendo."
L["Undercity has it all, {name}: a bank, an inn, and opinions in the sewers."] = "Sepulcra ha tutto, {name}: banca, locanda, e fogne che dicono la loro."
L["Even the rats bow to the Dark Lady here, {name}. Take this before one asks."] = "Qui i ratti s'inchinano alla Dama Oscura, {name}. Prendi, prima che lo chiedano."
L["Mind the canal, {name}. It's green for a reason, and the reason isn't moss."] = "Occhio al canale, {name}. È verde per un motivo, e il motivo non è il muschio."
L["Undercity's lovely this time of year, {name}. It's always this time of year."] = "Sepulcra è splendida in questo periodo, {name}. È sempre questo periodo."
L["We moved into Lordaeron's cellar, {name}, and kept the good silver."] = "Ci siamo presi la cantina di Lordaeron, {name}, argenteria buona compresa."
L["The Royal Quarter's that way, {name}. Bow low; the banshees keep score."] = "Il Quartiere Reale è di là, {name}. Inchinati bene: le banshee danno i voti."
L["The bat handler swears they're friendly, {name}. Take this before you test it."] = "Il custode giura che i pipistrelli non mordono, {name}. Prendi, prima di verificare."
L["Magic Quarter's that way, {name}. The glowing puddles aren't for drinking."] = "Il quartiere dei maghi è di là, {name}. Le pozze luminose non si bevono."
L["The throne room's just upstairs, {name}. Nobody sits in it. Bad memories."] = "La sala del trono è qui sopra, {name}. Nessuno ci si siede. Brutti ricordi."
L["Most folk greet a Forsaken with holy water, {name}. You're a welcome change."] = "Ai Reietti di solito tirano acqua santa, {name}. Tu sei una piacevole novità."
L["Few stop for a Forsaken, {name}. You did, and I noticed. Thank you."] = "Pochi si fermano per un Reietto, {name}. Tu sì, e l'ho notato. Grazie."
L["Contrary to rumour, {name}, not everything a Forsaken hands out is a plague."] = "Checché se ne dica, {name}, non tutto ciò che regala un Reietto è la peste."
L["Forsaken can't be charmed, {name}, they say. Asking nicely works, though."] = "I Reietti non si lasciano ammaliare, dicono, {name}. Ma con le buone funziona."
L["Take this instead of small talk, {name}. Mine tends to unsettle people."] = "Prendi questo al posto delle chiacchiere, {name}. Le mie turbano la gente."
L["They say the Forsaken have no friends, {name}. I'm recruiting."] = "Dicono che i Reietti non abbiano amici, {name}. Sto facendo colloqui."
L["Take this, {name}. If anyone asks, the Forsaken were perfectly charming."] = "Prendi, {name}. Se qualcuno chiede, i Reietti sono stati adorabili."
L["Stay alive, {name}. I've tried the alternative, and I can't recommend it."] = "Resta in vita, {name}. Ho provato l'alternativa e non la consiglio."
L["The Earth Mother saw your kindness, {name}. She nudged me. Quite hard."] = "La Madre Terra ha notato il tuo gesto, {name}. E mi ha dato di gomito. Forte."
L["Thank you, {name}. May the winds guide you."] = "Grazie, {name}. Che i venti ti guidino."
L["Thank you, {name}. I'm deeply moved, and it takes a lot to move a tauren."] = "Grazie, {name}. Mi hai commosso, e smuovere un tauren non è facile."
L["It's a long way up to a tauren's heart, {name}. You found it."] = "Il cuore di un tauren sta in alto, {name}. L'hai raggiunto."
L["I felt that from horn to hoof, {name}. Returned, hoof to horn."] = "L'ho sentito dalle corna agli zoccoli, {name}. E ritorno."
L["A gift given is a seed planted, {name}. Here is the harvest."] = "Un dono fatto è un seme piantato, {name}. Ecco il raccolto."
L["That deserves a feast, {name}. The feast can wait; {buff} can't."] = "Questo merita un banchetto, {name}. Il banchetto può aspettare; {buff} no."
L["Thank you, {name}. Should you ever need a wall to hide behind, I'm free."] = "Grazie, {name}. Se ti serve un muro dietro cui nasconderti, sono a disposizione."
L["Thank you, {name}. My grandmother said kindness comes back on the wind."] = "Grazie, {name}. Mia nonna diceva che la gentilezza torna col vento."
L["Returned faster than a wind rider, {name}, and with much less screeching."] = "Ricambiato più in fretta di una viverna, {name}, e con molti meno strilli."
L["Returned, {name}. The quilboar never learned to give back, and look at them."] = "Ricambiato, {name}. Gli Irsuti non hanno mai imparato a restituire, e guardali."
L["Thank you, {name}. My ancestors are all nodding. It's a great deal of nodding."] = "Grazie, {name}. Gli antenati annuiscono tutti. È un gran dondolare di corna."
L["In Mulgore we return a gift before the grass under it grows back, {name}."] = "A Mulgore si ricambia un dono prima che l'erba sotto ricresca, {name}."
L["Thank you, {name}. I'll name my next kodo calf after you. They're lovely."] = "Grazie, {name}. Darò il tuo nome al prossimo vitellino di kodo. Sono adorabili."
L["Kindness is rarer than shade in the Barrens, {name}. Here's some back."] = "La gentilezza è rara come l'ombra nelle Savane, {name}. Te ne rendo un po'."
L["I'll carve this on a totem, {name}. Tauren carve slowly; expect it by spring."] = "Lo inciderò su un totem, {name}. I tauren incidono piano: pronto per primavera."
L["Bloodhoof Village will hear of this at supper, {name}. Thank you."] = "A Mulgore lo racconteranno a cena, {name}. Grazie."
L["Cairne taught us to honour every kindness, {name}, and so I do."] = "Cairne ci ha insegnato a onorare ogni gentilezza, {name}, e così faccio."
L["Of course, {name}. Stand tall and be at peace. I'll handle the tall part."] = "Certo, {name}. Testa alta e resta in pace. Alla parte 'alta' ci penso io."
L["Ask and it is given, {name}. The herd shares what it has."] = "Chiedi e ti sarà dato, {name}. La mandria divide ciò che ha."
L["Of course, {name}. Stand back a pace; I do this with my whole body."] = "Certo, {name}. Fai un passo indietro: lo faccio con tutto il corpo."
L["Gladly, {name}. Mind the tail."] = "Con piacere, {name}. Occhio alla coda."
L["The Earth Mother gives freely, {name}, and so do her largest children."] = "La Madre Terra dona senza riserve, {name}, e così i suoi figli più grossi."
L["Gladly, {name}. Tauren are slow to anger and quick to help."] = "Volentieri, {name}. Noi tauren siamo lenti all'ira e svelti ad aiutare."
L["Refuse you, {name}? My ancestors would never let me hear the end of it."] = "Dirti di no, {name}? I miei antenati me lo rinfaccerebbero per l'eternità."
L["Of course, {name}. A tauren says yes the way the plains grow grass: easily."] = "Certo, {name}. Un tauren dice sì come la pianura fa l'erba: senza fatica."
L["Of course, {name}. One moment; my hands are big and the spell is small."] = "Certo, {name}. Un attimo: io ho le mani grandi e l'incantesimo è piccolo."
L["After a season herding kodo, {name}, a polite request is a holiday. Here."] = "Dopo una stagione coi kodo, {name}, una richiesta educata è una vacanza. Ecco."
L["The Earth Mother says share, {name}. My stomach says lunch. She outranks it."] = "La Madre Terra dice di condividere, {name}. La pancia dice pranzo. Vince lei."
L["Of course, {name}. Stand still as a totem; this won't take long."] = "Certo, {name}. Immobile come un totem: ci vorrà poco."
L["Spirits of the plains, lend me your strength. Here, {name}."] = "Spiriti delle pianure, prestatemi la vostra forza. Ecco, {name}."
L["Magatha would want a favour for it, {name}. Baine would just say yes. So: yes."] = "Magatha vorrebbe un favore in cambio, {name}. Baine direbbe sì e basta. Quindi: sì."
L["Hold still, {name}. I've practised on kodo, and they're far less polite."] = "Non muoverti, {name}. Mi sono esercitato sui kodo, e sono molto meno educati."
L["Of course, {name}. A shu'halo never refuses a traveller. Or a second helping."] = "Certo, {name}. Uno shu'halo non rifiuta mai un viandante. Né il bis."
L["Walk with the Earth Mother, {name}. She's everywhere, so you can't get lost."] = "Cammina con la Madre Terra, {name}. È ovunque, quindi non puoi perderti."
L["May An'she light your path, {name}."] = "Che An'she illumini il tuo cammino, {name}."
L["You looked like you could use a friend, {name}. I'm a very big one."] = "Ti serviva una spalla, {name}? Ne ho due, belle grosse."
L["Take this, {name}. The Earth Mother would scold me if I walked past."] = "Prendi, {name}. La Madre Terra mi sgriderebbe se tirassi dritto."
L["Tread lightly, {name}. Take it from someone who never has."] = "Passo leggero, {name}. Fidati di chi non ce l'ha mai avuto."
L["The wind said you'd pass this way, {name}. The wind is a terrible gossip."] = "Il vento ti ha annunciato, {name}. Il vento è un gran pettegolo."
L["Take this, {name}. I'd lend you my kodo too, but he's less generous than me."] = "Prendi, {name}. Ti presterei anche il mio kodo, ma è meno generoso di me."
L["The shu'halo say carry what you can for others, {name}. I can carry a lot."] = "Gli shu'halo dicono: porta ciò che puoi per gli altri, {name}. Io posso molto."
L["Take this, {name}. If the centaur trouble you, say Thunder Bluff sends regards."] = "Prendi, {name}. Se i centauri ti danno noie, di' che li saluta Picco del Tuono."
L["Here, {name}. Plainstriders run from me for no reason at all. You needn't."] = "Tieni, {name}. Le bestie delle pianure mi scappano, chissà perché. Tu resta."
L["For you, {name}. Visit Mulgore sometime. The grass is soft and nobody hurries."] = "Per te, {name}. Vieni a Mulgore, una volta. L'erba è morbida e nessuno ha fretta."
L["Here, {name}. Grandmother blessed travellers and fed them. I'm out of bread."] = "Tieni, {name}. La nonna benediceva i viandanti e li sfamava. Il pane è finito."
L["The spirits asked me to mind you, {name}. I said yes before they'd finished."] = "Gli spiriti mi han chiesto di vegliare su di te, {name}. Ho detto sì a metà frase."
L["Here, {name}. Kodo share the watering hole; I can share this."] = "Tieni, {name}. I kodo dividono la pozza; io posso dividere questo."
L["Here, {name}. Tauren leave the world a little better, and a little trampled."] = "Tieni, {name}. I tauren lasciano il mondo un po' migliore, e un po' calpestato."
L["The Earth Mother would offer you a nap, {name}. I offer this."] = "La Madre Terra ti offrirebbe un pisolino, {name}. Io ti offro questo."
L["Druids call it a blessing, hunters luck, {name}. Tauren call it manners."] = "I druidi la chiamano benedizione, i cacciatori fortuna, {name}. I tauren, buone maniere."
L["Take this, {name}. If a harpy screeches at you, screech back. They hate that."] = "Prendi, {name}. Se un'arpia ti strilla contro, strillale anche tu. Lo odiano."
L["Here, {name}. A tauren blessing: sturdy, slow to fade, smells faintly of sage."] = "Tieni, {name}. Una benedizione tauren: robusta, dura a lungo, sa un po' di salvia."
L["The Earth Mother watches over us both, {name}."] = "La Madre Terra veglia su di noi due, {name}."
L["Somebody warn the doorframes, {name}. There are two of us now."] = "Qualcuno avverta gli stipiti, {name}. Adesso siamo in due."
L["Plains or peaks, {name}, a shu'halo heart is a big one."] = "Pianure o vette, {name}, il cuore di uno shu'halo è grande."
L["Horns and helmets, {name}. Only another tauren knows the pain."] = "Un elmo coi buchi giusti, {name}: solo un tauren sa che strazio trovarlo."
L["Rain on fur takes a week to dry, {name}. Only another tauren ever believes me."] = "Col pelo bagnato ci vuole una settimana, {name}. Mi crede solo un altro tauren."
L["Between tauren, {name}: Thunder Bluff's lifts were built by somebody smaller."] = "Tra tauren, {name}: chi ha fatto gli ascensori di Picco del Tuono era più basso."
L["Our ancestors watch us both, {name}. Let's give them something nice to see."] = "I nostri antenati ci guardano, {name}. Diamo loro un bello spettacolo."
L["From Mulgore to Feralas, {name}, the herd always finds itself."] = "Da Mulgore a Feralas, {name}, la mandria si ritrova sempre."
L["Get behind me, {name}. There's room back there for the whole party."] = "Mettiti dietro di me, {name}. C'è posto per tutto il gruppo."
L["The herd moves together, {name}. Mind my hooves; the herd has learned to."] = "La mandria si muove unita, {name}. Occhio ai miei zoccoli: la mandria ha imparato."
L["Low ceilings ahead, {name}? I'll be the first to find out. Take this."] = "Soffitti bassi più avanti, {name}? La mia testa lo scoprirà per prima. Prendi."
L["I'm slow to anger, {name}, but I hold a grudge for the whole party."] = "Mi arrabbio piano, {name}, ma porto rancore per tutto il gruppo."
L["Need a wall to hide behind, {name}? I'm most of one. Come on."] = "Ti serve un muro, {name}? Io lo sono quasi. Vieni."
L["When I war stomp, {name}, everybody sit down. It saves you falling over."] = "Quando batto lo zoccolo, {name}, sedetevi tutti. Così non cadete."
L["Everyone fed? Everyone blessed? Good, {name}. Tauren never lead a hungry herd."] = "Tutti sazi? Tutti benedetti? Bene, {name}. Mai guidare una mandria affamata."
L["Tauren don't swim, {name}, we wade. If it's deep, you're riding on me."] = "I tauren non nuotano, {name}, guadano. Se l'acqua è alta, sali in groppa."
L["Stay close, {name}. My ancestors walk with us. They're quieter than you lot."] = "Stammi vicino, {name}. Gli antenati sono con noi, e fanno meno chiasso di voi."
L["If I fall, {name}, don't try to carry me. Drag me. Fondly."] = "Se cado, {name}, non provare a portarmi. Trascinami. Con affetto."
L["We move like a stampede, {name}: all together, and sorry about the flowers."] = "Ci muoviamo come una mandria imbizzarrita, {name}: uniti, e scusate i fiori."
L["Nobody walks alone at the rear, {name}. That's where I'll be, looming kindly."] = "In coda non resta solo nessuno, {name}. Ci sarò io, a incombere con gentilezza."
L["Tell me when to charge, {name}. Tauren are slow to start, and slower to stop."] = "Dimmi quando caricare, {name}. Un tauren è lento a partire, e più lento a fermarsi."
L["Nobody wander, {name}. The last party that did in the Barrens is still walking."] = "Nessuno si perda, {name}. L'ultimo gruppo sparito nelle Savane cammina ancora."
L["An'she rises, {name}, and so do we. Slower, in my case."] = "An'she sorge, {name}, e noi con lui. Io un po' più lentamente."
L["The sun is An'she's eye, {name}. He's watching, so let's look busy."] = "Il sole è l'occhio di An'she, {name}. Ci guarda: facciamo finta di lavorare."
L["Morning, {name}. The kodo are up, the grass is wet, and this is yours."] = "Buongiorno, {name}. I kodo sono svegli, l'erba è bagnata, e questo è tuo."
L["Morning, {name}. I've greeted the sun, the wind and two plainstriders. Now you."] = "Buongiorno, {name}. Ho salutato il sole, il vento e due struzzi. Ora tocca a te."
L["Morning, {name}. Dew on the grass, dew on my fur. I'll be damp till noon."] = "'Giorno, {name}. Rugiada sull'erba e sul pelo: resto umido fino a mezzogiorno."
L["Early, {name}. That mist over Mulgore at dawn? Mostly kodo breath."] = "Presto, {name}. La nebbia all'alba su Mulgore? Quasi tutta fiato di kodo."
L["Mu'sha keeps the night watch, {name}. I'll tell her to keep an eye on you."] = "Mu'sha fa la guardia di notte, {name}. Le dirò di tenerti d'occhio."
L["The moon's out, {name}. Mu'sha sees you, and she approves. I asked."] = "C'è la luna, {name}. Mu'sha ti vede, e approva. Gliel'ho chiesto."
L["Late, {name}. The kodo are asleep, and they snore like thunder. Take this."] = "È tardi, {name}. I kodo dormono, e russano come tuoni. Prendi."
L["Stars out, {name}. Each one's an ancestor, they say. That one's winking at you."] = "Stelle in cielo, {name}. Ognuna è un antenato, dicono. Quello ti fa l'occhiolino."
L["Late, {name}. Mulgore is so quiet at night you can hear the grass argue."] = "È tardi, {name}. A Mulgore, di notte, senti perfino l'erba litigare."
L["Quiet now, {name}. At this hour, even my hooves try to tiptoe."] = "Piano, {name}. A quest'ora i miei zoccoli vanno in punta di piedi."
L["Ya too kind, {name}! This one's from me."] = "Si' troppo gentile, {name}! Chisto è da parte mia."
L["Thanks, mon! Da spirits smile on ya, {name}."] = "Grazie assaje, cumpà! 'E spiriti te sorrideno, {name}."
L["Ya gave me good mojo, {name}. Now ya get some back, extra spicy."] = "M'hai dato buon mojo, {name}. Mo' te lo torno, cu 'o peperoncino."
L["Death's gonna be real disappointed, {name}. Thanks, mon."] = "'A morte ce resta proprio male, {name}. Grazie, cumpà."
L["Fine work, {name}. Almost as fine as me. Almost."] = "Bello lavoro, {name}. Bello quasi quanto a me. Quasi."
L["A troll can grow back a hand, {name}. Can't grow back honour. Here."] = "A 'nu troll 'na mano ricresce, {name}. L'onore no. Piglia."
L["Ya just made a troll smile, {name}, and we got a lot of teeth."] = "Hai fatto ridere 'nu troll, {name}. E tenimmo assaje diente."
L["Da loa keep a tally, {name}. You're on the good side of it."] = "'E loa tengono 'o conto, {name}. Tu staje dalla parte bbona."
L["Beat me to it, {name}! Darkspear hate bein' second. Now we're even."] = "Primo tu, {name}! 'E Lanciascura odiano 'o secondo posto. Mo' simmo pari."
L["I owe ya now, {name}, and trolls only like owin' da loa. Settled."] = "Mo' te devo, {name}, e 'nu troll vò debiti sulo c''e loa. Saldato."
L["I'll tell all of Sen'jin 'bout ya, {name}. Makes a change from crabs."] = "Parlerò 'e te a tutta Sen'jin, {name}. Almeno nun se parla sempe 'e granchi."
L["My hair just stood up taller, {name}. Didn't know it could. Thanks, mon."] = "'A cresta s'è alzata ancora, {name}. Nun sapevo ca puteva. Grazie, cumpà."
L["The spirits say give it back, {name}. They nag, but they're right."] = "'E spiriti dicono 'e ricambià, {name}. So' pesante, ma teneno ragione."
L["Mojo for mojo, {name}: oldest trade in the jungle."] = "Mojo pe' mojo, {name}: 'o scambio cchiù antico d''a giungla."
L["Vol'jin said repay kindness quick, {name}. He said a lot. Dat one stuck."] = "Vol'jin diceva 'ricambia ampressa', {name}. Diceva assaje. Chesta m'è rimasta."
L["That deserves a dance, {name}. Lucky ya: {buff} instead."] = "Chesto merita 'nu ballo, {name}. Pe' furtuna toja: {buff}."
L["Jungle rule, {name}: what ya give comes back, often with teeth. Not this one."] = "Legge d''a giungla, {name}: chello ca daje torna, spisso cu 'e diente. Chisto no."
L["A gift for a troll, {name}? We never forget a kindness."] = "'Nu regalo a 'nu troll, {name}? Nuje nun scurdammo maje 'na gentilezza."
L["Sure thing, {name}. Hold still; mojo hates a movin' target."] = "Va bbuono, {name}. Nun te movere: 'o mojo odia chi se move."
L["No trouble, {name}. Da loa like ya."] = "Nisciun problema, {name}. 'E loa te vonno bene."
L["Stay away from da voodoo, {name}. Except this one. This one's fine."] = "Statte luntano d''o voodoo, {name}. Chisto no: chisto è bbuono."
L["Close ya eyes, {name}. Mojo gets shy when people watch."] = "Chiudi l'uocchie, {name}. 'O mojo è timido si 'a gente guarda."
L["Ya don't gotta ask twice, {name}. Ya barely gotta ask once."] = "Nun c'è bisogno 'e chiedere due volte, {name}. Manco una."
L["Sure, {name}. A troll is mostly swagger. The rest is this."] = "Certo, {name}. 'Nu troll è quasi tutto stile. 'O resto è chisto."
L["Ya asked polite, {name}. Polite gets the good stuff."] = "Hai chiesto cu garbo, {name}. Chi è educato se piglia 'a roba bbona."
L["Ya came to the right troll, {name}. The wrong one's over there, fishin'."] = "Hai truvato 'o troll giusto, {name}. Chillo sbagliato sta llà, a pescà."
L["Yes, {name}. The loa owe me a favour, and I'm spendin' it on you."] = "Sì, {name}. 'E loa me devono 'nu favore, e 'o spendo pe' te."
L["Got a pouch full of mojo, {name}. Don't touch the other pouch."] = "Tengo 'na sacca chiena 'e mojo, {name}. L'ata sacca nun 'a tuccà."
L["Anything for ya, {name}. Not my hair, though. Hair is sacred."] = "Tutto pe' te, {name}. Tranne 'e capille. 'E capille so' sacre."
L["Troll magic, {name}, served hot. Blow on it first."] = "Magia troll, {name}, servita calda. Sciùsciace primma."
L["Right away, {name}. A Zandalari priest would make a week of this."] = "Subbito, {name}. 'Nu prevete zandalari ce mettesse 'na semmana."
L["Easy one, {name}. Hard one's gettin' a raptor to sit still."] = "Chesto è facile, {name}. 'O difficile è fa' sta' fermo 'nu raptor."
L["Troll rule, {name}: never make a friend beg or a raptor wait. Here."] = "Regola troll, {name}: mai fa' pregà n'amico o aspettà 'nu raptor. Piglia."
L["Don't wiggle, {name}. Last one who did got the spell and a new haircut."] = "Nun te movere, {name}. L'ultimo ca l'ha fatto: magia e taglio 'e capille."
L["Da loa watch over ya, {name}. They're real nosy that way."] = "'E loa te tengono d'uocchio, {name}. So' curiuse assaje."
L["Stay sharp, {name}. Take this with ya."] = "Uocchie aperte, {name}. Portate chisto."
L["Ya look like somebody who appreciate quality, {name}. Here: quality."] = "Tieni 'a faccia 'e chi apprezza 'a qualità, {name}. Ecco: qualità."
L["Here, {name}. Walk like ya own the jungle. I do."] = "Piglia, {name}. Cammina comm'a padrone d''a giungla. Io 'o faccio."
L["Everybody need mojo, {name}. I make so much I gotta give it away."] = "A tutti serve 'o mojo, {name}. Io ne tengo accussì tanto che 'o regalo."
L["A little somethin' for ya, {name}. Don't ask where da loa got it."] = "'Nu pensierino pe' te, {name}. Nun chiedere addò l'hanno pigliato 'e loa."
L["Go on, {name}. Whatever tries to eat ya now gets indigestion."] = "Va', {name}. Mo' chi te prova a magnà se piglia 'n'indigestione."
L["Ya look dangerous now, {name}. Almost as dangerous as a troll."] = "Mo' tieni 'n'aria pericolosa, {name}. Quasi comme 'nu troll."
L["No charge, {name}. Ya don't owe the loa a thing. Probably."] = "Gratis, {name}. 'E loa nun vonno niente 'a te. Probabilmente."
L["Raptors got bigger teeth than me, {name}. Now they got a problem."] = "'E raptor teneno 'e diente cchiù gruosse d''e mie, {name}. Mo' so' guai lloro."
L["Troll hospitality, {name}: ya get mojo, ya get a smile, ya don't get my fish."] = "Ospitalità troll, {name}: mojo sì, 'nu sorriso sì, 'o pesce mio no."
L["Walk with mojo, {name}. Everybody else is just walkin'."] = "Cammina cu 'o mojo, {name}. L'ate camminano e basta."
L["Free mojo, {name}! Quick, before the witch doctor finds out."] = "Mojo gratis, {name}! Ampressa, primma ca 'o stregone se n'accorge."
L["The loa said give this to the next good soul, {name}. That's you."] = "'E loa hanno ditto: dallo 'a prossima anema bbona, {name}. Si' tu."
L["Here, {name}. Hakkar never shared. Look what happened to him."] = "Piglia, {name}. Hakkar nun spartiva maje. Vide comm'è fernuto."
L["Jungle's got two kinds of folk, {name}: ready, and lunch. You're ready."] = "'A giungla tene doje razze 'e gente, {name}: 'e pronti e 'o pranzo. Tu staje cu 'e pronti."
L["Easy, {name}. This one tickles. Don't laugh; it gets offended."] = "Chiano, {name}. Chisto fa 'o solletico. Nun ridere: s'offende."
L["Take this, {name}. Darkspear never send a friend off empty-handed."] = "Piglia, {name}. 'E Lanciascura nun mannano maje 'n'amico a mani vacante."
L["We look after our own, {name}. Always, mon."] = "Nuje penzammo a 'e nuoste, {name}. Sempe, cumpà."
L["Da rest of Azeroth stand up straight, {name}. We got more style."] = "'O resto 'e Azeroth sta dritto, {name}. Nuje tenimmo cchiù stile."
L["Ya tusks look sharp, {name}. Mine too, obviously."] = "Che zanne affilate, {name}. Pure 'e mie, se capisce."
L["Every troll's family, {name}. Even the ones who still owe me gold."] = "Ogni troll è famiglia, {name}. Pure chi me deve ancora 'e sorde."
L["One day we take the Echo Isles back from Zalazane, {name}. Together."] = "'Nu juorno ce ripigliammo 'e Isole dell'Eco da Zalazane, {name}. Insieme."
L["Two trolls, {name}. Da room just got taller and a lot more relaxed."] = "Duje troll, {name}: 'a stanza mo' è cchiù auta e cchiù tranquilla."
L["The loa got their eyes on both of us now, {name}. Behave."] = "'E loa ce tengono d'uocchio a tutt'e duje, {name}. Comportate bene."
L["Troll to troll, {name}: only we know how hard it is to buy boots."] = "Da troll a troll, {name}: sulo nuje sapimmo quant'è difficile truvà 'e stivali."
L["Our ancestors had empires, {name}. We got each other. Fair trade, I say."] = "'E nonni nuoste tenevano imperi, {name}. Nuje tenimmo a nuje. Affare fatto."
L["Stay close, {name}. Trolls regenerate; da rest of ya gotta be careful."] = "Stamme vicino, {name}. 'E troll se rigenerano; vuje no, quindi occhio."
L["Crew's got style, {name}. Now it's got mojo too."] = "Stu gruppo tene stile, {name}. E mo' pure 'o mojo."
L["We go in together, {name}, we come out together. That's the plan, mon."] = "Trasimmo 'nzieme, {name}, e ascimmo 'nzieme. Chisto è 'o piano, cumpà."
L["Nobody fallin' today, {name}. Death can wait for the next group."] = "Oggi nun cade nisciuno, {name}. 'A morte aspettasse 'o prossimo gruppo."
L["Keep ya head down, {name}. I keep mine up. Somebody gotta look good."] = "Tieni 'a capa bassa, {name}. Io 'a tengo auta: qualcuno adda fa' bella figura."
L["Raptor formation, {name}: fast, loud, and nobody look back."] = "Formazione raptor, {name}: veloci, rumorosi, e nisciuno se gira."
L["If a big snake shows up, {name}, don't run. Stand behind me."] = "Si esce 'nu serpente gruosso, {name}, nun fuì. Mettite arreto a me."
L["Need more mojo, {name}? Just shout. Not too loud; the loa are nappin'."] = "Serve cchiù mojo, {name}? Chiamame. Ma chiano: 'e loa fanno 'a pennichella."
L["They'll tell this one at Sen'jin, {name}. Let's give it a happy endin'."] = "Chesta 'a raccontano a Sen'jin, {name}. Facimmola cu 'o lieto fine."
L["My tusks are sharp, {name}, but they can't be everywhere. Stay near."] = "'E zanne meje so' affilate, {name}, ma nun stanno dappertutto. Stamme vicino."
L["Nobody panic, {name}. Panic is bad mojo. Swagger is good mojo."] = "Niente panico, {name}. 'O panico è mojo malamente. 'O stile è mojo bbuono."
L["See an idol with glowin' eyes, {name}? Don't touch it. Trust me."] = "Vide 'n'idolo cu ll'uocchie ca luceno, {name}? Nun 'o tuccà. Fidate."
L["Night's the best time for mojo, {name}. Nobody sees where it's from."] = "'A notte è 'o mumento meglio p''o mojo, {name}. Nisciuno vede 'a do' vene."
L["The jungle wakes at night, {name}. So do I. This one's fresh."] = "'A giungla se sceta 'e notte, {name}. Pure io. Chisto è frisco frisco."
L["High moon, {name}, restless spirits. This keeps 'em off ya."] = "Luna auta, {name}, spiriti irrequieti. Chisto t''e tene luntano."
L["Hir'eek the bat loa keeps late hours too, {name}. This is from us both."] = "Pure Hir'eek, 'o loa pipistrello, fa tardi, {name}. Chisto è 'a parte 'e tutt'e duje."
L["This late, {name}, only trolls and trouble are up. I'm the nice one."] = "A chest'ora, {name}, stanno scetati sulo troll e guaie. Io so' 'a parte bbona."
L["Stars out, {name}. Each one a loa, Granny said. That's a lot of watchers."] = "Ecco 'e stelle, {name}. Ognuna è 'nu loa, diceva nonna. Quant'uocchie!"
L["Such courtesy does you credit, {name}. Nearly as much as it does me."] = "Tanta cortesia ti fa onore, {name}. Quasi quanto ne fa a me."
L["How gracious, {name}. Allow me to return the favour."] = "Che gesto raffinato, {name}. Permettimi di ricambiare il favore."
L["Thank you, {name}. I haven't felt this radiant since... well, this morning."] = "Grazie, {name}. Non mi sentivo così raggiante da... be', stamattina."
L["Kind of you, {name}. We sin'dorei never turn down free magic. Ask anyone."] = "Che gentile, {name}. Un sin'dorei non rifiuta mai magia gratis. Chiedi in giro."
L["Exquisite, {name}. I would know; I only accept the exquisite."] = "Squisito, {name}. Me ne intendo: accetto solo ciò che è squisito."
L["Lovely, {name}. I'll be insufferable about this all day. More than usual."] = "Delizioso, {name}. Sarò insopportabile tutto il giorno. Più del solito."
L["Thank you, {name}. It even goes with my gold trim. You have an eye."] = "Grazie, {name}. Si abbina persino alle mie finiture dorate. Hai occhio."
L["Returned in kind, {name}. A prettier kind, admittedly. I can't help it."] = "Ricambiato, {name}. In modo più grazioso, lo ammetto. Non posso farci niente."
L["Thank you, {name}. Visit Silvermoon; I'll show you all of it but Murder Row."] = "Grazie, {name}. A Lunargenta ti mostrerò tutto, tranne il vicolo dei tagliagole."
L["Returned, {name}. Unlike Kael'thas, I give things back."] = "Ricambiato, {name}. Io, a differenza di Kael'thas, restituisco."
L["Thank you, {name}. I felt that to the tips of my ears, and that's a long way."] = "Grazie, {name}. L'ho sentito fino alla punta delle orecchie: un bel viaggio."
L["Thank you, {name}. That was so kind my eyes nearly changed colour again."] = "Grazie, {name}. Così gentile che quasi mi cambiano di nuovo colore gli occhi."
L["A gift, unasked? Farstriders would call that an ambush. A lovely one, {name}."] = "Un dono non chiesto? Per un ranger è un'imboscata. Deliziosa, {name}."
L["Better than a mana crystal, {name}, and I've given those up. Mostly. Thank you."] = "Meglio di un cristallo di mana, {name}, e io ho smesso. Quasi del tutto. Grazie."
L["Quick of you, {name}. Elves live for centuries, and you still beat me to it."] = "Che rapidità, {name}. Noi elfi viviamo secoli, eppure mi hai battuto sul tempo."
L["Charming, {name}. The sun favours the generous, and so do I."] = "Delizioso, {name}. Il sole favorisce chi è generoso, e io pure."
L["Thank you, {name}. I'll mention you at court. Well, at a very exclusive picnic."] = "Grazie, {name}. Parlerò di te a corte. Be', a un picnic molto esclusivo."
L["Thank you, {name}. Courtesy is rare outside Silvermoon. Yours shines."] = "Grazie, {name}. Fuori da Lunargenta la cortesia è rara. La tua risplende."
L["Unasked kindness, {name}! Somebody tell Rommath; he'll want to study it."] = "Gentilezza non richiesta, {name}! Qualcuno avvisi Rommath: vorrà studiarla."
L["Naturally, {name}. Only the finest for you."] = "Naturalmente, {name}. Solo il meglio per te."
L["For you, {name}? Of course. The sun gives freely."] = "Per te, {name}? Ma certo. Il sole dona senza riserve."
L["Patience, {name}. Radiance can't be rushed, only admired."] = "Pazienza, {name}. Lo splendore non si mette fretta: si ammira."
L["Of course, {name}. {buff}, delivered with impeccable posture."] = "Certo, {name}. {buff}, con un portamento impeccabile."
L["You asked nicely, {name}. In Silvermoon that counts for everything."] = "Hai chiesto con garbo, {name}. A Lunargenta è tutto ciò che conta."
L["One moment, {name}. I never cast anything without checking my hair."] = "Un momento, {name}. Non lancio mai nulla senza sistemarmi i capelli."
L["At once, {name}. Keeping someone waiting is so terribly unfashionable."] = "Subito, {name}. Far aspettare qualcuno è così terribilmente fuori moda."
L["Certainly, {name}. Stand back a step; my sleeves are enchanted and very wide."] = "Certo, {name}. Un passo indietro: le mie maniche sono incantate e molto ampie."
L["Magisters would bill you, {name}. Blood Knights would lecture. I merely glow."] = "Magistri: parcella. Cavalieri del Sangue: predica. Io, {name}? Brillo e basta."
L["At once, {name}. If it goes well, tell everyone. If not, blame the robe."] = "Subito, {name}. Se va bene, dillo a tutti. Se no, colpa della veste."
L["At once, {name}. The dragonhawk can wait; it's used to waiting while I dress."] = "Subito, {name}. Il dragofalco può aspettare: ci è abituato, mentre mi vesto."
L["Gladly, {name}. We once took the Light from a naaru. Asking is so much nicer."] = "Volentieri, {name}. Noi la Luce l'abbiamo rubata a un Naaru. Chiedere è più chic."
L["Three centuries of casting, {name}, and you're the first to say please."] = "Tre secoli di incantesimi, {name}, e nessuno prima di te ha detto per favore."
L["Gladly, {name}. Silvermoon's brooms sweep themselves, so my hands are free."] = "Volentieri, {name}. A Lunargenta le scope spazzano da sole: ho le mani libere."
L["Of course, {name}. I keep my other spells for the rude."] = "Certo, {name}. Gli altri incantesimi li tengo per i villani."
L["Anar'alah belore, {name}. May the sun guide you, and light your good side."] = "Anar'alah belore, {name}. Che il sole ti guidi, e illumini il tuo lato migliore."
L["Shorel'aran, {name}. Fight with elegance."] = "Shorel'aran, {name}. Combatti con eleganza."
L["Take this, {name}. Whatever happens out there is merely a setback."] = "Prendi, {name}. Qualunque cosa succeda là fuori, sarà solo un contrattempo."
L["Everyone deserves to shine, {name}. Only a little less than me, of course."] = "Tutti meritano di brillare, {name}. Un po' meno di me, s'intende."
L["The sun is with you, {name}. I simply held the door for it."] = "Il sole è con te, {name}. Io gli ho solo tenuto la porta."
L["Go on, {name}, take it. The Sunwell's back; we can afford to be generous."] = "Prendi pure, {name}. Il Pozzo Solare è tornato: ce lo possiamo permettere."
L["For you, {name}: {buff}, lightly scented with Silvermoon."] = "Per te, {name}: {buff}, con un leggero profumo di Lunargenta."
L["Here, {name}. Hand-cast in Silvermoon, so do try not to scuff it."] = "Tieni, {name}. Artigianato di Lunargenta: cerca di non graffiarlo."
L["A little Sunwell for you, {name}. It's been through a lot; treat it kindly."] = "Un po' di Pozzo Solare per te, {name}. Ne ha passate tante: trattalo bene."
L["Be prepared, {name}. We weren't, once, and now we have a scar for a road."] = "Preparati, {name}. Noi, una volta, no: e ora abbiamo una cicatrice per strada."
L["Here, {name}. I only give to the worthy. How convenient that you walked by."] = "Tieni, {name}. Dono solo ai meritevoli. Che combinazione: passavi proprio tu."
L["Take this, {name}. It's been in my family for moments."] = "Prendi, {name}. È in famiglia da secondi."
L["We sin'dorei have lost much, {name}. Never our generosity. Or our cheekbones."] = "Noi sin'dorei abbiamo perso molto, {name}. Mai la generosità. Né gli zigomi."
L["Take this, {name}. Should a mana wyrm follow you, it's only jealous."] = "Prendi, {name}. Se ti segue una serpe di mana, è solo invidiosa."
L["Seven thousand years to perfect generosity, {name}. We started last week."] = "Settemila anni per perfezionare la generosità, {name}. Abbiamo iniziato martedì."
L["Take this, {name}. It came through the Undercity orb, so it's slightly dizzy."] = "Prendi, {name}. È passato dal globo di Sepulcra: gli gira un po' la testa."
L["For you, {name}. It matches everything. I checked, obviously."] = "Per te, {name}. Si abbina a tutto. Ho controllato, ovviamente."
L["If a ghoul stops you, {name}, say Silvermoon's still standing. They hate that."] = "Se ti ferma un ghoul, {name}, digli che Lunargenta è ancora in piedi. Lo odiano."
L["The Sunwell shines for us both, {name}."] = "Il Pozzo Solare splende per noi due, {name}."
L["Two sin'dorei in one place, {name}. The day just got twice as elegant."] = "Due sin'dorei insieme, {name}. Eleganza raddoppiata."
L["You too, {name}? Two sin'dorei, one mirror. We'll have to take turns."] = "Anche tu, {name}? Due sin'dorei, uno specchio. Dovremo fare a turno."
L["Like the phoenix, {name}: we keep rising, and we look good doing it."] = "Come la fenice, {name}: risorgiamo sempre, e con stile."
L["Between sin'dorei, {name}: yes, the Horde is loud. Yes, we're used to it now."] = "Tra sin'dorei, {name}: sì, l'Orda è rumorosa. Sì, ormai ci siamo abituati."
L["Sin'dorei to sin'dorei, {name}: we never speak of the green eyes. Agreed?"] = "Da sin'dorei a sin'dorei, {name}: degli occhi verdi non si parla. D'accordo?"
L["Magister or Farstrider, {name}, the sun rises for us all."] = "Magistro o ranger, {name}, il sole sorge per tutti noi."
L["We both remember Quel'Thalas before the Scourge, {name}. Let's earn the after."] = "Ricordiamo entrambi Quel'Thalas prima del Flagello, {name}. Meritiamoci il dopo."
L["Do keep pace, {name}. We have a reputation for arriving beautifully."] = "Tieni il passo, {name}. Abbiamo una reputazione: arrivare con eleganza."
L["Stand where the light is good, {name}. If we must fight, we'll look splendid."] = "Mettiti in buona luce, {name}. Se si deve combattere, tanto vale essere splendidi."
L["A party at last, {name}. I did dress for one."] = "Un gruppo, finalmente, {name}. E ho l'abito da festa."
L["The sun shines on all of us, {name}. Mostly on me, but it shares."] = "Il sole splende su tutti noi, {name}. Soprattutto su di me, ma condivide."
L["One for you, {name}, and one for the party's image, which I've taken on myself."] = "Uno per te, {name}, e uno per l'immagine del gruppo, di cui mi occupo io."
L["If I fall, {name}, arrange me attractively. The rest I leave to the priest."] = "Se cado, {name}, sistemami in una posa graziosa. Al resto pensi il sacerdote."
L["Nobody touch the enchanted relics, {name}. Well, I may. I've had training."] = "Nessuno tocchi le reliquie incantate, {name}. Be', io sì: ho studiato."
L["Every expedition needs a ranger, {name}. I'm not one, but I have the boots."] = "Ogni spedizione vuole un ranger, {name}. Non lo sono, ma ho gli stivali."
L["We fight together, {name}, then tell it beautifully. I'll handle the telling."] = "Combattiamo insieme, {name}, e poi lo raccontiamo bene. Al racconto penso io."
L["Whoever mends us is to be thanked, {name}. Me, admired. Carry on."] = "Chi ci cura si ringrazia, {name}. Me, mi si ammira. Avanti."
L["If this goes badly, {name}, we blame the Scourge. It's traditional."] = "Se va male, {name}, diamo la colpa al Flagello. È tradizione."
L["Mana potions are for emergencies, {name}. I've had eleven emergencies today."] = "Le pozioni di mana sono per le emergenze, {name}. Oggi ne ho avute undici."
L["We walked out of the ashes once, {name}. We'll walk out of whatever's ahead."] = "Dalle ceneri siamo già usciti, {name}. Usciremo da qualunque cosa ci aspetti."
L["The sun has risen, {name}, and so have I. We coordinate."] = "Il sole è sorto, {name}, e io con lui. Ci coordiniamo."
L["Dawn over Quel'Thalas is lovelier, {name}, but this will do. Just."] = "L'alba su Quel'Thalas è più bella, {name}, ma questa può andare. A malapena."
L["Morning light, {name}. The most flattering hour. For both of us, naturally."] = "Luce del mattino, {name}: l'ora che dona di più. A te e a me, naturalmente."
L["Breakfast in Eversong is fruit, tea and arcane, {name}. Skip to the arcane."] = "Colazione a Cantoeterno: frutta, tè e arcano, {name}. Passa subito all'arcano."
L["Dawn, {name}. Red and gold across the sky. Somebody's been copying us."] = "L'alba, {name}. Rosso e oro in tutto il cielo. Qualcuno ci ha copiati."
L["Morning, {name}. Only Silvermoon's arcane guardians are up this early. And me."] = "Buongiorno, {name}. Così presto sono in giro solo i guardiani arcani. E io."
L["Your generosity is noted, {name}. In triplicate. Suramar remembers its friends."] = "Generosità annotata, {name}. In triplice copia. Suramar ricorda i suoi amici."
L["Most gracious, {name}. Allow me to repay you in kind."] = "Assai cortese, {name}. Permettimi di ricambiare come si conviene."
L["Thank you, {name}. Ten thousand years under a dome; I'm still practising that."] = "Grazie, {name}. Diecimila anni sotto una cupola: ci sto ancora prendendo la mano."
L["A gift with no favour owed? The court would faint. Thank you, {name}."] = "Un dono senza favori in cambio? A corte sverrebbero. Grazie, {name}."
L["Returned, {name}. We keep careful accounts of kindness. And of slights."] = "Ricambiato, {name}. Teniamo un conto preciso delle gentilezze. E degli sgarbi."
L["I'll mention you to First Arcanist Thalyssra, {name}. Favourably, even."] = "Parlerò di te alla Prima Arcanista Thalyssra, {name}. Persino bene."
L["Most kind, {name}. In Suramar we'd hold a banquet. Consider it held."] = "Molto gentile, {name}. A Suramar daremmo un banchetto. Consideralo dato."
L["I'd send a formal letter of thanks, {name}, but this seemed quicker."] = "Una lettera formale di ringraziamento, {name}? Così si fa prima."
L["In Elisande's court a gift hid a knife, {name}. Yours hides none. Thank you."] = "Alla corte di Elisande un dono nascondeva un pugnale, {name}. Il tuo no. Grazie."
L["Thank you, {name}. My manasaber approves of you, and she approves of no one."] = "Grazie, {name}. Piaci alla mia cavalcatura, e a lei non piace nessuno."
L["Exquisite, {name}. Once I'd have said 'adequate'. The world has humbled me."] = "Squisito, {name}. Un tempo avrei detto \"adeguato\". Il mondo mi ha reso umile."
L["You fed a mind that once went hungry, {name}. We never forget those who do."] = "Hai sfamato una mente che conobbe la fame, {name}. Non lo dimentichiamo."
L["Centuries of court etiquette, {name}, and 'thank you' still says it best."] = "Secoli di etichetta di corte, {name}, e un 'grazie' resta il modo migliore."
L["Thank you, {name}. You're invited to the next masquerade. Masks mandatory."] = "Grazie, {name}. Ti invito al prossimo ballo in maschera. Maschera obbligatoria."
L["Thank you, {name}. Oculeth would open a portal to say so. I'll simply cast."] = "Grazie, {name}. Oculeth aprirebbe un portale per dirlo. Io mi limito a lanciare."
L["Of course, {name}. A little arcane polish, just for you."] = "Certo, {name}. Un po' di lustro arcano, solo per te."
L["A reasonable request, {name}. Granted."] = "Una richiesta ragionevole, {name}. Concessa."
L["Certainly, {name}. The short version; the long one takes a lunar cycle."] = "Certamente, {name}. La versione breve: quella lunga richiede un ciclo lunare."
L["A request, how refreshing. The court only ever made demands. Here, {name}."] = "Una richiesta, che novità. A corte si pretendeva e basta. Ecco, {name}."
L["Done, {name}, and free. Elisande would have charged you a favour for it."] = "Fatto, {name}, e gratis. Elisande ti avrebbe chiesto un favore in cambio."
L["There, {name}. No need to bow. A small nod would be lovely, though."] = "Ecco, {name}. Non serve inchinarsi. Un cenno del capo, però, sarebbe gradito."
L["Of course, {name}. I've perfected this since before most cities had walls."] = "Certo, {name}. Lo perfeziono da prima che quasi tutte le città avessero mura."
L["Granted, {name}. I'd ask a favour back, but I'm trying to be less Suramar."] = "Concesso, {name}. Chiederei un favore in cambio, ma cerco di essere meno Suramar."
L["Certainly, {name}. Forgive the flourish. We can't cast plainly; we've tried."] = "Certo, {name}. Perdona i ghirigori: sobri non sappiamo lanciare. Ci abbiamo provato."
L["At once, {name}. Elisande once stopped time. I only need a second."] = "Subito, {name}. Elisande fermava il tempo. A me basta un secondo."
L["Of course, {name}. The ley lines here are shallow, but I'll make do."] = "Certo, {name}. Qui le linee arcane sono poco profonde, ma mi arrangio."
L["Very well, {name}. Stand in the moonlight. Or by that lamp. Lamps will do."] = "Bene, {name}. Mettiti al chiaro di luna. O sotto quel lampione. Può andare."
L["Naturally, {name}. Suramar had a spell for everything. I remember several."] = "Certo, {name}. A Suramar c'era un incantesimo per tutto. Ne ricordo qualcuno."
L["Take this, {name}. Arcane gifts are wasted on the idle."] = "Prendi, {name}. I doni arcani sono sprecati per chi sta in ozio."
L["A spark of Suramar's arcana for you, {name}. Use it wisely."] = "Una scintilla dell'arcano di Suramar, {name}. Usala con saggezza."
L["I've gone without magic once, {name}. I don't recommend it. Take this."] = "Ho già fatto a meno della magia, {name}. Non lo consiglio. Prendi."
L["The world outside the dome is so large, {name}. And so under-enchanted. Here."] = "Il mondo fuori dalla cupola è così grande, {name}. E così poco incantato. Tieni."
L["Arcwine is traditional, {name}, but {buff} travels better."] = "Il vino arcano è tradizione, {name}, ma {buff} viaggia meglio."
L["Do take this, {name}. It's rude to refuse Suramar's hospitality. Very rude."] = "Prendi pure, {name}. È scortese rifiutare l'ospitalità di Suramar. Molto scortese."
L["Here, {name}. I'm told this is how outsiders say hello. Charming custom."] = "Tieni, {name}. Mi dicono che fuori si saluta così. Usanza deliziosa."
L["Take this, {name}. Magic hoarded is magic spoiled, as Suramar learned."] = "Prendi, {name}. Magia accumulata è magia sprecata: Suramar l'ha imparato."
L["Once, I'd have made you bow for this, {name}. We've all grown."] = "Un tempo avresti dovuto inchinarti, {name}. Siamo cresciuti tutti."
L["The Kirin Tor do this too, {name}, bless them. Quite nicely, for newcomers."] = "Lo fa anche il Kirin Tor, {name}, che cari. Niente male, per dei principianti."
L["A gift from under the dome, {name}. Kept fresh for a very, very long time."] = "Un dono da sotto la cupola, {name}. Tenuto in fresco per tanto, tanto tempo."
L["Enjoy this, {name}. I used to cast it on nobility. You're an improvement."] = "Goditelo, {name}. Lo lanciavo sui nobili. Tu sei un passo avanti."
L["I packed for the outside world like a gala, {name}. Four capes. Take this."] = "Bagagli da gran gala per il mondo di fuori, {name}: quattro mantelli. Tieni."
L["Here, {name}. Suramar work: overdesigned, overdecorated, and flawless."] = "Tieni, {name}. Lavoro di Suramar: barocco, sfarzoso e impeccabile."
L["Here, {name}. In Suramar this came with a string quartet. Do hum something."] = "Tieni, {name}. A Suramar arrivava con un quartetto d'archi. Canticchia qualcosa."
L["Suramar's children shine together again, {name}."] = "I figli di Suramar tornano a brillare insieme, {name}."
L["Shal'dorei, {name}! You packed arcwine? Outsider wine is just... grapes."] = "Shal'dorei, {name}! Hai portato il vino arcano? Il vino di fuori è solo... uva."
L["Suramar's own, {name}. Try not to be too impressed by the rest of the world."] = "Siamo di Suramar, {name}. Non lasciarti impressionare troppo dal resto del mondo."
L["We survived the Legion and the withering, {name}. The rest is small talk."] = "Legione e avvizzimento superati, {name}. Il resto sono chiacchiere."
L["Our tailors made it out of Suramar too, {name}. Thank the stars."] = "Anche i nostri sarti sono usciti da Suramar, {name}. Grazie alle stelle."
L["We both remember going hungry, {name}. Never again, for either of us."] = "Ricordiamo entrambi la fame, {name}. Mai più, per nessuno dei due."
L["Out from under the dome, {name}. Is the sky still this big for you too?"] = "Fuori dalla cupola, {name}. Anche a te il cielo sembra ancora così grande?"
L["Two shal'dorei in one place, {name}. The locals will assume it's a gala."] = "Due shal'dorei insieme, {name}. La gente del posto penserà a un gala."
L["An expedition, {name}! In Suramar this needed six permits and a masquerade."] = "Una spedizione, {name}! A Suramar servivano sei permessi e un ballo in maschera."
L["The dome kept us safe, {name}. Now we must make do with one another. Gladly."] = "La cupola ci proteggeva, {name}. Ora dobbiamo arrangiarci tra noi. Con piacere."
L["Arcane for everyone, {name}. The court would call it waste. I call it company."] = "Arcano per tutti, {name}. A corte lo chiamerebbero spreco. Io lo chiamo compagnia."
L["Do follow my lead, {name}. I've had ten thousand years of walking in step."] = "Seguimi pure, {name}. Ho diecimila anni di passo cadenzato alle spalle."
L["In a party one shares one's magic, {name}. How novel. I rather like it."] = "In gruppo si condivide la magia, {name}. Che novità. Mi piace, direi."
L["An outing is like a masquerade, {name}: smile, keep moving, watch for knives."] = "Una spedizione è un ballo in maschera, {name}: sorridi, muoviti, occhio ai pugnali."
L["Stay in the light of my spells, {name}. It's the most flattering in the party."] = "Resta alla luce dei miei incantesimi, {name}: è quella che dona di più."
L["After Elisande's court, {name}, this outing is a holiday. Nobody plots."] = "Dopo la corte di Elisande, {name}, questa uscita è una vacanza. Nessuno trama."
L["Lost? Follow the one who glows, {name}. That's me. It's always me."] = "Non trovi la strada? Segui chi brilla, {name}. Sono io. Sempre io."
L["If I start lecturing on ley lines, {name}, do interrupt. Politely."] = "Se parto con le linee arcane, {name}, interrompimi. Con garbo."
L["I watched my people wither, {name}. I won't watch friends fade. Nobody falls."] = "Ho visto avvizzire il mio popolo, {name}. Gli amici no. Oggi non cade nessuno."
L["Tell me if I'm being grand, {name}. I lose track. It's the millennia."] = "Avvisami se divento solenne, {name}. Perdo il conto. Sono i millenni."
L["Night at last, {name}. Add a few thousand lanterns and it's nearly Suramar."] = "Finalmente notte, {name}. Aggiungi qualche migliaio di lanterne ed è quasi Suramar."
L["Under the dome it was always night, {name}. I feel quite at home."] = "Sotto la cupola era sempre notte, {name}. Mi sento proprio a casa."
L["The stars are out, {name}. We had better ones in Suramar. These will do."] = "Sono uscite le stelle, {name}. A Suramar erano più belle. Queste possono andare."
L["Nightborne, {name}, and here's the night. At last I'm dressed for the hour."] = "Noi Nobili Oscuri, {name}, e finalmente è buio. Ho l'abito giusto per l'ora."
L["At this hour, {name}, Suramar was only just getting dressed for dinner."] = "A quest'ora, {name}, Suramar si stava appena vestendo per la cena."
L["Daylight, {name}. Ten thousand years under a dome, and it still startles me."] = "La luce del giorno, {name}. Diecimila anni sotto una cupola, e ancora mi sorprende."
L["An early hour, {name}. The court never rose before noon. I'm reforming."] = "Di buon'ora, {name}. A corte ci si alzava a mezzogiorno. Sto cambiando."
L["Morning, {name}. The sun here is so very... unenchanted. Take this instead."] = "Buongiorno, {name}. Il sole qui è così... disincantato. Prendi questo, piuttosto."
L["Morning, {name}. We warded Suramar against every threat but the sun."] = "Buongiorno, {name}. Suramar aveva difese contro tutto, tranne il sole."
L["Dawn, {name}: when the court's gossip went to bed. Here's mine: you look well."] = "All'alba, a corte, i pettegolezzi andavano a letto, {name}. Ecco il mio: stai bene."
L["A favour for a favour, {name}! Pleasure doing business."] = "Favore per favore, {name}! È un piacere fare affari con te."
L["Thanks, {name}! Consider your account settled in full."] = "Grazie, {name}! Il tuo conto è saldato per intero."
L["Aw, {name}. I'd invoice you, but I'm feeling sentimental. It'll pass."] = "Oh, {name}. Ti farei la fattura, ma oggi sono sentimentale. Passerà."
L["Thanks, {name}! I checked it for fine print. There wasn't any. Weird!"] = "Grazie, {name}! Ho cercato le clausole in piccolo. Niente. Strano!"
L["Returned with interest, {name}. Minus the interest. Don't get used to it."] = "Ricambiato con gli interessi, {name}. Interessi esclusi. Non ci fare l'abitudine."
L["Much obliged, {name}! You've just been upgraded to preferred customer."] = "Grazie mille, {name}! Da oggi hai la tessera cliente oro."
L["I'd name a rocket after you, {name}, but my rockets never last long. Thanks!"] = "Ti dedicherei un razzo, {name}, ma i miei razzi non durano mai molto. Grazie!"
L["I'd have charged fifty gold for that, {name}. Let's call us even."] = "Io l'avrei fatto pagare cinquanta d'oro, {name}. Facciamo pari."
L["Thanks, {name}! Quick hands. You'd do well in Booty Bay."] = "Grazie, {name}! Mani svelte. A Baia del Bottino faresti carriera."
L["A deal where both sides profit, {name}! I'd heard of those. Never seen one."] = "Un affare vantaggioso per entrambi, {name}! Me ne avevano parlato. Mai visto."
L["First free gift since Kezan blew up, {name}. Returning it before I price it."] = "Primo omaggio dal botto di Kezan, {name}. Lo ricambio prima di prezzarlo."
L["Thanks, {name}! I appraised it at priceless. Here's one appraised the same."] = "Grazie, {name}! L'ho stimato: inestimabile. Eccone uno di pari valore."
L["Kindness in, kindness out, {name}. Best returns since the kaja'mite boom."] = "Dai gentilezza, ricevi gentilezza, {name}. Rendimenti da boom della kaja'mite."
L["Even trade, {name}? My accountant just fainted. He does that around fair deals."] = "Alla pari, {name}? Il mio contabile è svenuto. Gli capita, con gli affari onesti."
L["Thanks, {name}! I'd shake on it, but I count my fingers after. Habit, not you."] = "Grazie, {name}! Ti darei la mano, ma poi conto le dita. Abitudine, non sfiducia."
L["Thanks, {name}! Gadgetzan could use a few more like you."] = "Grazie, {name}! A Meccania servirebbe qualcun altro come te."
L["You got it, {name}! Time is money, friend!"] = "Detto fatto, {name}! Il tempo è denaro, amico!"
L["Deal, {name}! I'll put it on your tab. Kidding!"] = "Affare fatto, {name}! Lo metto sul tuo conto. Scherzo!"
L["Right away, {name}! Satisfaction guaranteed or your {buff} back."] = "Subito, {name}! {buff}: soddisfatti o rimborsati."
L["{buff}, {name}! Tips optional. Encouraged. Optional."] = "{buff}, {name}! Mancia facoltativa. Gradita. Facoltativa."
L["Fast, cheap or good, {name}? Today you get all three. Don't spread it around."] = "Veloce, economico o fatto bene, {name}? Oggi tutti e tre. Non spargere la voce."
L["Sure thing, {name}! No explosions this time, I promise. Mostly promise."] = "Certo, {name}! Niente esplosioni stavolta, promesso. Quasi promesso."
L["For you, {name}? No charge. Put that in writing and I'll deny it."] = "Per te, {name}? Gratis. Mettilo per iscritto e negherò tutto."
L["Sure, {name}! Quote's zero gold. Lowest I've ever quoted. It stings a little."] = "Certo, {name}! Preventivo: zero oro. Il più basso della mia vita. Brucia un po'."
L["Coming up, {name}! Full warranty included. Valid until it wears off."] = "Arriva, {name}! Garanzia totale inclusa. Valida finché non svanisce."
L["Sure, {name}! I'd tinker with it, but you look in a hurry."] = "Certo, {name}! Ci smanetterei sopra, ma sembri di fretta."
L["Easy, {name}. Steamwheedle rule: keep customers alive. They pay longer."] = "Facile, {name}. Regola del cartello: i clienti vivi pagano più a lungo."
L["Gadgetzan's got the water trade, {name}. I've got this. Better margins."] = "Meccania ha il commercio dell'acqua, {name}. Io ho questo. Margini migliori."
L["Kezan standard, {name}: fast, loud, and done before you read the terms."] = "Qualità Kezan, {name}: rapido, rumoroso, e fatto prima di leggere le clausole."
L["On it, {name}! Goblins never keep a customer waiting. Unless it pays."] = "Subito, {name}! Un goblin non fa mai aspettare un cliente. A meno che non convenga."
L["This one's on the house, {name}. Don't tell the Trade Prince."] = "Questo lo offre la casa, {name}. Non dirlo al Principe del Commercio."
L["Top-shelf stuff, zero fees, {name}. Today only!"] = "Roba di prima scelta, zero commissioni, {name}. Solo per oggi!"
L["Free sample, {name}! If you like it, you know where to find me."] = "Campione omaggio, {name}! Se ti piace, sai dove trovarmi."
L["Here, {name}. If anything explodes near you today, that was unrelated."] = "Tieni, {name}. Se oggi ti esplode qualcosa vicino, io non c'entro."
L["Goodwill's an asset, {name}. Here's some {buff} for my books."] = "Anche la simpatia va a bilancio, {name}. Ecco {buff}."
L["Take this, {name}. Safety first! Or third. It's on the list somewhere."] = "Prendi, {name}. Prima la sicurezza! O terza. È in lista, da qualche parte."
L["Cast in record time, {name}! The record's mine. I set it just now."] = "Lanciato a tempo di record, {name}! Il record è mio. L'ho appena stabilito."
L["Kaja'Cola gives you ideas, {name}. This does the rest. Take it!"] = "Kaja'Cola ti dà le idee, {name}. Questo fa il resto. Prendi!"
L["Here, {name}. Go make your fortune. I'll want a cut."] = "Tieni, {name}. Va' a fare fortuna. Voglio la mia percentuale."
L["Zeppelin's late again, {name}, so I've time to be generous."] = "Zeppelin di nuovo in ritardo, {name}: ho tempo per un gesto generoso."
L["Here, {name}. Patent pending. Try it out and tell your rich friends."] = "Tieni, {name}. Brevetto depositato. Provalo e parlane ai tuoi amici ricchi."
L["Consider this an investment, {name}. In you. I expect heroic returns."] = "Consideralo un investimento, {name}. Su di te. Mi aspetto rendimenti eroici."
L["Take it, {name}! My last shipment sank off Kezan, so everything's clearance."] = "Prendi, {name}! L'ultimo carico è affondato al largo di Kezan: tutto in svendita."
L["The Venture Company charges for this, {name}. I'm the competition. Here."] = "Gli altri goblin te lo fanno pagare, {name}. Io sono la concorrenza. Tieni."
L["Every goblin has a soft spot, {name}. Mine's small and guarded. You found it."] = "Ogni goblin ha un debole, {name}. Il mio è piccolo e blindato. L'hai trovato."
L["Take this, {name}. It's the only thing I own with no lien on it."] = "Prendi, {name}. È l'unica cosa che ho senza un'ipoteca sopra."
L["You'll be rich someday, {name}. I can tell. Remember who gave you this."] = "Un giorno farai fortuna, {name}. Si vede. Ricordati chi ti ha dato questo."
L["Anything for a fellow entrepreneur, {name}!"] = "Tutto per un collega imprenditore, {name}!"
L["Kezan's finest, together again, {name}. Keep a hand on your coin purse."] = "Il meglio di Kezan, di nuovo insieme, {name}. Tieni una mano sul borsello."
L["Fellow goblin, {name}? Then you know this is a very, very rare discount."] = "Anche tu goblin, {name}? Allora sai che questo è uno sconto rarissimo."
L["Goblins look after goblins, {name}. It's cheaper than hiring guards."] = "I goblin badano ai goblin, {name}. Costa meno che assumere guardie."
L["Kezan's gone, {name}, but the greed made it out. Look at us."] = "Kezan non c'è più, {name}, ma l'avidità si è salvata. Guardaci."
L["Between goblins, {name}, this never happened. I have a reputation."] = "Tra goblin, {name}, questo non è mai successo. Ho una reputazione."
L["Bilgewater or Steamwheedle, {name}, we always float to the top. Like oil."] = "Acquasporca o altri cartelli, {name}, veniamo sempre a galla. Come l'olio."
L["Remember the volcano, {name}? We sold tickets to it. Proud times."] = "Ti ricordi il vulcano, {name}? Vendevamo i biglietti. Bei tempi."
L["Group rate, {name}! Everybody here gets it half off. Of free."] = "Tariffa di gruppo, {name}! Tutti a metà prezzo. Metà di gratis."
L["Nobody dies on my contract, {name}. The paperwork's a nightmare."] = "Col mio contratto non muore nessuno, {name}. Troppe scartoffie."
L["We split the take even, {name}. I'll do the maths. Trust me."] = "Si divide in parti uguali, {name}. I conti li faccio io. Fidati."
L["There, {name}. Everyone's stronger, and everyone owes me. Invoices later."] = "Ecco, {name}. Tutti più forti, e tutti in debito con me. Le fatture dopo."
L["Stick together, {name}. Mercenaries cost gold; friends only cost this."] = "Restiamo uniti, {name}. I mercenari costano oro; gli amici solo questo."
L["Everybody's covered, {name}. Not insured, mind. Covered. Different price."] = "Tutti coperti, {name}. Non assicurati, eh. Coperti. Prezzo diverso."
L["I read the risk report on this outing, {name}. Short read. It just says 'no'."] = "Ho letto il rapporto sui rischi, {name}. Lettura breve. Dice solo \"no\"."
L["Nobody touches the big red lever, {name}. There's always a big red lever."] = "Nessuno tocchi la grossa leva rossa, {name}. C'è sempre una grossa leva rossa."
L["If this goes south, {name}, I've got a rocket. Seats one. I'm working on it."] = "Se si mette male, {name}, ho un razzo. Un posto solo. Ci sto lavorando."
L["We're a company now, {name}. I'm treasurer. The vote was unanimous. Mine."] = "Ora siamo una società, {name}. La cassa la tengo io. Voto unanime: il mio."
L["Stay alive, {name}. Nobody's found a way to sell resurrections yet. I'm trying."] = "Non morire, {name}. Le resurrezioni non si possono ancora vendere. Ci sto provando."
L["Stay close, {name}. I've already sold the story of this trip. Make it good."] = "Stammi vicino, {name}. Ho già venduto la storia di questo viaggio. Che sia bella."
L["Early bird gets the gold, {name}! Here's a freebie. Don't tell the other birds."] = "Il mattino ha l'oro in bocca, {name}! Un omaggio. Non dirlo a chi dorme."
L["Morning, {name}! Markets open in an hour. Until then, I'm feeling generous."] = "Buongiorno, {name}! I mercati aprono tra un'ora. Fino ad allora, offro io."
L["Up early, {name}? Smart. Time is money, and it's cheapest in the morning."] = "Già in piedi, {name}? Mossa furba. Il tempo è denaro, e al mattino costa meno."
L["Dawn, {name}. Rich goblins sleep in. I'm not rich yet."] = "L'alba, {name}. I goblin ricchi dormono fino a tardi. Io non ancora."
L["Fresh day, fresh ledger, {name}. You're the first entry. The good column."] = "Giorno nuovo, registro nuovo, {name}. Sei la prima voce. Nella colonna buona."
L["Thank you, {name}! The caravan always repays a kindness. Usually in string."] = "Grazie, {name}! La carovana ricambia sempre una gentilezza. Di solito in spago."
L["How kind, {name}! You're on the caravan's good list now."] = "Che gentile, {name}! Ora sei nella lista dei buoni della carovana."
L["Oh, I'll keep this, {name}! I keep everything. Here's one for you."] = "Oh, questo me lo tengo, {name}! Io tengo tutto. Eccone uno per te."
L["Thanks, {name}! Here's yours back. Well, a new one. Hardly used."] = "Grazie, {name}! Te lo rendo. Be', uno nuovo. Usato pochissimo."
L["My ears just went straight up, {name}. That means I'm very pleased."] = "Mi si sono drizzate le orecchie, {name}. Vuol dire che sono al settimo cielo."
L["By tonight's campfire, {name}, this story will have a sandworm in it. Thanks!"] = "Al falò di stasera, {name}, questa storia avrà un verme delle sabbie. Grazie!"
L["I'd gift-wrap yours, {name}, but all my wrapping is somebody's old map."] = "Te lo incarterei, {name}, ma la mia carta regalo è la vecchia mappa di qualcuno."
L["The alpacas saw that, {name}. They'll tell everyone how nice you are. Thanks!"] = "Gli alpaca hanno visto, {name}. Diranno a tutti quanto sei gentile. Grazie!"
L["Thank you, {name}! I'd give you my best button, but this is better. Slightly."] = "Grazie, {name}! Ti darei il mio bottone più bello, ma questo è meglio. Di poco."
L["Ooh, a present, {name}! I'll trade you one of mine."] = "Oh, un regalo, {name}! Te ne scambio uno dei miei."
L["Thanks, {name}! That goes in the good pouch. Not the rock pouch. The good one."] = "Grazie, {name}! Va nel sacchetto buono. Non in quello dei sassi. Quello buono."
L["In Vol'dun that would've cost a whole waterskin, {name}. Thank you!"] = "A Vol'dun questo sarebbe costato un otre intero, {name}. Grazie!"
L["Thanks, {name}! Your name goes on the wagon. Between the alpaca and the dent."] = "Grazie, {name}! Scrivo il tuo nome sul carro. Tra l'alpaca e l'ammaccatura."
L["Kindness is the one thing the desert never buried, {name}. Thank you."] = "Il deserto ha sepolto tutto, {name}, tranne la gentilezza. Grazie."
L["Rakera says repay quick, {name}, before you forget which pocket it's in. Here!"] = "Rakera dice: ricambia in fretta, {name}, prima di perderlo in qualche tasca. Ecco!"
L["Nobody's given me anything I didn't dig up first, {name}. Thank you!"] = "Mai ricevuto niente che non avessi prima dissotterrato, {name}. Grazie!"
L["Of course, {name}! Shake the sand out and hold still."] = "Certo, {name}! Scuoti via la sabbia e non muoverti."
L["Coming right up, {name}! Caravan service, no waiting."] = "Arriva subito, {name}! Servizio carovana, niente attese."
L["Sure, {name}! Let me dig it out... rope, rocks, a nice rock... here it is!"] = "Certo, {name}! Fammi cercare... corda, sassi, un bel sasso... eccolo!"
L["Hold on, {name}! Tail's in the way, one moment... there!"] = "Aspetta, {name}! La coda è d'intralcio, un attimo... ecco!"
L["One {buff}, {name}! Only slightly sandy."] = "{buff} per te, {name}! Con appena un po' di sabbia."
L["Ask a vulpera and you'll get something, {name}. Usually odd. Not today!"] = "Chiedi a un vulpera e ricevi qualcosa, {name}. Di solito strano. Oggi no!"
L["Yours, {name}! Vulpera love giving things. Almost as much as finding them."] = "Tuo, {name}! Ai vulpera piace regalare. Quasi quanto trovare."
L["Here, {name}! Patched it up myself. Holds better than it looks."] = "Ecco, {name}! L'ho rattoppato io. Tiene meglio di come sembra."
L["Sure, {name}! Stand upwind. Sandstorm last week; I'm still shedding it."] = "Certo, {name}! Stai sopravvento: ho ancora mezza tempesta di sabbia nel pelo."
L["YES! Sorry, {name}, too loud? The desert's very big. You have to shout in it."] = "SÌ! Scusa, {name}, troppo forte? Il deserto è grande. Lì bisogna urlare."
L["Of course, {name}. Caravan rule: nobody asks twice for water or for help."] = "Certo, {name}. Regola della carovana: acqua e aiuto non si chiedono due volte."
L["On it, {name}! Small spell, big fox, bigger ears. Wait. Other way round."] = "Subito, {name}! Magia piccola, volpe grossa, orecchie enormi. Anzi, viceversa."
L["For you, {name}? Easy! Caravan folk never say no to a neighbour."] = "Per te, {name}? Facile! Chi vive in carovana non dice mai di no a un vicino."
L["Every traveller needs something for the road, {name}. I checked: not a rock."] = "Ogni viandante merita qualcosa per il viaggio, {name}. Controllato: niente sassi."
L["Keep this, {name}. The desert is long and the water is short."] = "Tienilo, {name}. Il deserto è lungo e l'acqua è poca."
L["Found this lying around, {name}. Kidding! It's fresh. Take it!"] = "L'ho trovato per terra, {name}. Scherzo! È fresco. Prendi!"
L["Here, {name}. Best thing in my pack, and I've got a lot of pack."] = "Tieni, {name}. La cosa migliore nel mio zaino, e di zaino ne ho parecchio."
L["In the dunes you share your shade and your spells, {name}. Here."] = "Tra le dune si condividono l'ombra e gli incantesimi, {name}. Tieni."
L["Some {buff} for you, {name}. I'd haggle, but you look busy."] = "Un po' di {buff} per te, {name}. Contratterei, ma hai da fare."
L["A gift from the whole caravan, {name}! They'll never know."] = "Un regalo da tutta la carovana, {name}! Non lo sapranno mai."
L["For the road, {name}. Roads are the best part. Roads, and snacks."] = "Per la strada, {name}. La strada è il bello. La strada, e gli spuntini."
L["Here, {name}! I swapped a hat for a thing, and the thing for this. Good trade!"] = "Tieni, {name}! Cappello per un coso, coso per questo. Affarone!"
L["Nobody walks past anybody in the dunes, {name}. Bad luck, and rude. Here."] = "Tra le dune non si ignora nessuno, {name}. Porta sfortuna, ed è scortese. Tieni."
L["My nose says trouble's ahead of you, {name}. Take this. My nose is never wrong."] = "Il mio naso fiuta guai davanti a te, {name}. Prendi. Il mio naso non sbaglia mai."
L["Too many spells in my pack, {name}. They jingle. Take one, please."] = "Troppi incantesimi nello zaino, {name}. Tintinnano. Prendine uno, dai."
L["If you find anything shiny later, {name}, you know where my ears are. Here!"] = "Se poi trovi qualcosa che luccica, {name}, sai dove sono le mie orecchie. Tieni!"
L["Wait, {name}! You nearly left without this. Deserts eat people who do that."] = "Aspetta, {name}! Stavi per andartene senza. Il deserto si mangia chi lo fa."
L["Stew's not ready yet, {name}, so this is the starter."] = "Lo stufato non è pronto, {name}: intanto, l'antipasto."
L["A fellow wanderer! The caravan is never far, {name}."] = "Un compagno di strada! La carovana non è mai lontana, {name}."
L["Ears up, {name}! Always nice to share a spell with a fellow fox."] = "Orecchie dritte, {name}! Un incantesimo tra volpi è sempre un piacere."
L["One vulpera to another, {name}: I've three spare spoons if you need one."] = "Da vulpera a vulpera, {name}: ho tre cucchiai di scorta, se ti serve."
L["Vol'dun raised us both, {name}. Sand in the fur, luck in the pack."] = "Siamo figli di Vol'dun, {name}. Sabbia nel pelo, fortuna nello zaino."
L["Ears to ears, {name}: between us we've heard everything said in this place."] = "Da orecchie a orecchie, {name}: in due abbiamo sentito ogni parola detta qui."
L["Remember the caravan fires, {name}? Everybody sang badly. It was perfect."] = "Ti ricordi i falò della carovana, {name}? Tutti stonati. Era perfetto."
L["Vol'dun's far behind us, {name}. Half of it followed us here in our fur."] = "Vol'dun è ormai alle spalle, {name}. Metà ce la siamo portata nel pelo."
L["Caravan rules, {name}: stay together, share the water, nobody sells the alpaca."] = "Regole della carovana, {name}: uniti, acqua per tutti, e l'alpaca non si vende."
L["Anything shiny in there, {name}, I saw it first. Caravan law."] = "Se luccica, {name}, l'ho visto prima io. Legge della carovana."
L["One for the party, {name}! A caravan's only as fast as its slowest alpaca."] = "Uno per il gruppo, {name}! Una carovana va veloce quanto il suo alpaca più lento."
L["Keep your pack shut, {name}. I don't mean to take things. They follow me."] = "Chiudi lo zaino, {name}. Non prendo le cose apposta: sono loro che mi seguono."
L["Lost in a city, {name}, never in a cave. Caves are just houses with no rent."] = "In città mi perdo, {name}, in grotta mai. Le grotte sono case senza affitto."
L["I'm small, {name}, so I'll check the tiny tunnels. You lot take the big ones."] = "Taglia piccola, {name}: controllo io i cunicoli. Voi prendete i tunnel grandi."
L["Shout if you need anything, {name}. I've probably got it. It's probably dented."] = "Ti serve qualcosa, {name}? Chiedi. Forse ce l'ho. Forse è ammaccato."
L["I'll take the back, {name}. Nobody gets left behind in a caravan."] = "Io sto in coda, {name}. In carovana nessuno resta indietro."
L["A caravan with no wagon, {name}! Very fast. Very light. Nowhere to nap."] = "Carovana senza carro, {name}! Velocissima. Leggerissima. Pisolini: zero."
L["Scouted ahead, {name}. By nose. Smells of danger and very old cheese."] = "Perlustrato, {name}. A naso. Sa di pericolo e di formaggio stravecchio."
L["Everybody fed? Everybody watered? Good. Now this, {name}. Caravan order."] = "Tutti sazi? Tutti dissetati? Bene. Ora questo, {name}. Legge di carovana."
L["We vulpera travel by night, {name}. Cool sand, sleepy scorpids."] = "Noi vulpera viaggiamo di notte, {name}. Sabbia fresca, scorpidi assonnati."
L["Desert nights get cold, {name}. Here, something warm-ish."] = "Di notte il deserto gela, {name}. Ecco qualcosa di tiepidino."
L["Stars out, {name}. Every one's a signpost if you know how to read it. I don't."] = "Ecco le stelle, {name}. Ognuna è un cartello, se sai leggerla. Io no."
L["Good hour for foxes, {name}. The ears work best when everything's quiet."] = "L'ora delle volpi, {name}. Nel silenzio le orecchie rendono al massimo."
L["Past dark and I'm just waking up, {name}. In the dunes, noon's for napping."] = "Fa buio e io mi alzo ora, {name}. Tra le dune, a mezzogiorno si fa la pennica."
L["I'll curl up in my tail later, {name}. Best blanket I own. First, this."] = "Poi mi acciambello nella coda, {name}: coperta perfetta. Prima, questo."
L["A kindness returned is a kindness doubled, {name}."] = "Una gentilezza ricambiata è una gentilezza raddoppiata, {name}."
L["Thank you, {name}. You have restored my balance."] = "Grazie, {name}. Hai ristabilito il mio equilibrio."
L["Somewhere, a Sha just went hungry. Thank you, {name}."] = "Da qualche parte, uno Sha è rimasto a digiuno. Grazie, {name}."
L["Thank you, {name}. Aysa would bow, Ji would cheer. I will do both, badly."] = "Grazie, {name}. Aysa farebbe un inchino, Ji esulterebbe. Io, tutti e due. Male."
L["Thank you, {name}. I will think of you at my next meal, and the one after."] = "Grazie, {name}. Ti penserò al prossimo pasto, e a quello dopo."
L["Chen always said: never refuse a gift. Or a drink. Thank you, {name}."] = "Chen diceva sempre: mai rifiutare un dono. O un bicchiere. Grazie, {name}."
L["I was about to nap, {name}, but this is better. Slightly. Thank you."] = "Stavo per fare un pisolino, {name}, ma questo è meglio. Di poco. Grazie."
L["A hozen would have thrown something, {name}. I was raised better. Thank you."] = "Un hozen ti avrebbe tirato qualcosa, {name}. Io ho più educazione. Grazie."
L["That was very pandaren of you, {name}. All that's missing is a dumpling."] = "Un gesto molto pandaren, {name}. Manca solo un raviolo."
L["At Halfhill that earns a prize turnip, {name}. I left mine at home. Thank you."] = "In Pandaria varrebbe una rapa da concorso, {name}. È rimasta a casa. Grazie."
L["Grandmother kept a jar of kindnesses, {name}. Yours goes in; this comes out."] = "La nonna teneva un barattolo di gentilezze, {name}. La tua entra, questo esce."
L["Thank you, {name}. In the Jade Forest my door is open, and my pantry more so."] = "Grazie, {name}. Alla Foresta di Giada porta aperta, e dispensa spalancata."
L["You move like the Shado-Pan, {name}. I never saw that coming. Thank you."] = "Ti muovi come uno Shado-Pan, {name}. Non ti ho visto arrivare. Grazie."
L["Like rain on a rice paddy, {name}. The paddy never says thank you. I do."] = "Come pioggia sulla risaia, {name}. La risaia non dice mai grazie. Io sì."
L["Thank you, {name}. Li Li would put this in her travel journal. With drawings."] = "Grazie, {name}. Li Li lo metterebbe nel suo diario di viaggio. Con i disegni."
L["Thank you, {name}. The August Celestials are busy, so I thank you for all four."] = "Grazie, {name}. I Celestiali sono impegnati: ringrazio io per tutti e quattro."
L["Stormstout ale knocks a pandaren flat, {name}. So did that. Thank you."] = "Solo la birra di Chen stende un pandaren, {name}. E ora anche tu. Grazie."
L["Now we are even, {name}. A pandaren never lets a kindness go cold."] = "Ora siamo pari, {name}. Un pandaren non lascia mai raffreddare una gentilezza."
L["Of course, {name}. Patience, and it is done. Patience is the slow part."] = "Certo, {name}. Un po' di pazienza, ed è fatto. La pazienza è la parte lenta."
L["With pleasure, {name}. A kind deed is never wasted."] = "Con piacere, {name}. Una buona azione non è mai sprecata."
L["At once, {name}. Quick for a pandaren, which is not saying much."] = "Subito, {name}. Veloce per un pandaren, il che non vuol dire molto."
L["Master Shang Xi said: help whoever asks, {name}. I listened."] = "Maestro Shang Xi diceva: aiuta chi chiede, {name}. Io l'ho ascoltato."
L["A Tushui master would make you meditate first, {name}. I will skip that part."] = "Un maestro Tushui ti farebbe prima meditare, {name}. Io salto questa parte."
L["Anything for you, {name}. Except the last dumpling. Let us not be silly."] = "Tutto per te, {name}. Tranne l'ultimo raviolo. Non esageriamo."
L["One {buff}, {name}, brewed strong. The recipe stays a secret."] = "{buff} per te, {name}, in infusione forte. La ricetta resta segreta."
L["Stand like a crane, {name}: one leg, calm face. Two legs is also fine."] = "Posizione della gru, {name}: una gamba, viso sereno. Anche due vanno bene."
L["We never refuse a request, {name}. Or a second helping."] = "Non rifiutiamo mai una richiesta, {name}. Né il bis."
L["The last to ask me for help, {name}, was an island-sized turtle. You're easier."] = "Prima di te aiutai una tartaruga grande come un'isola, {name}. Con te è facile."
L["Pandaren help like we cook, {name}: slowly, generously, and far too much of it."] = "Noi pandaren aiutiamo come cuciniamo, {name}: piano, di cuore e sempre troppo."
L["Certainly, {name}. Let me put down my bowl. ...There. That was the hard part."] = "Certo, {name}. Fammi posare la ciotola. ...Ecco. Quella era la parte difficile."
L["Yes, {name}. Grandfather said never make guests ask twice. He said it twice."] = "Sì, {name}. Mai far chiedere due volte, diceva il nonno. Due volte."
L["Hold still, {name}. I am calm, you are calm, the spell is calm. Nobody panic."] = "Non muoverti, {name}. Calma io, calma tu, calma l'incantesimo. Niente panico."
L["Take this, {name}. And perhaps a cup of tea afterward?"] = "Prendi, {name}. E dopo, magari, una tazza di tè?"
L["Balance in all things, {name}. Now go with a light heart."] = "Equilibrio in ogni cosa, {name}. Ora va' con il cuore leggero."
L["Take this, {name}. A grummle would sell it to you for a luckydo."] = "Prendi, {name}. Un grummle te lo venderebbe in cambio di un portafortuna."
L["The jinyu say the waters foretold this, {name}. They say that a lot."] = "I jinyu dicono che le acque l'avevano predetto, {name}. Lo dicono spesso."
L["The Huojin say act first. The Tushui say think first. I say: here, {name}."] = "Gli Huojin dicono: prima agisci. I Tushui: prima pensa. Io dico: tieni, {name}."
L["A pandaren stood up to give you this, {name}. Treasure it."] = "Un pandaren si è alzato per darti questo, {name}. Fanne tesoro."
L["Fight like a monk, {name}: calm, quick, and then a long lunch."] = "Combatti come un monaco, {name}: calma, rapidità, e poi un lungo pranzo."
L["Go gently, {name}. The turtle got where it was going and never hurried once."] = "Chi va piano va sano e va lontano, {name}. Chiedilo alla tartaruga."
L["A hug would be forward, {name}. This is next best, and less furry."] = "Un abbraccio sarebbe troppo, {name}. Questo ci va vicino, e perde meno pelo."
L["If a fight finds you, {name}, roll away. Rolling is very underrated."] = "Se la rissa ti trova, {name}, rotola via. Rotolare è sottovalutato."
L["For you, {name}. It is warm, round and full of good intentions. Like me."] = "Per te, {name}. È caldo, rotondo e pieno di buone intenzioni. Come me."
L["Take this, {name}. My kite is stuck in a tree, so I have time for good deeds."] = "Prendi, {name}. L'aquilone è finito su un albero: ho tempo per le buone azioni."
L["I carried this from Pandaria, {name}. Also a keg. The keg is mine."] = "Portato fin da Pandaria, {name}. Con un barile. Il barile è mio."
L["The virmen stole my carrots, {name}, but this they will never get. Here."] = "I virmen mi hanno preso le carote, {name}, ma questo mai. Tieni."
L["On the Wandering Isle, {name}, strangers get soup. This travels better."] = "Sull'Isola Errante si offre zuppa, {name}. Questo si rovescia meno."
L["Pandaren look soft, {name}. So does a sack of rice, until it lands on you."] = "Sembriamo morbidi, {name}. Anche un sacco di riso, finché non ti cade addosso."
L["Chi-Ji says there is always hope, {name}. I say there is always a spare. Here."] = "Per Chi-Ji c'è sempre speranza, {name}. Per me c'è sempre una scorta. Tieni."
L["We must share a brew when the road allows, {name}!"] = "Dobbiamo farci una birra quando la strada lo permette, {name}!"
L["Shen-zin Su would be proud of us both, {name}. Or asleep. Hard to tell."] = "Shen-zin Su sarebbe fiero di noi, {name}. O dormirebbe. Difficile dirlo."
L["Two pandaren together, {name}. Somewhere, an innkeeper just felt a chill."] = "Due pandaren insieme, {name}. Da qualche parte, un oste rabbrividisce."
L["Liu Lang would approve, {name}: two of us, both a long way from home."] = "Liu Lang approverebbe, {name}: noi due, così lontano da casa."
L["Tushui or Huojin, {name}, we both left the turtle, and we both miss the food."] = "Tushui o Huojin, {name}, abbiamo lasciato la tartaruga, e ci manca la cucina."
L["One pandaren to another, {name}: the brews out here are thin. Share mine later."] = "Da pandaren a pandaren, {name}: qui la birra è acqua. Più tardi offro io."
L["We both smell of rice wine and road dust, {name}. The smell of home."] = "Odoriamo tutti e due di vino di riso e polvere, {name}. Profumo di casa."
L["Pandaren look after pandaren, {name}. Mostly by feeding them. This comes first."] = "Tra pandaren ci si aiuta, {name}. Soprattutto a tavola. Prima, questo."
L["A fight, then a meal, {name}. That is the correct order. Never the reverse."] = "Prima si combatte, poi si mangia, {name}. Mai il contrario."
L["Stay together, {name}, like dumplings in a steamer. Warm, and ready."] = "Restiamo uniti, {name}, come ravioli nel cestello. Caldi e pronti."
L["We move as one, {name}. Slowly, perhaps, but as one."] = "Tutti come uno, {name}. Piano, magari, ma come uno."
L["Balance, {name}: one fights, one heals, and one carries the snacks. Me."] = "Equilibrio, {name}: uno combatte, uno cura, uno porta gli spuntini. Io."
L["If we fall, {name}, we fall together, and then we nap. Let us not."] = "Se cadiamo, {name}, cadiamo insieme, e poi un pisolino. Meglio di no."
L["Stay behind me, {name}. I am soft, but I am very wide."] = "Stai dietro di me, {name}. Sono soffice, ma copro molto."
L["If we win, {name}, I will cook. If we lose, I will also cook, but sadly."] = "Se vinciamo, {name}, cucino io. Se perdiamo, cucino lo stesso, ma triste."
L["Everyone breathe, {name}. In, and out. Now hit things, calmly."] = "Respiriamo, {name}. Dentro, e fuori. Ora picchiamo, con calma."
L["Keep up, {name}. I am in a hurry. It happens to pandaren about once a decade."] = "Tieni il passo, {name}. Ho fretta. A un pandaren succede ogni dieci anni."
L["A party is like a brew, {name}: odd ingredients, wonderful together. Mostly."] = "Gruppo e birra, {name}: ingredienti strani, risultato ottimo. Quasi sempre."
L["If I fall, {name}, roll me somewhere safe. Carrying me is not an option."] = "Se cado, {name}, rotolami al sicuro. Portarmi in braccio non è un'opzione."
L["Pandaren fight like water, {name}: calm, patient, and then suddenly everywhere."] = "Combattiamo come l'acqua, {name}: calmi, pazienti, poi d'un tratto ovunque."
L["Up before the tea, {name}? Brave. Here, instead of the tea."] = "In piedi prima del tè, {name}? Che coraggio. Tieni, al posto del tè."
L["Morning, {name}. First this, then breakfast, then more breakfast."] = "Buongiorno, {name}. Prima questo, poi la colazione, poi altra colazione."
L["A new day, {name}, and nobody has spilled anything yet. Let us begin gently."] = "Un nuovo giorno, {name}, e nessuno ha ancora rovesciato niente. Cominciamo piano."
L["Halfhill's farmers have been up for hours, {name}. I have been up for minutes."] = "I contadini dei Quattro Venti sono in piedi da ore, {name}. Io da minuti."
L["Morning mist, {name}. It looked just like home. Then a kobold walked by."] = "Nebbia del mattino, {name}. Sembrava proprio casa. Poi è passato un coboldo."
L["Good morning, {name}. My stomach woke first and has been giving orders since."] = "Buongiorno, {name}. Lo stomaco si è svegliato prima di me e ora comanda lui."
L["Past my first nap, {name}, and before my second. Quickly, while I'm awake."] = "Tra il primo pisolino e il secondo, {name}. Presto, finché ho gli occhi aperti."
L["Late, {name}. The brewmasters are asleep. The brews, I suspect, are not."] = "È tardi, {name}. I mastri birrai dormono. Le birre, sospetto, no."
L["Midnight snack time, {name}. This is the appetiser."] = "Spuntino di mezzanotte, {name}. Questo è l'antipasto."
L["Dark already, {name}? Back home, Grandfather's stories would just be starting."] = "Già buio, {name}? A casa, adesso il nonno comincerebbe a raccontare."
L["The moon is round and full tonight, {name}. We have a great deal in common."] = "Stanotte la luna è tonda e piena, {name}. Abbiamo molto in comune."
L["Your kindness is noted, {name}. Dragons do not forget."] = "Non scorderò la tua gentilezza, {name}. I draghi non dimenticano."
L["Thank you, {name}. Returned on swift wings."] = "Grazie, {name}. Ricambio su ali veloci."
L["Wings, fire and scales, {name}, and still you thought I needed help. Touching."] = "Ali, fuoco e scaglie, {name}, e mi hai aiutato lo stesso. Commovente."
L["I would bow, {name}, but last time my wings cleared a table. Thank you."] = "Mi inchinerei, {name}, ma l'ultima volta le mie ali hanno sparecchiato. Grazie."
L["That goes straight into my hoard, {name}. Kind deeds are the only gold I keep."] = "Finisce dritto nel mio tesoro, {name}. Le buone azioni sono l'unico oro che conservo."
L["I was made to be a weapon, {name}. I much prefer this part. Thank you."] = "Dovevo essere un'arma, {name}. Preferisco di gran lunga questa parte. Grazie."
L["Thank you, {name}. Wrathion would have made a speech of it. I will not."] = "Grazie, {name}. Wrathion ci avrebbe fatto un discorso. Io no."
L["Returned with a little fire in it, {name}. Only a little. I am practising."] = "Ricambiato con un pizzico di fuoco, {name}. Solo un pizzico. Mi sto esercitando."
L["A mortal gift, {name}: small, brief and kind. I am learning to like all three."] = "Dono da mortali, {name}: piccolo, breve, gentile. Tre qualità che imparo ad amare."
L["Thank you, {name}. Mortal customs are new to me. Do I pay you? No? Then this."] = "Grazie, {name}. Le usanze mortali mi sono nuove. Devo pagarti? No? Allora questo."
L["Thank you, {name}. I have scales where most have feelings. That got through."] = "Grazie, {name}. Ho scaglie dove altri hanno sentimenti. Eppure è passato."
L["You're on my list of favourite mortals, {name}. It was empty until today."] = "Sei nella mia lista dei mortali preferiti, {name}. Fino a oggi era vuota."
L["The red in me is grateful, {name}. The black in me is suspicious. The red wins."] = "Il mio lato rosso è grato, {name}. Quello nero è sospettoso. Vince il rosso."
L["Thank you, {name}. Dragons are not used to receiving. I find I like it."] = "Grazie, {name}. I draghi non sono abituati a ricevere. Scopro che mi piace."
L["A dragon's thanks comes with a roar, {name}. I will spare the neighbours."] = "Il grazie di un drago è un ruggito, {name}. Risparmierò i vicini."
L["Very well, {name}. Stand still, I would hate to singe you."] = "Molto bene, {name}. Non muoverti, mi dispiacerebbe bruciacchiarti."
L["Granted, {name}. A dragon keeps its word."] = "Concesso, {name}. Un drago mantiene la parola."
L["Certainly, {name}. Stand clear of the tail."] = "Certo, {name}. Tieniti alla larga dalla coda."
L["Of course, {name}. Is this still how it is done? I was asleep for a while."] = "Certo, {name}. Si fa ancora così? Ho fatto un pisolino un po' lungo."
L["Gladly, {name}. All five dragonflights are in me, and all five say yes."] = "Volentieri, {name}. I cinque stormi che ho dentro dicono sì all'unanimità."
L["Right away, {name}. Dragon-sized help, in a conveniently smaller form."] = "Subito, {name}. Un aiuto da drago, in comodo formato tascabile."
L["Of course, {name}. Neltharion only gave orders. A request is much nicer."] = "Certo, {name}. Neltharion sapeva solo dare ordini. Chiedere è più gentile."
L["Right away, {name}. Stand back a little; I am still learning how big I am."] = "Subito, {name}. Indietro un po': sto ancora imparando quanto sono grande."
L["Certainly, {name}. Claws are not ideal for spellwork, but I manage."] = "Certo, {name}. Gli artigli non sono l'ideale per gli incantesimi, ma me la cavo."
L["Of course, {name}. Dragons usually demand tribute. I'm waiving it, this once."] = "Certo, {name}. Di solito i draghi esigono un tributo. Stavolta te lo abbuono."
L["Of course, {name}. Please don't scream. Mortals often do. It's the horns."] = "Certo, {name}. Non urlare, ti prego. Lo fanno in molti. Saranno le corna."
L["My breath is fire, {name}, so we will do this the other way."] = "Il mio soffio è fuoco, {name}, quindi faremo in un altro modo."
L["Gladly, {name}. Mortals so rarely ask a dragon for anything but mercy."] = "Volentieri, {name}. I mortali chiedono di rado a un drago altro che pietà."
L["A small magic, {name}, but I cast it with enormous dignity."] = "Una piccola magia, {name}, ma la lancio con enorme dignità."
L["Take this, {name}. Even a dragon needs allies. Especially one this size."] = "Prendi, {name}. Anche a un drago servono alleati. Specie a uno così piccolo."
L["A gift from the Dragon Isles, {name}. Fly well."] = "Un dono dalle Isole dei Draghi, {name}. Buon volo."
L["Alexstrasza says every life is precious, {name}. I am starting with yours."] = "Alexstrasza dice che ogni vita è preziosa, {name}. Io comincio dalla tua."
L["I slept through ten thousand years of good deeds, {name}. Catching up now."] = "Ho diecimila anni di buone azioni arretrate, {name}. Comincio da qui."
L["Tell them a dragon did this, {name}. It sounds far grander than it was."] = "Di' a tutti che è stato un drago, {name}. Suona molto più epico di com'era."
L["Scalecommander's orders, {name}. I am not a Scalecommander, but still."] = "Ordine del Comandante delle Scaglie, {name}. Io non lo sono, ma suonava bene."
L["Take this, {name}. Ancient dragon magic, only slightly out of date."] = "Prendi, {name}. Antica magia draconica, appena un po' scaduta."
L["A dragon giving, {name}, not taking. I am trying something new."] = "Un drago che regala invece di accumulare, {name}. Sto sperimentando."
L["In visage form I look harmless, {name}. So did Lady Prestor. I really am."] = "Da mortale ho l'aria innocua, {name}. Come Lady Prestor. Ma io lo sono."
L["A gift from above, {name}. I landed specially. It took two tries."] = "Un dono dall'alto, {name}. Atterraggio apposta. Al secondo tentativo."
L["Here, {name}. Every dragon should guard something. I have chosen you, for now."] = "Tieni, {name}. Ogni drago deve custodire qualcosa. Per ora ho scelto te."
L["Take this, {name}. It's from five dragonflights, so it clashes with everything."] = "Prendi, {name}. Viene da cinque stormi, quindi non si abbina a niente."
L["I'd fly you there myself, {name}, but dracthyr carry no riders. Take this."] = "Ti ci porterei in volo, {name}, ma i dracthyr non portano cavalieri. Prendi."
L["Dragons gifted the world at its dawn, {name}. Mine is smaller, and later."] = "I draghi colmarono di doni il mondo nascente, {name}. Io meno, e in ritardo."
L["A little essence for you, {name}. It is what I'm made of, so handle it gently."] = "Un po' di essenza per te, {name}. È la mia materia prima: maneggiala con cura."
L["Take this, {name}. It will feel warm. Most things do, after I touch them."] = "Prendi, {name}. Lo sentirai caldo. Quasi tutto lo è, dopo che l'ho toccato."
L["The Forbidden Reach feels far behind us now, {name}."] = "L'Isola Proibita ormai sembra così lontana, {name}."
L["Two dracthyr in one place, {name}. Mind the wings; there is not room for four."] = "Due dracthyr qui, {name}? Occhio alle ali: in quattro non ci stanno."
L["Remember when the whole world was new to us, {name}? It still is, mostly."] = "Ricordi quando il mondo intero ci era nuovo, {name}? Lo è ancora, quasi tutto."
L["In visage form nobody can tell, {name}. Between us: we look better in scales."] = "In sembianze mortali non si nota, {name}. Tra noi: con le scaglie stiamo meglio."
L["Made for war, {name}, and look at us: sharing. Somebody's plans went wrong."] = "Nati per la guerra, {name}, e ora condividiamo. A qualcuno è saltato il piano."
L["Visage or scales, {name}, I would know one of us anywhere. It is the posture."] = "Sembianze o scaglie, {name}, riconoscerei uno di noi ovunque. È la postura."
L["Mortals always ask us the same thing, {name}: will we fly them. Still no."] = "I mortali chiedono sempre un passaggio in volo, {name}. Ancora no."
L["Between two dracthyr, {name}: the horns never get any easier with hats."] = "Tra dracthyr, {name}: con le corna, i cappelli restano un'impresa."
L["Tell me when to breathe fire, {name}. And, please, when not to."] = "Dimmi quando sputare fuoco, {name}. E, per favore, anche quando no."
L["I woke in a cave full of strangers, {name}. This is far better company."] = "Mi svegliai in una grotta di sconosciuti, {name}. Qui si sta molto meglio."
L["Neltharion made us to fight alone, {name}. We have improved on him."] = "Neltharion ci creò solitari, {name}. Abbiamo migliorato il progetto."
L["Stay clear of my tail, {name}. It hasn't yet learned whose side it's on."] = "Stai alla larga dalla mia coda, {name}. Non sa ancora da che parte sta."
L["A flight of our own, {name}. So this is what the dragons meant."] = "Uno stormo tutto nostro, {name}. Ecco cosa intendevano i draghi."
L["If I say 'take cover', {name}, I mean behind my wings. They are good for that."] = "Se dico 'al riparo', {name}, intendo dietro le mie ali. Servono a questo."
L["Stand beside me, {name}, never in front. I cannot aim my breath politely."] = "Stammi accanto, {name}, mai davanti. Non so soffiare con educazione."
L["Leave the big ones to me, {name}. Well, the ones smaller than me. That is most."] = "Lascia a me i grossi, {name}. Be', quelli più piccoli di me. Cioè quasi tutti."
L["Stay close, {name}. I can glide us all down from anywhere. Up is your problem."] = "Resta vicino, {name}. Posso farci planare giù da ovunque. La salita è affar tuo."
L["Keep moving, {name}. A dragon in a hurry is grand. One waiting is just big."] = "Avanti, {name}. Un drago in corsa è maestoso. Fermo, è solo ingombrante."
L["Tell me the plan slowly, {name}. I was made for battles, not for plans."] = "Spiegami il piano, {name}. Piano. Io so combattere, non pianificare."
L["Mortals live so briefly, {name}. Let us not make today any shorter."] = "I mortali vivono così poco, {name}. Non accorciamo anche oggi."
L["It is good to see one of our own, {name}."] = "È bello vedere qualcuno della nostra gente, {name}."
L["Our people are few, {name}. That makes each of us count."] = "Siamo in pochi, {name}. Per questo ognuno di noi conta."
L["Thank you, {name}. The Alliance looks after its own, and today that's me."] = "Grazie, {name}. L'Alleanza si prende cura dei suoi, e oggi tocca a me."
L["Kindness answered, {name}. For the Alliance!"] = "Gentilezza ricambiata, {name}. Per l'Alleanza!"
L["Stormwind has a statue for every hero, {name}. I'm putting in a word for yours."] = "Roccavento ha una statua per ogni eroe, {name}. Metto una buona parola per la tua."
L["The Alliance way, {name}: you help me, I help you, a dwarf buys the drinks."] = "Regola dell'Alleanza, {name}: tu aiuti me, io aiuto te, un nano paga da bere."
L["Bolvar would bow, Magni would hug, {name}. I'll just return it."] = "Bolvar si inchinerebbe, Magni ti abbraccerebbe, {name}. Io ricambio e basta."
L["If the Alliance gave medals for manners, {name}, you'd need a second tabard."] = "Se l'Alleanza desse medaglie al galateo, {name}, ti servirebbe un'altra tabarda."
L["Returned in full, {name}. An ally who gives first is worth a whole garrison."] = "Ricambio per intero, {name}. Un alleato che dona per primo vale una guarnigione."
L["Thank you, {name}. I'll mention you in my letter home. Mother reads them aloud."] = "Grazie, {name}. Ti citerò nella lettera a casa. La mamma le legge ad alta voce."
L["Thank you, {name}. Even the Stormwind guards would smile at that."] = "Grazie, {name}. Perfino le guardie di Roccavento sorriderebbero."
L["The Alliance at its finest, {name}: nobody asked, somebody helped. Thanks."] = "L'Alleanza migliore, {name}: nessuno chiede, qualcuno aiuta. Grazie."
L["I'll tell everyone on the Deeprun Tram, {name}. It's a long tram. Thank you."] = "Lo dirò a tutti sul Tram degli Abissi, {name}. È un tram lungo. Grazie."
L["Most gallant, {name}. If I had a lion on my tabard, it would be purring."] = "Che galanteria, {name}. Se avessi un leone sulla tabarda, farebbe le fusa."
L["Our kings bicker, {name}, but their people get on splendidly. Thank you."] = "I re bisticciano, {name}, ma i popoli vanno d'amore e d'accordo. Grazie."
L["The Alliance was forged by folk keeping their word, {name}. Here's mine."] = "L'Alleanza è nata da gente di parola, {name}. Ecco la mia."
L["Of course, {name}. Allies help each other. It's practically in the name."] = "Certo, {name}. Gli alleati si aiutano a vicenda. Lo dice la parola stessa."
L["At once, {name}. The Alliance does not leave a friend wanting."] = "Subito, {name}. L'Alleanza non lascia un amico nel bisogno."
L["Of course, {name}. It's in the Alliance charter. Somewhere near the back."] = "Certo, {name}. È nello statuto dell'Alleanza. In una nota a piè di pagina."
L["By order of the Alliance, {name}: one {buff}, effective at once."] = "Per ordine dell'Alleanza, {name}: {buff}, con effetto immediato."
L["Anything for an ally, {name}. Within reason. This is well within reason."] = "Tutto per un alleato, {name}. Nei limiti del ragionevole. Questo ci rientra."
L["Right away, {name}. SI:7 knew you would ask. I only just found out."] = "Subito, {name}. Il SI:7 lo sapeva già. Io l'ho scoperto adesso."
L["Straight away, {name}. The Alliance marches on requests like yours. And bread."] = "Subito, {name}. L'Alleanza va avanti a richieste come la tua. E a pane."
L["Yes, {name}. From Stormwind to Ironforge, 'please' opens every gate."] = "Sì, {name}. Da Roccavento a Forgiardente, 'per favore' apre ogni porta."
L["Right away, {name}. I've worn the blue all day hoping somebody would ask."] = "Subito, {name}. È da stamattina che porto il blu sperando in una richiesta."
L["Hold still, {name}. I learned this faster than the Alliance anthem."] = "Non muoverti, {name}. L'ho imparato prima dell'inno dell'Alleanza."
L["Of course, {name}. Armies win wars; small favours win allies. Here's one."] = "Certo, {name}. Gli eserciti vincono guerre; i favori, alleati. Eccone uno."
L["For the Alliance, {name}! Stay strong out there. Stronger, now."] = "Per l'Alleanza, {name}! Resta forte là fuori. Anzi, ora più forte."
L["Onward, {name}. The Alliance is with you."] = "Avanti, {name}. L'Alleanza è con te."
L["Take this, {name}. Had a gnome made it, it would come with twelve levers."] = "Prendi, {name}. Se l'avesse fatto uno gnomo, avrebbe dodici leve."
L["Compliments of the Alliance, {name}. We've done these since the Second War."] = "Omaggio dell'Alleanza, {name}. Qualità garantita dalla Seconda Guerra."
L["Chin up, {name}. Somewhere in Stormwind, a bard is writing about this."] = "Su con la vita, {name}. A Roccavento un bardo sta già scrivendo di te."
L["Every ally counts, {name}. Today, you count double."] = "Ogni alleato conta, {name}. Oggi tu conti doppio."
L["Anduin would want me to share, {name}, and I'd hate to disappoint him."] = "Anduin vorrebbe che condividessi, {name}, e non voglio deluderlo."
L["Take this, {name}. Stormwind's walls can't follow you, so this will have to."] = "Prendi, {name}. Le mura di Roccavento non possono seguirti: ci penserà questo."
L["Here, {name}. The gryphons get you there; this gets you back."] = "Tieni, {name}. I grifoni ti portano là; questo ti riporta a casa."
L["Alliance rule, {name}: keep your word, your walls, your friends. Here, friend."] = "Regola dell'Alleanza, {name}: parola, mura e amici vanno difesi. Tieni, tra amici."
L["Every ally deserves a lion at their back, {name}. I'm the nearest lion."] = "Ogni alleato merita un leone alle spalle, {name}. Il più vicino sono io."
L["A gift from the Alliance, {name}. Signed, sealed and hand-delivered."] = "Un dono dall'Alleanza, {name}. Firmato, sigillato e consegnato a mano."
L["The Alliance never forgets the brave, {name}. Give it something to remember."] = "L'Alleanza non dimentica i coraggiosi, {name}. Dalle qualcosa da ricordare."
L["Together we stand, {name}. For the Alliance!"] = "Uniti siamo forti, {name}. Per l'Alleanza!"
L["Right, {name}: shields up, heads down, and nobody charges before the plan does."] = "Allora, {name}: scudi alti, testa bassa, e nessuno carica prima del piano."
L["The finest company the Alliance ever fielded, {name}. Or at least the nearest."] = "La miglior compagnia mai schierata dall'Alleanza, {name}. O almeno la più vicina."
L["Together, {name}, we're practically a regiment. A small, well-dressed regiment."] = "Insieme, {name}, siamo quasi un reggimento. Un reggimento piccolo ma elegante."
L["Watch each other's backs, {name}. The Alliance was built by people who did."] = "Guardiamoci le spalle, {name}. L'Alleanza è nata proprio così."
L["Shields together, {name}. The Alliance never won anything in single file."] = "Scudi uniti, {name}. L'Alleanza non ha mai vinto niente in fila indiana."
L["If this goes in the history books, {name}, let's be a chapter, not a footnote."] = "Se finiamo nei libri di storia, {name}, meglio un capitolo che una nota."
L["Whoever carries the banner, {name}, gets painted looking noble. Volunteers?"] = "Chi regge lo stendardo, {name}, verrà ritratto con aria nobile. Volontari?"
L["Dwarven nerve, elven patience, human stubbornness, {name}: the Alliance recipe."] = "Fegato nanico, pazienza elfica, testardaggine umana, {name}: ricetta dell'Alleanza."
L["Keep the lion roaring, {name}. Softly, mind. We're sneaking."] = "Ruggiamo da leoni, {name}. Sottovoce, però: siamo in incognito."
L["Strength and honour, {name}. And kindness, it turns out. Repaid in full."] = "Forza e onore, {name}. E gentilezza, a quanto pare. Ripagata per intero."
L["The Horde takes care of its own, {name}."] = "L'Orda non abbandona i suoi, {name}."
L["Strength given, strength returned, {name}. That's all of Horde diplomacy."] = "Forza data, forza resa, {name}. Ecco tutta la diplomazia dell'Orda."
L["I'd carve your name on Orgrimmar's gates, {name}, but they're full. Thanks."] = "Inciderei il tuo nome sulle porte di Orgrimmar, {name}, ma sono piene. Grazie."
L["A goblin would've sent you an invoice, {name}. I'm sending this instead."] = "Un goblin ti avrebbe mandato una fattura, {name}. Io ti mando questo."
L["You did not have to do that, {name}. That is why the Horde remembers it."] = "Non dovevi farlo, {name}. Per questo l'Orda se lo ricorda."
L["In the Horde we do not say thank you twice, {name}. So: once, and meant."] = "Nell'Orda non si dice grazie due volte, {name}. Quindi: una, e sentita."
L["In the Horde a debt is carried like an axe, {name}: openly, and not for long."] = "Nell'Orda un debito è come un'ascia, {name}: si porta in vista, e non a lungo."
L["The gate grunts will hear of you, {name}. They'll grunt. It means respect."] = "I grunt alle porte sapranno di te, {name}. Grugniranno. È rispetto."
L["The Horde keeps two lists, {name}: grudges and favours. Yours is the short one."] = "L'Orda tiene due liste, {name}: rancori e favori. Tu sei in quella corta."
L["Honour says repay you, {name}. Manners say smile. I'm working on the smile."] = "L'onore dice ripaga, {name}. Il galateo, sorridi. Sul sorriso ci lavoro."
L["That landed softer than any zeppelin I've ridden, {name}. Thank you."] = "Atterraggio più morbido di qualunque zeppelin, {name}. Grazie."
L["Thanks, {name}, in Orcish, Taur-ahe, Zandali and Gutterspeak. Pick one."] = "Grazie, {name}, in orchesco, taur-ahe, zandali e gergo reietto. Scegli."
L["Thrall taught the Horde honour, {name}. Nobody had to teach you. Thank you."] = "Thrall insegnò l'onore all'Orda, {name}. A te non è servito. Grazie."
L["You gave first, {name}. In the Horde that earns first cut of the roast. Here."] = "Hai cominciato tu, {name}. Nell'Orda ti spetta la prima fetta d'arrosto. Tieni."
L["The Warchief can't thank everyone himself, {name}. He's delegated it to me."] = "Il Capoguerra non può ringraziare tutti, {name}. Ha delegato me."
L["Consider it done, {name}. For the Horde, and for anyone who asks nicely."] = "Consideralo fatto, {name}. Per l'Orda, e per chiunque chieda con gentilezza."
L["You only had to ask, {name}. The Horde answers."] = "Bastava chiedere, {name}. L'Orda risponde."
L["The Horde usually helps with axes, {name}. Today, {buff}."] = "Di solito l'Orda aiuta a colpi d'ascia, {name}. Oggi con {buff}."
L["Done, {name}. No speeches. The Horde has plenty of those already."] = "Fatto, {name}. Niente discorsi. L'Orda ne ha già fin troppi."
L["You asked, {name}. In Orgrimmar, that counts as a formal treaty."] = "Hai chiesto, {name}. A Orgrimmar vale come un trattato ufficiale."
L["Asking is no weakness, {name}. Refusing an ally would be."] = "Chiedere non è debolezza, {name}. Rifiutare un alleato sì."
L["No need to bang a war drum, {name}. You asked; it's done."] = "Niente tamburi di guerra, {name}. Hai chiesto, è fatto."
L["Of course, {name}. In the Horde, 'please' outranks everyone but the Warchief."] = "Certo, {name}. Nell'Orda 'per favore' è secondo solo al Capoguerra."
L["In Orgrimmar we'd have argued about it first, {name}. Tradition. Here."] = "A Orgrimmar prima si litiga, {name}. È tradizione. Tieni."
L["Consider it requisitioned, {name}. The quartermaster needn't hear about it."] = "Requisizione d'ufficio, {name}. Il furiere non deve saperlo."
L["Done, {name}. If anyone asks, I scowled the whole time. I've a reputation."] = "Fatto, {name}. Se chiedono, ho tenuto il muso. Ho una fama da difendere."
L["Of course, {name}. Horde hospitality: rough edges, full helpings."] = "Certo, {name}. Ospitalità dell'Orda: modi spicci, piatti pieni."
L["The Horde came together because somebody always said yes, {name}. Yes."] = "L'Orda è nata perché qualcuno ha sempre detto sì, {name}. Sì."
L["For the Horde, {name}! Go with strength. I've just handed you some."] = "Per l'Orda, {name}! Va' e sii forte. La forza te l'ho appena data."
L["Go with honour, {name}. Victory awaits."] = "Va' con onore, {name}. La vittoria ti attende."
L["Go and do something worth a song, {name}. Loud songs. The Horde likes loud."] = "Fa' qualcosa che meriti una canzone, {name}. Da urlare: all'Orda piace forte."
L["Walk tall, {name}. The Horde always made room for those the world turned away."] = "Cammina a testa alta, {name}. L'Orda ha sempre accolto chi il mondo respingeva."
L["Take this, {name}, and a word of Horde wisdom: hit first, apologise never."] = "Prendi, {name}, e un detto dell'Orda: prima si colpisce, le scuse mai."
L["Victory or death, {name}. I'd prefer victory, so take this."] = "Vittoria o morte, {name}. Preferisco la vittoria, quindi prendi."
L["Blood and thunder, {name}! Go and be the thunder."] = "Sangue e tuono, {name}! Va' e sii il tuono."
L["For the Horde, {name}, and for you. The Horde's big; you're closer."] = "Per l'Orda, {name}, e per te. L'Orda è grande; tu sei più a portata."
L["Here, {name}. Stronger together, they say, and I've just done my half."] = "Tieni, {name}. Insieme si è più forti, dicono. La mia metà l'ho fatta."
L["Carry this, {name}. It weighs less than a Horde banner and flies just as proud."] = "Tieni, {name}. Pesa meno di uno stendardo dell'Orda e sventola fiero uguale."
L["Here, {name}. The Horde feeds its own, arms its own, and now enchants them."] = "Tieni, {name}. L'Orda sfama i suoi, arma i suoi, e ora li incanta pure."
L["Take this, {name}. Whatever's out there is about to meet the Horde."] = "Prendi, {name}. Chiunque ci sia là fuori, sta per conoscere l'Orda."
L["Here, {name}. Wherever you're headed, arrive looking like the Horde sent you."] = "Tieni, {name}. Ovunque tu vada, arriva come se ti mandasse l'Orda."
L["The Crossroads never turned a traveller away, {name}. It overcharged a few."] = "Il Crocevia non ha mai respinto un viandante, {name}. Qualcuno l'ha spennato."
L["The Horde raises you tough, {name}. This is for the days tough isn't enough."] = "L'Orda ti tempra, {name}. Questo è per i giorni in cui non basta."
L["Take this, {name}. A Horde gift: no ribbon, no speech, no refunds."] = "Tieni, {name}. Dono dell'Orda: senza fiocco, discorsi o resi."
L["Stand tall, {name}. Taller than that. The Horde has tauren to keep up with."] = "Testa alta, {name}. Più alta. Nell'Orda c'è da stare al passo coi tauren."
L["Our strength is each other, {name}. For the Horde!"] = "La nostra forza siamo noi, {name}. Per l'Orda!"
L["Forward, {name}. The Horde advances together. Retreats... never, officially."] = "Avanti, {name}. L'Orda avanza unita. Ritirate... mai, ufficialmente."
L["Together we're a war band, {name}. Apart, we're just loud."] = "Insieme siamo un esercito, {name}. Divisi, solo baccano."
L["Shoulder to shoulder, {name}. Whoever charges first buys the grog."] = "Spalla a spalla, {name}. Chi carica per primo paga il grog."
L["Nobody gets left behind, {name}. I've counted us twice."] = "Nessuno resta indietro, {name}. Ci ho contati due volte."
L["Rule of the warband, {name}: nobody eats until everybody's back."] = "Regola della brigata, {name}: si mangia solo quando tornano tutti."
L["Drums up, {name}. If we can't be quiet, we'll be terrifying."] = "Tamburi, {name}! Se non sappiamo stare zitti, faremo paura."
L["The Horde never won a thing alone, {name}. Let's not start now."] = "L'Orda non ha mai vinto niente da sola, {name}. Non cominciamo ora."
L["We fight like the Horde, {name}: all at once, and nobody waits for the signal."] = "Combattiamo da Orda, {name}: tutti insieme, e nessuno aspetta il segnale."
L["Right, {name}. Spoils shared, blame shared, glory to the loudest."] = "Allora, {name}. Bottino diviso, colpe divise, gloria a chi urla di più."
L["Look at us, {name}. The Warchief would be proud. Mildly. From a distance."] = "Guardaci, {name}. Il Capoguerra sarebbe fiero. Moderatamente. Da lontano."
L["Tusks, horns, long ears and bare bone, {name}. Finest warband going."] = "Zanne, corna, orecchie lunghe, ossa nude, {name}. Brigata imbattibile."
L["The war stories get bigger after, {name}. Let's give them a head start."] = "Dopo, le storie di guerra si ingigantiscono, {name}. Portiamoci avanti."
L["Thank you, {name}. Good hearts turn up on every side, and apparently here."] = "Grazie, {name}. I cuori buoni si trovano ovunque, e a quanto pare anche qui."
L["Thank you, {name}. No side, no title, just kindness. Legends start like this."] = "Grazie, {name}. Né fazione né titoli, solo gentilezza. Così nascono le leggende."
L["Thank you, {name}. Kindness has no faction, which is handy, since I have none."] = "Grazie, {name}. La gentilezza non ha fazione. Comodo: nemmeno io."
L["Thank you, {name}. Whichever side gets you is getting a bargain."] = "Grazie, {name}. La fazione che ti prenderà farà un affarone."
L["Whoever claims me in the end, {name}, I'll remember you first. Thank you."] = "Da qualunque parte io finisca, {name}, mi ricorderò prima di te. Grazie."
L["Strictly neutral, {name}, but gratitude doesn't count. Thank you."] = "Rigorosamente neutrale, {name}, ma la gratitudine non conta. Grazie."
L["Thank you, {name}. I carry no banner, so both hands are free to return this."] = "Grazie, {name}. Non porto stendardi, quindi ho due mani libere per ricambiare."
L["The Steamwheedle stay neutral for gold, {name}. I do it for moments like this."] = "I cartelli goblin sono neutrali per l'oro, {name}. Io per momenti come questo."
L["Neither side has taught me their thanks yet, {name}, so here's the plain kind."] = "Nessuna fazione mi ha insegnato il suo grazie, {name}. Ecco quello semplice."
L["Thank you, {name}. I stand between two great banners, and still you noticed me."] = "Grazie, {name}. Sto tra due grandi stendardi, eppure mi hai notato."
L["Two sides at war, {name}, and us being lovely right in the middle. Thank you."] = "Due fazioni in guerra, {name}, e noi due, adorabili, proprio in mezzo. Grazie."
L["Gladly, {name}, whatever banner you fly. I don't even own a banner."] = "Con piacere, {name}, qualunque sia il tuo stendardo. Io non ne ho."
L["Certainly, {name}. I help everyone. It's the one thing I've decided."] = "Certo, {name}. Aiuto tutti. È l'unica cosa che ho deciso."
L["Everyone asks me which side I'm on, {name}. Much nicer to be asked for help."] = "Tutti mi chiedono da che parte sto, {name}. Farmi chiedere aiuto è molto meglio."
L["Of course, {name}. No war council to ask; just me, and I say yes."] = "Certo, {name}. Niente consiglio di guerra: decido io, e dico sì."
L["Here you are, {name}. No oath, no colours, no fee."] = "Ecco, {name}. Senza giuramenti, bandiere o tariffe."
L["I can't pick a side yet, {name}, but I can pick a good cause. This is one."] = "Una fazione non posso sceglierla, {name}, una buona causa sì. Eccola."
L["At once, {name}. I have no side to be on, so for now I am entirely on yours."] = "Subito, {name}. Non ho una fazione: per ora sto dalla tua, al cento per cento."
L["Of course, {name}. Nobody pays me to take sides, so I take requests instead."] = "Certo, {name}. Nessuno mi paga per prendere le parti: prendo richieste."
L["Neutral does not mean unwilling, {name}. It means I help first and argue never."] = "Neutralità non è pigrizia, {name}. È aiutare subito e non litigare mai."
L["Friends can come from any side, {name}. Or, like me, from none in particular."] = "Gli amici vengono da ogni parte, {name}. O, come me, da nessuna in particolare."
L["Soon they'll hand us tabards, {name}. Until then, we look after each other."] = "Presto ci daranno le tabarde, {name}. Fino ad allora, badiamo l'uno all'altro."
L["I haven't chosen a side yet, {name}, so I'm being kind to both. Take this."] = "Non ho ancora scelto una fazione, {name}: sono gentile con entrambe. Prendi."
L["A gift with no strings, {name}. I don't even have a faction to tie them to."] = "Un dono senza lacci né lacciuoli, {name}. Non ho una fazione a cui legarli."
L["Go on, {name}. Two whole factions are waiting to argue over us."] = "Vai, {name}. Ci sono due fazioni intere pronte a contenderci."
L["No quartermaster yet, {name}, so nobody's counting. Have plenty."] = "Niente furiere per ora, {name}: nessuno conta. Prendine a volontà."
L["Take this, {name}. Neutral ground travels with me; you're standing on some."] = "Prendi, {name}. Il territorio neutrale viaggia con me: ci sei sopra adesso."
L["The Argent Dawn helps whoever needs it, {name}. I'm learning from the best."] = "L'Alba d'Argento aiuta chiunque ne abbia bisogno, {name}. Imparo dai migliori."
L["Booty Bay's rule: no fighting on the docks, {name}. Mine: no refusing a gift."] = "Baia del Bottino vieta le risse sul molo, {name}. Io vieto di rifiutare regali."
L["The one thing both factions agree on, {name}. They just don't know it yet."] = "Su questo le due fazioni sono d'accordo, {name}. Solo che ancora non lo sanno."
L["This goes with any tabard, {name}. I made sure by giving it no colours at all."] = "Si abbina a ogni tabarda, {name}. Per sicurezza, non gli ho dato colori."
L["For you, {name}. Neither Orgrimmar nor Stormwind sent it. It works anyway."] = "Per te, {name}. Non lo manda né Orgrimmar né Roccavento. Funziona uguale."
L["Here, {name}. I belong to no nation yet, so I practise belonging to everyone."] = "Tieni, {name}. Non ho ancora una patria, così mi esercito con tutte."
L["Side by side, {name}, whatever comes."] = "Fianco a fianco, {name}, qualunque cosa accada."
L["No flag over this party, {name}, just us. That's plenty."] = "Nessuna bandiera qui, {name}: solo noi. Basta e avanza."
L["One day we'll pick sides, {name}. Today we pick fights, together."] = "Un giorno sceglieremo con chi stare, {name}. Oggi, chi picchiare."
L["Whatever side the rest of the world is on, {name}, I'm on this party's."] = "Il mondo scelga pure la sua parte, {name}. Io sto con questo gruppo."
L["Neutral in the war, {name}, but very partial to this group."] = "Neutrale in guerra, {name}, ma per questo gruppo sono di parte."
L["They call us a neutral party, {name}. Nobody said it had to be a quiet one."] = "Siamo un gruppo neutrale, {name}. Nessuno ha detto silenzioso."
L["Whatever we fight today, {name}, it's nothing personal. Just very thorough."] = "Chiunque affronteremo, {name}, niente di personale. Solo lavoro fatto bene."
L["One side in this party, {name}: ours. Smallest faction on Azeroth. The best."] = "Una fazione sola, {name}: la nostra. La più piccola di Azeroth. La migliore."
L["No orders from any capital, {name}. We choose our road. Let's choose quickly."] = "Nessuna capitale ci comanda, {name}. Scegliamo noi la strada. Ma in fretta."
L["No war to win today, {name}, just this one fight. Much more manageable."] = "Oggi niente guerre, {name}, solo questo scontro. Molto più alla portata."
L["One good turn deserves another, {name}."] = "Una cortesia ne merita un'altra, {name}."
L["Have some {buff} in return, {name}."] = "In cambio, ecco {buff} per te, {name}."
L["Kindness should go both ways, {name}. Thank you."] = "La gentilezza va ricambiata, {name}. Grazie."
L["You went first, {name}, so I'll go second and we'll call it friendship."] = "Prima mossa tua, {name}, seconda mia. Chiamiamola amicizia."
L["I'd write you a song, {name}, but {buff} is less off-key."] = "Ti scriverei una canzone, {name}, ma con {buff} stono meno."
L["A gift for a gift, {name}. At this rate we'll be unstoppable by supper."] = "Dono per dono, {name}. Di questo passo, per cena saremo inarrestabili."
L["All square, {name}. Unless you'd like to make it best of three."] = "Pari e patta, {name}. O vuoi giocarti la bella?"
L["You started it, {name}. I'm only finishing it."] = "Hai cominciato tu, {name}. Io finisco e basta."
L["That was kind, {name}. The day just got noticeably better. Here's my half."] = "Che gentile, {name}. La giornata è appena migliorata. Ecco la mia metà."
L["I was about to do that for you, {name}. Honestly. Here's proof."] = "Stavo per farlo io per te, {name}. Davvero. Ecco la prova."
L["Thank you, {name}. I'll sleep better tonight, and I sleep in a ditch."] = "Grazie, {name}. Stanotte dormirò meglio, e dormo in un fosso."
L["Two good things today, {name}: your kindness, and the chance to return it."] = "Due cose belle oggi, {name}: la tua gentilezza, e l'occasione di ricambiarla."
L["You had me in your debt for all of three seconds, {name}. There."] = "Il mio debito con te è durato ben tre secondi, {name}. Ecco."
L["Gratitude is best served quickly, {name}. Here it is, still warm."] = "La gratitudine va servita subito, {name}. Eccola, ancora calda."
L["Well, {name}, now I have to be a better person all day. Thanks for that."] = "Ecco, {name}: ora mi tocca essere migliore per tutto il giorno. Grazie, eh."
L["Returned with a bow, {name}. A figurative one. My back isn't what it was."] = "Ricambio con un inchino, {name}. Figurato. La mia schiena ha i suoi anni."
L["Thank you, {name}. Somebody had to go first, and I'm glad it was you."] = "Grazie, {name}. Qualcuno doveva cominciare, e sono felice che sia toccato a te."
L["Thank you, {name}. You've rescued a day I'd written off at breakfast."] = "Grazie, {name}. Hai salvato una giornata persa già a colazione."
L["You asked, {name}, and here it is."] = "Hai chiesto, {name}, ed ecco fatto."
L["{buff}, coming right up, {name}."] = "{buff} in arrivo, {name}."
L["Gladly, {name}. One moment."] = "Con piacere, {name}. Un attimo."
L["Asked and answered, {name}. Next question?"] = "Chiesto e fatto, {name}. Prossima domanda?"
L["Say the word and it's yours, {name}. You said several. Here."] = "Basta una parola, {name}, e tu ne hai dette parecchie. Ecco."
L["For you, {name}? Gladly. I was hoping someone would ask."] = "Per te, {name}? Volentieri. Speravo che qualcuno lo chiedesse."
L["Of course, {name}. Easiest yes I'll say all day."] = "Certo, {name}. Il sì più facile di tutta la giornata."
L["Right away, {name}. Finally, a question I know the answer to."] = "Subito, {name}. Finalmente una domanda di cui so la risposta."
L["Of course, {name}. Nicely asked, gladly given."] = "Certo, {name}. Chiesto con garbo, dato con piacere."
L["Hold still, {name}. It works best on people who aren't fidgeting. So, nobody."] = "Non muoverti, {name}. Funziona meglio su chi sta fermo. Quindi, su nessuno."
L["Here you are, {name}. I'd make you wait for effect, but that seems rude."] = "Ecco a te, {name}. Farei una pausa a effetto, ma sarebbe scortese."
L["Yes, {name}. I'd have said it sooner if you'd asked sooner."] = "Sì, {name}. Te l'avrei detto prima, se me l'avessi chiesto prima."
L["Say no more, {name}. Done before you finished asking."] = "Non dire altro, {name}. Fatto prima che finissi di chiederlo."
L["There, {name}. Next time, don't ask; just stand near me looking hopeful."] = "Fatto, {name}. La prossima volta basta starmi vicino con gli occhioni dolci."
L["Coming up, {name}. This is the one part of my day that goes to plan."] = "Arriva, {name}. È l'unica cosa della mia giornata che va secondo i piani."
L["Asking nicely works, {name}. Tell everyone. The world could use the news."] = "Chiedere con garbo funziona, {name}. Spargi la voce: il mondo ne ha bisogno."
L["At once, {name}. Stay put, or this lands on your shadow instead."] = "Subito, {name}. Non muoverti, o finisce sulla tua ombra."
L["Safe travels, {name}. {buff} packs lighter than a sword."] = "Buon viaggio, {name}. {buff} pesa meno di una spada."
L["A small blessing for the road, {name}."] = "Una piccola benedizione per il viaggio, {name}."
L["Go well, {name}, and come back in one piece."] = "Buon cammino, {name}, e torna senza un graffio."
L["No reason, {name}. It just felt like a {buff} sort of day."] = "Nessun motivo, {name}. Oggi è una giornata da {buff}."
L["Don't mind me, {name}. Just passing, with a spare {buff}."] = "Non badare a me, {name}. Passavo di qui con {buff} d'avanzo."
L["Consider it a gift, {name}. I'd wrap it, but it glows through the paper."] = "È un regalo, {name}. Lo incarterei, ma brilla attraverso la carta."
L["Here, {name}. Pass it on when you meet someone who needs it."] = "Tieni, {name}. Passalo a chi ne avrà bisogno."
L["Whatever brings you here, {name}, may it go better than planned."] = "Qualunque cosa ti porti qui, {name}, che vada meglio del previsto."
L["Just being neighbourly, {name}. Very, very temporary neighbours."] = "Buon vicinato, {name}. Vicini molto, molto temporanei."
L["You looked about to do something brave, {name}. Here, for that."] = "Hai l'aria di chi sta per fare un'impresa, {name}. Tieni, per quella."
L["No need to stop, {name}. It works while you walk."] = "Non fermarti, {name}. Funziona anche da asporto."
L["Nothing asked, nothing owed, {name}. Nothing to do but go and be splendid."] = "Niente chiesto, niente dovuto, {name}. Non ti resta che andare e brillare."
L["Call it a wager, {name}, that you'll do something worthwhile with it."] = "Consideralo una scommessa, {name}: che ne farai qualcosa di buono."
L["A gift from a passing stranger, {name}. The best kind, the old stories say."] = "Il dono di un viandante, {name}: il più bello, dicono le vecchie storie."
L["It's rude to pass someone without a greeting, {name}. This is mine."] = "È scortese passare senza salutare, {name}. Questo è il mio saluto."
L["Same road as me, {name}? Then take this for the journey."] = "Stessa strada, {name}? Allora prendi questo per il viaggio."
L["If today goes well, {name}, remember me. If it goes badly, I was never here."] = "Se oggi va bene, {name}, ricordati di me. Se va male, non mi hai mai visto."
L["Hold still a moment, {name}. There. Best-prepared person in sight."] = "Non muoverti, {name}. Ecco fatto: la persona più preparata nei dintorni."
L["Everyone ready? You are now, {name}."] = "Tutti pronti? Ora lo sei anche tu, {name}."
L["A little something for the party, {name}."] = "Un pensierino per il gruppo, {name}."
L["Stay close, {name}. We go further together."] = "Stammi vicino, {name}. Insieme si va più lontano."
L["House rules, {name}: nobody dies, nobody sulks, everybody eats after."] = "Regole, {name}: niente morti, niente musi lunghi, e dopo tutti a tavola."
L["There, {name}. Now if this goes badly, it won't be my fault."] = "Ecco, {name}. Ora, se va male, non sarà colpa mia."
L["All set, {name}. I'd give a speech, but we'd be here all day."] = "Pronti, {name}. Farei un discorso, ma staremmo qui fino a sera."
L["Look after that, {name}. It's the only one I brought for you."] = "Abbine cura, {name}. È l'unico che ho portato per te."
L["Now we look the part, {name}. Let's go and be it."] = "Ora sembriamo eroi, {name}. Andiamo a esserlo davvero."
L["Fresh {buff} all round, {name}. The rest is luck and elbows."] = "{buff} per tutti, {name}. Il resto è fortuna e gomitate."
L["If anyone has a plan, {name}, now's the time. No? Wonderful. Onward."] = "Se qualcuno ha un piano, {name}, è il momento. No? Splendido. Avanti."
L["One each, {name}. Don't swap; they're fitted."] = "Uno a testa, {name}. Niente scambi: sono su misura."
L["Whoever starts the fight, {name}, has to tell the story afterwards."] = "Chi comincia la rissa, {name}, dopo deve raccontarla a tutti."
L["Good friends, sharp steel, {buff}. What else is there, {name}?"] = "Buoni amici, lame affilate, {buff}. Cos'altro serve, {name}?"
L["Stay where I can see you, {name}. I can't help what I can't find."] = "Resta dove ti vedo, {name}. Non posso aiutare chi non trovo."
L["If this ends up a legend, {name}, I want a line in it. Just the one."] = "Se diventa una leggenda, {name}, voglio almeno una battuta. Una sola."
L["Brace yourselves, {name}. And each other, if it comes to that."] = "Tenetevi forte, {name}. Anche l'uno all'altro, se serve."
L["Chin up, {name}. Whatever's ahead has never met this lot before."] = "Testa alta, {name}. Là davanti non sanno ancora chi sta arrivando."
L["Do try to stay in one piece, {name}. I'm only equipped for small repairs."] = "Cerca di non andare in pezzi, {name}. Faccio solo piccole riparazioni."
L["Well, {name}, we look ready. Let's go before we find out otherwise."] = "Bene, {name}, sembriamo pronti. Andiamo, prima di scoprire il contrario."
L["If we get lost, {name}, we're exploring. Nobody ever scolded an explorer."] = "Se ci perdiamo, {name}, stiamo esplorando. Nessuno sgrida mai un esploratore."
L["Thank you, {name}. I'd conjure a gift in return, but it would only be water."] = "Grazie, {name}. Ti evocherei un regalo, ma verrebbe fuori solo acqua."
L["Much obliged, {name}. I'll write it up properly later. Several pages."] = "Grazie mille, {name}. Poi ne farò una relazione. Di parecchie pagine."
L["Thank you, {name}. They never taught gratitude at Dalaran. I'm self-taught."] = "Grazie, {name}. A Dalaran la gratitudine non si insegna. Sono autodidatta."
L["Kind of you, {name}. Everyone assumes mages need no help. We do."] = "Gentile da parte tua, {name}. Tutti pensano che ai maghi non serva aiuto. Invece sì."
L["Thank you, {name}. I nearly Counterspelled that on reflex. So glad I didn't."] = "Grazie, {name}. Per riflesso stavo per usare Controincantesimo. Meno male."
L["Even a frost mage would thaw at that, {name}. Thank you."] = "Anche un mago del gelo si scioglierebbe, {name}. Grazie."
L["Thank you, {name}. Noted in my spellbook, between Frost Nova and lunch."] = "Grazie, {name}. Segnato sul mio tomo, tra Nova di Gelo e la merenda."
L["Repaid at once, {name}, before I pass a bookshop. I've lost weeks that way."] = "Ricambio subito, {name}, prima di incrociare una libreria. Ci ho perso mesi."
L["Twenty years in the library, {name}, and no book mentioned people like you."] = "Vent'anni in biblioteca, {name}, e nessun libro parlava di gente come te."
L["Arcane theory says nothing comes free, {name}. Theory was wrong. Thank you."] = "La teoria arcana dice che nulla è gratis, {name}. Si sbagliava. Grazie."
L["Of course, {name}. And yes, I suppose you'll want water as well."] = "Certo, {name}. E sì, immagino che vorrai anche l'acqua."
L["As requested, {name}. I'll find my page again later."] = "Come richiesto, {name}. Ritroverò il segno più tardi."
L["At once, {name}. Carefully, too; I've blinked into two walls today."] = "Subito, {name}. Con calma: oggi con la Traslazione ho già preso due muri."
L["Gladly, {name}. Knowledge should be shared. The Kirin Tor say so, reluctantly."] = "Con piacere, {name}. Il sapere va condiviso. Lo dice il Kirin Tor, a malincuore."
L["Certainly, {name}. I'll cast it slowly. The hand movements are the best part."] = "Certo, {name}. Lo lancio con calma: gesticolare è la parte migliore."
L["Of course, {name}. Think of it as homework, and I've done it for you."] = "Certo, {name}. Sono i compiti per casa, e te li ho già fatti io."
L["Of course, {name}. Antonidas taught me this. He also taught me to duck."] = "Certo, {name}. Me l'ha insegnato Antonidas. E pure ad abbassare la testa."
L["At once, {name}. Arcane, not fire. I did check."] = "Subito, {name}. Arcano, non fuoco. Ho controllato."
L["Certainly, {name}. It's this or a lecture on ley lines, and you've been kind."] = "Certo, {name}. Era questo o una lezione di teoria arcana. Ti meriti questo."
L["You asked a mage, {name}. The spell is instant; the explanation is not."] = "Hai chiesto a un mago, {name}. L'incantesimo è istantaneo; la spiegazione no."
L["I've cast this a thousand times, {name}. Nine hundred and ninety went well."] = "L'avrò lanciato mille volte, {name}. Novecentonovanta sono andate bene."
L["Certainly, {name}. Stand still. Fidgeters have been known to end up woolly."] = "Certo, {name}. Non muoverti: chi si agita a volte finisce a belare."
L["Here, {name}. I had a spare thought and nowhere to put it."] = "Tieni, {name}. Mi avanzava un pensiero, e non sapevo dove metterlo."
L["Take this, {name}. I'd add bread, but conjured bread tastes of nothing."] = "Prendi, {name}. Ci aggiungerei il pane, ma quello evocato non sa di niente."
L["{buff} for you, {name}. No charge, unlike the portals."] = "{buff} per te, {name}. Gratis, non come i portali."
L["Here, {name}. Most folk I point at turn into sheep. Today's your lucky day."] = "Tieni, {name}. Di solito chi punto diventa una pecora. Oggi ti è andata bene."
L["Nothing on fire, nothing frozen, {name}. I'm branching out."] = "Niente fuoco, niente gelo, {name}. Sto ampliando il repertorio."
L["For you, {name}. I was practising, and you happened to be the nearest head."] = "Per te, {name}. Mi stavo esercitando, e la tua era la testa più vicina."
L["Here, {name}. Freshly cast, and hardly crackling at all."] = "Tieni, {name}. Lanciato ora, e quasi non crepita."
L["Kings once hired Dalaran for this, {name}. You get it for nothing."] = "Un tempo i re pagavano Dalaran per questo, {name}. A te è gratis."
L["Take this, {name}. It wears off, unlike my last experiment."] = "Prendi, {name}. Questo svanisce. Il mio ultimo esperimento no."
L["For you, {name}: everything I learned in Dalaran, minus the essays."] = "Per te, {name}: tutto quello che ho imparato a Dalaran, tesine escluse."
L["Here, {name}. Arcane magic is best shared, before it gets ideas of its own."] = "Tieni, {name}. La magia arcana va condivisa, prima che prenda iniziative."
L["Evocation takes an age, {name}, so I spend my mana where it counts. Here."] = "L'Evocazione dura un'eternità, {name}, quindi il mana lo spendo bene. Tieni."
L["Here, {name}. A mage who walks past without helping is just a very tall hat."] = "Tieni, {name}. Un mago che non aiuta è solo un cappello a punta con le gambe."
L["Now that you're clever, {name}, stand between me and the angry things."] = "Ora che sei un genio, {name}, mettiti tra me e quelli arrabbiati."
L["For the record, {name}, I only blink away when it's tactically sound."] = "Per la cronaca, {name}, scappo con la Traslazione solo per motivi tattici."
L["Water's on me after, {name}. Please don't ask for it mid-fight."] = "L'acqua dopo la offro io, {name}. Non chiedermela in pieno scontro."
L["Minds sharpened, {name}. I'll handle the fire, the frost and the panicking."] = "Menti affilate, {name}. Io penso a fuoco, gelo e panico."
L["Right, {name}: if I say 'Frost Nova', run. If I say 'run', also run."] = "Allora, {name}: se dico 'Nova di Gelo', corri. Se dico 'corri', corri."
L["Pyroblast takes a while, {name}. Whatever interrupts it, I take personally."] = "La Pirosfera è lenta, {name}. Se qualcuno me la interrompe, è una cosa personale."
L["If I ice-block, {name}, I'm not frozen with fear. I'm frozen on purpose."] = "Se uso Blocco di Ghiaccio, {name}, non è la paura che mi gela. È strategia."
L["Portals home are on me after, {name}. Getting there alive is on all of us."] = "Il portale per casa lo offro io, {name}. Arrivarci vivi tocca a tutti."
L["Anything you'd rather not fight, {name}, point at it. It'll be wool by teatime."] = "Indicami cosa non vuoi combattere, {name}. Entro sera sarà un gomitolo."
L["I'll drop a Blizzard on them, {name}. You're welcome to watch, from outside it."] = "Gli scateno addosso una bufera di neve, {name}. Guarda pure, ma da fuori."
L["Keep them off me, {name}, and I'll keep them on fire."] = "Tienimeli lontani, {name}, e io li terrò in fiamme."
L["If I go quiet, {name}, it's Evocation, not sulking. Usually."] = "Se non parlo, {name}, è Evocazione, non broncio. Di solito."
L["If this goes badly, {name}, I've a teleport home. I'd never use it. Probably."] = "Se va male, {name}, ho un teletrasporto per casa. Non lo userei mai. Credo."
L["How thoughtful, {name}. The Light keeps accounts; I settle mine early."] = "Che premura, {name}. La Luce tiene i conti, e io pago in anticipo."
L["Thank you, {name}. I'll put in a good word with the Light. It owes me several."] = "Grazie, {name}. Metterò una buona parola con la Luce. Me ne deve parecchie."
L["Thank you, {name}. A small miracle, and I didn't even have to pray for it."] = "Grazie, {name}. Un piccolo miracolo, e non ho nemmeno dovuto pregare."
L["Thank you, {name}. My faith in people is restored. It was only resting."] = "Grazie, {name}. La mia fede nel prossimo è tornata. Stava solo riposando."
L["Thank you, {name}. You're in tonight's prayers. Near the top."] = "Grazie, {name}. Stasera sei nelle mie preghiere. In cima."
L["Healers are rarely on this end of it, {name}. I'd forgotten how nice it is."] = "Di solito siamo noi guaritori a dare, {name}. Avevo scordato che bello ricevere."
L["Thank you, {name}. You've saved me a prayer, and I'm always one short."] = "Grazie, {name}. Mi hai risparmiato una preghiera, e me ne manca sempre una."
L["Thank you, {name}. I'd give a sermon on generosity, but you've just given it."] = "Grazie, {name}. Farei una predica sulla generosità, ma me l'hai appena fatta tu."
L["Thank you, {name}. I'll light a candle for you. Two. I'm feeling reckless."] = "Grazie, {name}. Accenderò una candela per te. Anzi, due. Oggi si esagera."
L["Even my shadowy side is smiling, {name}. It has no face, so take my word."] = "Anche il mio lato d'Ombra sorride, {name}. Non ha una faccia, ma fidati."
L["Of course, {name}. The Light keeps no hours, and neither, sadly, do I."] = "Certo, {name}. La Luce non ha orari, e purtroppo nemmeno io."
L["Straight away, {name}. Most prayers take longer; you've found a shortcut."] = "Subito, {name}. Le preghiere sono più lente: hai trovato la scorciatoia."
L["Certainly, {name}. The Light shines on those who ask. I just aim it."] = "Certo, {name}. La Luce splende su chi chiede. Io mi limito a puntarla."
L["With pleasure, {name}. Faith moves mountains; I'm starting smaller."] = "Con piacere, {name}. La fede sposta le montagne; io parto dai sassi."
L["Of course, {name}. Confessions are extra, and I'd rather not hear them."] = "Certo, {name}. Le confessioni si pagano a parte, e preferirei non sentirle."
L["Of course, {name}. Nobody who asks goes without. The Light's rule, and mine."] = "Certo, {name}. Chi chiede non resta senza. Regola della Luce, e mia."
L["Certainly, {name}. A warm glow means the Light. A cold one, tell me at once."] = "Certo, {name}. Un bagliore caldo è la Luce. Se è freddo, dimmelo subito."
L["Of course, {name}. I'll pray it lasts. I'm told I have an in."] = "Certo, {name}. Pregherò che duri: ho un santo in paradiso."
L["Certainly, {name}. I heal, I smite, I do funerals. This is the cheerful bit."] = "Certo, {name}. Curo, punisco, celebro funerali. Questa è la parte allegra."
L["Bless you, {name}. No, you didn't sneeze; I'm simply thorough."] = "Salute, {name}! No, non hai starnutito: te la regalo e basta."
L["Here, {name}. Think of it as a prayer that arrived early."] = "Tieni, {name}. Consideralo una preghiera esaudita in anticipo."
L["The Light asked me to pass this along, {name}. I'm paraphrasing."] = "La Luce mi ha chiesto di passartelo, {name}. Più o meno."
L["Take this, {name}. It saves us both an awkward resurrection later."] = "Prendi, {name}. Ci risparmia una resurrezione imbarazzante più tardi."
L["Freely given, {name}. Faith costs nothing. The robes, sadly, did."] = "Dato gratis, {name}. La fede non costa nulla. Le vesti, purtroppo, sì."
L["Here, {name}. Think of me as a small, walking temple. No steps to climb."] = "Tieni, {name}. Sono un piccolo tempio ambulante. Senza scalini da salire."
L["A blessing for a stranger, {name}. The Light insists there's no such thing."] = "Una benedizione a uno sconosciuto, {name}? Per la Luce non ne esistono."
L["Take this, {name}. No collection plate follows. Look: empty hands."] = "Prendi, {name}. Niente cestino delle offerte. Guarda: mani vuote."
L["Here, {name}. I'd preach, but you look like somebody with somewhere to be."] = "Tieni, {name}. Farei una predica, ma hai l'aria di chi ha fretta."
L["Small mercies are my speciality, {name}. Here's one."] = "Le piccole grazie sono la mia specialità, {name}. Eccone una."
L["Here, {name}. I'd float over properly, but levitating in public draws a crowd."] = "Tieni, {name}. Arriverei levitando, ma in pubblico si forma sempre la folla."
L["Your turn, {name}. Now, I beg you all: make my job boring."] = "A te, {name}. E ora vi supplico tutti: fatemi annoiare."
L["Everyone stay near me, {name}. The Light has a limited range."] = "State tutti vicino a me, {name}. La Luce ha una portata limitata."
L["There, {name}. If anyone falls, I'll be very disappointed, then fix it."] = "Ecco, {name}. Se qualcuno cade, ci resterò molto male, poi rimedierò."
L["Done, {name}. I'll be at the back, praying loudly."] = "Fatto, {name}. Sarò in fondo, a pregare ad alta voce."
L["If I scream, {name}, it's a spell, and everything runs. Please don't join in."] = "Se urlo, {name}, è un incantesimo e scappano tutti. Tu non unirti, per favore."
L["If I Fade, {name}, I haven't gone. I've just become deeply uninteresting."] = "Se svanisco, {name}, non me ne vado: divento solo di una noia mortale."
L["One shield each, {name}. After that, souls need a lie-down. Pace yourselves."] = "Uno scudo a testa, {name}. Dopo, l'anima deve riposare. Andateci piano."
L["Let's all come back from this the usual way, {name}: walking."] = "Torniamo tutti nel modo solito, {name}: sulle nostre gambe."
L["I'll keep you alive, {name}. You keep me from having to say 'I told you so'."] = "Io ti tengo in vita, {name}. Tu evita di farmi dire 'te l'avevo detto'."
L["I prayed over this group, {name}. The Light said 'good luck'. I'll take it."] = "Ho pregato per il gruppo, {name}. La Luce ha detto 'auguri'. Lo prendo per buono."
L["Thank you, {name}. I'd offer you berries, but I ate them all."] = "Grazie, {name}. Ti offrirei delle bacche, ma le ho mangiate tutte."
L["Thanks, {name}. Like rain in a dry season."] = "Grazie, {name}. Come pioggia nella stagione secca."
L["Much obliged, {name}. My cat form wants to bring you a rabbit. I've said no."] = "Grazie, {name}. La mia forma felina voleva portarti un coniglio. Le ho detto no."
L["Thank you, {name}. I'll plant a tree in your honour. Give it a century."] = "Grazie, {name}. Pianterò un albero in tuo onore. Dagli un secolo."
L["Thank you, {name}. May your road stay green and your water sweet."] = "Grazie, {name}. Che la tua strada resti verde e la tua acqua dolce."
L["Kindly done, {name}. I felt that right down to my roots."] = "Che gentile, {name}. L'ho sentito fin nelle radici."
L["Nature returns everything eventually, {name}. I'm quicker. Thank you."] = "La natura prima o poi restituisce tutto, {name}. Io faccio prima. Grazie."
L["Barkskin keeps most things out, {name}. Kindness got straight through. Thanks."] = "Pelle di Corteccia ferma quasi tutto, {name}, ma non la gentilezza. Grazie."
L["Thank you, {name}. As a bear this would be a hug. Be glad I'm in this shape."] = "Grazie, {name}. Da orso sarebbe un abbraccio. Buon per te che ho questa forma."
L["Certainly, {name}. Give me a moment to remember which shape has hands."] = "Certo, {name}. Un attimo che ricordo quale forma ha le mani."
L["Of course, {name}. Hold still, like an oak. Oaks are wonderful at it."] = "Certo, {name}. Immobile come una quercia: le querce sono campionesse."
L["Gladly, {name}. The wild shares everything. Well, not the bears."] = "Con piacere, {name}. La natura condivide tutto. Be', gli orsi no."
L["Right away, {name}. The wild's had a good season; it can spare this."] = "Subito, {name}. La natura ha avuto una buona stagione: questo se lo può permettere."
L["Of course, {name}. Nature doesn't take requests, but I do."] = "Certo, {name}. La natura non accetta richieste. Io sì."
L["Gladly, {name}. Ask a tree and you'll wait a year. Ask a druid and it's now."] = "Con piacere, {name}. Un albero ci mette un anno. Un druido, un attimo."
L["Of course, {name}. The balance tips a little your way. Don't tell the balance."] = "Certo, {name}. L'equilibrio pende un po' dalla tua parte. Non dirlo all'equilibrio."
L["I'd have run over, {name}, but as a cheetah, and you'd have screamed. Here."] = "Ti avrei raggiunto di corsa, {name}, ma da ghepardo, e avresti urlato. Tieni."
L["Of course, {name}. The wild is kind to all who ask. Midges excepted."] = "Certo, {name}. La natura è gentile con chi chiede. Zanzare escluse."
L["Fresh from the Emerald Dream, {name}. Sorry if I yawn."] = "Vengo dal Sogno di Smeraldo, {name}. Scusa se sbadiglio."
L["Take this, {name}. Nature provides, and I'm its errand runner today."] = "Prendi, {name}. La natura provvede, e oggi le consegne le faccio io."
L["The wild calls you friend now, {name}. Handy, since most of it has teeth."] = "Ora la natura è tua amica, {name}. Comodo, visto che quasi tutta ha i denti."
L["I'd have picked you flowers, {name}, but this keeps better."] = "Ti avrei colto dei fiori, {name}, ma questo dura di più."
L["Here, {name}. Cenarius would want you to have it. I'm nearly sure."] = "Tieni, {name}. Cenarius vorrebbe che fosse tuo. Quasi di sicuro."
L["Here, {name}. For cold nights, sharp claws and long roads."] = "Tieni, {name}. Per notti fredde, artigli affilati e strade lunghe."
L["Take this, {name}. The wild has been watching you, and it's decided you'll do."] = "Prendi, {name}. La natura ti ha osservato e ha deciso che vai bene."
L["There, {name}. Walk lightly, and the forest will walk with you."] = "Ecco, {name}. Cammina con passo lieve, e la foresta camminerà con te."
L["For you, {name}. The Moonglade sends its regards. It sends very few."] = "Per te, {name}. La Radura Lunare ti saluta. Non saluta quasi nessuno."
L["Nature is cruel, lovely and damp, {name}. This helps with two of those."] = "La natura è crudele, splendida e umida, {name}. Questo aiuta con due su tre."
L["I tie strangers up in roots most days, {name}. This is the nicer part."] = "Di solito lego sconosciuti con le radici, {name}. Questa è la parte bella."
L["Ready, {name}? Now, whatever happens, nobody startle the bear."] = "Pronti, {name}? Qualunque cosa accada, nessuno spaventi l'orso."
L["There, {name}. I'll be the cat, the bear or, if we must swim, the seal."] = "Ecco, {name}. Farò il gatto, l'orso o, se c'è da nuotare, la foca."
L["I've one rebirth in me, {name}. Please, nobody make me choose."] = "Ho una sola Rinascita, {name}. Vi prego, non fatemi scegliere."
L["Close ranks, {name}. The forest is watching, and it's rooting for us."] = "Ranghi serrati, {name}. La foresta tifa per noi con tutte le radici."
L["I'll heal or I'll maul, {name}. Tell me which before it's urgent."] = "Curo o sbrano, {name}. Dimmi quale prima che sia urgente."
L["I've one Innervate, {name}. Whoever looks most desperate gets it. No acting."] = "Ho un'Innervazione sola, {name}. Va a chi sembra più disperato. Niente recite."
L["If I start glowing and hooting, {name}, that's moonkin. It's a serious form."] = "Se mi metto a brillare e a bubolare, {name}, è il lunagufo. È una forma seria."
L["If it gets crowded, {name}, I'll call a Hurricane. Hold on to your hats."] = "Se c'è troppa ressa, {name}, chiamo un Uragano. Tenetevi i cappelli."
L["We move like a herd, {name}. A mixed herd. One of us is sometimes a bear."] = "Ci muoviamo in branco, {name}. Un branco misto: uno di noi a volte è un orso."
L["Kindness, {name}? My favourite virtue. Just ahead of polishing."] = "Gentilezza, {name}? La mia virtù preferita. Seguita dalla lucidatura."
L["For that, {name}, my best blessing. Not the second best. The best."] = "Per te, {name}, la benedizione migliore. Non la seconda. La migliore."
L["Virtue rewarded on the spot, {name}! I do love it when that happens."] = "Virtù premiata all'istante, {name}! Adoro quando succede."
L["Thank you, {name}. My oath says to repay kindness. I'd do it anyway."] = "Grazie, {name}. Il mio giuramento impone di ricambiare. Lo farei comunque."
L["I'll judge you favourably, {name}. I judge most things harshly. Thank you."] = "Ti giudicherò con favore, {name}. Di solito giudico duramente. Grazie."
L["Thank you, {name}. My aura just brightened. It does that when I'm touched."] = "Grazie, {name}. La mia aura si è illuminata. Fa così quando mi commuovo."
L["A kindness, {name}! I'll have it engraved on my shield, beside the dents."] = "Una gentilezza, {name}! La farò incidere sullo scudo, accanto alle ammaccature."
L["Much obliged, {name}. My warhorse sends thanks as well. He's more reserved."] = "Grazie mille, {name}. Anche il mio destriero ringrazia. Lui è più riservato."
L["I swore to protect the good, {name}. You've just gone to the top of the list."] = "Ho giurato di proteggere i buoni, {name}. Ora sei in cima alla lista."
L["By the Light, {name}, of course! I've been hoping somebody would ask."] = "Per la Luce, {name}, certo! Speravo proprio che qualcuno me lo chiedesse."
L["You have my blessing, {name}, in every sense."] = "Hai la mia benedizione, {name}, in ogni senso."
L["Certainly, {name}. Kneel if you like. I won't insist. I'll be delighted."] = "Certo, {name}. Inginocchiati, se vuoi. Non insisto. Però mi farebbe piacere."
L["Gladly, {name}. I never run short of blessings. Mana, now and then."] = "Volentieri, {name}. Benedizioni ne ho sempre. Mana, non sempre."
L["Certainly, {name}. Hold still. My aim is righteous; my gauntlets are clumsy."] = "Certo, {name}. Non muoverti: la mira è giusta, i guanti d'arme un po' goffi."
L["Gladly, {name}. Helping is the oath. Shining while I do it is a bonus."] = "Con piacere, {name}. Aiutare è il giuramento; brillare è un di più."
L["Of course, {name}. Stand fast, chin up, and look deserving. There. You do."] = "Certo, {name}. Piedi saldi, mento alto, aria meritevole. Ecco. Ce l'hai."
L["Of course, {name}. You'd be amazed how rarely anyone asks the tin can for help."] = "Certo, {name}. Non immagini quanto di rado si chieda aiuto alla scatola di latta."
L["Of course, {name}. A moment while I pick the blessing. I do have favourites."] = "Certo, {name}. Un attimo che scelgo la benedizione. Ho le mie preferite."
L["The Light asks nothing in return, {name}. I, however, accept thanks."] = "La Luce non chiede nulla in cambio, {name}. Io, però, accetto un grazie."
L["Go with the Light, {name}. I'll be right behind you, clanking."] = "Va' con la Luce, {name}. Io sarò subito dietro di te, sferragliando."
L["The blessing's free, {name}. You've been spared the sermon. This time."] = "La benedizione è gratis, {name}. Il sermone te lo risparmio. Per stavolta."
L["There, {name}. It won't last forever, so be heroic while it does."] = "Ecco, {name}. Non è per sempre: compi gesta eroiche finché dura."
L["Stand tall, {name}. The Light walks with you, and it has excellent posture."] = "Testa alta, {name}. La Luce cammina con te, e ha un portamento impeccabile."
L["Take this, {name}. I'd give you my hammer too, but it's very attached to me."] = "Prendi, {name}. Ti darei anche il martello, ma è molto attaccato a me."
L["Blessings are for handing out, {name}. Hoarding them is frowned upon. By me."] = "Le benedizioni vanno distribuite, {name}. Accumularle è malvisto. Da me."
L["Justice for the wicked, blessings for the rest, {name}. You're the rest."] = "Giustizia per i malvagi, benedizioni per gli altri, {name}. Tu sei gli altri."
L["Take this, {name}. My libram says to share. It says a lot; this bit I like."] = "Prendi, {name}. Il mio tomo dice di condividere. Dice tanto; questo mi piace."
L["Chivalry isn't dead, {name}. It's in heavy armour, and it brought you this."] = "La cavalleria non è morta, {name}: è in armatura a piastre, e ti porta questo."
L["Wear it with pride, {name}. Pride's a sin, but only in large amounts."] = "Portalo con orgoglio, {name}. È peccato solo a dosi massicce."
L["You're blessed, {name}. Keep behind my shield and we'll do fine."] = "Benedizione fatta, {name}. Resta dietro il mio scudo e andrà tutto bene."
L["Stand fast, {name}. We have the Light, and I have a very large hammer."] = "Tenete duro, {name}. Abbiamo la Luce, e io ho un martello molto grosso."
L["One blessing each, {name}. The Light is generous, but it insists on turns."] = "Una benedizione a testa, {name}. La Luce è generosa, ma pretende i turni."
L["Splendid, {name}. Now, nobody look directly at me. I'm rather bright today."] = "Splendido, {name}. Ora non guardatemi dritto: oggi splendo parecchio."
L["Stay inside my aura, {name}. It's warmer than it looks."] = "Resta nella mia aura, {name}. È più calda di come sembra."
L["If I stun something, {name}, hit it while it's thinking things over."] = "Se stordisco qualcosa, {name}, colpiscilo mentre ci ripensa."
L["The glowing ground is mine, {name}. Stand in it freely; it only bites them."] = "Il terreno che brilla è mio, {name}. Calpestalo pure: morde solo loro."
L["I'll judge them, {name}, and you sentence them. A very efficient court."] = "Io li giudico, {name}, tu esegui la sentenza. Un tribunale efficientissimo."
L["If I shout 'for the Light', {name}, it means charge. Or pray. Usually both."] = "Se grido 'Per la Luce!', {name}, vuol dire carica. O prega. Di solito entrambe."
L["Armour polished, hammer blessed, {name}, and my horse is sulking. We're ready."] = "Armatura lucida, martello benedetto, {name}, e il cavallo tiene il muso. Pronti."
L["I've called on Righteous Fury, {name}. Let them come to me."] = "Ho invocato la furia sacra, {name}. Che vengano da me."
L["How kind, {name}. My imp says thank you too. He's lying, but I'm not."] = "Che gentile, {name}. Anche il mio imp ti ringrazia. Mente, ma io no."
L["Thank you, {name}. It's been ages since anyone gave me something uncursed."] = "Grazie, {name}. Da secoli nessuno mi regalava qualcosa di non maledetto."
L["Thank you, {name}. I'll repay you with something I didn't find in a crypt."] = "Grazie, {name}. Ti ripagherò con qualcosa che non ho trovato in una cripta."
L["Most gracious, {name}. I've asked the voidwalker to stop looming at you."] = "Troppo gentile, {name}. Ho detto al Viandante del Vuoto di non fissarti."
L["Thank you, {name}. Most folk cross the road when they see me."] = "Grazie, {name}. Quasi tutti cambiano marciapiede quando mi vedono."
L["No blood, no bargain, no binding, {name}? What a strange way to trade. Thanks."] = "Senza sangue, senza patto, senza sigillo, {name}? Che affari strani. Grazie."
L["Thank you, {name}. Should anything haunt you, send it my way."] = "Grazie, {name}. Se qualcosa ti perseguita, mandalo da me."
L["How thoughtful, {name}. Everything I'm given, I return. Except souls. Here."] = "Che pensiero, {name}. Restituisco tutto ciò che ricevo. Tranne le anime. Tieni."
L["Of course, {name}. No soul required. This time."] = "Certo, {name}. Nessuna anima richiesta. Per stavolta."
L["You asked a warlock for help, {name}. Bold. I like you already."] = "Chiedere aiuto a chi evoca demoni, {name}? Che fegato. Mi piaci già."
L["Of course, {name}. The imp offered to help, and I said no, for all our sakes."] = "Certo, {name}. L'imp voleva aiutare. Gli ho detto di no, per il bene di tutti."
L["Certainly, {name}. Of all my spells, this is the one I can do at parties."] = "Certo, {name}. Dei miei incantesimi, è l'unico presentabile alle feste."
L["Gladly, {name}. A good deed on my record; the Shadow Council would be appalled."] = "Volentieri, {name}. Buona azione in fedina: il Consiglio dell'Ombra inorridirà."
L["Of course, {name}. Please don't read the book I'm holding. For your own sake."] = "Certo, {name}. Non leggere il libro che ho in mano. Per il tuo bene."
L["Certainly, {name}. Feel watched? That's only the Eye of Kilrogg. Hold still."] = "Certo, {name}. Senti occhi addosso? È solo l'Occhio di Kilrogg. Non muoverti."
L["Of course, {name}. I only curse people who don't ask nicely. You're quite safe."] = "Certo, {name}. Maledico solo chi non chiede con garbo. Sei al sicuro."
L["Yes, {name}, it's the one without screaming. Hold still."] = "Sì, {name}, è quello senza urla. Non muoverti."
L["Of course, {name}. Going somewhere wet? I won't ask. Warlocks never ask."] = "Certo, {name}. Si va a fare un tuffo? Non chiedo. Gli stregoni non chiedono."
L["Here, {name}. Don't ask where it came from. Really, don't."] = "Tieni, {name}. Non chiedermi da dove viene. Davvero, non farlo."
L["Fall in a lake someday, {name}, and you'll think of me fondly."] = "Se un giorno cadrai in un lago, {name}, penserai a me con affetto."
L["Breathe easy, {name}. I'd hate to lose you to anything as dull as water."] = "Respira pure, {name}. Perderti per colpa dell'acqua sarebbe così banale."
L["Here, {name}. You'll want a soulstone too, but that's a bigger conversation."] = "Tieni, {name}. Per la Pietra dell'Anima ci vorrà un discorso a parte."
L["Take this, {name}. It's the only spell of mine the priests approve of."] = "Prendi, {name}. È l'unico mio incantesimo che i sacerdoti approvano."
L["Take this, {name}. My mother still thinks I'm a mage. Let's keep it that way."] = "Prendi, {name}. Mia madre crede ancora che io sia un mago. Acqua in bocca."
L["Here, {name}. It isn't green, it doesn't whisper, and it won't follow you home."] = "Tieni, {name}. Non è verde, non sussurra e non ti segue a casa."
L["Here, {name}. Dark magic, used for good. Do tell my old tutor; he'll hate it."] = "Tieni, {name}. Magia oscura a fin di bene. Dillo al mio vecchio maestro: lo odierà."
L["Here, {name}. I keep the darker spells for people who've earned them."] = "Tieni, {name}. Gli incantesimi più oscuri li tengo per chi se li merita."
L["Here, {name}. I'm not all curses and fear. Mostly, but not all."] = "Tieni, {name}. Non sono solo maledizioni e paura. Quasi, ma non solo."
L["My grimoire has a chapter on kindness, {name}. It's short, but I've read it."] = "Il mio grimorio ha un capitolo sulla gentilezza, {name}. È corto, ma l'ho letto."
L["Everyone ready, {name}? Souls intact? Good. Let's keep it that way."] = "Tutti pronti, {name}? Anime intatte? Bene. Teniamole così."
L["Stay close, {name}. The voidwalker takes the hits; I take the credit."] = "Stammi vicino, {name}. I colpi li prende il Viandante, i meriti io."
L["Swim all you like, {name}. If anyone drifts off, I'll summon them back."] = "Nuota quanto vuoi, {name}. Chi si perde, lo evoco indietro."
L["Do pet the felhunter, {name}. Just take your spells off first."] = "Accarezza pure il Vilsegugio, {name}. Ma prima togliti gli incantesimi."
L["If I fear something, {name}, don't chase it. It comes back. Angrier."] = "Se metto Paura a qualcosa, {name}, non inseguirlo. Torna più arrabbiato."
L["I trade blood for mana, {name}. It looks worse than it is."] = "Scambio sangue per mana, {name}. Sembra peggio di quanto sia."
L["Healthstones after, {name}. For a crisis, mind, not as a snack."] = "Pietre della Salute dopo, {name}. Per le crisi, non per merenda."
L["Keep clear when I cast Hellfire, {name}. I burn too. That's the tragic part."] = "Stai lontano dal mio Fuoco Infernale, {name}. Brucio anch'io: è il lato tragico."
L["My imp is on fire, {name}, and he's on our side. Please stop dousing him."] = "Il mio imp va a fuoco, {name}, ma è dei nostri. Smettila di spegnerlo."
L["If something green falls from the sky, {name}, that's mine. Cheer."] = "Se dal cielo piove qualcosa di verde, {name}, è mio. Applaudi."
L["Thank you, {name}! Sorry, was that loud? I only have the one volume."] = "Grazie, {name}! Scusa, ho urlato? Ho un solo volume."
L["Much obliged, {name}. No spells to give back, but I do a very sincere shout."] = "Grazie mille, {name}. Incantesimi non ne ho, ma faccio un urlo sincerissimo."
L["Thanks, {name}. Now I'm twice as angry. In the good way."] = "Grazie, {name}. Ora ho il doppio della rabbia. In senso buono."
L["Thanks, {name}. You've earned a place right behind me. Safest spot there is."] = "Grazie, {name}. Hai un posto dietro di me: il più sicuro che ci sia."
L["Thank you, {name}. Kindness makes me soft. Luckily I've plenty of armour."] = "Grazie, {name}. La gentilezza mi ammorbidisce. Per fortuna ho tanta armatura."
L["Thank you, {name}. My armourer thanks you too. I paid for his house."] = "Grazie, {name}. Ti ringrazia anche il mio armaiolo. Gli ho pagato la casa."
L["Thanks, {name}. I'd bandage something for you, but you look annoyingly fine."] = "Grazie, {name}. Ti fascerei qualcosa, ma stai irritantemente bene."
L["Thank you, {name}. I switched to my grateful stance for that. It's rarely used."] = "Grazie, {name}. Per l'occasione, Postura della Gratitudine. La uso di rado."
L["You've given me magic, {name}. No idea where to keep it. I'll wear it. Thanks."] = "Mi hai dato della magia, {name}. Non so dove tenerla. La indosso. Grazie."
L["Owing folk makes me restless, {name}, and restless makes me charge things."] = "Essere in debito mi agita, {name}, e quando mi agito carico qualcosa."
L["You want a shout, {name}? I was going to shout anyway."] = "Vuoi un urlo, {name}? Tanto avrei urlato comunque."
L["Of course, {name}. A fighter who asks for courage already has some."] = "Certo, {name}. Chi chiede coraggio ne ha già un po'."
L["Right away, {name}. Square your shoulders. There, that's half of it."] = "Subito, {name}. Spalle dritte. Ecco, metà del lavoro è fatta."
L["Happily, {name}! Go hit something for me."] = "Con piacere, {name}! Va' a colpire qualcosa per me."
L["Right, {name}. Deep breath. Not you. Me."] = "Bene, {name}. Respiro profondo. Non tu. Io."
L["Happy to, {name}. First request today that didn't involve lifting something."] = "Volentieri, {name}. Prima richiesta di oggi senza pesi da sollevare."
L["Coming up, {name}. Plant your feet. This one has a kick to it."] = "Arriva, {name}. Piedi ben piantati. Questo ha un bel calcio."
L["Of course, {name}. Most folk only ask me to stop. This is a nice change."] = "Certo, {name}. Di solito mi chiedono solo di smettere. Che bel cambiamento."
L["Of course, {name}. Took me years to learn. Years of yelling at trees, mostly."] = "Certo, {name}. Anni di studio. Soprattutto anni a urlare contro gli alberi."
L["Consider yourself shouted at, {name}. Affectionately."] = "Ti ho appena urlato addosso, {name}. Con affetto."
L["No incense, no prayers, {name}. Just me, shouting encouragingly."] = "Niente incenso, niente preghiere, {name}. Solo urla d'incoraggiamento."
L["Chin up, {name}! If anything bothers you, I'll charge it."] = "Su con la vita, {name}! Se qualcosa ti dà fastidio, lo carico."
L["There, {name}! Anything that doesn't feel braver now wasn't listening."] = "Ecco, {name}! Chi non si sente più coraggioso ora, non stava ascoltando."
L["Here, {name}, some courage. Spend it freely; I've plenty more."] = "Tieni, {name}: coraggio. Spendilo pure, ne ho in abbondanza."
L["Here, {name}. Something sharper than a whetstone: morale."] = "Tieni, {name}. Qualcosa di più affilato di una cote: il morale."
L["Take this, {name}. Warriors don't carry spells, so we carry each other."] = "Prendi, {name}. Noi guerrieri non abbiamo magie, ma ci copriamo le spalle."
L["Here, {name}. You look about to walk into something big. Walk in harder."] = "Tieni, {name}. Stai per buttarti in un grosso guaio? Buttati a capofitto."
L["Here, {name}. No magic in it. Just a warrior believing in you, very firmly."] = "Tieni, {name}. Niente magia: solo un guerriero che crede in te. Tantissimo."
L["Take this, {name}. It's loud, it's free, and I mean it."] = "Prendi, {name}. È rumoroso, è gratis, e lo dico sul serio."
L["Here, {name}. Tell whatever you fight that a warrior vouched for you."] = "Tieni, {name}. Di' a chiunque combatti che un guerriero garantisce per te."
L["That one was for you, {name}. The next one's for whatever's in your way."] = "Quello era per te, {name}. Il prossimo è per chi ti sbarra la strada."
L["Listen up, {name}! That's it. That was the whole speech."] = "Ascoltatemi, {name}! Ecco. Era tutto il discorso."
L["Where's the danger, {name}? Never mind, I'll find it. Face first."] = "Dov'è il pericolo, {name}? Niente, lo trovo io. Con la faccia."
L["Right, {name}! I go first, I shout loudest, and nobody touches the healer."] = "Bene, {name}! Io entro prima, urlo più forte, e nessuno tocca il guaritore."
L["Everybody angrier? Good. Onward, {name}, and mind my backswing."] = "Tutti più arrabbiati? Bene. Avanti, {name}, e occhio al mio rovescio."
L["I need to be hit before I'm any use, {name}. Nobody panic when it happens."] = "Devo prenderle prima di servire, {name}. Niente panico quando succede."
L["Bandages are in my pack, {name}. I tied the knots, so they're very secure."] = "Le bende sono nello zaino, {name}. I nodi li ho fatti io: non si sciolgono più."
L["Right, {name}: I take the hits, you take the credit, and we split the repairs."] = "Allora, {name}: io prendo i colpi, tu prendi il merito, e le riparazioni a metà."
L["If I go red and quiet, {name}, that's Berserker Rage. Red and loud, all's well."] = "Faccia rossa e muta, {name}? Rabbia del berserker. Rossa e urlante? Tutto a posto."
L["My shield's seen worse than this, {name}. So has my face. Onward."] = "Il mio scudo ne ha viste di peggio, {name}. La mia faccia pure. Avanti."
L["A sharper mind for you, {name}. Mine cost me an eyebrow in Dalaran."] = "Una mente più acuta, {name}. La mia costò un sopracciglio a Dalaran."
L["A clearer head for you, {name}. What you fill it with is your own affair."] = "Una mente più limpida, {name}. Cosa ci metti dentro sono affari tuoi."
L["Thoughts humming, {name}? Normal. If they hum back, come and find me."] = "Pensieri che ronzano, {name}? Normale. Se ti rispondono, cercami."
L["A little arcane for your thoughts, {name}. Keep the change."] = "Un po' d'arcano per i tuoi pensieri, {name}. Tieni il resto."
L["Brilliance, bottled, {name}. The Kirin Tor would charge you for the bottle."] = "Brillantezza in bottiglia, {name}. Il Kirin Tor ti farebbe pagare il vuoto."
L["Sharper wits, {name}. Spend them on spells, locks or riddles; I won't judge."] = "Più acume, {name}. Usalo per incantesimi, serrature o indovinelli: non giudico."
L["On loan from the Violet Citadel, {name}. Late returns are fined in sheep."] = "In prestito dalla Cittadella Violacea, {name}. Chi lo rende tardi, bela."
L["Clever enough to spot the trap now, {name}. Avoiding it is a separate spell."] = "Ora la trappola la vedi, {name}. Per evitarla serve un altro incantesimo."
L["There, {name}. Wiser already: look, you're standing further from me."] = "Ecco, {name}. Funziona già: vedi come prendi le distanze da me?"
L["The one spell of mine that's never set anything alight, {name}. Enjoy."] = "Il mio unico incantesimo che non ha mai incendiato nulla, {name}. Goditelo."
L["A gnome's instructions make sense now, {name}. Still don't follow them."] = "Ora capisci le istruzioni degli gnomi, {name}. Non seguirle comunque."
L["Fortitude, {name}: a priest's polite way of saying 'stand in front'."] = "Fermezza, {name}: in sacerdotese vuol dire 'mettiti davanti'."
L["Every bit of stamina is one less panicked prayer from me, {name}."] = "Ogni punto di tempra è una preghiera disperata in meno per me, {name}."
L["Tougher already, {name}. Please don't take that as a dare."] = "Già più resistente, {name}. Non prenderla come una sfida."
L["There are other Power Words, {name}. 'Shield', and in emergencies, 'Run'."] = "Ci sono altre Parole del Potere, {name}: 'Scudo' e, in emergenza, 'Scappa'."
L["Sturdier now, {name}. Falls, bears and bad decisions all hurt a bit less."] = "Ora cadute, orsi e cattive decisioni fanno un po' meno male, {name}."
L["{buff}, {name}. Three words where 'be tougher' would do."] = "{buff}, {name}. Tante parole, quando bastava 'tieni duro'."
L["A little more of you to go round, {name}. Spend it slowly."] = "Ora di te ce n'è un po' di più, {name}. Non sprecarti."
L["Harder to knock down now, {name}. The ground will miss you."] = "Ora è più difficile buttarti giù, {name}. Il suolo sentirà la tua mancanza."
L["Stubbornness, really, {name}. Dwarves are born with it; the rest of us pray."] = "È testardaggine, in fondo, {name}. I nani ci nascono; noi altri preghiamo."
L["The only armour that never needs repairing, {name}. The smiths hate it."] = "L'unica armatura che non va mai riparata, {name}. I fabbri la odiano."
L["Consider your spirits lifted, {name}. Divinely, as it happens."] = "Spirito sollevato, {name}. Divinamente, per giunta."
L["Like a good night's sleep, {name}, without all the lying down."] = "Come una bella dormita, {name}, ma senza doversi sdraiare."
L["A second helping of spirit, {name}. The Light always insists on seconds."] = "Un altro po' di spirito, {name}. La Luce è come la nonna: il bis è d'obbligo."
L["Keep your spirit where it is, {name}. Loose ones wander off."] = "Lo spirito tienilo dov'è, {name}. Quelli sciolti se ne vanno in giro."
L["Cheer up, {name}. That's not advice this time; it's a spell."] = "Tirati su, {name}. Stavolta non è un consiglio, è un incantesimo."
L["Recover faster, {name}, from long fights and longer walks."] = "Riprenditi prima, {name}, da lunghe lotte e marce più lunghe."
L["A deep breath's worth of calm, {name}, without having to take one."] = "La calma di un respiro profondo, {name}, senza nemmeno farlo."
L["The Light's own second wind, {name}. Don't waste it on arguments."] = "Il secondo fiato della Luce, {name}. Non sprecarlo a litigare."
L["Proof against shadow, {name}. I know its tricks; I've borrowed a few."] = "A prova d'ombra, {name}. Conosco i suoi trucchi: ne ho usati un paio."
L["Should the Void call, {name}, you can now pretend you're out."] = "Se il Vuoto chiama, {name}, ora puoi fingere di non essere in casa."
L["For when the dark gets personal, {name}. It usually does."] = "Per quando il buio ce l'ha con te, {name}. Capita spesso."
L["The shadows will have to knock first now, {name}."] = "Ora le ombre dovranno bussare prima di entrare, {name}."
L["The dark still bites, {name}, but now it has to chew."] = "Il buio morde ancora, {name}, ma ora gli tocca masticare."
L["A lining against the dark, {name}. Like a cloak, only on the inside."] = "Una fodera contro il buio, {name}. Come un mantello, ma dentro."
L["Curses slide right off you now, {name}. The cultists will take it personally."] = "Ora le maledizioni ti scivolano addosso, {name}. I cultisti se la prenderanno."
L["Priests study the Shadow to guard against it, {name}. Mostly."] = "I sacerdoti studiano l'Ombra per difendersene, {name}. Quasi tutti."
L["For crypts, cults and Scholomance, {name}. The dark gets chatty in all three."] = "Per cripte, culti e Scholomance, {name}. Lì il buio attacca bottone."
L["It won't keep off gloom, {name}. For that you want company. Here I am."] = "Contro l'umor nero non funziona, {name}. Lì serve compagnia. Eccomi."
L["Marked by the wild, {name}. The deer will tip their antlers as you pass."] = "Marchio della natura, {name}. Al tuo passaggio i cervi chineranno le corna."
L["You may smell faintly of moss, {name}. That's how you know it's working."] = "Potresti sapere un po' di muschio, {name}. È così che capisci che funziona."
L["Mark of the Wild, {name}. The wolves will still bite, but they'll feel bad."] = "Il marchio della natura, {name}. I lupi morderanno lo stesso, ma con rimorso."
L["The wild's own seal of approval, {name}. The squirrels were consulted."] = "Marchio di qualità della natura, {name}. Sentito il parere degli scoiattoli."
L["A little of the wild in you now, {name}. Resist the urge to howl."] = "Un po' di selvaggio in te, {name}. Trattieni la voglia di ululare."
L["Hide, claw and a thick coat, {name}. The wild packs light but thorough."] = "Pelle, artigli e pelliccia, {name}. La natura viaggia leggera, ma completa."
L["Cenarius signs every one of these, {name}. Well, a tree does, on his behalf."] = "Cenarius li firma uno per uno, {name}. Be', un albero firma per lui."
L["The forest's own armour, {name}. It doesn't clank, and it smells of rain."] = "L'armatura della foresta, {name}. Non sferraglia e sa di pioggia."
L["A tougher hide in seconds, {name}. The oaks took centuries and are furious."] = "Scorza dura in un attimo, {name}. Le querce ci hanno messo secoli, e rosicano."
L["It's a loan from the wild, {name}. Try not to bring it back chewed."] = "È un prestito della natura, {name}. Non restituirlo rosicchiato."
L["Anything that bites you now gets a mouthful, {name}."] = "Chi ti morde, {name}, avrà la bocca piena di spine."
L["Let the boar charge, {name}. It'll leave with regrets and splinters."] = "Lascia caricare il cinghiale, {name}. Ripartirà con rimpianti e schegge."
L["Like a rose, {name}: lovely to look at, a mistake to grab."] = "Non c'è rosa senza spine, {name}. E ora nemmeno tu."
L["Thorns, {name}. I grew them myself, so do be polite to them."] = "Spine, {name}. Le ho coltivate io, quindi sii gentile con loro."
L["A hedge you can wear, {name}. Neatly trimmed; I'm not a barbarian."] = "Una siepe da indossare, {name}. Ben potata: mica siamo barbari."
L["Nature never turns the other cheek, {name}. It grows spikes on it."] = "La natura non porge l'altra guancia, {name}. Ci fa crescere le spine."
L["Raptors learn slowly, {name}. This teaches them one bite at a time."] = "I raptor imparano piano, {name}. Questo insegna loro un morso alla volta."
L["Prickly on the outside, {name}. What's inside is your own business."] = "Come una castagna, {name}: spine fuori. Il dentro è affar tuo."
L["Mind your cloak, {name}. Wool and brambles never did get along."] = "Occhio al mantello, {name}. Lana e rovi non sono mai andati d'accordo."
L["Blessing of Kings, {name}. No crown, no throne, no taxes owed."] = "Benedizione dei Re, {name}. Niente corona, trono o tasse."
L["Long may you reign, {name}. For the next while, anyway."] = "Lungo regno a te, {name}. Almeno per i prossimi minuti."
L["A little more of everything, {name}. Kings never did settle for less."] = "Un po' di più in tutto, {name}. I re non si sono mai accontentati."
L["A king's blessing, {name}. Worn by better heads than mine, and some worse."] = "Benedizione da re, {name}. Portata da teste migliori della mia. E peggiori."
L["Every strength a little higher, {name}. Kings like to hedge their bets."] = "Tutto un po' più forte, {name}. I re tengono sempre il piede in più staffe."
L["Crown not included, {name}. Everything else is, a little."] = "Corona non inclusa, {name}. Tutto il resto sì, un pochino."
L["All of you, only more so, {name}. Wear it well."] = "Tu, ma un po' di più, {name}. Portalo con orgoglio."
L["A blessing fit for royalty, {name}. You'll have to do your own waving."] = "Benedizione regale, {name}. Il saluto con la manina, però, fallo da te."
L["Stronger, cleverer, hardier, {name}. Kings had advisers for that; you have me."] = "Più forza, acume e tempra, {name}. I re avevano i consiglieri; tu hai me."
L["Royal treatment, {name}, minus the courtiers and the poisoned wine."] = "Trattamento da re, {name}, senza cortigiani né vino avvelenato."
L["Might doesn't make right, {name}, but it does help the argument."] = "La forza non ti dà ragione, {name}, ma nelle discussioni aiuta."
L["A firmer swing for you, {name}. The Light loves a good follow-through."] = "Un colpo più deciso, {name}. La Luce ama chi va fino in fondo."
L["Stronger arms, {name}. Kindly point them at something that deserves it."] = "Braccia più forti, {name}. Puntale, per favore, su chi se lo merita."
L["Blessing of Might, {name}. It'll surprise you. It'll surprise them far more."] = "Benedizione della Potenza, {name}. Sorprenderà te. E loro molto di più."
L["Swing away, {name}. The Light will take the credit if it goes well."] = "Colpisci pure, {name}. Se va bene, il merito se lo prende la Luce."
L["Hit harder, {name}. Them, I mean. Not me. Never the paladin."] = "Picchia più forte, {name}. Loro, eh. Non me. Mai chi ti benedice."
L["More weight behind every swing, {name}. The Light calls it conviction."] = "Più peso in ogni colpo, {name}. La Luce la chiama convinzione."
L["Doors, crates and ogres will all give way easier now, {name}."] = "Porte, casse e ogre ora cederanno più facilmente, {name}."
L["Your weapon will feel lighter, {name}. It isn't. You're just holier."] = "L'arma ti sembrerà più leggera, {name}. È solo un effetto di Luce."
L["The Light's own elbow grease, {name}. Put it somewhere useful."] = "Olio di gomito della Luce, {name}. Usalo per qualcosa di utile."
L["Wisdom for you, {name}. I kept a little back for myself. Very little."] = "Saggezza per te, {name}. Un po' l'ho tenuta per me. Pochissima."
L["Wisdom for your mana, {name}. The other kind still comes from bad decisions."] = "Saggezza per il tuo mana, {name}. L'altra si impara ancora dagli errori."
L["Your mana creeps back on its own now, {name}, like a cat that's forgiven you."] = "Ora il mana torna da solo, {name}, come un gatto che ti ha perdonato."
L["Fewer sips between fights, {name}. The innkeepers will be heartbroken."] = "Meno bevute tra uno scontro e l'altro, {name}. I locandieri piangeranno."
L["Drink less, cast more, {name}. The Light's own budget advice."] = "Bevi meno, lancia di più, {name}. Consigli di risparmio dalla Luce."
L["Blessing of Wisdom, {name}: the one blessing that pays for itself."] = "Benedizione della Saggezza, {name}: l'unica che si ripaga da sola."
L["A steadier well to draw from, {name}. Draw deep."] = "Un pozzo più costante a cui attingere, {name}. Attingi a fondo."
L["Wisdom usually comes with age, {name}. This comes with a paladin. Quicker."] = "La saggezza viene con gli anni, {name}. Questa con un paladino: fa prima."
L["May you know when to fight and when to sit down, {name}."] = "Che tu sappia quando combattere e quando sederti, {name}."
L["A wise blessing for a wise choice, {name}: keeping a paladin around."] = "Saggezza per una scelta saggia, {name}: tenerti accanto un paladino."
L["A blessing of quiet, {name}. Monsters will forget whose fault it was."] = "Benedizione di quiete, {name}. I mostri scorderanno di chi era la colpa."
L["Blessing of Salvation, {name}. You are now somebody else's problem."] = "Benedizione della Salvezza, {name}. Ora sei un problema di qualcun altro."
L["Saved, {name}. Not your soul, mind. Just your hide."] = "In salvo, {name}. Non l'anima, bada. Solo la pelle."
L["Hit hard, {name}. If anything turns round, look innocent. The Light will."] = "Colpisci forte, {name}. Se qualcosa si gira, fai l'innocente. Come la Luce."
L["The monsters will find you forgettable now, {name}. Today, that's a compliment."] = "Ora i mostri ti troveranno dimenticabile, {name}. Oggi è un complimento."
L["Go on, hit it, {name}. It'll blame whoever's wearing the most plate."] = "Dai, colpiscilo, {name}. Darà la colpa a chi ha più piastre addosso."
L["The art of being in the fight, {name}, and out of the argument."] = "L'arte di stare nella mischia, {name}, ma fuori dal mirino."
L["The Light's kindest alibi, {name}. Use it often."] = "L'alibi più gentile della Luce, {name}. Usalo spesso."
L["The Light will find you easier now, {name}. Try not to squint."] = "Ora la Luce ti trova meglio, {name}. Non strizzare gli occhi."
L["Holy Light lands harder on you now, {name}. Please don't make me prove it."] = "Ora Luce Sacra ti cura di più, {name}. Non costringermi a dimostrarlo."
L["You'll heal easier, {name}. The Light appreciates a willing patient."] = "Guarirai meglio, {name}. La Luce apprezza i pazienti collaborativi."
L["Blessing of Light, {name}. Saving you is simpler now. Not that you'll need it."] = "Benedizione della Luce, {name}. Salvarti ora è più facile. Non che ti servirà."
L["The Light knows the way to you now, {name}. Let's keep its visits social."] = "Ora la Luce sa la strada di casa tua, {name}. Solo visite di cortesia, però."
L["A blessing that makes my job easier, {name}. Generous and lazy all at once."] = "Mi semplifica il lavoro, {name}. Generosità e pigrizia in un colpo solo."
L["Holy Light fits you better now, {name}, like a well-cut tabard."] = "Ora Luce Sacra ti sta meglio, {name}, come una tabarda su misura."
L["Mending you just got cheaper, {name}. Not that I'd ever send a bill."] = "Curarti ora costa meno, {name}. Non che ti abbia mai presentato il conto."
L["Block a blow now, {name}, and the Light hits back for you. It's petty."] = "Para un colpo, {name}, e la Luce risponde per te. È permalosa."
L["Every blow lands softer now, {name}. Complaints go to the Light."] = "Ogni colpo fa meno male, {name}. Reclami alla Luce."
L["All the shelter of a temple, {name}, and none of the roof repairs."] = "Tutto il riparo di un tempio, {name}, senza le spese del tetto."
L["Claim sanctuary, {name}. It's easier when you bring your own."] = "Rifugiati nel santuario, {name}. È più facile se te lo porti dietro."
L["Every blow is a little less rude now, {name}. The Light teaches manners."] = "Ora ogni colpo è meno maleducato, {name}. La Luce insegna le buone maniere."
L["Nobody can evict you from this sanctuary, {name}. I checked the deeds."] = "Nessuno può sfrattarti da questo santuario, {name}. Ho controllato il rogito."
L["An ogre's club lands like a pillow now, {name}. A heavy, angry pillow."] = "La clava di un ogre ora è un cuscino, {name}. Pesante e arrabbiato."
L["Instructions, {name}: hit things harder. There is no page two."] = "Istruzioni, {name}: colpisci più forte. Non c'è una seconda pagina."
L["Your sword arm is sorted, {name}. For the rest of you, see a priest."] = "Il braccio armato è a posto, {name}. Per il resto, chiedi a un sacerdote."
L["Battle Shout, {name}. Not a spell, really. A strongly worded suggestion."] = "Urlo di Battaglia, {name}. Più che un incantesimo, un consiglio energico."
L["RAAAGH! That one was for you, {name}. Everyone else just overheard."] = "RAAAGH! Quello era per te, {name}. Gli altri hanno solo origliato."
L["Priests pray, mages study, {name}. I clear my throat."] = "Chi prega, chi studia, {name}. Io mi schiarisco la voce."
L["Words matter, {name}. Mostly the loud ones."] = "Contano le parole, {name}. Specie quelle forti."
L["The shout lasts a few minutes, {name}. The ringing in your ears, rather longer."] = "L'urlo dura qualche minuto, {name}. Il fischio nelle orecchie, un po' di più."
L["There were words in that shout once, {name}. They slowed it down."] = "Una volta quell'urlo aveva delle parole, {name}. Lo rallentavano."
L["A little breath from the damned, {name}. They weren't using it."] = "Un po' di fiato dai dannati, {name}. Tanto non lo usavano."
L["Unending Breath, {name}. The fish will have so many questions."] = "Fiato infinito, {name}. I pesci avranno mille domande."
L["Stay down as long as you like, {name}. The air's on me."] = "Resta giù quanto vuoi, {name}. L'aria la offro io."
L["Swim deep, {name}. If a murloc asks, you're only visiting."] = "Nuota a fondo, {name}. Se un murloc chiede, sei solo di passaggio."
L["Air from a place where air isn't strictly air, {name}. Breathe it anyway."] = "Aria da un posto dove l'aria non è proprio aria, {name}. Respirala comunque."
L["The Vile Reef awaits, {name}. Try not to find out how it earned the name."] = "Laggiù c'è una scogliera dal nome sinistro, {name}. Non scoprire perché."
L["Dropped something in a lake, {name}? Now's your chance."] = "Ti è caduto qualcosa in un lago, {name}? Ora puoi ripescarlo."
L["No gills, {name}. I read the small print; gills were extra."] = "Niente branchie, {name}. Ho letto le clausole: erano un extra."
L["Folk will think we're duelling, {name}. Thanks for the {gift}."] = "Penseranno che stiamo duellando, {name}. Grazie per {gift}."
L["{gift} for {buff}. No auctioneer's cut, {name}."] = "{gift} per {buff}. Senza commissioni d'asta, {name}."
L["Beaten to it, {name}! Your {gift} was quicker than my manners."] = "Che tempismo, {name}! {gift} ha battuto le mie buone maniere."
L["{gift} in, {buff} out. Finest economy in all Azeroth."] = "Entra {gift}, esce {buff}. L'economia migliore di tutta Azeroth."
L["{gift}, for me? All I have is this, {name}, but it's heartfelt."] = "{gift}, per me? Ho solo questo, {name}, ma è di cuore."
L["Your {gift} fits perfectly, {name}. Did you measure me?"] = "{gift} mi calza a pennello, {name}. Mi hai preso le misure?"
L["A treaty in spells, {name}: {gift} for {buff}."] = "Un trattato magico, {name}: {gift} per {buff}."
L["{gift}! I feel taller already. Have some {buff}."] = "{gift}! Già mi sento crescere. Ecco {buff} per te."
L["I was about to ask for {gift}, {name}. You read my mind."] = "Stavo per chiederti {gift}, {name}. Mi hai letto nel pensiero."
L["Your {gift} still fizzes, {name}. Here's some fizz back."] = "{gift} frizza ancora, {name}. Eccoti un po' di bollicine."
L["Such a kind {gift}, {name}. I'll tell the whole inn. Twice."] = "{gift}, che gentile, {name}. Lo dirò a tutta la locanda. Due volte."
L["You cast {gift} first, {name}? My mother would despair of me."] = "{gift} prima tu, {name}? Mia madre si vergognerebbe di me."
L["I'll remember your {gift} fondly, {name}. Until it wears off."] = "Ricorderò {gift} con affetto, {name}. Finché non svanisce."
L["{gift} for {buff}, free. Somewhere, a goblin weeps."] = "{gift} per {buff}, gratis. Chissà dove, un goblin piange."
L["Your {gift}, my {buff}. We'll be unbearable now."] = "{gift} da te, {buff} da me. Ora saremo insopportabili."
L["Thanks for the {gift}, {name}. I'll earn it before it fades."] = "Grazie per {gift}, {name}. Ne sarò all'altezza finché dura."
L["For {gift} I'd hand you both moons, {name}. This'll have to do."] = "Per {gift} ti darei entrambe le lune, {name}. Accontentati di questo."
L["You brought {gift}, I brought {buff}. Now it's a party."] = "Tu hai portato {gift}, io {buff}. Ora sì che è una festa."
L["{gift} means 'good luck'. {buff} means 'you too'."] = "{gift} sta per 'in bocca al lupo'. {buff}, per 'crepi'."
L["Your {gift} came first; my {buff} tries twice as hard."] = "{gift} mi ha battuto sul tempo; {buff} si impegna il doppio."
L["If anyone asks, {buff} came before {gift}. Deal?"] = "Se chiedono, {buff} c'era prima di {gift}. Intesi?"
L["{gift} made my day; {buff} should make your hour."] = "{gift} mi ha svoltato la giornata; {buff} almeno l'ora."
L["Saved my {buff} for someone worthy. Then came {gift}."] = "Tenevo {buff} per qualcuno che lo meritasse. Poi mi hai dato {gift}."
L["Your {gift} went to my head; my {buff} goes to yours."] = "{gift} mi ha dato alla testa; {buff} ora va alla tua."
L["{gift} on me, {buff} on you. We wear each other's work."] = "{gift} a me, {buff} a te. Ci vestiamo a vicenda."
L["{gift} and {buff} fade. Kindness lasts. Well, longer."] = "{gift} e {buff} passano. La gentilezza resta. Un po' di più."
L["You shared {gift}; I share {buff}. Ale's next."] = "Tu {gift}, io {buff}. Poi una birra."
L["{gift} caught me empty-handed. Not any more: {buff}."] = "{gift} mi ha colto a mani vuote. Non più: ecco {buff}."
L["{gift}, best thing all day. {buff}, my bid for second."] = "{gift}: il top di oggi. {buff}: miro all'argento."
L["{gift} deserves a statue. I'm no sculptor, so: {buff}."] = "{gift} merita una statua. Non so scolpire, quindi: {buff}."
L["{gift} for {buff}? Keep this up and we'll draw a queue."] = "{gift} per {buff}? Di questo passo si formerà la fila."
L["{gift} was kind. {buff} is kind back, and competitive."] = "{gift}, che gentilezza. {buff} ricambia, e vuole vincere."
L["{gift} came like good news. {buff}, by return post."] = "{gift}, una bella notizia. {buff}, a stretto giro di posta."
L["{gift}, meet {buff}. Do get along, you two."] = "{gift}, ti presento {buff}. Fate i bravi, voi due."
L["Trade you {buff} for {gift}? Ah, you've already paid."] = "Scambio {buff} con {gift}? Ah, hai già pagato."
L["{gift} and {buff}. The inn will say we rehearsed."] = "{gift} e {buff}. In locanda diranno che era tutto combinato."
L["{gift}! I just had three clever thoughts, {name}. This was one."] = "{gift}! Ho appena avuto tre idee geniali, {name}. Questa era una."
L["With {gift}, {name}, I finally understand my own notes. Thanks."] = "Con {gift}, {name}, finalmente capisco i miei appunti. Grazie."
L["Cleverer already, {name}. Clever enough to know I owe you one. Here."] = "Già più intelligente, {name}: so che te ne devo una. Ecco."
L["Your {gift} found me the word for this, {name}: 'thanks'."] = "{gift} mi ha fatto trovare la parola giusta, {name}: 'grazie'."
L["{gift}! I understood a goblin contract, {name}. I'm appalled."] = "{gift}! Ho capito un contratto goblin, {name}. Che orrore."
L["Thank you, {name}. My thoughts are lining up politely."] = "Grazie, {name}. I miei pensieri si mettono in fila con garbo."
L["I'll use your {gift} for more than arguing, {name}. Probably."] = "Userò {gift} non solo per avere l'ultima parola, {name}. Forse."
L["Thank you, {name}. My next spell gets three extra syllables, just to show off."] = "Grazie, {name}. Il prossimo incantesimo avrà tre sillabe in più, per fare scena."
L["{gift}, {name}? I'll stand at the front for once. Briefly."] = "{gift}, {name}? Per una volta starò in prima fila. Per poco."
L["Knees, elbows and pride, {name}: all fortified. Thank you."] = "Ginocchia, gomiti e orgoglio, {name}: tutti rinforzati. Grazie."
L["Hit me now, {name}. Actually, don't. But thank you; I'd survive it."] = "Colpiscimi pure, {name}. Anzi, no. Ma grazie: sopravviverei."
L["Nigh unbreakable now, {name}. Let's never test the 'nigh'. Thank you."] = "Quasi indistruttibile, {name}. Il 'quasi' non lo verifichiamo. Grazie."
L["{gift}! My healer owes you a letter, {name}. I owe you this."] = "{gift}! Il mio guaritore ti deve un bigliettino, {name}. Io, questo."
L["Every bruise I don't get today, {name}, I owe to your {gift}."] = "Ogni livido che oggi non mi farò, {name}, lo devo a {gift}."
L["I could lose an argument with an ogre now and live, {name}. Thank you."] = "Ora posso litigare con un ogre, perdere e sopravvivere, {name}. Grazie."
L["Thank you, {name}. I feel like a castle wall. A grateful one."] = "Grazie, {name}. Mi sento un bastione. Riconoscente, per giunta."
L["Thank you, {name}. The next boar to charge me is in for a long afternoon."] = "Grazie, {name}. Il prossimo cinghiale che mi carica avrà un pomeriggio lungo."
L["{gift}! I feel ten years younger, {name}. Thank you."] = "{gift}! Mi sento dieci anni più giovane, {name}. Grazie."
L["I feel twice as calm and half as grumpy, {name}. Thank you."] = "Il doppio della calma e metà del malumore, {name}. Grazie."
L["Your {gift} nearly made me sing, {name}. Take this. It's kinder."] = "{gift} mi ha quasi fatto cantare, {name}. Ti risparmio: tieni questo."
L["{gift}, {name}? I've forgiven three people already. Thank you."] = "{gift}, {name}? Ho già perdonato tre persone. Grazie."
L["I was on fumes, {name}. Your {gift} was a hot meal and a hearth."] = "Ero in riserva, {name}. {gift} vale un pasto caldo e un focolare."
L["I've stopped counting mana between fights, {name}. Thank you."] = "Ho smesso di contare il mana tra gli scontri, {name}. Grazie."
L["My spirit's topped up, {name}, and the rest of me is grateful too."] = "Spirito al pieno, {name}, e anche il resto di me ringrazia."
L["Shadow-proof, thanks to you, {name}. The whispers are furious."] = "A prova d'ombra grazie a te, {name}. I sussurri sono furiosi."
L["Nothing dark gets in now, {name}. Here's something bright going the other way."] = "Ora il buio non entra, {name}. In cambio, esce un po' di luce."
L["{gift}! Shadowfang Keep can keep its shadows, {name}. Thank you."] = "{gift}! Il Forte di Zannascura si tenga le ombre, {name}: il forte sono io."
L["The next shadow bolt's in for a letdown, {name}. Thank you."] = "Il prossimo Dardo d'Ombra resterà deluso, {name}. Grazie."
L["On your {gift} I'll brave Duskwood tonight, {name}. Or tomorrow."] = "Con {gift} affronterò Boscotetro stanotte, {name}. O domani."
L["{gift}! A squirrel just nodded at me, {name}. Here's yours."] = "{gift}! Uno scoiattolo mi ha appena salutato, {name}. Ricambio."
L["Tougher hide, sharper senses, {name}. I may have to fight the urge to forage."] = "Pelle più dura, sensi più acuti, {name}. Ora ho voglia di cercare ghiande."
L["I feel all wild and leafy, {name}. Thank you. Sorry if I shed bark."] = "Mi sento un po' bosco, {name}. Grazie. Scusa se perdo corteccia."
L["Thicker skin from your {gift}, {name}. Arrows and insults both."] = "{gift} mi ha dato la pelle dura, {name}. Contro frecce e insulti."
L["{gift}! A bird tried to nest on me, {name}. Thanks, I think."] = "{gift}! Un uccello mi ha scelto per il nido, {name}. Grazie, credo."
L["Thanks for the {gift}, {name}. The woods feel like home now."] = "Grazie per {gift}, {name}. Ora il bosco mi sembra casa."
L["Thank you, {name}. I've an urge to stand in the rain and grow. I'll resist."] = "Grazie, {name}. Ho voglia di stare sotto la pioggia a crescere. Resisterò."
L["Every bramble in the Barrens will think twice now, {name}. Thank you."] = "Ogni rovo delle Savane ora ci penserà due volte, {name}. Grazie."
L["Thank you, {name}. Rain, cold and wolves: let them all try."] = "Grazie, {name}. Pioggia, freddo e lupi: ci provino pure."
L["{gift}, {name}! Nobody's hugging me today. Have this instead."] = "{gift}, {name}! Oggi niente abbracci per me. Tieni questo invece."
L["Prickly now, thanks to you, {name}. More than usual, I mean."] = "Ora sono pungente grazie a te, {name}. Più del solito, intendo."
L["Your {gift}, {name}! Let the next kobold try for my candle."] = "{gift}, {name}! Ora un coboldo provi a toccarmi la candela."
L["{gift}! I'm a thicket with opinions now, {name}. Thank you."] = "{gift}! Ora sono un roveto, {name}. Non ardente, ma polemico. Grazie."
L["Thank you, {name}. The next thing that bites me will need a moment to reflect."] = "Grazie, {name}. Chi mi morderà avrà modo di riflettere."
L["{gift} from you, {name}? I'll try not to found a dynasty."] = "{gift} da te, {name}? Cercherò di non fondare una dinastia."
L["A little better at everything, {name}. Is this how kings feel? No wonder."] = "Un po' meglio in tutto, {name}. È così che si sentono i re? Ecco perché."
L["Your {gift}! My first decree, {name}: thank you."] = "{gift}! Primo decreto reale, {name}: grazie."
L["{gift} on a commoner, {name}? I'll try to look regal."] = "{gift} alla plebe, {name}? Cercherò di avere un'aria regale."
L["With your {gift} I could rule a small kingdom, {name}. Westfall."] = "Con {gift} potrei governare un piccolo regno, {name}. Marcaovest."
L["Thank you, {name}. Every bit of me is grateful, and they rarely agree."] = "Grazie, {name}. Ogni parte di me ti è grata, e di rado vanno d'accordo."
L["Stronger arms already, {name}. I'll try not to hug anyone. Thank you."] = "Braccia già più forti, {name}. Eviterò di abbracciare qualcuno. Grazie."
L["With {gift} I could lift a kodo, {name}. I won't, but thank you."] = "Con {gift} potrei sollevare un kodo, {name}. Non lo farò, ma grazie."
L["Your {gift} has my arms very confident, {name}. Thank you."] = "{gift} ha fatto montare la testa alle mie braccia, {name}. Grazie."
L["{gift}! Opened a jar I've fought since Stranglethorn, {name}."] = "{gift}! Ho aperto un barattolo che mi resisteva da Rovotorto, {name}."
L["Thank you, {name}. My next swing is dedicated to you. So is the dent."] = "Grazie, {name}. Ti dedico il prossimo colpo. E anche l'ammaccatura."
L["{gift} from you, {name}, and my first wise act is this."] = "{gift} da te, {name}, e il mio primo gesto saggio è questo."
L["Wiser already, {name}. Wise enough to know a kindness when I see one."] = "Ho già più giudizio, {name}. Abbastanza da riconoscere una gentilezza."
L["My mana thanks you for {gift}, {name}. It's the shy one of us."] = "Il mio mana ti ringrazia per {gift}, {name}. È il più timido di noi."
L["Your {gift} refills me faster than I spend, {name}. Nearly."] = "{gift} mi ricarica più in fretta di quanto spendo, {name}. Quasi."
L["Your {gift}, {name}: mana back, and an urge to give advice."] = "{gift}, {name}: torna il mana, e la voglia di dare consigli."
L["{gift}! The monsters forgot me at once, {name}. I won't."] = "{gift}! I mostri mi hanno scordato subito, {name}. Io no."
L["Nothing wants to fight me now, {name}. It's lovely. Thank you."] = "Ora niente vuole combattermi, {name}. Che meraviglia. Grazie."
L["{gift}! Nothing's glared at me in minutes, {name}. Thank you."] = "{gift}! Nessuno mi guarda storto da minuti, {name}. Grazie."
L["{gift}! A mouse at a dragon's feast, {name}: unseen, well fed."] = "{gift}! Un topo al banchetto del drago, {name}: invisibile e sazio."
L["Thanks to {gift} I'm just a rumour in a fight, {name}."] = "Grazie a {gift}, in battaglia sono solo una diceria, {name}."
L["The Light finds me easier now, {name}. I'll try to deserve it."] = "Ora la Luce mi trova meglio, {name}. Cercherò di meritarlo."
L["Easier to heal now, {name}. Whoever patches me up thanks you too."] = "Ora curarmi è più facile, {name}. Ti ringrazia anche chi mi rattoppa."
L["With your {gift}, {name}, mending feels like coming home."] = "Con {gift}, {name}, guarire è come tornare a casa."
L["{gift}! The Light and I are on first-name terms now, {name}."] = "{gift}! Ora con la Luce ci diamo del tu, {name}."
L["With {gift} the Light hears me first, {name}. No need to shout."] = "Con {gift} la Luce mi sente subito, {name}. Non serve urlare."
L["Blows land softer on me now, {name}. My bruises thank you, and so do I."] = "I colpi ora fanno meno male, {name}. Grazie dai miei lividi, e da me."
L["Every hit gentler, thanks to you, {name}. I'll make sure they notice."] = "Colpi più leggeri grazie a te, {name}. Farò in modo che se ne accorgano."
L["Your {gift} softens every blow, {name}. I'm upholstered."] = "{gift} attutisce ogni colpo, {name}. Ora ho l'imbottitura."
L["{gift}! Now the Light takes every hit personally, {name}."] = "{gift}! Ora la Luce prende ogni colpo sul personale, {name}."
L["With your {gift} I'm half fortress, half chapel, {name}."] = "Con {gift} sono metà fortezza e metà cappella, {name}."
L["You shouted at me, {name}, and I've never felt so encouraged. Here."] = "Mi hai urlato addosso, {name}, e non ho mai avuto tanto coraggio. Tieni."
L["My ears are ringing, {name}, and my arms feel twice as strong. Thank you!"] = "Mi fischiano le orecchie, {name}, e ho le braccia forti il doppio. Grazie!"
L["{gift}, {name}! I felt that in my teeth. In a good way."] = "{gift}, {name}! L'ho sentito fin nei denti. In senso buono."
L["I'll answer your {gift} quietly, {name}. Somebody should."] = "Rispondo a {gift} sottovoce, {name}. Qualcuno deve pur farlo."
L["Your {gift} nearly had me charging a wall, {name}. Here, calmly."] = "Con {gift} stavo per caricare un muro, {name}. Ecco, con calma."
L["All Azeroth heard your {gift}, {name}. Thank you for my share."] = "Tutta Azeroth ha sentito {gift}, {name}. Grazie per la mia parte."
L["That shout put iron in my spine, {name}. Thank you."] = "Quel grido mi ha dato una spina dorsale d'acciaio, {name}. Grazie."
L["I didn't catch the words, {name}, but my arms did. Thank you!"] = "Non ho capito le parole, {name}, ma le mie braccia sì. Grazie!"
L["Thank you, {name}. I'll hit the next thing twice as hard and blame you."] = "Grazie, {name}. Picchierò il doppio, e la colpa sarà tua."
L["I can breathe underwater, {name}! I may never need to, but thank you."] = "Respiro sott'acqua, {name}! Forse non mi servirà mai, ma grazie."
L["Lungs like a murloc, thanks to you, {name}. I'll try not to gurgle."] = "Polmoni da murloc, grazie a te, {name}. Cercherò di non gorgogliare."
L["With {gift} I'll raid every sunken wreck, {name}. Half's yours."] = "Con {gift} saccheggerò ogni relitto, {name}. Metà bottino è tuo."
L["I won't ask where {gift} gets its air, {name}. Just: thanks."] = "Non chiederò da dove {gift} prende l'aria, {name}. Solo: grazie."
L["With {gift} I'll cross Lordamere Lake, {name}. Underneath."] = "Con {gift} attraverserò il Lago Lordamere, {name}. Da sotto."
L["We have to stop meeting like this, {name}. Actually, no, we don't."] = "Dobbiamo smetterla di vederci così, {name}. Anzi, no."
L["Again, {name}? Splendid. I've been practising since last time."] = "Ancora tu, {name}? Splendido. Ho fatto pratica dall'ultima volta."
L["You again, {name}? People will start saying we're friends."] = "Di nuovo tu, {name}? La gente inizierà a dire che siamo amici."
L["Same face, same spell, {name}. I do love a tradition."] = "Stessa faccia, stessa magia, {name}. Adoro le tradizioni."
L["Another round, {name}? I'm keeping score, and we're both winning."] = "Un altro giro, {name}? Tengo il punteggio, e stiamo vincendo entrambi."
L["Ah, {name}! My favourite repeat customer."] = "Ah, {name}! La mia clientela più affezionata."
L["Our paths keep crossing, {name}. I think the road is dropping hints."] = "Continuiamo a incrociarci, {name}. Mi sa che la strada ci fa l'occhiolino."
L["Once more, {name}. Do stop me if you've heard this one."] = "Ancora una volta, {name}. Fermami se l'hai già sentita."
L["I kept some aside, {name}, in case you came back. Good instinct, mine."] = "Te ne avevo tenuto un po' da parte, {name}. Che fiuto, il mio."
L["Back already, {name}? The day's improving."] = "Già di ritorno, {name}? La giornata migliora."
L["Again, {name}? At this rate I'll have to learn your middle name."] = "Di nuovo, {name}? Di questo passo mi toccherà imparare il tuo cognome."
L["Once is kindness, twice is a habit, {name}. I've never broken a habit yet."] = "Una volta è gentilezza, due è un vizio, {name}. E io i vizi non li perdo."
L["An encore, {name}, for my most faithful audience."] = "Un bis, {name}, per il mio pubblico più fedele."
L["One more of these, {name}, and we'll have to draw up a guild charter."] = "Ancora uno così, {name}, e dovremo firmare uno statuto di gilda."
L["I'll remember your face now, {name}, and I'm terrible with faces."] = "Ora mi ricorderò la tua faccia, {name}, e io con le facce sono un disastro."
L["Us again, {name}. The world must be running out of other people."] = "Di nuovo noi, {name}. Al mondo staranno finendo le altre persone."
L["Last time went so well, {name}, I've changed nothing."] = "L'ultima volta è andata così bene, {name}, che non ho cambiato niente."
L["Good to see someone I know, {name}. They're rarer than you'd think."] = "Che bello vedere qualcuno che conosco, {name}. Sono più rari di quanto pensi."
L["Oh, it's you, {name}. Good. I hate giving these to strangers."] = "Oh, sei tu, {name}. Bene. Odio fare regali agli sconosciuti."
L["{name}, at this point we should just share a reagent pouch."] = "{name}, ormai ci serve una borsa dei reagenti in comune."
L["Same time tomorrow, {name}? I'll bring {buff}. You bring you."] = "Stessa ora domani, {name}? Io porto {buff}. Tu, porta solo te."
L["I've lost count, {name}, and I've decided that's a compliment."] = "Ho perso il conto, {name}, e ho deciso che è un complimento."
L["Keep this up, {name}, and the bards will write a very dull song about us."] = "Continua così, {name}, e i bardi ci dedicheranno una canzone noiosissima."
L["I could do this one in my sleep by now, {name}. I may have."] = "Ormai potrei farlo nel sonno, {name}. Forse l'ho già fatto."
L["The usual, {name}? Of course the usual."] = "Il solito, {name}? Ma certo, il solito."
L["We ought to have a secret handshake by now, {name}. Next time, perhaps."] = "Ci manca solo una stretta di mano segreta, {name}. Alla prossima, magari."
L["By now, {name}, I think we've built a small economy between us."] = "Ormai, {name}, tra noi due c'è una piccola economia."
L["Old friends by now, {name}. Well, old acquaintances with excellent timing."] = "Vecchi amici, ormai, {name}. Be', vecchi conoscenti dal tempismo perfetto."
L["Let the record show: {name} and I, undefeated at being prepared."] = "Che resti agli atti: {name} e io, imbattuti nell'essere pronti."
L["My spellbook opens to your page on its own now, {name}."] = "Il mio grimorio si apre da solo alla tua pagina, {name}."
L["If you stopped turning up, {name}, I'd report you missing to the guards."] = "Se smettessi di farti vedere, {name}, denuncerei la tua scomparsa alle guardie."
L["We keep this up, {name}, and one of us owes the other a drink."] = "Se continuiamo così, {name}, uno dei due dovrà offrire da bere all'altro."
L["We're a local landmark now, {name}. Travellers give directions by us."] = "Siamo un punto di riferimento, {name}. I viandanti ci usano per orientarsi."
L["Regular as the tides, {name}, and twice as welcome."] = "Come le maree, {name}, torni sempre. E fa doppio piacere."
L["I'd trust you with my last potion, {name}. That's saying something."] = "Ti affiderei la mia ultima pozione, {name}. E ho detto tutto."
L["Next time, {name}, we share a fire and you tell me where you're bound."] = "La prossima volta, {name}, dividiamo un fuoco e mi racconti dove vai."
L["I'd miss this if it stopped, {name}. So let's not stop."] = "Mi mancherebbe, se finisse, {name}. Quindi non finiamo."
L["There's nobody I'd rather keep running into, {name}."] = "Non c'è nessuno che preferirei continuare a incontrare, {name}."
L["You always turn up at the right moment, {name}."] = "Arrivi sempre al momento giusto, {name}."
L["Safe walls, warm beds, and now {buff}. You're spoiled, {name}."] = "Mura sicure, letti caldi e ora {buff}. Che lusso, {name}."
L["The guards have it covered, {name}, but I like to be thorough."] = "Ci pensano le guardie, {name}, ma io non lascio nulla al caso."
L["Careful, {name}. Look this capable in town and folk will ask you favours."] = "Occhio, {name}. Se in città sembri così capace, ti chiederanno favori."
L["Not a monster for miles, {name}. Still, one never knows about the cooking."] = "Non c'è un mostro per chilometri, {name}. Ma con la cucina non si sa mai."
L["For the crowds, {name}. In town, they're the real danger."] = "Per la folla, {name}. In città, è lei il vero pericolo."
L["Rest easy, {name}. I'll count that my good deed and go find a pint."] = "Rilassati, {name}. Buona azione fatta: vado a farmi una birra."
L["Even in town, {name}, a dragon has been known to drop in. Better safe."] = "Anche in città, {name}, può piombare un drago. Meglio essere prudenti."
L["Best do it in here, {name}. Out there, nobody stands still long enough."] = "Meglio farlo qui, {name}. Là fuori nessuno sta fermo abbastanza."
L["Mind the pickpockets, {name}. This is the one thing on you they can't lift."] = "Occhio ai borseggiatori, {name}. Questa è l'unica cosa che non possono sfilarti."
L["City rules, {name}: no blades drawn, no spells thrown. This one's allowed."] = "Regole di città, {name}: niente lame, niente incantesimi. Questo è permesso."
L["Nothing to fight here but stray cats, {name}. Take this anyway."] = "Qui non c'è niente da combattere tranne i gatti randagi, {name}. Prendi lo stesso."
L["For the walk to the bank, {name}. It's always further than it looks."] = "Per la strada fino alla banca, {name}. È sempre più lunga di quanto sembri."
L["Enjoy a warm hearth while you can, {name}. The road's never far."] = "Goditi un focolare caldo finché puoi, {name}. La strada non è mai lontana."
L["The watch has the walls, {name}. I'll see to you."] = "Alle mura ci pensa la ronda, {name}. A te ci penso io."
L["For the stairs, {name}. Whoever built this place never met a short way up."] = "Per le scale, {name}. Chi ha costruito questo posto non conosceva le scorciatoie."
L["Everything else in town has a price, {name}. This slipped past the merchants."] = "In città tutto il resto ha un prezzo, {name}. Questo è sfuggito ai mercanti."
L["Buy nothing from anyone who calls you 'friend', {name}. Except me."] = "Non comprare niente da chi ti chiama 'amico', {name}. Tranne me."
L["Out here everything wants to eat you, {name}. Now it'll need a bigger fork."] = "Qui fuori tutto vuole mangiarti, {name}. Ora servirà una forchetta più grande."
L["No guards for miles, {name}, and the boars know it. Take this."] = "Nessuna guardia in giro, {name}, e i cinghiali lo sanno. Prendi."
L["Nobody out here but us and the wildlife, {name}. Let's be the tougher half."] = "Qui ci siamo solo noi e le bestie, {name}. Siamo noi la metà più tosta."
L["If a bear asks, {name}, you were like this when I found you."] = "Se un orso chiede, {name}, eri già così quando ti ho trovato."
L["The wolves have been eyeing you, {name}. This should give them pause."] = "I lupi ti tengono d'occhio, {name}. Questo dovrebbe farli riflettere."
L["Wild country, {name}. Best not to meet it armed with good intentions alone."] = "Terre selvagge, {name}. Meglio non affrontarle con le sole buone intenzioni."
L["Map, canteen, {buff}. Now you can get lost properly, {name}."] = "Mappa, borraccia, {buff}. Ora puoi perderti come si deve, {name}."
L["Camp's a long way off, {name}. Consider this a roof you can carry."] = "L'accampamento è lontano, {name}. Consideralo un tetto portatile."
L["Out past the last farm, {name}, you're on your own. Nearly."] = "Oltre l'ultima fattoria, {name}, sei per conto tuo. Quasi."
L["Nearest inn's a day's walk, {name}. The nearest thing with teeth is closer."] = "La locanda è a un giorno di cammino, {name}. Le zanne sono molto più vicine."
L["Two hills and a swamp to the next town, {name}. The swamp has opinions."] = "Due colline e una palude fino al paese, {name}. La palude dice la sua."
L["Camp carefully, {name}. Every nice clearing has an owner, and it has claws."] = "Accampati con giudizio, {name}. Ogni bella radura ha un padrone, con gli artigli."
L["Fresh air, open sky, {name}. Enjoy it while nothing's chasing you."] = "Aria fresca, cielo aperto, {name}. Goditela finché niente ti insegue."
L["Something's following you, {name}. Probably a boar. This is in case it isn't."] = "Qualcosa ti segue, {name}. Forse un cinghiale. Questo è per il 'forse'."
L["Stay on the road, {name}. The road has guards. Some of the time."] = "Resta sulla strada, {name}. La strada ha le guardie. Ogni tanto."
L["Rain's coming, {name}, and so are the wolves. One of those I can help with."] = "Arrivano pioggia e lupi, {name}. Per uno dei due ho il rimedio."
L["Somewhere in here a villain is rehearsing a speech, {name}. Let's interrupt."] = "Qui dentro un cattivo sta provando il suo discorso, {name}. Interrompiamolo."
L["Whatever waits at the end of this place, {name}, let's make it regret it."] = "Qualunque cosa ci aspetti in fondo, {name}, facciamola pentire."
L["They say nobody leaves here alive, {name}. Let's be rude and prove them wrong."] = "Dicono che da qui nessuno esca vivo, {name}. Facciamo i maleducati: smentiamoli."
L["Our host had years to prepare, {name}. We have {buff}."] = "Il padrone di casa si prepara da anni, {name}. Noi abbiamo {buff}."
L["Nobody builds a dungeon with a back door, {name}. Take this instead."] = "Nessuna segreta ha l'uscita sul retro, {name}. Prendi questo, piuttosto."
L["Dark halls, old traps, worse tempers. At least you're ready, {name}."] = "Sale buie, trappole vecchie, caratteracci. Almeno tu sei a posto, {name}."
L["Better I hand you this now, {name}, than a eulogy later."] = "Meglio darti questo adesso, {name}, che un elogio funebre dopo."
L["There's treasure in here, {name}, and something very large sat on it."] = "Qui c'è un tesoro, {name}, e qualcosa di molto grosso ci sta seduto sopra."
L["If a door slams shut behind us, {name}, that's tradition. Take this first."] = "Se la porta si sbarra dietro di noi, {name}, è tradizione. Prima, prendi."
L["Mind the patrols, {name}. They walk the same loop forever and resent it."] = "Occhio alle pattuglie, {name}. Stesso giro da secoli: sono di pessimo umore."
L["Whoever built this place, {name}, spent it all on skulls and nothing on lamps."] = "Qui l'architetto, {name}, ha speso tutto in teschi e niente in lampade."
L["The last lot through here were never seen again, {name}. They lacked this."] = "Gli ultimi passati di qui sono spariti, {name}. Non avevano questo."
L["Check the ceiling, {name}. In places like this, something always drops in."] = "Occhio al soffitto, {name}. Qui dentro c'è sempre chi piomba in visita."
L["If we meet a talking skull, {name}, let me do the talking."] = "Se incontriamo un teschio che parla, {name}, lascia parlare me."
L["If the walls start whispering, {name}, don't answer. It only encourages them."] = "Qui i muri hanno orecchie e pure la bocca, {name}. Non rispondere: li vizi."
L["Touch nothing that glows, pull nothing that clicks, {name}. Wear this."] = "Non toccare niente che brilla o fa clic, {name}. E indossa questo."
L["Stick together in here, {name}. Echoes carry, and so do grudges."] = "Restiamo uniti, {name}. Qui l'eco arriva lontano, e i rancori pure."
L["Flags, towers, graveyards, {name}. Whatever we're fighting over, take this."] = "Bandiere, torri, cimiteri, {name}. Per qualunque cosa si combatta, prendi."
L["Win or lose, {name}, nobody will say you went in unprepared."] = "Comunque vada, {name}, nessuno dirà che mancavi di preparazione."
L["The graveyard's just over there, {name}. Let's both not visit it."] = "Il cimitero è proprio lì, {name}. Evitiamo di visitarlo, tutti e due."
L["Honour's on the line, {name}. So is the flag. Mostly the flag."] = "In gioco c'è l'onore, {name}. E la bandiera. Soprattutto la bandiera."
L["Stay with the group, {name}. Lone heroes make short songs."] = "Resta col gruppo, {name}. Gli eroi solitari finiscono in canzoni brevi."
L["Our banner looks better with you under it, {name}. Stand tall."] = "Il nostro stendardo sta meglio con te sotto, {name}. Testa alta."
L["Keep your head down and your colours up, {name}."] = "Testa bassa e bandiera alta, {name}."
L["Hold the line, {name}. The songs are always about the ones who stood."] = "Tieni duro, {name}. Le ballate sono sempre per chi resta in piedi."
L["Come back in one piece, {name}. That's all I ask."] = "Torna senza un graffio, {name}. Non chiedo altro."
L["Drums are for courage, {name}. This is for everything else."] = "I tamburi danno coraggio, {name}. Questo, tutto il resto."
L["Some fight for glory, {name}. I fight for whoever's beside me."] = "C'è chi combatte per la gloria, {name}. Io combatto per chi ho accanto."
L["Fight for the banner, {name}, but come back for the singing. Mine's dreadful."] = "Combatti per lo stendardo, {name}, ma torna per i canti. Io stono da paura."
L["Early bird, {name}? Here's something better than a worm."] = "Il mattino ha l'oro in bocca, {name}. E io ho questo per te."
L["Good morning, {name}. Consider this your first cup of something strong."] = "Buongiorno, {name}. Consideralo il tuo primo espresso."
L["Early start, {name}. The day hasn't had a chance to go wrong yet."] = "Di buon'ora, {name}. La giornata non ha ancora fatto in tempo a guastarsi."
L["Not even lunch yet, {name}, and you're already better prepared than I am."] = "Non è nemmeno ora di pranzo, {name}, e la tua preparazione batte già la mia."
L["Morning, {name}. Somewhere, the monsters are still yawning."] = "Buongiorno, {name}. Da qualche parte i mostri sbadigliano ancora."
L["A fresh day and a fresh {buff}, {name}. Let's not waste either."] = "Nuovo giorno e {buff} di giornata, {name}. Non sprechiamoli."
L["Up with the sun, {name}? Show-off. Here; the sun doesn't get one."] = "Gara col sole, {name}? Hai vinto. Tieni: al sole niente premio."
L["Rise and shine, {name}. The shining can wait till after breakfast."] = "Sveglia, {name}! A splendere ci pensiamo dopo colazione."
L["Everything's golden and nobody's shouted yet, {name}. Let's enjoy it."] = "Tutto è dorato e nessuno ha ancora urlato, {name}. Godiamocela."
L["Too early for heroics, {name}? Nonsense. Heroics go best before lunch."] = "Troppo presto per l'eroismo, {name}? Macché: rende meglio prima di pranzo."
L["The birds are singing, {name}. They haven't seen what's out there yet."] = "Gli uccellini cantano, {name}. Non hanno ancora visto cosa c'è là fuori."
L["First good deed of the day, {name}. It's all downhill from here."] = "Prima buona azione del giorno, {name}. Da qui in poi è tutta discesa."
L["Still yawning, {name}? This works faster than tea."] = "Sbadigli, {name}? Questo sveglia più di un espresso."
L["Early, {name}. The dawn patrol looks at us like we've lost our minds."] = "Presto, eh, {name}? La ronda dell'alba ci guarda come due matti."
L["Out this late, {name}? The night is hungrier than the day. Take this."] = "In giro così tardi, {name}? La notte ha più fame del giorno. Prendi."
L["Past bedtime, {name}. The sensible folk are asleep, which leaves us."] = "Ora di nanna passata, {name}. La gente saggia dorme: restiamo noi."
L["Can't sleep either, {name}? Then we may as well be useful."] = "Nemmeno tu riesci a dormire, {name}? Allora tanto vale renderci utili."
L["Mind the dark, {name}. Not everything out there is as friendly as I am."] = "Occhio al buio, {name}. Là fuori non tutti sono amichevoli come me."
L["It's late, {name}. This should keep you going till the sun remembers us."] = "È tardi, {name}. Questo ti basterà finché il sole non si ricorda di noi."
L["Only the owls and us awake, {name}, and the owls get no {buff}."] = "Svegli solo noi e i gufi, {name}, e ai gufi niente {buff}."
L["The inns have locked up, {name}. This is the only thing still being served."] = "Locande chiuse, {name}. Qui però si serve ancora: offre la casa."
L["It's the hour for ghost stories, {name}. Take this, in case one is true."] = "È l'ora delle storie di fantasmi, {name}. Prendi, nel caso una sia vera."
L["Candles low, stars high, {name}. A good hour for small kindnesses."] = "Candele basse, stelle alte, {name}. Ora buona per piccole gentilezze."
L["Quiet hour, {name}. Every creak sounds like an ambush. Most of them aren't."] = "Ora quieta, {name}. Ogni scricchiolio sembra un agguato. Quasi mai lo è."
L["This late, {name}, even the guards are talking to themselves."] = "A quest'ora, {name}, anche le guardie parlano da sole."
L["This is the hour things climb out of graves, {name}. Take this; walk briskly."] = "È l'ora in cui si esce dalle tombe, {name}. Prendi, e allunga il passo."
L["Tomorrow you'll wonder why you stayed up, {name}. This is one good reason."] = "Domani ti chiederai perché hai fatto tardi, {name}. Eccoti un buon motivo."
L["Takes one to know one, {name}. Takes one to do it properly, too."] = "Chi si somiglia si piglia, {name}. E si aiuta come si deve."
L["From one of our trade to another, {name}. No need to check my work."] = "Da collega a collega, {name}. Non serve controllare il mio lavoro."
L["Professional courtesy, {name}. We don't charge each other."] = "Cortesia professionale, {name}. Tra colleghi non ci si fa pagare."
L["Two of a kind, {name}. Between us we could write the manual."] = "Della stessa pasta, {name}. Insieme potremmo scrivere il manuale."
L["Don't look so surprised, {name}. Same trainer, I expect."] = "Non stupirti, {name}. Avremo avuto lo stesso istruttore."
L["I'd critique your technique, {name}, but mine looks exactly the same."] = "Criticherei la tua tecnica, {name}, ma la mia è identica."
L["Don't tell the others, {name}, but ours really is the finest calling."] = "Non dirlo agli altri, {name}, ma la nostra è davvero la vocazione migliore."
L["Look at us, {name}. Two experts, making it look easy. It isn't, is it?"] = "Guardaci, {name}. Due esperti che la fanno sembrare facile. Non lo è, vero?"
L["Between colleagues, {name}: I also have no idea how half of it works."] = "Tra colleghi, {name}: anch'io metà di questa roba non l'ho mai capita."
L["We walked the same road to get here, {name}. Good to meet another on it."] = "Abbiamo fatto la stessa strada per arrivare qui, {name}. Bello trovarci qualcun altro."
L["If anyone asks, {name}, we trained each other."] = "Se chiedono, {name}, ci siamo addestrati a vicenda."
L["Calling to calling, {name}. We should compare notes some time."] = "Stessa vocazione, {name}: prima o poi confrontiamo gli appunti."
L["Colleague, {name}. We look after our own."] = "Collega, {name}. Noi pensiamo ai nostri."
L["Good to see the old craft in steady hands, {name}."] = "Che bello vedere l'antica arte in mani salde, {name}."
L["I'd shout some encouragement, {name}, but you do that far better."] = "Ti urlerei un incoraggiamento, {name}, ma tu urli molto meglio di me."
L["Charge in as usual, {name}. I'll simply feel better about it now."] = "Carica come al solito, {name}. Almeno ora mi preoccupo meno."
L["For the one who goes in first, {name}. Somebody has to, and it's never me."] = "Per chi entra per primo, {name}. Qualcuno deve farlo, e non sono mai io."
L["You take the hits so the rest of us don't, {name}. It's the least I can do."] = "Prendi i colpi al posto nostro, {name}. È il minimo che possa fare."
L["Go on, {name}, charge. I'll be right behind you."] = "Vai, {name}, carica. Sono subito dietro di te."
L["For the one who fixes every problem by hitting it, {name}. It usually works."] = "Per chi risolve ogni problema a mazzate, {name}. Di solito funziona."
L["I'd shake your hand, {name}, but both of yours are holding something sharp."] = "Ti stringerei la mano, {name}, ma in tutte e due tieni qualcosa di affilato."
L["A little help for a lot of armour, {name}. I hope it fits under there."] = "Un piccolo aiuto per tanta armatura, {name}. Spero ci stia, lì sotto."
L["You'll charge something enormous soon, {name}. I'm just helping it lose."] = "Tra poco caricherai qualcosa di enorme, {name}. Io lo aiuto solo a perdere."
L["Save your Light for later, {name}. This one's from me."] = "Tieni la tua Luce per dopo, {name}. Questo è da parte mia."
L["You bless everyone else all day, {name}. Here's one going the other way."] = "Tutto il giorno benedici gli altri, {name}. Stavolta tocca a te."
L["The Light already favours you, {name}. Here's a little more of it."] = "La Luce ti favorisce già, {name}. Eccone un altro po'."
L["Even the Light's own champion needs a hand now and then, {name}."] = "Anche ai campioni della Luce serve una mano, ogni tanto, {name}."
L["I'd ask for a blessing back, {name}, but then we'd be here all day."] = "Ti chiederei una benedizione in cambio, {name}, ma non finiremmo più."
L["For the one who carries a hammer and a conscience, {name}. Heavy load."] = "Per chi si porta dietro martello e coscienza, {name}. Che fardello."
L["Don't thank the Light for this one, {name}. This was me."] = "Non ringraziare la Luce per questo, {name}. È merito mio."
L["No need to kneel, {name}. I know it's a habit."] = "Non inginocchiarti, {name}. Lo so, è l'abitudine."
L["One for you, {name}, and a pat on the head for your companion."] = "Questo per te, {name}, e una carezza al tuo compagno."
L["You watch everyone's back from range, {name}. I've got yours."] = "Copri le spalle a tutti dalla distanza, {name}. Io copro le tue."
L["Hunter's Mark for them, {buff} for you, {name}. Much nicer."] = "Marchio del Cacciatore per loro, {buff} per te, {name}. Molto meglio."
L["Aim true, {name}. And if it charges you anyway, run towards the rest of us."] = "Mira bene, {name}. E se ti carica comunque, corri verso di noi."
L["Keen eye, steady hand, {name}. Here's something for the long hunt."] = "Occhio acuto, mano ferma, {name}. Ecco qualcosa per la lunga caccia."
L["Nothing for the pet this time, {name}. It's already had three of my sandwiches."] = "Stavolta niente al famiglio, {name}: si è già mangiato tre miei panini."
L["I'd have brought arrows, {name}, but I never know which kind you like."] = "Ti avrei portato delle frecce, {name}, ma non so mai quali ti piacciono."
L["You can track anything, {name}, but you never saw this one coming."] = "Segui le tracce di tutto, {name}, ma questo non l'hai visto arrivare."
L["Quick hands, quiet feet, {name}. Here's luck to go with them."] = "Mani svelte, passi silenziosi, {name}. Ed ecco la fortuna che li accompagni."
L["Quick, {name}, before you vanish again."] = "Presto, {name}, prima che tu sparisca di nuovo."
L["Poison on the blades, {buff} on you. Very thorough, {name}."] = "Veleno sulle lame, {buff} su di te. Che precisione, {name}."
L["I'd slip it in your pocket, {name}, but you'd notice. You always notice."] = "Te lo infilerei in tasca, {name}, ma te ne accorgeresti. Come sempre."
L["For the one who opens every locked box, {name}. This one comes unlocked."] = "Per chi apre ogni scrigno chiuso, {name}. Questo arriva già aperto."
L["Nobody sees you coming, {name}. Now it's even worse news when they do."] = "Nessuno ti vede arrivare, {name}. Ora, quando ti vedono, è pure peggio."
L["Take this, {name}. Very discreet. It even walks quietly."] = "Prendi, {name}. Discretissimo. Cammina in punta di piedi."
L["I'd have wrapped it, {name}, but you'd only pick the knot."] = "Te l'avrei incartato, {name}, ma avresti scassinato il fiocco."
L["Keep this one, {name}. You don't even have to steal it."] = "Questo tienilo, {name}. Non devi nemmeno rubarlo."
L["For once, {name}, somebody's looking after the priest."] = "Per una volta, {name}, qualcuno cura chi cura."
L["Save your prayers for the rest of us, {name}. This one's already answered."] = "Tieni le preghiere per noi, {name}. Questa è già esaudita."
L["Light or Shadow, {name}, I don't ask which. This suits both."] = "Luce o Ombra, {name}, non chiedo quale. Questo va bene per entrambe."
L["Sit down after this fight, {name}. That's an order, from a grateful patient."] = "Dopo questo scontro, siediti, {name}. Ordine dei tuoi pazienti riconoscenti."
L["You keep us all standing, {name}. Here's a little of it coming back."] = "Ci tieni tutti in piedi, {name}. Eccotene un po' indietro."
L["You've knelt beside all of us, {name}. Stand tall a minute."] = "Sempre in ginocchio per noi, {name}. Ora un minuto a testa alta."
L["Something that needed no prayer, {name}. You've said plenty of those today."] = "Qualcosa che non ha richiesto preghiere, {name}. Oggi ne hai dette abbastanza."
L["No voice in your head comes with this one, {name}. Refreshing, isn't it?"] = "Niente voce nella testa, con questo, {name}. Che sollievo, eh?"
L["The Ebon Blade asks no favours, {name}. I'm giving one anyway."] = "La Lama d'Ebano non chiede favori, {name}. Te ne faccio uno comunque."
L["A little warmth, {name}. I know you don't feel the cold. It's the thought."] = "Un po' di calore, {name}. So che non senti il freddo. È il pensiero che conta."
L["You came back from the dead, {name}. The least I can do is help you stay back."] = "Hai lasciato la tomba, {name}. Il minimo è aiutarti a non tornarci."
L["Runes, plague and frost, {name}. Take this too; it completes the set."] = "Rune, pestilenza e gelo, {name}. Aggiungi questo: collezione completa."
L["A skeletal horse and a sword that talks back, {name}. Here's something normal."] = "Cavallo scheletrico, spada che risponde a tono, {name}. Ecco qualcosa di normale."
L["No need to drag me over on a chain, {name}. I was coming anyway."] = "Non serve la Presa Mortale, {name}. Venivo comunque."
L["Welcome back to the land of the living, {name}. Well, its general direction."] = "Di nuovo tra i vivi, {name}. Be', più o meno da quelle parti."
L["The elements look after you, {name}, but they don't make house calls."] = "Gli elementi vegliano su di te, {name}, ma non fanno visite a domicilio."
L["Tell the spirits I said hello, {name}. They never write back."] = "Saluta gli spiriti da parte mia, {name}. Non mi rispondono mai."
L["Plant a totem in my honour, {name}. A small one. I'm modest."] = "Pianta un totem in mio onore, {name}. Uno piccolo, per modestia."
L["Earth, fire, water, air and me, {name}. Admittedly the least of the five."] = "Terra, fuoco, acqua, aria e io, {name}. Io valgo meno, lo ammetto."
L["Totems up already, {name}? Then this goes with them."] = "Totem già piantati, {name}? Allora questo va con loro."
L["The wind would have brought you this, {name}, but it's flighty. I'm reliable."] = "Te l'avrebbe portato il vento, {name}, ma è volubile. Io sono affidabile."
L["You speak for the land, {name}. I hope it speaks kindly of me."] = "Tu parli per la terra, {name}. Spero che lei parli bene di me."
L["The spirits said you'd earned this, {name}. I didn't ask; they volunteered."] = "Per gli spiriti te lo meriti, {name}. Non ho chiesto: si sono offerti loro."
L["A gift for a mage, {name}. Hard to find one you can't conjure."] = "Un dono per chi fa magie, {name}. Il difficile è che tu non sappia evocarlo."
L["You solve most problems with sheep, {name}. This covers the rest."] = "Risolvi quasi tutto con le pecore, {name}. Questo copre il resto."
L["You could teleport out of any trouble, {name}. This is for the trouble first."] = "Puoi uscire da ogni guaio con un portale, {name}. Questo è per entrarci."
L["For the clever one, {name}. Please don't thank me by making me a sheep."] = "Per la mente del gruppo, {name}. Non ringraziarmi trasformandomi in pecora."
L["Blink wherever you like, {name}. This comes too."] = "Usa la Traslazione dove vuoi, {name}. Questo ti segue."
L["Stand a little back from the fire you're about to start, {name}. Here."] = "Stai un po' lontano dal fuoco che stai per appiccare, {name}. Tieni."
L["You keep us all fed and watered, {name}. Your turn to be looked after."] = "Ci dai sempre da mangiare e da bere, {name}. Ora tocca a te farti coccolare."
L["Portal fees are steep, {name}. Call this a down payment on my next one."] = "I portali costano cari, {name}. Consideralo un acconto sul prossimo."
L["Entirely demon-free, {name}. I checked."] = "Senza demoni, {name}. Ho controllato."
L["Your imp may be jealous, {name}. Tell it there's plenty to go round."] = "Il tuo imp potrebbe essere geloso, {name}. Digli che ce n'è per tutti."
L["No contract, no fine print, {name}. Just a gift."] = "Niente contratto né clausole, {name}. Solo un regalo."
L["For the one who hands out healthstones, {name}. Nobody ever thanks you."] = "Per chi distribuisce Pietre della Salute, {name}. Nessuno ti ringrazia mai."
L["Here, {name}. Summon the rest of us later and we'll call it even."] = "Tieni, {name}. Poi evochi il resto di noi e siamo pari."
L["Your voidwalker can stop hovering, {name}. I mean well."] = "Il tuo Viandante del Vuoto può rilassarsi, {name}. Vengo in pace."
L["Your felhunter eats magic, {name}. Keep it off this one; it's for you."] = "Il tuo Vilsegugio mangia magia, {name}. Questo non è per lui: è per te."
L["For the one who reads what nobody else dares, {name}."] = "Per chi legge ciò che nessun altro osa, {name}."
L["Carrying a bag of souls all day, {name}? Your shoulders must need this."] = "Una borsa d'anime in spalla tutto il giorno, {name}? Questo ti serve."
L["Roll wherever you like, {name}. This rolls with you."] = "Rotola dove vuoi, {name}. Questo rotola con te."
L["Brew first or fight first, {name}? Either way, take this."] = "Prima la birra o prima la rissa, {name}? In ogni caso, prendi."
L["Inner peace for you, {name}, and outer peace too, as long as this lasts."] = "Pace interiore per te, {name}, e anche esteriore, finché dura."
L["Chi flows better with a little help, {name}. Or so a monk once told me."] = "Il chi scorre meglio con un aiutino, {name}. Così mi disse un monaco."
L["Kick, flip, roll, {name}. I'll just stand here and do this bit."] = "Calci, capriole, rotolate, {name}. Io sto qui e faccio questa parte."
L["Teach me to flip without spilling my drink, {name}, and we're even."] = "Insegnami la capriola senza versare la birra, {name}, e siamo pari."
L["Tea, meditation and this, {name}. The three pillars of a good day."] = "Tè, meditazione e questo, {name}. I tre pilastri di una buona giornata."
L["Tell the bear this is for them too, {name}."] = "Di' all'orso che è anche per lui, {name}."
L["Hold still, {name}. I've never once managed to catch you as a cheetah."] = "Non muoverti, {name}. In forma di ghepardo non ti ho mai preso."
L["Nature looks after you already, {name}. Today she sent me to help."] = "La natura ti protegge già, {name}. Oggi ha mandato me a darle una mano."
L["Whatever shape you're in next, {name}, this goes with you."] = "Qualunque forma prenderai, {name}, questo viene con te."
L["For the forest's friend, {name}. Give my regards to the trees."] = "Per chi parla con la foresta, {name}. Salutami gli alberi."
L["Cenarion work is never done, {name}. Here's a little help."] = "Il lavoro del Circolo Cenariano non finisce mai, {name}. Eccoti un aiutino."
L["I'd give it to the cat, {name}, but the cat would pretend not to care."] = "Lo darei al gatto, {name}, ma il gatto farebbe finta che non gli importi."
L["Say hello to your moonkin form for me, {name}. It always looks so startled."] = "Salutami la tua forma di Lunagufo, {name}. Ha sempre l'aria così stupita."
L["You were not prepared, {name}. Now you are."] = "Non siete preparati, diceva Illidan. Tu ora sì, {name}."
L["Years in a Warden's cell, {name}. You've earned a small kindness."] = "Anni nella cella di una Custode, {name}. Una piccola gentilezza te la meriti."
L["You gave up so much to fight the Legion, {name}. Here's a little back."] = "Hai dato tanto per combattere la Legione, {name}. Eccoti un po' in cambio."
L["For the one who leaps first, {name}. Do land somewhere friendly."] = "Per chi salta prima di tutti, {name}. Atterra in un posto amichevole."
L["Fel and fury, {name}, and now a little kindness. It'll balance out."] = "Fuoco vile e furia, {name}, e ora un po' di gentilezza. Si compenserà."
L["I'd ask if you saw this coming, {name}, but you see everything."] = "Ti chiederei se l'hai visto arrivare, {name}, ma tu vedi tutto."
L["You can see souls, {name}. Mine's the one being generous."] = "Tu vedi le anime, {name}. La mia è quella generosa."
L["Illidan never let anyone help him, {name}. You're wiser than your teacher."] = "Illidan non si faceva mai aiutare, {name}. Tu hai superato il maestro."
L["A demon inside and a Legion outside, {name}. Here's one thing on your side."] = "Un demone dentro e la Legione fuori, {name}. Ecco qualcosa dalla tua parte."
L["For you, {name}. Please don't breathe on it."] = "Per te, {name}. Ti prego, non soffiarci sopra."
L["A little help for a dragon, {name}. I'll be telling my grandchildren."] = "Un aiutino a un drago, {name}. Lo racconterò ai miei nipoti."
L["The Aspects sent you out into the world, {name}. I'm making it friendlier."] = "Gli Aspetti ti hanno mandato nel mondo, {name}. Io lo rendo più accogliente."
L["Take to the skies after this, {name}. I'll wave from down here."] = "Dopo questo, spicca il volo, {name}. Io ti saluto da quaggiù."
L["A dragon on our side, {name}. I've never felt safer being generous."] = "Un drago alleato, {name}. Essere generosi non è mai stato così sicuro."
L["A gift for a dragon, {name}. Normally folk bring gold and hope to leave again."] = "Un dono per un drago, {name}. Di solito si porta oro e si spera di uscirne vivi."
L["For the one who could fly me to the next town, {name}. Not asking. Hinting."] = "Per chi potrebbe darmi un passaggio in volo, {name}. Non chiedo. Butto lì."
L["I've met a few dragons, {name}. You're the first I didn't run from."] = "Di draghi ne ho visti, {name}. Da te è la prima volta che non scappo."
L["For the world's youngest ancient, {name}."] = "Per l'antico più giovane del mondo, {name}."
L["{buff} for a mage, {name}. Like lending a library a book."] = "{buff} tra maghi, {name}. Come prestare un libro a una biblioteca."
L["Mage to mage, {name}: I won't ask you for water if you won't ask me."] = "Da mago a mago, {name}: io non ti chiedo l'acqua se tu non la chiedi a me."
L["Two mages, {name}. Between us we can portal anywhere and still be late."] = "Due maghi, {name}. Portali ovunque, e arriviamo comunque in ritardo."
L["A mage for a mage, {name}. Our old masters would approve."] = "Da mago a mago, {name}. I nostri vecchi maestri approverebbero."
L["A mage enchanting a mage, {name}. We'll both pretend we needed it."] = "Mago che incanta mago, {name}. Fingiamo entrambi che servisse."
L["Neither of us will admit which spells we still read off the page, {name}."] = "Nessuno dei due ammetterà quali incantesimi legge ancora dal libro, {name}."
L["One mage is a scholar, {name}. Two is an argument. Here's my opening point."] = "Un mago è uno studioso, {name}. Due, una discussione. Ecco la mia prima tesi."
L["We both know this spell by heart, {name}. Humour me."] = "Lo sappiamo a memoria tutti e due, {name}. Assecondami."
L["More mana for you, {name}. Try not to spend it all on one fireball."] = "Più mana per te, {name}. Non spenderlo tutto in una Palla di Fuoco."
L["Priest to priest, {name}: who blesses the blessers? Today, me."] = "Da sacerdote a sacerdote, {name}: chi benedice i benedicenti? Oggi io."
L["Between us, {name}, we'll pretend the warriors listen."] = "Tra noi, {name}, faremo finta che i guerrieri ascoltino."
L["A priest looking after a priest, {name}. It feels almost forbidden."] = "Sacerdoti che si curano a vicenda, {name}. Sa quasi di peccato."
L["Two priests, {name}. Twice the praying and half the panic."] = "Due sacerdoti, {name}. Il doppio delle preghiere e metà del panico."
L["If it all goes wrong, {name}, we two are the last ones standing."] = "Se va tutto storto, {name}, noi due saremo gli ultimi in piedi."
L["Rest your prayers a while, {name}. Mine can keep watch."] = "Fai riposare le tue preghiere, {name}. Le mie montano la guardia."
L["I'd preach to you, {name}, but you've heard it. You've probably given it."] = "Ti farei la predica, {name}, ma la conosci. Forse l'hai pure scritta tu."
L["Same vows and same sore knees, {name}. Here's something for yours."] = "Stessi voti, stesse ginocchia doloranti, {name}. Ecco per le tue."
L["If I fall, {name}, you know the words. If you fall, so do I. Let's neither."] = "Se cado, {name}, sai le parole. Se cadi tu, le so io. Meglio non cadere."
L["Two druids, {name}. The Cenarion Circle would call this a quorum."] = "Due druidi, {name}. Per il Circolo Cenariano c'è il numero legale."
L["Druid to druid, {name}: bear or cat, I'd know you by the leaves in your hair."] = "Da druido a druido, {name}: orso o gatto, ti riconosco dalle foglie nei capelli."
L["From one shapeshifter to another, {name}: this one fits every shape."] = "Da mutaforma a mutaforma, {name}: questo va bene in ogni forma."
L["No handshake, {name}. Two druids, and neither of us has the right shape for it."] = "Niente stretta di mano, {name}. Due druidi, e nessuno dei due ha la forma giusta."
L["Between us, {name}, we've a shape for every problem. Mostly bears."] = "In due, {name}, abbiamo una forma per ogni problema. Perlopiù orsi."
L["Fellow druid, {name}? Then you know the trees told me you were coming."] = "Druido anche tu, {name}? Allora sai che gli alberi mi hanno avvisato."
L["If you see me as a cat later, {name}, pretend you don't know me. Dignity."] = "Se poi mi vedi da gatto, {name}, fai finta di non conoscermi. Dignità."
L["Paladin to paladin, {name}: heavy hammer, light heart."] = "Da paladino a paladino, {name}: martello pesante, cuore leggero."
L["A blessing for a paladin, {name}. Now we're both insufferably radiant."] = "Benedizione tra paladini, {name}. Ora siamo insopportabilmente radiosi."
L["Two paladins, {name}. Somewhere, a priest is quietly relieved."] = "Due paladini, {name}. Da qualche parte, un sacerdote respira sollevato."
L["One of us should be humble about this, {name}. Neither of us will be."] = "Uno di noi dovrebbe essere umile, {name}. Nessuno dei due lo sarà."
L["Same oath, different polish, {name}. Yours is shinier; I noticed."] = "Stesso voto, lucido diverso, {name}. Il tuo brilla di più: l'ho notato."
L["Between us, {name}, we could light a cathedral. Or a small, very holy room."] = "Insieme, {name}, illumineremmo una cattedrale. O uno sgabuzzino santissimo."
L["Two suits of plate, {name}. Nobody will hear us sneak up. Nobody ever does."] = "Due armature di piastre, {name}. Arriveremo di soppiatto. Si fa per dire."
L["Your libram and mine agree on this one, {name}. Rare, that."] = "I nostri libri sacri concordano, {name}. Succede di rado."
L["Warlock to warlock, {name}: keep your imp away from mine. They gossip."] = "Tra stregoni, {name}: tieni il tuo imp lontano dal mio. Spettegolano."
L["Fellow warlock, {name}? Then you'll know this one's harmless."] = "Collega stregone, {name}? Allora saprai che questo è innocuo."
L["Two warlocks, {name}. Let's not compare soul shards in public."] = "Due stregoni, {name}. Non confrontiamo i frammenti d'anima in pubblico."
L["Between us, {name}, the demons do all the work. This bit I do myself."] = "Tra noi, {name}, tutto il lavoro lo fanno i demoni. Questo lo faccio io."
L["Another warlock, {name}. Let's be polite; I've seen what you summon."] = "Un altro stregone, {name}. Siamo gentili: ho visto cosa evochi."
L["A spell from one warlock to another, {name}. Check it for curses. I would."] = "Da stregone a stregone, {name}. Cerca maledizioni: io lo farei."
L["Fellow warlock, {name}. The only one who won't ask where this came from."] = "Collega stregone, {name}. L'unico che non chiederà da dove arriva questo."
L["Two warlocks, one kind deed, {name}. The Burning Legion must be livid."] = "Due stregoni, una buona azione, {name}. La Legione Infuocata sarà furibonda."
L["I'd summon you a drink, {name}, but we both know how summoning goes."] = "Ti evocherei da bere, {name}, ma sappiamo come finiscono le evocazioni."
L["Two warriors, {name}. Somewhere, a healer just sighed."] = "Due guerrieri, {name}. Chissà dove, un guaritore sospira."
L["Warrior to warrior, {name}: first into the fight buys the drinks. I'm buying."] = "Da guerriero a guerriero, {name}: chi entra per primo paga da bere. Offro io."
L["Shout for shout, {name}. We'll deafen the whole place together."] = "Urlo per urlo, {name}. Insieme assorderemo tutto il posto."
L["No plan, {name}? Perfect. We'll get along."] = "Nessun piano, {name}? Perfetto. Andremo d'accordo."
L["Warriors, {name}: the only folk who think shouting is a spell. We're right."] = "Noi guerrieri, {name}: urlare per noi è un incantesimo. E abbiamo ragione."
L["One warrior to another, {name}: keep your shield up and your temper hot."] = "Da guerriero a guerriero, {name}: scudo alto e sangue caldo."
L["You know this one, {name}. You've probably shouted it at me already."] = "Questo lo conosci, {name}. Probabilmente me l'hai già urlato addosso."
L["Our trainer would be proud, {name}. He'd shout it, but he'd be proud."] = "Il nostro istruttore sarebbe fiero, {name}. Lo urlerebbe, ma sarebbe fiero."
L["Fellow warrior? Then you know the blacksmith's first name too, {name}."] = "Guerriero anche tu? Allora anche tu chiami il fabbro per nome, {name}."
L["No mana to fill, {name}. It'll just stand about being clever, like me."] = "Niente mana da riempire, {name}. Starà lì a fare il sapientone, come me."
L["My spell on a warrior, {name}. Call it a small experiment."] = "Il mio incantesimo su un guerriero, {name}. Chiamalo un piccolo esperimento."
L["I only know the one spell for friends, {name}. Rage or mana, you're getting it."] = "Per gli amici conosco un solo incantesimo, {name}. Ira o mana, te lo becchi."
L["Your rage doesn't need this, {name}, but I'd feel rude walking past you."] = "La tua ira non ne ha bisogno, {name}, ma tirare dritto sarebbe scortese."
L["No mana, I know, {name}. A sharp mind never hurt a sharp blade."] = "Niente mana, lo so, {name}. Una mente acuta non ha mai guastato una lama affilata."
L["It's meant for mana, {name}. You'll find a use. Rogues always find a use."] = "Sarebbe per il mana, {name}. Un uso lo troverai: i ladri lo trovano sempre."
L["Not your kind of magic, {name}. Call it a very clever lockpick."] = "Non è la tua magia, {name}. Diciamo un grimaldello molto sveglio."
L["Aye, {name}, ye only had to ask. Hold still now!"] = "Ma certo, {name}, bastava chiedere! E ora non muoverti."
L["Here, {name}, a wee somethin' to keep ye on yer feet."] = "Tieni, {name}, un aiutino per tenerti in piedi."
L["My thanks, {name}. Allow me to return the kindness."] = "Ti ringrazio, {name}. Permettimi di ricambiare la cortesia."
L["Of course, {name}. Stand fast a moment."] = "Certo, {name}. Non muoverti per un istante."
L["The road ahead is long, {name}. Take this with you."] = "La strada è lunga, {name}. Porta questo con te."
L["Ishnu-alah, {name}. Your kindness is returned."] = "Ishnu-alah, {name}. Ricambio la tua gentilezza."
L["Elune-adore, {name}. Walk softly beneath the stars."] = "Elune-adore, {name}. Cammina lieve sotto le stelle."
L["The Light rewards kindness, {name}, and so shall I."] = "La Luce premia la gentilezza, {name}, e così farò anch'io."
L["Of course, {name}. May the Naaru guide your steps."] = "Certo, {name}. Che i Naaru guidino i tuoi passi."
L["The Light is with you, {name}. Go in peace."] = "La Luce è con te, {name}. Va' in pace."
L["Much obliged, {name}. Gilneas never forgets a kindness."] = "Grazie infinite, {name}. Gilneas non dimentica mai una gentilezza."
L["Lok'tar ogar, {name}! Take this into battle."] = "Lok'tar ogar, {name}! Portalo con te in battaglia."
L["The Earth Mother sees your kindness, {name}. I return it."] = "La Madre Terra vede la tua gentilezza, {name}. Io la ricambio."
L["Of course, {name}. Stand tall and be at peace."] = "Certo, {name}. Tieni alta la testa e resta in pace."
L["Walk with the Earth Mother, {name}."] = "Cammina con la Madre Terra, {name}."
L["Ya be too kind, {name}! Dis one be from me."] = "Si' troppo gentile, {name}! Chisto t'o dong' io."
L["Sure ting, {name}. Hold still now."] = "Sicuro, {name}. Mo' nun te movere."
L["Da loa be watchin' over ya, {name}."] = "'E loa te guardano 'e spalle, {name}."
L["Such courtesy does you credit, {name}. Anar'alah belore."] = "Tanta cortesia ti fa onore, {name}. Anar'alah belore."
L["Anar'alah belore, {name}. May the sun guide you."] = "Anar'alah belore, {name}. Che il sole ti guidi."
L["Your generosity is noted, {name}. Suramar remembers its friends."] = "Prendo nota della tua generosità, {name}. Suramar ricorda i suoi amici."
L["Thank you, {name}! The caravan always repays a kindness."] = "Grazie, {name}! La carovana ricambia sempre una gentilezza."
L["Every traveller needs something for the road, {name}."] = "Ogni viandante merita qualcosa per il viaggio, {name}."
L["Of course, {name}. Patience, and it is done."] = "Certo, {name}. Un po' di pazienza, ed è fatto."
L["Take this, {name}. Even a dragon needs allies."] = "Prendi, {name}. Anche un drago ha bisogno di alleati."
L["Thank you, {name}. The Alliance looks after its own."] = "Grazie, {name}. L'Alleanza si prende cura dei suoi."
L["Of course, {name}. Allies help each other."] = "Certo, {name}. Gli alleati si aiutano a vicenda."
L["For the Alliance, {name}! Stay strong out there."] = "Per l'Alleanza, {name}! Tieni duro là fuori."
L["Strength and honour, {name}. Your kindness is repaid."] = "Forza e onore, {name}. La tua gentilezza è ripagata."
L["Consider it done, {name}. For the Horde."] = "Consideralo fatto, {name}. Per l'Orda."
L["For the Horde, {name}! Go with strength."] = "Per l'Orda, {name}! Va' e sii forte."
L["Thank you, {name}. Good hearts are found everywhere."] = "Grazie, {name}. I cuori buoni si trovano ovunque."
L["Gladly, {name}, whatever banner you fly."] = "Con piacere, {name}, qualunque sia il tuo stendardo."
L["Friends can come from any side, {name}."] = "Gli amici possono venire da ogni parte, {name}."
L["Safe travels, {name}. Take some {buff} with you."] = "Buon viaggio, {name}. Porta con te un po' di {buff}."
L["Bwonsamdi gonna be real disappointed, {name}. Thanks, mon."] = "Bwonsamdi ce resta malissimo, {name}. Grazie, cumpà."
L["Sure ting, {name}. Hold still; da mojo don't like a movin' target."] = "Sicuro, {name}. Nun te movere: 'o mojo nun ama 'e bersagli mobili."
L["No worries, {name}. Da loa got ya covered."] = "Nun te preoccupà, {name}. Ce pensano 'e loa."
L["Stay away from da voodoo, {name}. ...Except dis voodoo. Dis one fine."] = "Statte luntano d''o voodoo, {name}. ...Tranne chisto. Chisto va bbuono."
L["Da loa be watchin' over ya, {name}. Dey real nosy like dat."] = "'E loa te guardano 'e spalle, {name}. So' curiosi assaje."
L["Stay sharp out dere, {name}. Take dis wit' ya."] = "Occhi aperti llà fore, {name}. Pigliate chisto."
L["Take dis, {name}. Walk like ya own da jungle. I do."] = "Piglia, {name}. Cammina da padrone d''a giungla. Comme a me."
L["Hey, {name}! Always good to see family, mon."] = "Uè, {name}! Fa sempre piacere vedé 'a famiglia, cumpà."
L["Dis crew got style, {name}. Now it got mojo too."] = "Sta compagnia tene stile, {name}. Mo' tene pure 'o mojo."
L["We go in together, {name}, we come out together. Dat be da whole plan, mon."] = "Trasimmo insieme, {name}, e ascimmo insieme. Chisto è tutto 'o piano, cumpà."
L["Night be da best time for mojo, {name}. Nobody see where it come from."] = "'A notte è l'ora d''o mojo, {name}. Nisciuno vede da dove vene."
L["We split the loot even, {name}. I'll do the maths. Trust me."] = "Bottino in parti uguali, {name}. I conti li faccio io. Fidati."
L["Returning a favour:"] = "Ricambiando un favore:"
L["Answering a request:"] = "Rispondendo a una richiesta:"
L["In your group:"] = "Nel tuo gruppo:"
L["Offering unasked:"] = "Di tua iniziativa:"
L["Returning a favour of %s:"] = "Ricambiando un favore di %s:"
L["Meeting somebody a third time:"] = "Incontrando qualcuno per la terza volta:"
L["(nothing -- speech off, or no usable lines)"] = "(niente -- messaggi disattivati o nessuna frase utilizzabile)"
L["In character"] = "Nel personaggio"
L["an in-character line"] = "una frase adatta al tuo personaggio"
L["Favour ledger"] = "Registro dei favori"
L["Close (Escape works too)"] = "Chiudi (funziona anche Esc)"
L["No favours recorded today."] = "Nessun favore registrato oggi."
L["Nothing you cast could return today's favours."] = "Nulla di ciò che lanci poteva ricambiare i favori di oggi."
L["Returned %d of 1 favour today."] = "Favori ricambiati oggi: %d su 1."
L["Returned %d of %d favours today."] = "Favori ricambiati oggi: %d su %d."
L["1 favour still owed."] = "1 favore ancora da ricambiare."
L["%d favours still owed."] = "%d favori ancora da ricambiare."
L["You gave 1 buff unprompted today."] = "Oggi hai dato 1 beneficio di tua iniziativa."
L["You gave %d buffs unprompted today."] = "Oggi hai dato %d benefici di tua iniziativa."
L["All time -- received: %d, returned: %d, given to your group: %d, to strangers: %d"] = "Da sempre -- ricevuti: %d, ricambiati: %d, dati al tuo gruppo: %d, a sconosciuti: %d"
L["All time"] = "Da sempre"
L["received"] = "ricevuti"
L["returned"] = "ricambiati"
L["to your group"] = "al tuo gruppo"
L["to strangers"] = "a sconosciuti"
L["%d-%d of %d"] = "%d-%d di %d"
L["Everything"] = "Tutto"
L["Favours"] = "Favori"
L["Buffs you gave"] = "Benefici dati"
L["Nothing recorded. When somebody buffs you it is listed here, and so is what you give back and who you buff unprompted."] = "Nessuna voce registrata. Quando qualcuno ti dà un beneficio compare qui, così come ciò che ricambi e a chi dai un beneficio di tua iniziativa."
L["No favours recorded. When somebody buffs you, they are listed here."] = "Nessun favore registrato. Quando qualcuno ti dà un beneficio, compare qui."
L["No buffs given unprompted. When the prompt buffs somebody who did not buff you first, it is listed here."] = "Nessun beneficio dato di tua iniziativa. Quando il riquadro dà un beneficio a qualcuno che non te ne aveva dato uno prima, compare qui."
L["Nothing is recorded while Manners is switched off."] = "Non viene registrato nulla mentre Manners è disattivato."
L["Nothing is recorded while the prompt has nothing to cast on this character."] = "Non viene registrato nulla mentre il riquadro non ha niente da lanciare con questo personaggio."
L["Clear"] = "Svuota"
L["Click again to clear"] = "Clic di nuovo: svuota"
L["Empties the list, and today's count with it. Favours you still owe stay, and the all-time totals are kept."] = "Svuota l'elenco, e con esso il conteggio di oggi. I favori ancora da ricambiare restano, e i totali di sempre vengono conservati."
L["Still owed"] = "Da ricambiare"
L["Returned"] = "Ricambiato"
L["Let go"] = "Lasciato perdere"
L["Gave"] = "Dato"
L["with %s"] = "con %s"
L["the time to return it ran out"] = "il tempo per ricambiarlo è scaduto"
L["nothing you cast is any use to them"] = "niente di ciò che lanci gli serve"
L["forgotten at a logout or reload"] = "dimenticato all'uscita o al ricaricamento"
L["you put them on your never-offer list"] = "l'hai aggiunto ai tuoi esclusi"
L["%s, in your group"] = "%s, nel tuo gruppo"
L["%s, to a stranger"] = "%s, a uno sconosciuto"
L["%s, to %d who needed it"] = "%s, a %d che ne avevano bisogno"
L["a buff"] = "un beneficio"
L["Buffed you with %s, %s."] = "Ti ha dato %s, %s."
L["They buffed you %d times; one buff back repays all of it."] = "Ti ha dato un beneficio %d volte; ricambiarne uno basta a saldare tutto."
L["Still owed. The prompt offers them until you return it or the time runs out."] = "Ancora da ricambiare. Il riquadro continua a proportelo finché non ricambi il favore o il tempo scade."
L["Still owed. What you cast reaches only your own party, so the prompt offers them only while they are in it."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo, quindi il riquadro te lo propone solo mentre ne fa parte."
L["Still owed. What you cast reaches only your own party -- in a raid, your own subgroup -- so the prompt offers them only while they are in it."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo -- in un'incursione, il tuo sottogruppo -- quindi il riquadro te lo propone solo mentre ne fa parte."
L["Still owed. What you cast reaches only your own party or raid, so the prompt offers them only while they are in it."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo o la tua incursione, quindi il riquadro te lo propone solo mentre ne fa parte."
L["You returned it %s later."] = "L'hai ricambiato %s dopo."
L["You returned it %s later, with %s."] = "L'hai ricambiato %s dopo, con %s."
L["Let go: the time to return it ran out before you did."] = "Lasciato perdere: il tempo per ricambiarlo è scaduto prima che lo facessi."
L["Let go: nothing you can cast is any use to them."] = "Lasciato perdere: niente di ciò che puoi lanciare gli serve."
L["Let go: \"%s\" (%s tab, under %s) is off, so it was forgotten when you logged out or reloaded."] = "Lasciato perdere: l'opzione \"%s\" (scheda %s, sotto %s) è disattivata, quindi il favore è stato dimenticato all'uscita dal gioco o al ricaricamento."
L["Keep favours through a /reload"] = "Conserva i favori dopo un /reload"
L["When to offer"] = "Quando proporre"
L["Let go: you put them on your never-offer list."] = "Lasciato perdere: l'hai aggiunto ai tuoi esclusi."
L["Still owed, but Manners is switched off, so the prompt will not offer them."] = "Ancora da ricambiare, ma Manners è disattivato, quindi il riquadro non te lo proporrà."
L["Still owed, but the prompt is not offering favours while \"People who buff me\" is off."] = "Ancora da ricambiare, ma il riquadro non propone favori mentre l'opzione \"Chi mi dà un beneficio\" è disattivata."
L["Still owed, but there is nothing on this character the prompt can cast."] = "Ancora da ricambiare, ma su questo personaggio non c'è niente che il riquadro possa lanciare."
L["Still owed. They are flagged for PvP, and buffing them would flag you, so the prompt offers them only if their flag drops before the time to return it runs out."] = "Ancora da ricambiare. Ha il PvP attivo, e dargli un beneficio lo attiverebbe anche a te, quindi il riquadro te lo propone solo se il suo PvP si disattiva prima che scada il tempo per ricambiarlo."
L["Still owed. The prompt is snoozed until %s, so it offers them only if the snooze ends before the time to return it runs out."] = "Ancora da ricambiare. Il riquadro è in pausa fino alle %s, quindi te lo propone solo se la pausa finisce prima che scada il tempo per ricambiarlo."
L["Still owed. The prompt stays away while you are mounted, and offers them once you get off, until the time to return it runs out."] = "Ancora da ricambiare. Il riquadro resta nascosto mentre sei in sella, e te lo propone quando scendi dalla cavalcatura, finché non scade il tempo per ricambiarlo."
L["Still owed. What you cast reaches only your own party, so the prompt offers them only while they are in it, and it is snoozed until %s, so only if time is left then."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo, quindi il riquadro te lo propone solo mentre ne fa parte, ed è in pausa fino alle %s, quindi solo se a quel punto c'è ancora tempo."
L["Still owed. What you cast reaches only your own party -- in a raid, your own subgroup -- so the prompt offers them only while they are in it, and it is snoozed until %s, so only if time is left then."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo -- in un'incursione, il tuo sottogruppo -- quindi il riquadro te lo propone solo mentre ne fa parte, ed è in pausa fino alle %s, quindi solo se a quel punto c'è ancora tempo."
L["Still owed. What you cast reaches only your own party, so the prompt offers them only while they are in it, once you are no longer mounted, until the time runs out."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo, quindi il riquadro te lo propone solo mentre ne fa parte, quando non sei più in sella, finché il tempo non scade."
L["Still owed. What you cast reaches only your own party -- in a raid, your own subgroup -- so the prompt offers them only while they are in it, once you are no longer mounted, until the time runs out."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo -- in un'incursione, il tuo sottogruppo -- quindi il riquadro te lo propone solo mentre ne fa parte, quando non sei più in sella, finché il tempo non scade."
L["Still owed. What you cast reaches only your own party or raid, so the prompt offers them only while they are in it, and it is snoozed until %s, so only if time is left then."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo o la tua incursione, quindi il riquadro te lo propone solo mentre ne fa parte, ed è in pausa fino alle %s, quindi solo se a quel punto c'è ancora tempo."
L["Still owed. What you cast reaches only your own party or raid, so the prompt offers them only while they are in it, once you are no longer mounted, until the time runs out."] = "Ancora da ricambiare. Ciò che lanci raggiunge solo il tuo gruppo o la tua incursione, quindi il riquadro te lo propone solo mentre ne fa parte, quando non sei più in sella, finché il tempo non scade."
