L["Pick Above the action bars to put it back where it started."] = "Scegli Sopra le barre delle azioni per rimetterlo dov'era all'inizio."
L["Dragging the prompt afterwards sets this to Where I dragged it."] = "Se poi trascini il riquadro, questa opzione passa a Dove l'ho trascinato."
L["Above the action bars (default)"] = "Sopra le barre delle azioni (predefinito)"
L["Where I dragged it"] = "Dove l'ho trascinato"
