L["When a new person appears on the prompt."] = "Quando una nuova persona compare nel riquadro."
L["Sound"] = "Suono"
L["%s |cff808080(not loaded)|r"] = "%s |cff808080(non caricato)|r"
L["Only for people who buff me"] = "Solo per chi mi dà un beneficio"
L["Off, every new person makes a sound, passers-by included."] = "Se disattivata, ogni nuova persona fa partire il suono, passanti compresi."
L["%s is silent. Pick a sound above."] = "%s è muto. Scegli un suono qui sopra."
