L["Font"] = "Carattere"
L["Font size"] = "Dimensione del carattere"
L["Text colour"] = "Colore del testo"
L["Left at white, text turns dark on a light panel by itself. Other colours are used as picked, except for names while this is on:"] = "Se lo lasci bianco, il testo diventa scuro da solo su un pannello chiaro. Gli altri colori vengono usati così come li scegli, tranne per i nomi quando è attiva questa opzione:"
L["Colour names by class"] = "Colora i nomi in base alla classe"
L["Show a second line"] = "Mostra una seconda riga"
L["Needs a prompt at least %d pixels tall."] = "Richiede un riquadro alto almeno %d pixel."
L["Icon and waiting list"] = "Icona e lista d'attesa"
L["Show spell icon"] = "Mostra l'icona dell'incantesimo"
L["Icon size"] = "Dimensione dell'icona"
L["Kept inside the prompt -- make it taller or wider first for a bigger icon."] = "Resta dentro il riquadro -- per un'icona più grande, prima rendilo più alto o più largo."
L["This look sizes the icon from the prompt's height: %d at %d high. Make the prompt taller for a bigger icon."] = "Questo aspetto dimensiona l'icona in base all'altezza del riquadro: %d con %d di altezza. Rendi il riquadro più alto per un'icona più grande."
L["The icon is held at %d to fit a prompt %d wide."] = "L'icona è limitata a %d per stare in un riquadro largo %d."
