L["Reporting a bug"] = "Segnalare un bug"
L["Hide the report"] = "Nascondi la segnalazione"
L["Copy for a bug report"] = "Copia per segnalare un bug"
L["Opens a box with the build, what this client allows, the settings that matter and anything that has broken, ready to copy."] = "Apre una casella con il numero di versione, cosa permette questo client, le impostazioni che contano e tutto ciò che è andato storto, pronta da copiare."
L["Every character uses the Default profile unless you pick another here; make one per character for different settings."] = "Tutti i personaggi usano il profilo predefinito, a meno che tu non ne scelga un altro qui; creane uno per personaggio per avere impostazioni diverse."
L["Share as text"] = "Condividi come testo"
L["Copy your settings as text to share, or paste text someone gave you. Pasting keeps your own on/off, lock, position, minimap button and chat options, and never turns on Say a line."] = "Copia le tue impostazioni come testo da condividere, o incolla il testo che ti ha dato qualcuno. Incollare mantiene le tue scelte su attivazione, blocco, posizione, pulsante della minimappa e chat, e non attiva mai Di' una frase."
L["Hide the text"] = "Nascondi il testo"
L["Show my settings as text"] = "Mostra le mie impostazioni come testo"
L["Shows your settings as text below, ready to copy; %s does the same."] = "Mostra qui sotto le tue impostazioni come testo, pronte da copiare; %s fa lo stesso."
L["Click in the box, press Ctrl+A to select it all, then Ctrl+C to copy (Cmd on a Mac)."] = "Fai clic nella casella, premi Ctrl+A per selezionare tutto, poi Ctrl+C per copiare (Cmd su Mac)."
L["Paste settings here, then press Accept"] = "Incolla qui le impostazioni, poi premi Accetta"
L["Replaces this profile's settings; %s puts yours back."] = "Sostituisce le impostazioni di questo profilo; %s ripristina le tue."
